RG.HK["12"] = [{"id":"12_katori_jingu","n":"香取神宮（下総国一之宮）","yomi":"かとりじんぐう","cat":"寺社","y":1700,"era":["nara","heian","edo"],"sh":"国宝（海獣葡萄鏡）・国の重要文化財（本殿・楼門）","rank":"S","ad":"香取市香取","st":"JR鹿島線 香取駅から歩いて約30分。JR佐原駅からタクシーで約10分","la":35.8866,"lo":140.5277,"hook":"平安時代の «神社名簿» で «神宮» と呼ばれたのは、伊勢・鹿島・そしてここ香取の3つだけ。","lead":"«香取神宮» は、刀の神さま «経津主大神（ふつぬしのおおかみ）» をまつる、下総国でいちばん格の高い神社（一之宮）です。黒い漆ぬりの本殿は江戸幕府がつくったもの。境内には、地面の下の大ナマズを押さえているという «要石» もあります。","story":["いまの利根川の下流には、むかし «香取海（かとりのうみ）» という大きな入り江が広がっていました。その入り江をはさんで向かい合っていたのが、茨城の «鹿島神宮» と千葉の «香取神宮»。海の道で東北へ向かう人びとにとって、ふたつの宮は «東の国の入り口を守る神» だったのです。","神話では、経津主神は鹿島の武甕槌神（たけみかづちのかみ）とともに出雲へ行き、大国主神に «この国をゆずりなさい» と話をつけた神とされます。なぜ遠い東国の神が、この大役をまかされたのでしょう？ 朝廷が東へ力をのばすとき、軍の神としてあがめたから、と考える研究者もいます。","平安時代の『延喜式』の神名帳には、全国3000あまりの神社がのっています。そのうち «神宮» と書かれたのは、伊勢・鹿島・香取だけ。この扱いからも、香取が特別な場所だったことがわかります。","いまの本殿と楼門は、1700年（元禄13年）に将軍 «徳川綱吉» の命令で建てられたもの。黒い漆に金の飾りがはえる本殿は、重々しいのにどこか華やか。朱ぬりの楼門をくぐると、空気がすっと冷たくなるように感じられます。","境内の奥の «要石» は、地上に出ているのはほんの少し。地震を起こす大ナマズの頭を押さえているといわれ、水戸の «徳川光圀» が掘らせたけれど底が見えなかった、という話も伝わります。鹿島神宮にも対になる要石があり、«鹿島は凹、香取は凸» と言われるのもおもしろいところです。"],"tl":[["神話の時代","神武天皇18年に創建と社伝は伝える"],["927年","『延喜式』神名帳に «香取神宮» として名神大社で記される"],["平安〜鎌倉時代","下総国一之宮として国司や武士の信仰を集める"],["1700年","徳川綱吉の命で本殿・楼門を造営"],["1871年","近代社格制度で官幣大社に"],["現在","12年に一度、午年に «式年神幸祭» が行われる"]],"who":[["経津主大神","まつられている神。刀剣・武の神"],["徳川綱吉","5代将軍。いまの本殿・楼門を造営させた"],["徳川光圀","水戸藩主。要石を掘らせたと伝わる"],["千葉氏","下総の豪族。香取の神を厚く信仰した"]],"deep":["国宝 «海獣葡萄鏡» は中国・唐の時代の鏡とされ、奈良の正倉院の鏡と並ぶ名品といわれます。どうやって東国の神社に来たのか、はっきりしたことはわかっていません。","«神宮» の称号: 『延喜式』神名帳（927年完成）で «神宮» と記されたのは大神宮（伊勢）・鹿島神宮・香取神宮の3社だけ。東国の2社が入っていることが、古代朝廷の東国政策の重さを物語ります。","香取と鹿島は «香取海» をはさんで向かい合う位置にあり、水上交通の要。古代の «香取海» は、いまの霞ヶ浦・北浦・印旛沼・手賀沼をひとつにつなぐような内海でした。","本殿は «権現造» で、黒漆塗りに極彩色の飾り。楼門の中には、随身として «武内宿禰»・«藤原鎌足» の像があるといわれます（ほかの人物説もあり）。","«式年神幸祭» は12年に一度の午年に行われ、御神輿が船に乗って利根川をわたる «御船遊» が見どころ。古い水上交通の記憶を今に伝える祭りといえます。","要石は «鯰（なまず）押さえ» の石として江戸時代の «鯰絵» にも描かれました。1855年の安政江戸地震のあと、鯰絵が大流行したことはよく知られています。"],"look":["黒漆塗りの本殿（元禄の建築）","朱ぬりの楼門","奥宮と要石（本殿から少し離れた森の中）","参道の門前町の «草だんご»","宝物館（開館日を確認）"],"q":["平安時代の『延喜式』で «神宮» と呼ばれた神社は、伊勢・鹿島とあとひとつはどこ？","香取神宮。東国の2社が入っていることが特別さを示しています。"],"koji":[{"w":"鹿島立ち","m":"旅立ちのこと。防人たちが鹿島・香取の神に祈って旅に出たことから、といわれる"}],"myth":"創建年（神武天皇18年）は社伝。要石を光圀が掘らせた話・楼門の随身像の人物名は伝承や諸説あり。","img":["鹿島神宮","要石","香取海","経津主神"],"wp":"香取神宮","rel":{"ev":[],"grave":[]},"ph":[["c:c/c6/Katori-jingu_haiden_shomen.JPG",5998,3972,"香取神宮"],["c:f/f2/Shintoyama-kofun.JPG",6016,4000],["c:2/29/Shintokukan_omotemon_%28Katori-jingu%29.JPG",5489,3638],["c:7/77/Sakuraotoji-jinja_%28Katori-jingu%29-2.jpg",5544,3676],["c:e/ed/Rokusho-jinja_%28Katori-jingu%29.jpg",5566,3710],["c:0/08/Oshio-jinja_%28Katori-jingu%29.JPG",6002,3978],["c:a/a1/Oshide-jinja_%28Katori-jingu%29-2.jpg",5269,3452],["c:9/90/Okumiya_%28Katori-jingu%29-2.jpg",5566,3710]]},{"id":"12_kasori_kaizuka","n":"加曽利貝塚（日本最大級の縄文貝塚）","yomi":"かそりかいづか","cat":"遺跡","y":-3000,"era":["jomon"],"sh":"国指定特別史跡","rank":"S","ad":"千葉市若葉区桜木8丁目","st":"千葉都市モノレール 桜木駅から歩いて約15分","la":35.6243,"lo":140.164,"hook":"縄文人が数千年かけて積み上げた «ゴミ捨て場» が、いまや国の «特別史跡»。","lead":"«加曽利貝塚» は、縄文時代の人びとが食べた貝の殻が積もってできた、日本でも最大級の貝塚です。北と南の二つの輪の形の貝塚がつながり、上から見ると «8の字» に見えます。貝塚の断面や、たて穴住居のあとを、そのまま見学できます。","story":["いまから5000年ほど前。このあたりは海がもっと陸の奥まで入りこみ、近くの坂月川の先には東京湾の干潟が広がっていました。村の人びとは干潟でハマグリやイボキサゴをとり、土器で煮て食べ、殻を家の近くに捨てました。それが何百年、何千年と続いて、厚い貝の層になったのです。","«ゴミ捨て場» と聞くと、きたない場所を想像するかもしれません。でも貝塚からは、土器や石器、動物の骨、そして人のお墓まで見つかります。«なぜ大切な人を貝塚に葬ったの？» ——貝殻のカルシウムのおかげで骨が溶けずに残り、わたしたちは縄文人の体や暮らしを知ることができるのです。","加曽利貝塚の名は、土器の名前にもなっています。«加曽利E式» «加曽利B式» は、縄文時代の中期と後期のものさしとなる土器の型式。全国の研究者が、この名前を使って年代を話し合っています。","昭和30年代、このあたりは団地などの開発が進み、貝塚がこわされそうになりました。そのとき、研究者や市民が «守ろう» と声を上げます。発掘に参加したボランティアもたくさんいました。こうして貝塚は残り、1966年には貝塚博物館ができました。","2017年、加曽利貝塚は国の «特別史跡» になりました。縄文の貝塚として初めてのことです。いま、北貝塚の断面観覧施設では、積み重なった貝の層をガラス越しに見ることができます。数千年の時間が、目の前に地層として立ち上がる瞬間です。"],"tl":[["約7000年前","このころから人びとが住み始めたとされる"],["約5000年前（縄文中期）","北貝塚がつくられる"],["約4000年前（縄文後期）","南貝塚がつくられる"],["1907年","東京人類学会による発掘"],["1960年代","開発計画に対して保存運動がおこる"],["1966年","千葉市立加曽利貝塚博物館が開館"],["1971年・1977年","北貝塚・南貝塚が国の史跡に"],["2017年","国の特別史跡に指定"]],"who":[["縄文の村の人びと","干潟の貝を食べ、何千年もここで暮らした"],["保存運動の市民と研究者","開発からこの貝塚を守った"],["東京人類学会の研究者","明治時代に発掘調査を行った"]],"deep":["«8の字»: 北貝塚は直径約130mの環状、南貝塚は長さ約190mの馬蹄形とされ、二つが接しています。時期がずれており、村の中心が北から南へ移ったと考えられています。","主に出てくる貝は «イボキサゴ» という小さな巻き貝。1個は小指の先ほどなのに、なぜこんなに大量に食べたのか？ 出汁をとった、干して保存食にした、など諸説があります。","«加曽利E式»（中期）と «加曽利B式»（後期）は、関東の縄文土器編年の柱。E・Bは、発掘地点につけられた記号に由来するといわれます。","特別史跡の指定は2017年。縄文時代の貝塚として初めての特別史跡で、東京湾沿岸にある多くの貝塚の代表とされました。","犬がていねいに埋葬された例も知られ、縄文人と犬の関係を考える手がかりになっています。","博物館のある公園には復元されたたて穴住居もあり、縄文土器を使った煮炊きの体験など、市民参加の活動がさかんです。"],"look":["北貝塚の貝層断面観覧施設","南貝塚の住居跡群観覧施設","復元たて穴住居","加曽利貝塚博物館の土器展示","«8の字» の全体を地形で感じる散策路"],"q":["加曽利貝塚で一番多く見つかる、小指の先ほどの小さな貝は？","«イボキサゴ»。小さいのに大量に食べられていた理由は、今も研究が続いています。"],"myth":"貝塚の形・大きさの数値は資料により多少異なる。イボキサゴの使い方は諸説。","img":["貝塚","縄文時代","加曽利E式土器","イボキサゴ"],"wp":"加曽利貝塚","rel":{"ev":[],"grave":[]},"ph":[["c:5/52/Kasori_midden.jpg",756,552,"加曽利貝塚"],["c:0/0a/Kasori_midden_preserve_south.jpg",3978,1536],["c:b/b7/Kasori_midden_preserve_north.jpg",2048,1536],["c:8/83/Conchero_Arguin.jpg",2048,1536,"貝塚"],["c:4/42/Umbonium_moniliferum_01.JPG",11000,5698,"イボキサゴ"]]},{"id":"12_ryukakuji_kofun","n":"龍角寺古墳群と岩屋古墳","yomi":"りゅうかくじこふんぐん","cat":"遺跡","y":620,"era":["kofun","asuka"],"sh":"国指定史跡","rank":"S","ad":"印旛郡栄町龍角寺・成田市大竹","st":"JR成田線 安食駅からバスで約10分 «房総のむら» 下車","la":35.839,"lo":140.244,"hook":"古墳の時代が終わりに近づいたころ、ここに «日本最大級の四角い古墳» が築かれた。","lead":"«龍角寺古墳群» は、印旛沼の北の台地に100基をこえる古墳が集まった場所です。なかでも «岩屋古墳» は一辺約78mの方墳で、全国でもトップクラスの大きさ。すぐそばには、関東でも古い寺 «龍角寺» があり、古墳から寺へと時代が移るようすがわかります。","story":["台地の林の中に、小山のような盛り土がいくつも並んでいます。これがみんな古墳。前方後円墳もあれば、小さな円墳もあります。印旛沼をのぞむこの台地は、古墳時代の終わりごろ、ある有力な一族の «お墓の丘» でした。","いちばん目をひくのが «岩屋古墳»。四角い形の古墳で、一辺は約78m。同じころの天皇の墓とされる方墳にも負けない大きさです。«なぜ、都から遠いこの場所に、こんな大きなお墓が？» ——このなぞが、歴史好きの心をくすぐります。","岩屋古墳の石室は、貝の化石をふくむ «貝化石砂岩» を積み上げてつくられています。近くの浅間山古墳の石室には、筑波山のあたりの石が使われているといわれます。重い石を、どうやってここまで運んだのでしょう。印旛沼や香取海の水の道が使われたのかもしれません。","古墳づくりがやんだあと、すぐ近くに建てられたのが «龍角寺»。関東でも古い寺のひとつで、白鳳時代の仏さまの頭部が今に伝わります。«お墓をつくる力» が «お寺をつくる力» に切りかわった——この丘は、日本の大きな時代の変わり目を、一か所で見せてくれるのです。","この地を治めたのは «印波国造（いんばのくにのみやつこ）» の一族ではないか、と考えられています。いまは «房総のむら» と «風土記の丘資料館» があり、古墳のあいだの散策路を歩くことができます。"],"tl":[["6世紀前半","古墳群の造営が始まるとされる"],["7世紀前半","浅間山古墳（前方後円墳）が築かれる"],["7世紀前半〜中ごろ","岩屋古墳（方墳）が築かれる"],["7世紀後半","近くに龍角寺が建てられる"],["1976年","千葉県立房総風土記の丘が開設"],["2009年","名称を «龍角寺古墳群・岩屋古墳» とあらためて国指定史跡に"]],"who":[["印波国造の一族","古墳をつくったと考えられる地元の有力者（諸説）"],["龍角寺を建てた人びと","古墳の時代のあと、仏教の寺をひらいた"]],"deep":["岩屋古墳の一辺約78mは、同時代の方墳として全国最大級。奈良の春日向山古墳（用明天皇陵とされる）などの大王墓クラスとくらべられるほどです。","浅間山古墳の石室からは、金銅製の冠の飾りなど豪華な副葬品が出ています。前方後円墳の «最後のころ» の例として重要です。","古墳の数は «113基» «114基» など資料により差があります。前方後円墳をふくむ多くの古墳が、台地の上に群れをつくっています。","龍角寺の瓦には、奈良の山田寺式に近い文様があるとされ、都とのつながりを感じさせます。本尊の薬師如来坐像（頭部は白鳳期）は国の重要文化財です。","«前方後円墳 → 大型方墳 → 寺院» という流れが一つの台地で追えるのは珍しく、地方豪族が律令国家の中に組みこまれていく過程を示す遺跡とされます。"],"look":["岩屋古墳の石室入口（中には入れない）","浅間山古墳と周囲の古墳の並び","風土記の丘資料館の出土品","龍角寺の境内と塔の礎石"],"q":["岩屋古墳は、丸・四角・前方後円のどの形の古墳？","四角（方墳）。一辺約78mで、同時代の方墳として全国最大級です。"],"myth":"被葬者を印波国造の一族とするのは有力説だが確定ではない。古墳の数は資料により差がある。","img":["岩屋古墳","浅間山古墳 (千葉県栄町)","龍角寺","房総のむら"],"wp":"龍角寺古墳群","rel":{"ev":[],"grave":[]},"ph":[["c:5/52/Ryukakuzikohungun1.JPG",3296,2472,"龍角寺古墳群"],["c:5/5f/Ryukakuji_Iwaya_Kofun%2C_3D-1.jpg",5058,3161],["c:d/d2/Miso_Iwaya_Kofun%2C_3D-1.jpg",12495,7028],["c:0/04/Ryukakuzi-keidai1.JPG",3296,2472],["c:4/4d/Iwayakohun-sekisitu.JPG",2472,3296],["c:9/9a/Ryukakuzi-sengenyamakohun1.JPG",2641,1785],["c:7/79/Iwaya-kofun-zenkei.jpg",640,480],["c:e/ee/Ryukaku-ji%2C_gaikan.jpg",5554,3692,"龍角寺"]]},{"id":"12_kazusa_kokubunji","n":"上総国分寺跡","yomi":"かずさこくぶんじあと","cat":"遺跡","y":741,"era":["nara"],"sh":"国指定史跡","rank":"S","ad":"市原市惣社・国分寺台中央","st":"JR内房線 五井駅からバスで約10〜15分","la":35.5,"lo":140.108,"hook":"日本最大級の «尼寺» が、市原の台地にあった。","lead":"奈良時代、聖武天皇は全国に «国分寺» と «国分尼寺» をつくるよう命じました。上総国（いまの千葉県中部）の国分寺は七重塔をもつ大きな寺で、国分尼寺は全国でもとびぬけて広い敷地をもっていました。尼寺の跡には中門と回廊の一部が復元されています。","story":["741年、奈良の都では病気や飢きん、反乱が続いていました。«仏の力で国を守りたい» ——聖武天皇はそう考え、国ごとに «国分寺» と «国分尼寺» を建てる命令を出します。上総国でも、国府の近くのこの台地に、大きな寺づくりが始まりました。","国分寺には、高さ60mをこえたともいわれる七重塔が建っていたと考えられます。いまの高いビルほどもある塔が、平らな台地の上にそびえたっていたのです。«どうしてそんなに高く？» ——遠くからでも見える塔は、都の力を地方の人びとに示す «看板» でもありました。","おどろきは尼寺です。上総国分尼寺の敷地は、全国の国分尼寺のなかでも最大級。発掘では、金堂や講堂、尼さんたちが暮らした建物のあとが見つかりました。昭和の宅地開発のときに大規模に調べられ、多くのことがわかりました。","いま、尼寺跡には朱色の中門と回廊の一部が復元され、奈良時代の姿を想像させてくれます。展示館では、出土した瓦や土器を見ることができます。","国分寺の跡には、いまも «国分寺» という寺があり、江戸時代の薬師堂が建っています。千二百年以上の時をこえて、同じ場所で祈りが続いているのです。","国分寺と国分尼寺は、なぜ少しはなれて建てられたのでしょう？ 僧と尼がそれぞれの寺で修行し、国の平和と人びとの罪の消滅を祈るためでした。二つの寺は «国を守る両輪» だったのです。台地の上を歩いて二つの跡をめぐると、奈良時代の人が歩いた道のりを体で感じることができます。"],"tl":[["741年","聖武天皇が国分寺建立の詔を出す"],["8世紀中ごろ","上総国分寺・国分尼寺が建てられる"],["平安時代","律令制のゆるみとともに衰えていく"],["昭和40年代〜","国分寺台の宅地開発にともない大規模な発掘"],["1990年代","尼寺跡に中門・回廊の一部を復元"]],"who":[["聖武天皇","国分寺建立の詔を出した"],["光明皇后","聖武天皇の妻。国分尼寺の建立をすすめたといわれる"],["上総国司","国府を治め、寺づくりを進めた役人"]],"deep":["国分寺の正式名は «金光明四天王護国之寺»、尼寺は «法華滅罪之寺»。尼寺には «罪をほろぼす» 役目が与えられていました。","上総国分尼寺の寺域は、全国の国分尼寺でも最大規模とされ、尼寺の建物配置がよくわかる貴重な例です。","七重塔の高さは基壇の大きさなどから推定されるもので、«60m超» はあくまで推定値です。","上総国府の場所ははっきりしていませんが、市原市内にあったと考えられ、周辺では «惣社» など国府に関わる地名が残ります。","発掘された文字の書かれた土器（墨書土器）や瓦は、寺の運営や当時のくらしを知る手がかりになります。","国分僧寺には20人、国分尼寺には10人の僧尼を置くことが、国分寺建立の詔で定められていました。広大な尼寺に10人というのは意外な少なさで、実際には多くの人が寺の運営を支えていたと考えられます。"],"look":["国分尼寺跡の復元中門と回廊","尼寺跡展示館の出土品","国分寺の七重塔跡（基壇と礎石）","国分寺の薬師堂と仁王門"],"q":["国分寺づくりを全国に命じた天皇は？","聖武天皇。741年に国分寺建立の詔を出しました。"],"myth":"七重塔の高さや、光明皇后が尼寺建立を勧めたという話は推定・伝承を含む。","img":["国分寺","聖武天皇","上総国分尼寺","上総国"],"wp":"上総国分寺","rel":{"ev":["kokubunji"],"grave":[]},"ph":[["c:4/41/Kazusa-kokubunji_yakushi-dou-2.jpg",5986,3956,"上総国分寺"],["c:9/92/Minamida-kawaragama-ato.jpg",6016,4000],["c:0/01/Kazusa-kokubunji_shourou.jpg",5950,3900],["c:1/1c/Kazusa-kokubunji_nioumon-2.jpg",6016,4000],["c:5/58/Kazusa-kokubunji_hondou-2.jpg",5998,3972],["c:f/f7/Kazusa-kokubunji_Masakado-tou-2.jpg",5992,3964],["c:f/f5/Kazusa-kokubunji-ato_tou-shinso.jpg",6016,4000],["c:d/db/Kazusa-kokubunji-ato_tou-2.jpg",6016,4000]]},{"id":"12_kiyosumidera","n":"清澄寺（日蓮が立教開宗した寺）","yomi":"きよすみでら","cat":"寺社","y":1253,"era":["kamakura"],"sh":"","rank":"S","ad":"鴨川市清澄","st":"JR外房線 安房天津駅からバスで約20分（本数が少ない）。車が便利","la":35.1597,"lo":140.1464,"hook":"朝日に向かって «南無妙法蓮華経» ——日蓮の最初の声はこの山で上がった。","lead":"«清澄寺（せいちょうじ）» は、房総の山の上にある古い寺です。安房の漁村に生まれた少年が12歳でここに入り、のちに «日蓮» となって、この山の上で初めて自分の教えを語りました。樹齢千年ともいわれる大杉が、その日のことを見ていたかもしれません。","story":["1233年、12歳の少年がこの山寺をたずねました。のちの «日蓮» です。«日本一の知者になりたい» ——そう願って学問にはげんだと伝わります。寺で学んだあと、鎌倉や比叡山、奈良などで、たくさんのお経を読みくらべました。","«どのお経が、本当にお釈迦さまの教えの中心なのか？» 長い修行のすえに日蓮が出した答えは «法華経» でした。そして1253年、ふるさとの清澄寺に帰ってきた日蓮は、山の «旭の森» で朝日に向かい、«南無妙法蓮華経» と題目をとなえたといわれます。","ところがその教えは、ほかの宗派をきびしく批判するものでした。地元の地頭 «東条景信» は念仏の信者で、日蓮に大いに怒ります。日蓮は山を下り、鎌倉へ向かいました。のちに «小松原の法難» で命をねらわれるなど、ふるさととの関係は波乱にみちていました。","境内には、国の天然記念物 «清澄の大杉» がそびえています。樹齢は千年ともいわれ、日蓮が見上げた木かもしれない——そう思うと、ふしぎな気持ちになります。","旭の森には、日蓮の銅像が朝日の方角を向いて立っています。晴れた朝、太平洋から昇る日の光は、750年以上前とかわらずこの山を照らしているのです。","なぜ日蓮は、教えを始める場所にふるさとの清澄寺を選んだのでしょう？ 学問の出発点であり、育ててくれた師がいる場所で、まず最初に自分の答えを伝えたかったから——そう考えると、この山の上の決意の重さが伝わってきます。"],"tl":[["771年","不思議法師が開いたと伝わる"],["836年","円仁（慈覚大師）が再興したと伝わる"],["1233年","12歳の日蓮がこの寺に入る"],["1253年","日蓮が旭の森で題目を唱え、立教開宗"],["1264年","近くの小松原で日蓮が襲われる（小松原法難）"],["1949年","日蓮宗の寺となる"]],"who":[["日蓮","12歳で入山し、のちにここで立教開宗した"],["道善房","日蓮の師匠となった清澄寺の僧"],["東条景信","安房の地頭。日蓮と対立した"]],"deep":["清澄寺は長く天台宗や真言宗の寺で、日蓮宗の寺になったのは1949年（昭和24年）のこと。日蓮ゆかりの地でありながら、他宗の寺だった期間が長いのです。","立教開宗の日は «建長5年4月28日»（1253年）とされ、日蓮宗ではこの日を大切な記念日としています。","«清澄の大杉» は国の天然記念物。太い幹に長い年月が刻まれた、房総を代表する巨木です。","日蓮が «日本第一の智者となし給え» と虚空蔵菩薩に祈った話は、日蓮自身の手紙に出てくるとされます。","清澄山一帯は東京大学の演習林（千葉演習林）が広がり、豊かな森が守られています。","清澄山は房総丘陵の中でも高い場所にあり、晴れた日には太平洋を見わたせます。«旭の森» の名のとおり、海から昇る朝日を真正面から受ける位置にあることが、立教開宗の伝説と強く結びついています。"],"look":["旭の森と日蓮像（朝日の方角）","清澄の大杉","祖師堂","山門からの房総の山なみ"],"q":["日蓮が初めて «南無妙法蓮華経» をとなえたのは西暦何年？","1253年（建長5年）。清澄寺の旭の森でのことと伝わります。"],"koji":[{"w":"立教開宗","m":"新しい宗派の教えを初めて説きはじめること。日蓮宗では1253年の清澄寺での出来事をさす"}],"myth":"開創（771年・不思議法師）・円仁の再興は寺伝。旭の森での題目の場面は伝承による部分が大きい。","img":["日蓮","日蓮宗","清澄山","小松原法難"],"wp":"清澄寺","rel":{"ev":[],"grave":[]},"ph":[["c:0/06/Nichiren_Daishonin_Hakii_Portrait.jpg",600,612,"日蓮"],["c:9/98/%E6%97%A5%E8%93%AE%E5%AE%97%E6%A9%98%EF%BC%88%E6%97%A5%E8%93%AE%E5%AE%97%E3%81%AE%E5%AE%97%E7%B4%8B%EF%BC%89%E3%83%BB%E5%B9%B3%E4%BA%95%E7%AD%92%E3%81%AB%E6%A9%98.png",4000,4000,"日蓮宗"],["c:1/15/Seityouji.jpg",3648,2736,"清澄山"]]},{"id":"12_hokekyoji","n":"中山法華経寺（立正安国論の寺）","yomi":"なかやまほけきょうじ","cat":"寺社","y":1260,"era":["kamakura","edo"],"sh":"国宝（立正安国論・観心本尊抄）・国の重要文化財（祖師堂・五重塔ほか）","rank":"S","ad":"市川市中山2丁目","st":"京成本線 京成中山駅から歩いて約5分。JR総武線 下総中山駅から歩いて約10分","la":35.7212,"lo":139.942,"hook":"日蓮が幕府に突きつけた «立正安国論»。その本物が、この寺に国宝として眠る。","lead":"«中山法華経寺» は、日蓮の強い味方だった下総の武士の屋敷から始まった寺です。日蓮が自分で書いた『立正安国論』『観心本尊抄』（どちらも国宝）が伝わり、日蓮宗の大本山のひとつになっています。冬には、僧が100日間こもる «荒行» でも知られます。","story":["1260年、日蓮は鎌倉幕府の実力者 «北条時頼» に一冊の書を差し出しました。『立正安国論』です。«地震や飢きんが続くのは、人びとが正しい教えを捨てたから。このままでは外国が攻めてくる»——あまりに大胆な内容に、幕府も念仏の信者たちも怒りました。","その直後、鎌倉の松葉谷にあった日蓮の草庵が襲われます（松葉谷の法難）。命からがら逃れた日蓮をかくまったとされるのが、下総国の武士 «富木常忍（ときじょうにん）»。この中山の地にあった彼の屋敷が、のちに «法華経寺» となっていきます。","«なぜ日蓮の直筆がここに？» ——富木常忍は学問にも通じた人で、日蓮から多くの手紙や大切な書を受けとり、ていねいに保管しました。『観心本尊抄』は、佐渡に流された日蓮がそこで書き上げ、常忍に送ったものです。弟子たちの手で何百年も守られ、国宝として今に伝わりました。","境内には、比翼入母屋造という珍しい屋根の «祖師堂»、江戸時代の «五重塔»、«法華堂» など、国の重要文化財がずらりと並びます。参道には門前町の雰囲気が残り、下町の人びとにも «中山の鬼子母神» として親しまれてきました。","毎年11月1日から2月10日まで、境内の «大荒行堂» では僧たちが寒さの中で水をかぶり、お経を読み続ける100日間の修行をします。2月10日、やせた修行僧たちが門を出る «成満会» には、多くの人が出迎えに集まります。"],"tl":[["1260年","日蓮が『立正安国論』を北条時頼に提出"],["1260年","松葉谷の法難。日蓮が下総の富木常忍のもとへ逃れたと伝わる"],["1273年","佐渡で書かれた『観心本尊抄』が富木常忍に送られる"],["鎌倉時代後期","富木常忍の «法華寺» と太田乗明の «本妙寺» が中心となって寺が発展"],["1622年","五重塔が建てられる"],["江戸時代","祖師堂など現在の伽藍が整う"]],"who":[["日蓮","『立正安国論』の著者。この地の信者を訪ねた"],["富木常忍（日常）","下総の武士。日蓮を支え、屋敷を寺にした"],["太田乗明","富木常忍とともに日蓮を支えた武士"],["北条時頼","『立正安国論』を受けとった鎌倉幕府の実力者"]],"deep":["『立正安国論』は «旅客と主人の問答» という形式で書かれています。予言とされた «他国侵逼難（外国からの侵略）» は、のちの元寇と結びつけて語られるようになりました。","日蓮の直筆（真蹟）は «聖教殿» に収められ、ふだんは公開されていません。年に一度、11月3日の «お風入れ» のときに一部を見られる機会があります。","祖師堂の «比翼入母屋造» は、入母屋造の屋根を前後に二つ並べた形で、全国でも珍しい例です。","五重塔は1622年（元和8年）の建立とされ、本阿弥光室の寄進と伝わります。関東に残る江戸初期の五重塔として貴重です。","聖教殿は建築家 «伊東忠太» の設計とされ、インド風の意匠をとりいれた昭和初期の建物です。","富木常忍の法名は «日常»。武士でありながら深い学識をもち、日蓮との手紙のやりとりが多く残っていることが、当時の信仰と生活を知る貴重な史料になっています。"],"look":["祖師堂の比翼入母屋造の屋根","五重塔","法華堂・四足門","聖教殿（外観）","参道の門前町"],"q":["日蓮が北条時頼に差し出し、いま法華経寺に国宝として伝わる書は？","『立正安国論』。日蓮の直筆本が伝わっています。"],"myth":"松葉谷の法難後に日蓮が富木邸に逃れた話は伝承を含む。五重塔の寄進者は伝承。","img":["日蓮","立正安国論","富木常忍","観心本尊抄"],"wp":"法華経寺","rel":{"ev":[],"grave":[]},"ph":[["c:5/51/%E4%B8%AD%E5%B1%B1%E6%B3%95%E8%8F%AF%E7%B5%8C%E5%AF%BA_-_panoramio_%2822%29.jpg",5471,3647,"法華経寺"],["c:b/b0/%E4%B8%AD%E5%B1%B1%E6%B3%95%E8%8F%AF%E7%B5%8C%E5%AF%BA_01.jpg",6147,4098],["c:b/b6/%E4%B8%AD%E5%B1%B1%E6%B3%95%E8%8F%AF%E7%B5%8C%E5%AF%BA_-_panoramio_%287%29.jpg",4488,3168],["c:4/46/%E4%B8%AD%E5%B1%B1%E6%B3%95%E8%8F%AF%E7%B5%8C%E5%AF%BA_-_panoramio_%2813%29.jpg",5184,3456],["c:4/46/Nakayama_sanmon.JPG",3264,2448],["c:7/70/Nakayama_okunoin.JPG",3264,2448],["c:3/35/Risshou_Ankokuron.jpg",3820,1736],["c:f/f2/Nakayama_nichikozazou.jpg",1980,2048]]},{"id":"12_shinshoji","n":"成田山新勝寺（将門調伏の寺）","yomi":"なりたさんしんしょうじ","cat":"寺社","y":940,"era":["heian","edo"],"sh":"国の重要文化財（仁王門・三重塔・釈迦堂・光明堂・額堂）","rank":"S","ad":"成田市成田","st":"JR成田駅・京成成田駅から表参道を歩いて約15分","la":35.7862,"lo":140.3183,"hook":"平将門の乱をしずめるために、京都からお不動さまがやってきた。","lead":"«成田山新勝寺» は、平安時代に平将門の乱をしずめるために開かれたと伝わるお寺です。江戸時代には歌舞伎の «市川團十郎» の信仰で人気が爆発し、今では初詣に毎年ものすごい数の人が集まります。境内には江戸時代の建物がたくさん残っています。","story":["940年、関東では «平将門» が «新皇» を名のり、朝廷に反旗をひるがえしていました。京都はあわてます。«どうすれば将門をしずめられるか» ——朝廷の命を受けた僧 «寛朝（かんちょう）» は、京都・高雄山の不動明王像をたずさえて東国へ下りました。","寛朝がこの地で21日間の護摩（火をたいて祈る儀式）を行ったところ、ちょうどそのころ将門は討たれた、と寺では伝えます。都へ帰ろうとしたとき、不動明王像は重くなってびくとも動かなかった。«この地にとどまりたい» という仏の心だと考え、寺がひらかれました。だから名前は «新たに勝つ» と書いて «新勝寺»。","江戸時代、成田山を一気に有名にしたのが、歌舞伎役者の «初代市川團十郎»。子どもに恵まれなかった團十郎が成田山に祈ると、子どもが生まれた——そう伝わり、團十郎は成田山の不動明王を題材にした芝居を演じます。屋号 «成田屋» もここから。江戸っ子たちは «成田詣» に夢中になりました。","江戸の «出開帳» も人気の秘密です。お不動さまを江戸の深川などに運び、そこで拝めるようにしたのです。«江戸から歩いて成田へ» «成田から江戸へ出張» ——信仰とイベントが一体になっていました。","いま境内には、仁王門・三重塔・釈迦堂・光明堂・額堂という江戸時代の建物が国の重要文化財として残っています。鮮やかな三重塔の彫刻や、額堂に掲げられた奉納額を見ていると、江戸の人びとのにぎわいが聞こえてくるようです。"],"tl":[["940年","寛朝が不動明王を奉じ、将門調伏の護摩を行ったと伝わる"],["940年","平将門が討たれる"],["1700年ごろ","初代市川團十郎が成田山の不動を演じ、成田信仰が広まる"],["1712年","三重塔が建てられる"],["1858年","旧本堂（いまの釈迦堂）が建てられる"],["1968年","大本堂が完成"]],"who":[["寛朝","朝廷の命で不動明王を奉じ、開山となった僧"],["平将門","関東で反乱をおこした武将"],["初代市川團十郎","成田山を信仰した歌舞伎役者。屋号 «成田屋»"],["二宮尊徳","成田山で断食修行をしたと伝わる"]],"deep":["本尊の不動明王は «空海（弘法大師）がつくった» と伝わる像。もとは京都・高雄山神護寺にあったとされます。","«神田明神の氏子は成田山にお参りしない» という話があります。神田明神が将門をまつっているためで、俗信として知られています。","三重塔（1712年）は高さ約25m。軒下の雲の彫刻や十六羅漢の彫刻が見事で、極彩色がほどこされています。","釈迦堂は1858年（安政5年）に本堂として建てられ、大本堂ができるときに今の場所へ移されました。","成田への参詣が増えると、門前の «成田山表参道» が発達。うなぎ料理店が並ぶのは、印旛沼や利根川でうなぎがとれたことと関係があるといわれます。","額堂には、江戸・明治の商人や役者たちが奉納した額や絵馬が並び、当時の人気や経済力を知る資料になっています。"],"look":["仁王門と大提灯","三重塔の彫刻","釈迦堂・額堂・光明堂","成田山公園の池と森","表参道の町並み"],"q":["成田山を信仰した歌舞伎役者・市川團十郎家の屋号は？","«成田屋»。成田山の不動明王への信仰から来ています。"],"koji":[{"w":"成田屋！","m":"歌舞伎の見せ場でかかる掛け声。市川團十郎家への声援"}],"myth":"将門調伏の護摩と像が動かなくなった話は寺伝。神田明神の氏子の話は俗信。二宮尊徳の断食も伝承。","img":["平将門","寛朝","市川團十郎 (初代)","平将門の乱"],"wp":"新勝寺","rel":{"ev":[],"grave":[]},"ph":[["c:1/15/Naritasan-Shinshoji-Temple-2008.jpg",800,450,"新勝寺"],["c:2/23/Naritasan_Temple_building_a.jpg",5472,3648],["c:9/91/Naritasan_Temple_beside_the_3_storied_pagoda.jpg",5472,3648],["c:b/bb/120803_Narita-san_Shinsho-ji_Narita_Chiba_pref_Japan03bs5.jpg",3056,4592],["c:8/8f/Shinshoji.aerialshoot.jpg",3648,2736],["c:a/a5/%E6%96%B0%E5%8B%9D%E5%AF%BA_-_panoramio_-_%E3%81%8F%E3%82%8D%E3%81%B5%E3%81%AD_%286%29.jpg",3456,2592],["c:7/74/Nakayama_KankoChizu.jpg",2783,1777],["c:8/8a/Naritasan-Somon_201203.jpg",2400,1800]]},{"id":"12_motosakura_jo","n":"本佐倉城（千葉氏の本拠）","yomi":"もとさくらじょう","cat":"城","y":1484,"era":["muromachi","azuchi"],"sh":"国指定史跡","rank":"S","ad":"印旛郡酒々井町本佐倉・佐倉市大佐倉","st":"京成本線 大佐倉駅から歩いて約20分","la":35.7295,"lo":140.2715,"hook":"下総の名門・千葉氏が100年ほど本拠にした、土でつくられた巨大な山城。","lead":"«本佐倉城» は、戦国時代に下総の大名 «千葉氏» が本拠地にした城です。石垣はなく、台地をけずった «土の城»。空堀や土塁、いくつもの «郭（くるわ）» がよく残り、戦国の城の姿を体で感じることができます。","story":["千葉氏は、平安時代から下総に根をはった名門の武士です。鎌倉幕府を開いた源頼朝をいち早く助けた «千葉常胤» の子孫として知られます。はじめの本拠は、いまの千葉市にありました。","15世紀の半ば、千葉氏の中で一族どうしの争いが起こり、本家が滅ぼされます。生き残った一族は本拠を移すことにしました。«どこなら安全か？» ——選ばれたのが、印旛沼につながる水辺を見下ろすこの台地でした。千葉輔胤のころに城が築かれたとされます。","城は、いくつもの郭が堀で区切られた、まるで迷路のようなつくり。いちばん奥の «奥ノ山»、儀式の場ともいわれる «セッテイ山»、家臣が暮らした «東山» など、郭の名前もおもしろいものばかりです。水運で物が集まり、城下には町ができていきました。","戦国時代の終わり、千葉氏は小田原の北条氏に従う立場になっていました。1590年、豊臣秀吉が北条氏を攻め落とすと、千葉氏も大名としての歴史を閉じます。その後、徳川の家臣が入りましたが、近くに新しく «佐倉城» ができると、本佐倉城は役目を終えました。","いま城跡を歩くと、深い空堀と高い土塁に囲まれて、今にも戦国武者が現れそうな気配です。石垣のお城とはちがう、«関東の土の城» の迫力をたっぷり味わえます。"],"tl":[["1455年","千葉氏の内紛で本家が滅ぶ（享徳の乱の一幕）"],["文明年間（1469〜1487年）","千葉輔胤のころに本佐倉城が築かれたとされる"],["16世紀","千葉氏の本拠として城と城下が栄える"],["1590年","小田原合戦で北条方の千葉氏が大名としての地位を失う"],["1610年代","佐倉城の築城により廃城となる"],["1998年","国指定史跡に"]],"who":[["千葉輔胤","本佐倉城を築いたとされる千葉氏の当主"],["千葉常胤","鎌倉時代の千葉氏の祖。頼朝を助けた"],["千葉邦胤","戦国時代後期の当主"],["土井利勝","近くに佐倉城を築いた徳川の重臣"]],"deep":["本佐倉城は «本佐倉城跡» として1998年に国指定史跡となりました。酒々井町と佐倉市の二つの町にまたがっています。","郭の名前 «セッテイ山» は «接待» に由来するともいわれ、客をもてなしたり儀式を行ったりした場所とする説があります。","城の北側は低地で、かつては印旛沼につながる水辺でした。水運を押さえる位置にあることが、本拠地に選ばれた理由と考えられています。","千葉邦胤は1585年に家臣に殺されたと伝わり、その後は北条氏の影響が一気に強まりました。","発掘調査では建物の柱穴や、陶磁器などが見つかっており、城主の暮らしぶりが少しずつわかってきています。","本佐倉城の周辺には «酒々井» の城下町が発達し、宿場町として江戸時代にもにぎわいました。«酒々井» の名は、酒がわき出す井戸の伝説に由来するといわれます。"],"look":["奥ノ山（主郭）からの眺め","郭を区切る深い空堀","東山・城山・セッテイ山の郭めぐり","酒々井町の案内所で配布の縄張図","城跡のガイダンス施設（本佐倉城跡の案内所）"],"q":["本佐倉城は石垣の城？ それとも土の城？","土の城。台地をけずり、空堀と土塁で守る関東の戦国城郭の典型です。"],"myth":"築城年・築城者（千葉輔胤）には諸説。郭名の由来も諸説。","img":["千葉氏","佐倉城","千葉常胤","享徳の乱"],"wp":"本佐倉城","rel":{"ev":[],"grave":[]},"ph":[["c:f/f5/Motosakura_castle.jpg",800,600,"本佐倉城"],["c:7/7a/Moat_of_Settei_base%28Settei_Compound%29.jpg",5248,3936],["c:c/c8/Moat_between_Shiroyama_base_and_Okunoyama_base.jpg",5248,3936],["c:4/4f/Higashiyama_gate_of_Motosakura_Castle.jpg",5248,3936],["c:4/45/Gate_of_Shiroyama_base%28Compund%29.jpg",5248,3936],["c:5/56/Earthen_wall_of_Shiroyama_base%28Compound%29.jpg",5248,3936],["c:c/c5/%E6%97%A5%E6%9C%AC%E3%81%AE%E5%9F%8E%E8%B7%A1.png",971,940],["c:e/e3/Motosakura_castle_site.jpg",1000,750]]},{"id":"12_konodai_jo","n":"国府台城（二度の国府台合戦）","yomi":"こうのだいじょう","cat":"古戦場","y":1538,"era":["muromachi"],"sh":"","rank":"S","ad":"市川市国府台3丁目（里見公園）","st":"京成本線 国府台駅から歩いて約20分。JR市川駅からバスもある","la":35.7508,"lo":139.9055,"hook":"江戸川を見下ろす崖の上。ここで関東の覇権をかけた戦いが、二度もくり広げられた。","lead":"«国府台（こうのだい）» は、古代に下総国の国府があった台地です。戦国時代には城が置かれ、1538年と1564年の二度、北条氏と房総の勢力が激しく戦いました（国府台合戦）。いまは «里見公園» として整備され、桜の名所になっています。","story":["台地の下には江戸川が流れ、向こう岸には武蔵の国が広がります。«ここを押さえれば、下総への入り口を押さえられる» ——国府台は、昔から軍事の要でした。室町時代には太田道灌がここに陣を置いたとも伝えられています。","1538年、第一次の国府台合戦。«小弓公方» と名のった «足利義明» と、安房の «里見義堯» が組んで、小田原の «北条氏綱» と戦いました。義明は自ら先頭に立って戦い、討ち死にしてしまいます。里見軍は大きな戦いをせずに退いたともいわれ、«なぜ里見は助けなかったのか？» は今も議論になるところです。","それから26年後の1564年、第二次の合戦。今度は «里見義弘» と «北条氏康» がぶつかりました。緒戦では里見方が勝ったものの、正月の祝いで油断していたところを北条軍に攻められ、里見方は大敗したと伝わります。","公園の一角には «里見諸将霊墓» があり、この戦いでたおれた人びとをしのぶ碑が静かに立っています。また、討ち死にした武将の娘が石にすがって泣き続けた、という «夜泣き石» の伝説も残ります。","明治以降は陸軍の施設が置かれた台地でもあります。いまは桜とバラの名所としてにぎわいますが、足もとの土塁のあとに、戦国の人びとの必死の攻防が眠っているのです。"],"tl":[["奈良時代","国府台に下総国府が置かれる"],["1479年","太田道灌がこの地に陣を置いたと伝わる"],["1538年","第一次国府台合戦。足利義明が戦死"],["1564年","第二次国府台合戦。北条氏康が里見義弘を破る"],["1590年","小田原合戦ののち廃城となる"],["明治時代以降","台地に陸軍の施設が置かれる。戦後に里見公園として整備"]],"who":[["足利義明","小弓公方。第一次合戦で戦死"],["里見義堯","安房の大名。第一次合戦で義明と組んだ"],["北条氏綱","小田原北条氏2代。第一次合戦の勝者"],["北条氏康","北条氏3代。第二次合戦の勝者"],["里見義弘","義堯の子。第二次合戦で敗れた"]],"deep":["第二次合戦の年は «永禄7年（1564年）» とするのが一般的ですが、前年の永禄6年にも衝突があったとする説があり、«二度» の数え方には議論があります。","«国府台» の名は下総国府に由来します。国府の中心は、いまの和洋女子大学あたりと考えられ、発掘で役所の建物の跡が見つかっています。","第一次合戦で足利義明が敗れたことで «小弓公方» は滅び、房総での北条氏の影響が強まりました。里見氏にとっては、義明の死によって上総方面へ勢力をのばすきっかけにもなったといわれます。","«夜泣き石» は、里見方の武将の娘が父の死を嘆いて石にもたれて泣き、そのまま息たえたという伝説にもとづくものです。","江戸川をはさんだ対岸は東京都葛飾区柴又。«矢切の渡し» は、この台地の下あたりで今も江戸川を渡っています。"],"look":["里見公園の土塁の跡","里見諸将霊墓","夜泣き石","江戸川を見下ろす崖からの眺め","春の桜並木"],"q":["第一次国府台合戦で戦死した «小弓公方» は誰？","足利義明。自ら先陣に立って北条氏綱の軍と戦いました。"],"myth":"太田道灌の陣・夜泣き石・第二次合戦の «正月の油断» は伝承を含む。第二次合戦の年には諸説。","img":["国府台合戦","里見義堯","足利義明 (小弓公方)","北条氏康"],"wp":"国府台城","rel":{"ev":[],"grave":[]},"ph":[["c:b/b0/Konodai_Castle.jpg",2048,1536,"国府台城"],["c:c/c5/%E6%97%A5%E6%9C%AC%E3%81%AE%E5%9F%8E%E8%B7%A1.png",971,940],["c:d/d4/Battle_of_K%C5%8Dnodai_%28Osaka_battlefield%29.jpg",4592,3056,"国府台合戦"],["c:0/04/%E9%87%8C%E8%A6%8B%E7%BE%A9%E5%A0%AF%E6%9C%A8%E5%83%8F.jpg",1055,1200,"里見義堯"],["c:1/1d/Ujiyasu_Hojo.jpg",537,658,"北条氏康"]]},{"id":"12_tateyama_jo","n":"館山城（里見氏最後の城）","yomi":"たてやまじょう","cat":"城","y":1590,"era":["azuchi","edo"],"sh":"","rank":"S","ad":"館山市館山（城山公園）","st":"JR内房線 館山駅から歩いて約25分。バスで «城山公園前» 下車すぐ","la":34.9867,"lo":139.8617,"hook":"『南総里見八犬伝』の里見家が、最後にいた城。","lead":"«館山城» は、安房の大名 «里見氏» が戦国時代の終わりに本拠とした城です。1614年、里見氏は徳川幕府に領地を取り上げられ、城もこわされました。いま山の上に建つ天守は昭和につくられたもので、中は『南総里見八犬伝』の博物館になっています。","story":["里見氏は、戦国時代の房総半島で北条氏と戦い続けた大名です。本拠地は時代によって移り変わり、最後に選ばれたのが館山の城山でした。1590年ごろ、«里見義康» が城下町とともに整えたとされます。","義康は豊臣秀吉、そして徳川家康に従い、関ヶ原の戦いのあとには常陸に領地を加えられて12万石ほどの大名になりました。«やっと家が安定する» ——そう思えたかもしれません。","ところが1614年、義康の子 «里見忠義» は、幕府の重臣 «大久保忠隣» の失脚に巻きこまれます。忠義の妻が忠隣の孫だったためだといわれます。安房の領地は取り上げられ、忠義は伯耆国（いまの鳥取県）の倉吉へ移されました。館山城はこわされ、里見家の房総支配は終わります。","忠義は倉吉で若くして亡くなり、そのとき8人の家臣がともに亡くなったと伝わります。この «八人» の話が、のちに曲亭馬琴の『南総里見八犬伝』の «八犬士» の着想のひとつになったのでは、ともいわれます。","いまの天守は1982年に建てられた «模擬天守»（昔の本物ではない天守）で、館山市立博物館の分館として八犬伝の資料を展示しています。山頂からは館山湾と、晴れた日には富士山まで見わたせます。","里見氏がいなくなったあとも、房総の人びとは里見の名を忘れませんでした。約200年後、江戸の作家・曲亭馬琴は、この里見家を舞台に壮大な物語を書き上げます。伏姫と八匹の犬、そして八つの玉をもつ八犬士——物語の中で、里見家は正義の家として永遠に生き続けることになったのです。"],"tl":[["1580年代","里見氏がこの地に城を築きはじめたとされる"],["1590年ごろ","里見義康が本拠を館山城へ移す"],["1600年","関ヶ原の戦いのあと、常陸鹿島に領地を加えられる"],["1614年","里見忠義が改易、館山城は破却"],["1622年","忠義が倉吉で死去"],["1814年","曲亭馬琴『南総里見八犬伝』の刊行が始まる"],["1982年","模擬天守が完成"]],"who":[["里見義康","館山城を本拠とした里見氏の当主"],["里見忠義","最後の当主。改易され倉吉で死去"],["大久保忠隣","失脚した幕府の重臣。忠義の妻の祖父"],["曲亭馬琴","『南総里見八犬伝』の作者"]],"deep":["『南総里見八犬伝』は約28年をかけて書かれた長編で、史実の里見氏とは大きく異なる創作です。伏姫・八犬士は架空の人物です。","里見氏の改易の理由には、大久保忠隣との縁のほか、城の無断修築や家中の問題など諸説があります。","忠義に殉じた8人の家臣は «八賢士» とよばれ、倉吉の大岳院に墓があります。館山にも供養塔があります。","模擬天守は、近世の天守の形を参考に建てられたもので、里見時代に天守があったかどうかはわかっていません。","城山公園の周辺には、里見氏時代の曲輪や堀の跡が地形として残っているといわれます。"],"look":["模擬天守（八犬伝博物館）","山頂からの館山湾と富士山","城山公園の曲輪の地形","館山市立博物館本館の里見氏展示"],"q":["『南総里見八犬伝』の作者は？","曲亭馬琴（滝沢馬琴）。里見氏の歴史をもとにした長編の創作です。"],"myth":"八賢士が八犬伝の着想になったという話は説の一つ。里見時代の天守の有無は不明。","img":["里見氏","南総里見八犬伝","里見忠義","曲亭馬琴"],"wp":"館山城","rel":{"ev":[],"grave":[]},"ph":[["c:a/a1/Tateyama_Castle%2C_tenshu.JPG",5502,3655,"館山城"],["c:7/7d/Ch%C3%A2teau_de_Himeji02.jpg",2592,1944],["c:1/11/%E9%A4%A8%E5%B1%B1%E5%B8%82%E7%AB%8B%E5%8D%9A%E7%89%A9%E9%A4%A8_-_panoramio.jpg",1504,1000],["c:c/c5/%E6%97%A5%E6%9C%AC%E3%81%AE%E5%9F%8E%E8%B7%A1.png",971,940],["c:b/b7/Futatsuhikiryo_sw.jpg",300,300,"里見氏"],["c:f/fe/Satomi_and_the_Eight_%E2%80%9CDogs%E2%80%9D_WDL2937.pdf",1831,2500,"南総里見八犬伝"],["c:7/79/Kyokutei_Bakin.jpg",1191,1411,"曲亭馬琴"]]},{"id":"12_otaki_jo","n":"大多喜城（本多忠勝の城）","yomi":"おおたきじょう","cat":"城","y":1590,"era":["azuchi","edo"],"sh":"","rank":"S","ad":"夷隅郡大多喜町大多喜","st":"いすみ鉄道 大多喜駅から歩いて約15分","la":35.2857,"lo":140.2436,"hook":"«徳川四天王» 本多忠勝が、10万石で最初に城主となった城。","lead":"«大多喜城» は、徳川家康の重臣 «本多忠勝» が房総の押さえとして入った城です。里見氏ににらみをきかせるための重要な拠点でした。いまの天守は昭和に建てられたもので、県立博物館の分館になっています。城下町の古い町並みも残ります。","story":["1590年、関東に移った徳川家康は、家臣たちを要所に配置しました。房総半島の南には、まだ家康に従って日が浅い里見氏がいます。«ここを任せられるのは、あの男しかいない» ——選ばれたのが、生涯57回の戦いで一度も傷を負わなかったと伝わる猛将 «本多忠勝» でした。","忠勝は、もとからあった «小田喜城» を大きく改修し、城下町を整えました。城は夷隅川が大きく曲がる台地の上にあり、川を天然の堀にした守りのかたい城です。本丸の近くには、«日本一» ともいわれた大井戸が今も残っています。","1609年、この城に思いがけない客がやってきます。スペイン領フィリピンの前総督 «ドン・ロドリゴ» です。メキシコへ向かう船が嵐で御宿の海岸に打ち上げられ、村人に助けられました。大多喜城で忠勝の子 «本多忠朝» が彼をもてなしたと、ロドリゴ自身が記録に書き残しています。","忠朝は1615年の大坂夏の陣で、先陣として奮戦し討ち死にしました。父ゆずりの勇猛さだったといわれます。その後、大多喜の城主は何度か入れかわり、江戸時代の半ば以降は大河内松平家が明治まで治めました。","いまの天守は1975年に建てられたもの。本当に天守があったかどうかは議論がありますが、夷隅川ぞいの城下町を見下ろす姿は «房総の小江戸» 大多喜の顔になっています。"],"tl":[["16世紀前半","真里谷武田氏が «小田喜城» を築いたと伝わる"],["16世紀半ば","里見方の正木氏の城となる"],["1590年","本多忠勝が10万石で入り、城を大改修"],["1601年","忠勝が伊勢桑名へ移り、子の忠朝が城主に"],["1609年","ドン・ロドリゴが大多喜城を訪れる"],["1615年","本多忠朝が大坂夏の陣で戦死"],["1975年","模擬天守（県立博物館分館）が完成"]],"who":[["本多忠勝","徳川四天王の一人。大多喜城の初代近世城主"],["本多忠朝","忠勝の次男。ドン・ロドリゴを迎えた"],["ドン・ロドリゴ","前フィリピン総督。御宿沖で遭難し、大多喜を訪れた"],["正木時茂","里見氏の重臣。戦国期にこの城を拠点とした"]],"deep":["ドン・ロドリゴの記録『日本見聞録』には、大多喜城を訪ねて城主と会ったようすが書かれているとされ、同時代の城を外国人が描いた貴重な史料です。","大井戸は周囲約17m・深さ約20mといわれ、«日本一の大井戸» と伝えられています（数字は伝承）。","天守の存在については、忠勝時代の絵図などから «あった» とする説と、確証がないとする説があります。いまの天守は、そうした資料を参考にした模擬天守です。","本多忠勝の愛槍は «蜻蛉切»。穂先にとまったトンボが切れたという逸話で有名です（伝承）。","御宿町の岩和田には、ドン・ロドリゴ遭難を記念した «日西墨三国交通発祥記念之碑» が建っています。日本・スペイン・メキシコの交流の始まりとされます。"],"look":["模擬天守（県立中央博物館大多喜城分館。開館状況は事前に確認）","本丸跡近くの大井戸","夷隅川が囲む地形","大多喜の城下町（商家の町並み）"],"q":["1609年、嵐で遭難して大多喜城を訪れた外国人は誰？","ドン・ロドリゴ。前フィリピン総督で、城主の本多忠朝にもてなされました。"],"koji":[{"w":"家康に過ぎたるもの","m":"«家康に過ぎたるものは二つあり、唐の頭に本多平八» という落首。平八（忠勝）が家康にはもったいないほどの武将だとたたえた"}],"myth":"«57回の戦で無傷»・蜻蛉切の逸話・大井戸の寸法は伝承。天守の有無は諸説。","img":["本多忠勝","本多忠朝","御宿町","大多喜町"],"wp":"大多喜城","rel":{"ev":[],"grave":[]},"ph":[["c:7/7d/Otaki_Castle_02.jpg",3463,2309,"大多喜城"],["c:b/b7/Otaki_castle_yakuimon.jpg",3872,2592],["c:1/15/Otaki_castle_oido.jpg",3872,2592],["c:5/54/Otaki_Castle_04.jpg",3888,2592],["c:7/7c/%E5%A4%A7%E5%A4%9A%E5%96%9C%E5%9F%8E_-_panoramio.jpg",1600,900],["c:0/0a/%E3%82%B5%E3%82%AF%E3%83%A9%E5%92%B2%E3%81%8F%E9%A0%83%E3%81%AE%E5%A4%A7%E5%A4%9A%E5%96%9C%E5%9F%8EP1010050.jpg",1280,957],["c:c/c5/%E6%97%A5%E6%9C%AC%E3%81%AE%E5%9F%8E%E8%B7%A1.png",971,940],["c:8/83/Burg_Otaki_Plan.jpg",1050,742]]},{"id":"12_sakura_jo","n":"佐倉城（老中の城・歴博の地）","yomi":"さくらじょう","cat":"城","y":1611,"era":["edo","meiji"],"sh":"","rank":"S","ad":"佐倉市城内町（佐倉城址公園）","st":"京成本線 京成佐倉駅から歩いて約20分。JR佐倉駅からバスもある","la":35.721,"lo":140.217,"hook":"石垣のない城から、次々と «老中» が生まれた。","lead":"«佐倉城» は、江戸時代の初めに «土井利勝» が築いた城です。江戸の東を守る大事な城で、城主の多くが幕府の «老中» になりました。明治には陸軍の連隊が置かれ、いまは城跡の中に «国立歴史民俗博物館» が建っています。","story":["1610年ごろ、2代将軍 «徳川秀忠» の側近 «土井利勝» が佐倉に入り、新しい城づくりを始めました。千葉氏が本拠にした本佐倉城ではなく、印旛沼に近い別の台地が選ばれます。«江戸から近く、東国へにらみをきかせられる場所» ——それが佐倉でした。","佐倉城には石垣がありません。台地のがけと、深い空堀、高い土塁で守る城です。関東の土は石垣をつくる石に恵まれなかったから、ともいわれます。天守にあたる «御三階櫓» がありましたが、1813年に火事で焼けてしまいました。","江戸時代、佐倉の城主はたびたび入れかわり、そのうち何人もが老中になりました。幕末の城主 «堀田正睦» は老中首座として、アメリカとの通商条約を結ぶため京都へ行き、天皇の許しを得ようとしましたが、失敗に終わります。«開国か、攘夷か» ——時代のうねりの中心に、佐倉の殿さまがいたのです。","明治になると城は取りこわされ、陸軍の歩兵連隊が置かれました。«佐倉連隊» として多くの兵士がここから出征しています。","戦後、城跡は公園になり、1983年には国立歴史民俗博物館が開館しました。空堀や土塁、馬出しのあとをたどりながら、城と博物館をセットで歩くのが佐倉のおすすめコースです。"],"tl":[["1610年ごろ","土井利勝が築城を始める"],["1746年","堀田正亮が入り、以後明治まで堀田家が城主"],["1813年","御三階櫓（天守）が火事で焼失"],["1858年","城主・堀田正睦が条約勅許を得るため上京、失敗"],["1874年","陸軍歩兵第2連隊が置かれる"],["1983年","城跡に国立歴史民俗博物館が開館"]],"who":[["土井利勝","築城者。徳川秀忠の側近で老中・大老"],["堀田正睦","幕末の老中首座。日米修好通商条約の交渉にあたった"],["堀田正亮","堀田家として初めて佐倉に入った城主。老中"],["佐藤泰然","堀田正睦に招かれ、城下に «順天堂» を開いた蘭方医"]],"deep":["佐倉の城主からは土井利勝・堀田正亮・堀田正睦をはじめ多くの老中が出ており、«老中の城» とよばれることがあります。","城の西側にある «馬出し空堀» は、出入口を守るための工夫で、発掘成果にもとづいて復元整備されています。","«姥ヶ池» には、城主の子を預かった乳母が池に落ちた子を追って身を投げた、という伝説が残ります。","日本100名城のひとつ。近くには武家屋敷が残る «ひよどり坂» や «旧堀田邸»（国の重要文化財）もあり、城下町の雰囲気を味わえます。","連隊の兵営時代の門柱や、陸軍に関わる碑も公園内に点在し、城跡が «近代の軍都» だった歴史を伝えています。","佐倉藩の藩校 «成徳書院» では、幕末に蘭学や西洋医学の教育も取り入れられ、堀田正睦の開明的な姿勢を示すものとされています。"],"look":["本丸跡と天守（御三階櫓）跡","馬出し空堀と土塁","姥ヶ池","国立歴史民俗博物館","城下の武家屋敷とひよどり坂","城跡の «佐倉連隊» 関連の碑や門柱"],"q":["佐倉城の城主で、幕末にアメリカとの通商条約の勅許を得ようとした老中首座は？","堀田正睦。京都で許しを得ようとしましたが失敗しました。"],"myth":"石垣がない理由は諸説。姥ヶ池の話は伝説。","img":["堀田正睦","土井利勝","国立歴史民俗博物館","旧堀田家住宅"],"wp":"佐倉城","rel":{"ev":[],"grave":[]},"ph":[["c:d/d7/Sakura_Castle_2.JPG",4608,3456,"佐倉城"],["c:6/69/%E4%BD%90%E5%80%89%E5%9F%8E%E5%9D%80%E3%81%AB%E3%81%A6_%E5%87%BA%E4%B8%B8%E8%B7%A1_Sakura_Castle_2015.1.02_-_panoramio.jpg",4928,3264],["c:8/87/%E4%BD%90%E5%80%89%E5%9F%8E%E5%9D%80%E3%81%AB%E3%81%A6_Sakura_Castle_2015.1.02_-_panoramio_%281%29.jpg",4928,3264],["c:c/c5/%E6%97%A5%E6%9C%AC%E3%81%AE%E5%9F%8E%E8%B7%A1.png",971,940],["c:0/0b/Daimyo_Hotta_Masayoshi.png",580,845,"堀田正睦"],["c:1/11/Doi_Toshikatu.jpg",861,658,"土井利勝"],["c:b/bd/National_Museum_of_Japanese_History_2008%28cropped%29.jpg",3159,2124,"国立歴史民俗博物館"]]},{"id":"12_juntendo","n":"佐倉順天堂（蘭方医学の塾）","yomi":"さくらじゅんてんどう","cat":"幕末","y":1843,"era":["edo","meiji"],"sh":"県指定史跡","rank":"S","ad":"佐倉市本町","st":"京成本線 京成佐倉駅から歩いて約20分。JR佐倉駅からバスもある","la":35.725,"lo":140.229,"hook":"«西の長崎、東の佐倉» ——幕末の日本に、最先端の西洋医学の学校があった。","lead":"«佐倉順天堂» は、1843年に蘭方医（オランダ流の医者）«佐藤泰然» が開いた病院をかねた塾です。全国から若い医者が学びに集まりました。今の «順天堂大学» のルーツで、幕末の建物の一部が «佐倉順天堂記念館» として残っています。","story":["江戸で西洋医学の塾を開いていた «佐藤泰然» は、1843年、佐倉藩主 «堀田正睦» にまねかれて佐倉にやってきます。正睦は蘭学に熱心な «蘭癖大名» の一人。«これからは西洋の学問が必要だ» と考えていたのです。","泰然は城下の本町に «順天堂» を開きました。«天の道に順（したが）う» という意味です。ここでは、薬で治すだけでなく、外科手術も行いました。麻酔が十分でない時代に、乳がんの手術など、当時としてはとても高度な治療に挑んだと伝わります。","順天堂には、手術や治療ごとの料金をしるした «療治料金表» が残っています。«どの手術にいくらかかるか» を患者に示していたのです。今でいう «医療の見える化»。記念館でその複製を見ることができます。","全国から集まった塾生の中には、のちに北海道の開拓に尽くした «関寛斎» もいました。泰然の実の子には、幕府の医官となった «松本良順»、外交官として活躍した «林董» がいます。養子となった «佐藤尚中» は、明治に東京で «順天堂医院» を開き、それが今の順天堂大学へとつながりました。","記念館の建物は1858年に建てられたものの一部。畳の部屋に古い医療器具が並ぶ様子は、どこか静かで、でも熱気の名残を感じさせます。ここで命を救おうとした医者たちの姿を、ぜひ想像してみてください。"],"tl":[["1838年","佐藤泰然が江戸で蘭方医学の塾を開く"],["1843年","佐倉に «順天堂» を開く"],["1858年","現存する建物が建てられる"],["1873年","佐藤尚中が東京に順天堂医院を開く"],["現在","佐倉順天堂記念館として公開"]],"who":[["佐藤泰然","順天堂の創設者。蘭方医"],["堀田正睦","佐倉藩主。泰然を佐倉にまねいた"],["佐藤尚中","泰然の養子。東京に順天堂医院を開いた"],["松本良順","泰然の実子。幕府の医官、のち陸軍軍医総監"],["関寛斎","順天堂の塾生。晩年に北海道の開拓に尽くした"]],"deep":["«西の長崎、東の佐倉» は、長崎の鳴滝塾などと並ぶ西洋医学の拠点として佐倉をたたえた言い方です。","«療治料金表» には、手術の種類ごとに謝礼の目安が書かれ、当時の医療の中身を知る貴重な資料です。","泰然は長崎で蘭学を学んだとされ、江戸では薬研堀に塾を開いていました。佐倉移住後は、藩の医療や種痘にも関わったといわれます。","泰然の子・林董は、明治に外務大臣などを務めた人物で、医者の家から外交官が出たことになります。","順天堂大学は «日本最古の西洋医学塾を起源とする大学» と名のっています。佐倉の地は、その原点です。","泰然は «順天堂» を開く前、長崎で学んだ知識をもとに江戸で塾を開いていました。佐倉への移住には、藩主・堀田正睦の蘭学好みと、西洋医学への期待があったと考えられています。"],"look":["佐倉順天堂記念館の建物（1858年）","療治料金表などの資料（複製）","古い医療器具の展示","周辺の城下町の町並み","記念館の近くに残る城下町の小路"],"q":["佐倉順天堂を開いた蘭方医は？","佐藤泰然。1843年に佐倉藩主・堀田正睦にまねかれて開きました。"],"myth":"手術の «日本初» などの表現は資料によって異なるため、ここでは用いていない。","img":["佐藤泰然","佐藤尚中","順天堂大学","関寛斎"],"wp":"佐倉順天堂","rel":{"ev":[],"grave":[]},"ph":[["c:2/2a/Sat%C5%8D_Taizen.jpeg",607,900,"佐藤泰然"],["c:3/3d/Hisanaka_Sat%C5%8D_in_his_young_days.jpg",225,332,"佐藤尚中"],["c:7/75/Seki_Kansai_Monument.jpg",480,854,"関寛斎"]]},{"id":"12_ino_tadataka","n":"伊能忠敬旧宅と佐原の町並み","yomi":"いのうただたかきゅうたく","cat":"町","y":1794,"era":["edo"],"sh":"国指定史跡","rank":"S","ad":"香取市佐原イ","st":"JR成田線 佐原駅から歩いて約10分","la":35.8918,"lo":140.4995,"hook":"50歳で «第二の人生» を始めた男が、日本の形を初めて正確に描いた。","lead":"«伊能忠敬» は、佐原の商家の主人として家を盛りたてたあと、50歳で江戸に出て天文学を学び、17年かけて日本中を測量しました。その成果の地図は、驚くほど正確でした。小野川ぞいの旧宅と、川をはさんだ記念館で、その人生をたどれます。","story":["忠敬は1745年、九十九里浜に近い村で生まれました。17歳のとき、佐原の商家 «伊能家» の婿になります。伊能家は酒づくりや米の取引などを営む大きな家。忠敬は家業を立て直し、村のリーダーとしても活躍しました。天明の飢きんのときには、困った人びとに米を配ったといわれます。","«ずっと星や暦のことを学びたかった» ——49歳で家を息子にゆずった忠敬は、翌年江戸に出て、19歳も年下の天文学者 «高橋至時» の弟子になります。毎日、星を観測し、計算をくり返しました。","«地球の大きさを知りたい» ——そのためには長い距離を正確にはかる必要がありました。1800年、55歳の忠敬は蝦夷地（北海道）へ測量に向かいます。これが、17年にわたる全国測量の始まりでした。歩いた距離は約4万km、地球一周ほどともいわれます。","忠敬は1818年、地図の完成を見ずに亡くなります。弟子たちが仕事を引きつぎ、1821年に «大日本沿海輿地全図» が完成しました。その正確さは、のちに日本の地図を見たイギリス人たちをおどろかせたと伝わります。","佐原の旧宅は、小野川に面した店と、奥の書院・土蔵などからなります。書院は忠敬が自分で設計したといわれます。すぐ前の小野川には、水路の水が音を立てて流れ落ちる «樋橋（じゃあじゃあ橋）»。忠敬もこの音を聞いていたのかもしれません。"],"tl":[["1745年","上総国小関村（いまの九十九里町）に生まれる"],["1762年","佐原の伊能家に婿入り"],["1794年","家督を息子にゆずり隠居"],["1795年","江戸で高橋至時に入門"],["1800年","蝦夷地の測量に出発（第1次測量）"],["1816年","最後の測量（第10次、江戸府内）を終える"],["1818年","江戸で死去"],["1821年","«大日本沿海輿地全図» が完成・上呈"]],"who":[["伊能忠敬","佐原の商人から測量家へ。日本全図の作成者"],["高橋至時","幕府天文方。忠敬の師匠"],["高橋景保","至時の子。忠敬の死後、地図の完成をまとめた"],["間宮林蔵","忠敬から測量を学んだとされる探検家"]],"deep":["伊能忠敬記念館の «伊能忠敬関係資料» は2010年に国宝に指定され、地図・測量日記・器具など2000点以上がまとまっています。","測量は «導線法»（決まった歩幅や縄・鎖で距離をはかり、方位を測ってつなげる方法）と «交会法»（遠くの山などの方角を複数地点から測る方法）の組み合わせ。夜は星を観測して緯度を確かめました。","忠敬が求めた緯度1度の長さ «28.2里» は、現代の値とくらべてもほとんど誤差がないとされ、高橋至時も驚いたといわれます。","«大日本沿海輿地全図» は、大図214枚・中図8枚・小図3枚で構成されます。","旧宅は1930年に国の史跡に指定されました。佐原の町並みは、関東で初めて国の «重要伝統的建造物群保存地区» に選ばれています。","シーボルト事件（1828年）では、日本地図の写しを渡したことで高橋景保が捕らえられ、獄中で亡くなりました。忠敬の地図は «国の機密» でもあったのです。"],"look":["旧宅の店舗・書院・土蔵","小野川の «樋橋（じゃあじゃあ橋）»","伊能忠敬記念館の地図と測量器具","小野川ぞいの商家の町並み"],"q":["伊能忠敬が江戸に出て天文学を学びはじめたのは何歳ごろ？","50歳ごろ（1795年）。19歳年下の高橋至時に弟子入りしました。"],"koji":[{"w":"人生五十年","m":"昔の «人の一生は50年ほど» という考え方。忠敬はその年齢から新しい学びを始めた"}],"myth":"歩いた距離（約4万km）は概算。書院を忠敬が設計した話は伝承。","img":["伊能忠敬","大日本沿海輿地全図","佐原","高橋至時"],"wp":"伊能忠敬旧宅","rel":{"ev":[],"grave":[]},"ph":[["c:7/72/Inou-tadataka-house%2Ckatori-city%2Cjapan.JPG",1600,1200,"伊能忠敬旧宅"],["c:7/7d/Ch%C3%A2teau_de_Himeji02.jpg",2592,1944],["c:e/e6/Ino-tadataka-house-mise%2Ckatori-city%2Cjapan.JPG",1600,1200],["c:d/d7/Ino_Tadataka_%28cropped%29.jpg",1056,1248,"伊能忠敬"],["c:9/9a/%E4%BC%8A%E8%83%BD%E5%9B%B3%E5%85%A8%E4%BD%93%E5%9B%B3.webp",680,812,"大日本沿海輿地全図"],["c:a/a9/Grave_of_Takahashi_Yoshitoki_%28Genkuji_Taito%29.jpg",900,1300,"高橋至時"]]},{"id":"12_rekihaku","n":"国立歴史民俗博物館","yomi":"こくりつれきしみんぞくはくぶつかん","cat":"学び","y":1983,"era":["showa","heisei"],"sh":"","rank":"S","ad":"佐倉市城内町","st":"京成本線 京成佐倉駅から歩いて約15分。JR佐倉駅・京成佐倉駅からバスもある","la":35.7196,"lo":140.2143,"hook":"«弥生時代は500年早く始まっていた»——日本史の教科書をゆさぶった研究は、この博物館から生まれた。","lead":"«国立歴史民俗博物館»（通称 «歴博»）は、日本の歴史と人びとのくらしを、原始から現代まで一つの流れで見せる国立の博物館です。佐倉城の跡に1983年に開館しました。展示だけでなく、全国の研究者が集まる研究機関でもあります。","story":["«歴史を、人びとのくらしから見てみよう» ——歴博は、有名人や大事件だけでなく、ふつうの人の生活や信仰、祭りを大切にする博物館として生まれました。明治100年の記念事業として構想され、1983年、佐倉城跡に開館します。","展示室を歩いていくと、縄文のムラから古代の都、中世の町、江戸の暮らし、近代の工場、そして戦後の団地の部屋へと、時代が少しずつ移り変わっていきます。本物の資料と、実物大の復元模型が組み合わされ、«その時代に入りこむ» ような感覚を味わえます。","歴博は «研究する博物館» でもあります。2003年、歴博の研究グループは、土器についた炭化物を最新の方法で年代測定し、«弥生時代の始まりは、これまで考えられていたより約500年早い» と発表しました。«本当なのか？» と大きな議論になり、今も研究が続いています。","館の中には、京都の町のにぎわいを描いた «洛中洛外図屏風»（歴博甲本）など、名高い資料が数多く所蔵されています。展示替えがあるので、見たいものがあれば事前に確かめるのがおすすめです。","館の外には、日本人のくらしに関わる植物を集めた «くらしの植物苑» もあります。佐倉城の空堀と土塁に囲まれて、歴史を «読む» だけでなく «歩いて感じる» ことができる場所です。"],"tl":[["1966年","明治百年記念事業として構想が示される"],["1981年","国立歴史民俗博物館が設置される"],["1983年","佐倉城跡に開館"],["2003年","弥生時代の開始年代を早める研究成果を発表"],["2004年","大学共同利用機関法人 人間文化研究機構の一員に"],["2019年","第1展示室（先史・古代）をリニューアル"]],"who":[["井上光貞","古代史研究者。初代館長"],["全国の研究者","大学共同利用機関として共同研究に集まる"]],"deep":["歴博は «大学共同利用機関» で、全国の大学の研究者が共同研究を行う場でもあります。展示は研究成果を社会に届ける役割も担っています。","«弥生時代の始まりは紀元前10世紀ごろ» という年代観は、AMS法による炭素14年代測定にもとづくもので、学界では賛否がありました。","«洛中洛外図屏風 歴博甲本» は、現存する洛中洛外図の中でも古い形を伝えるものとされ、国の重要文化財です。","総合展示は «先史・古代»«中世»«近世»«民俗»«近代»«現代» などの展示室からなり、順次リニューアルが進められています。","建物は、佐倉城の本丸から少しはなれた場所にあり、城跡の地形を大きく壊さないよう配慮して建てられたといわれます。"],"look":["第1展示室（先史・古代）の実物大模型","中世の町並み模型","江戸の暮らしと民俗の展示","現代の展示（戦後のくらし）","くらしの植物苑"],"q":["歴博の研究グループが2003年に発表した、弥生時代の始まりについての説とは？","それまでの考えより約500年早く、紀元前10世紀ごろに始まったという説です。"],"myth":"弥生時代開始年代は学説が分かれる。","img":["佐倉城","洛中洛外図","弥生時代","人間文化研究機構"],"wp":"国立歴史民俗博物館","rel":{"ev":[],"grave":[]},"ph":[["c:b/bd/National_Museum_of_Japanese_History_2008%28cropped%29.jpg",3159,2124,"国立歴史民俗博物館"],["c:a/af/Rekihaku_sakura.jpg",4000,3000],["c:b/b5/%E5%9B%BD%E7%AB%8B%E6%AD%B4%E5%8F%B2%E6%B0%91%E4%BF%97%E5%8D%9A%E7%89%A9%E9%A4%A8%E3%83%90%E3%82%B9%E5%81%9C_2015.1.02_-_panoramio.jpg",3672,2448],["c:8/8f/Ancient_warriors%E3%83%BB%E5%80%AD.jpg",2409,3200],["c:f/ff/Various_clay_figurines.jpg",3200,1800],["c:8/80/Shiraito_Odoshi_Armor.jpg",1800,3200],["c:6/6f/Noble_attire.jpg",1800,3200],["c:2/2d/Nakatsuka_Shell_Mound.jpg",3200,1800]]},{"id":"12_tamasaki_jinja","n":"玉前神社（上総国一之宮）","yomi":"たまさきじんじゃ","cat":"寺社","y":927,"era":["heian","edo"],"sh":"","rank":"A","ad":"長生郡一宮町一宮","st":"JR外房線 上総一ノ宮駅から歩いて約8分","la":35.374,"lo":140.3697,"hook":"海からやってきた女神をむかえて、男たちが裸で浜を駆ける。","lead":"«玉前神社（たまさきじんじゃ）» は、上総国でいちばん格の高い «一之宮» です。まつられているのは、神武天皇の母とされる «玉依姫命（たまよりひめのみこと）»。毎年9月の «上総十二社祭り» では、神輿をかついだ男たちが九十九里の浜を走ります。","story":["一宮町の名前は、この神社が «上総国の一之宮» であることから来ています。平安時代の『延喜式』にも名の見える古い社で、長く地域の人びとの心のよりどころになってきました。","まつられている玉依姫命は、海の神の娘とされる女神です。«海からこの浜にあがってきた» という伝えがあり、神社と海とのつながりはとても深いのです。«なぜ海の神の娘が、この浜に？» ——九十九里の長い砂浜は、海の向こうから神がやってくる場所だと考えられていたのかもしれません。","その伝えを今に再現するのが、9月の «上総十二社祭り»。玉前神社と近くの神社の神輿が集まり、釣ヶ崎の海岸で «再会» します。さらしを巻いた男たちが神輿をかつぎ、波打ちぎわを駆けぬける姿は «上総の裸祭り» ともよばれ、1200年以上続くと伝えられます。","社殿は黒い漆でぬられた «権現造»。江戸時代前期に建てられたもので、落ち着いた重みがあります。境内には «はだし参り» の道もあり、はだしで歩いてお参りする人の姿も見られます。","源頼朝の妻・北条政子が、子どもを授かるよう祈ったという話も伝わり、子宝・安産の神としても信仰されています。静かな境内に、海風がそっと吹きこんできます。"],"tl":[["古代","創建（年代ははっきりしない）"],["927年","『延喜式』神名帳に名神大社として記される"],["鎌倉時代","源頼朝・北条政子の信仰が伝えられる"],["江戸時代前期","現在の黒漆塗りの社殿が造営される"],["1871年","近代社格制度で国幣中社に"],["現在","毎年9月に上総十二社祭りが行われる"]],"who":[["玉依姫命","まつられている女神。神武天皇の母とされる"],["北条政子","源頼朝の妻。安産を祈ったと伝わる"],["源頼朝","鎌倉幕府を開いた。上総の一之宮として崇敬したと伝わる"]],"deep":["上総十二社祭りでは、玉前神社と周辺の神社の神輿が釣ヶ崎の海岸に集まる «浜降り» が見どころ。地域の大切な民俗行事として受けつがれています。","社殿は黒漆塗りの権現造で、千葉県の有形文化財。江戸時代の神社建築として県内でも貴重な例とされます。","近年、玉前神社は «春分・秋分の日に朝日が昇る方角の先に、寒川神社や富士山、出雲大社が並ぶ» という «レイライン» の話で注目されています。これは現代に広まった説で、歴史的な根拠があるわけではありません。","«玉前» の読みは «たまさき»。«玉» は «魂»、«前（さき）» は «崎» に通じ、海に突き出た場所で神霊をまつったことに由来するという説があります（諸説）。","一之宮どうしの交流として、全国一の宮会の活動にも加わっており、御朱印めぐりの人も多く訪れます。","«一宮町» は、九十九里浜の南の端にあたり、いまはサーフィンの町としても知られています。2021年の東京オリンピックでは、町内の釣ヶ崎海岸がサーフィン競技の会場になりました。"],"look":["黒漆塗りの社殿","はだし参りの道","境内のご神木","9月の祭りの日の釣ヶ崎海岸（祭りの日のみ）"],"q":["玉前神社にまつられている女神は？","玉依姫命（たまよりひめのみこと）。神武天皇の母とされています。"],"myth":"頼朝・政子の祈願は伝承。祭りの «1200年以上» は伝え。レイラインは現代の説で史料の裏づけはない。","img":["上総十二社祭り","玉依姫","上総国","一宮町"],"wp":"玉前神社","rel":{"ev":[],"grave":[]},"ph":[["c:5/57/Tamasaki-jinja.jpg",2240,1538,"玉前神社"],["c:0/04/Tamasaki-jinja%2C_honden.JPG",6016,4000],["c:a/a6/Sazare_stone_in_Tamasaki_shrine%2C_Chiba%2C_Japan.JPG",4320,3240],["j:3/38/%E7%8E%89%E5%89%8D%E7%A5%9E%E7%A4%BE_%E7%A5%9E%E6%A5%BD%E6%AE%BF.JPG",3648,2736],["j:1/1c/%E7%8E%89%E5%89%8D%E7%A5%9E%E7%A4%BE_%E6%8B%9B%E9%AD%82%E6%AE%BF.JPG",3648,2736],["j:9/93/%E7%8E%89%E5%89%8D%E7%A5%9E%E7%A4%BE_%E5%A2%83%E5%86%85%E7%A4%BE%E5%8D%81%E4%BA%8C%E7%A4%BE.JPG",3634,2718],["j:5/54/%E7%8E%89%E5%89%8D%E7%A5%9E%E7%A4%BE_%E5%A2%83%E5%86%85%E7%A4%BE%E4%B8%89%E5%B3%AF%E7%A5%9E%E7%A4%BE.JPG",3616,2692],["c:4/4f/Tamasaki-jinja_Kaguraden.jpg",2352,1568]]},{"id":"12_awa_jinja","n":"安房神社（安房国一之宮）","yomi":"あわじんじゃ","cat":"寺社","y":807,"era":["nara","heian"],"sh":"","rank":"A","ad":"館山市大神宮","st":"JR内房線 館山駅からバスで約20分 «安房神社前» 下車","la":34.9128,"lo":139.8373,"hook":"四国の «阿波» から海をわたってきた人びとが、房総に «安房» の名をつけた。","lead":"«安房神社» は、房総半島の南のはしにある、安房国の一之宮です。平安時代の書物『古語拾遺』には、四国の阿波国の人びとがこの地に移り住み、麻を植えたと書かれています。«安房» という名前も、«上総»«下総» の «総（ふさ）» も、このお話とつながっています。","story":["807年、朝廷の祭りを担当する «斎部（忌部）広成» が、『古語拾遺』という書物を朝廷に差し出しました。そこには、こんな話が書かれています。«天富命（あめのとみのみこと）が、阿波の忌部の人びとを連れて東の地に向かい、よい土地をもとめて麻や穀（かじ）を植えた»。","«麻がよく育った» ——麻のことを昔は «総（ふさ）» ともいいました。そこでこの地は «総国（ふさのくに）»、のちに «上総»«下総» とよばれるようになった、と伝えられます。そして阿波の人びとが住んだ場所は、ふるさとの名をとって «安房» になったというのです。","天富命は、ここに祖先の神 «天太玉命（あめのふとだまのみこと）» をまつりました。それが安房神社の始まりとされます。天太玉命は、天の岩戸の神話で活躍した神。神社の «上の宮» にまつられています。","昭和のはじめ、境内で井戸を掘っていたところ、洞窟の中から古い時代の人の骨や、貝でつくった腕輪などが見つかりました。«ここには、ずっと昔から人びとが祈りをささげていたのでは？» ——神話の時代と考古学の発見が、ふしぎに重なる場所です。","深い森に囲まれた境内は、しんと静まりかえっています。本殿の奥に広がる山と、ふりそそぐ木もれ日。遠い昔、海をわたってやってきた人びとの思いが、今もここに息づいているようです。"],"tl":[["神話の時代","天富命が天太玉命をまつったと伝わる"],["807年","斎部広成が『古語拾遺』を撰上し、この由来を記す"],["927年","『延喜式』神名帳に名神大社として記される"],["中世","安房国一之宮として里見氏などの崇敬を受ける"],["1871年","近代社格制度で官幣大社に"],["1932年","境内の洞窟から人骨などが見つかる"]],"who":[["天太玉命","上の宮にまつられる神。忌部氏の祖とされる"],["天富命","天太玉命の孫とされ、阿波の忌部をひきいて房総をひらいたと伝わる"],["斎部広成","『古語拾遺』を著した平安初期の官人"],["里見氏","戦国時代の安房の大名。社を保護した"]],"deep":["『古語拾遺』は、中臣氏との勢力争いの中で、斎部氏が自分たちの由緒を主張するために書いた書物ともいわれます。記事の内容はそうした背景も考えて読む必要があります。","«安房» が «阿波» に由来するという話は『古語拾遺』の伝えによるもので、地名の由来としては諸説があります。","洞窟から見つかった人骨は境内の «忌部塚» にまつられていると伝わり、毎年祭りが行われています。","«総（ふさ）» を麻とする説は『古語拾遺』の話にもとづくもので、«総» の語源にはほかの説もあります。","安房国の一之宮については、安房神社とする説と、洲崎神社とする説があり、どちらも一之宮を名のっています。","下の宮には天富命と、その祖先の天忍日命がまつられ、上の宮・下の宮の二社で一つの神社を形づくっています。"],"look":["上の宮（本殿）","下の宮","洞窟遺跡のあった場所と忌部塚","境内の厳島社のある池と森"],"q":["«安房» の名前は、どこの国の人びとが移り住んだことに由来すると伝わる？","四国の «阿波» 国。『古語拾遺』に、阿波の忌部が房総をひらいた話が書かれています。"],"myth":"阿波の忌部による開拓と地名由来は『古語拾遺』の伝え。一之宮は洲崎神社と両説。洞窟遺跡の年代は資料で確認を。","img":["古語拾遺","天太玉命","忌部氏","安房国"],"wp":"安房神社","rel":{"ev":[],"grave":[]},"ph":[["c:f/f4/Awa-jinja%2C_haiden2.jpg",3168,2274,"安房神社"],["c:7/72/Tsurugaya-hachimangu%2C_haiden_and_yohaijo.JPG",6016,4000],["c:9/9d/Awa-jinja%2C_shaden.JPG",6016,4000],["c:a/a9/Awa-jinja%2C_okariya.JPG",6016,4000],["c:3/35/Awa-jinja%2C_ni-no-torii.JPG",6010,3992],["c:c/c5/Awa-jinja%2C_keidai.JPG",6016,4000],["c:a/a9/Awa-jinja%2C_ichi-no-torii.JPG",5529,3675],["c:e/e2/Awa-jinja%2C_honden.JPG",6016,4000]]},{"id":"12_suzaki_jinja","n":"洲崎神社（頼朝が祈った岬の社）","yomi":"すのさきじんじゃ","cat":"寺社","y":1180,"era":["kamakura","edo"],"sh":"","rank":"A","ad":"館山市洲崎","st":"JR内房線 館山駅からバスで約30分 «洲崎神社前» 下車","la":34.9717,"lo":139.7697,"hook":"戦いに敗れた若き源頼朝が、海をわたって最初にすがった岬の神。","lead":"«洲崎神社（すのさきじんじゃ）» は、房総半島の南西のはし、東京湾の入り口の岬にある神社です。1180年、石橋山の戦いに敗れて安房にのがれた «源頼朝» が、ここに参拝して再起を祈りました。海辺の鳥居の向こうに、晴れた日は富士山が見えます。","story":["1180年8月、伊豆で兵をあげた源頼朝は、相模の石橋山の戦いで平家方に大敗します。命からがら真鶴から船を出し、東京湾をわたって安房へ。«もう後がない»——そんな若き頼朝がたよったのが、この岬の神、洲崎明神でした。","鎌倉幕府の記録『吾妻鏡』には、頼朝が洲崎明神に参り、願いがかなえば神領を寄進すると約束したことが書かれています。その後、頼朝は房総の武士たちを味方につけ、あっという間に大軍となって鎌倉へ。«あの岬での祈りが、すべての始まりだった»のかもしれません。","神社は «御手洗山» という小さな山の中腹にあり、長い石段をのぼると社殿があります。一方、海辺には «浜鳥居»。ここからは東京湾の向こうに三浦半島、晴れた日には富士山が見え、夕日の名所になっています。","岬は東京湾の入り口。江戸時代の終わり、外国船が現れるようになると、江戸湾を守るためにこのあたりに砲台などの備えが置かれました。海の守りの神は、国の守りの最前線にもなったのです。","洲崎には、古い形を伝える «洲崎踊り» という踊りが伝わっています。祈りと踊りと海の風。千年以上、人びとはこの岬で海の安全を願ってきました。","頼朝がのちに鎌倉で幕府を開くことができたのは、安房・上総・下総の武士たちが味方になったからでした。千葉常胤や上総広常といった大きな力をもつ武士が加わり、頼朝の軍はふくれ上がります。その出発点が、この安房の岬だったのです。"],"tl":[["古代","創建（年代ははっきりしない）"],["927年","『延喜式』神名帳に «后神天比理乃咩命神社» として記されるとされる"],["1180年","源頼朝が参拝し、再起を祈る（『吾妻鏡』）"],["江戸時代後期","江戸湾防備のための備えがこの岬周辺に置かれる"],["現在","浜鳥居が夕日と富士山の名所に"]],"who":[["天比理乃咩命","まつられている女神。天太玉命の后とされる"],["源頼朝","石橋山の敗戦後に参拝し、再起を祈った"],["千葉常胤","頼朝を迎えた下総の武士"]],"deep":["『延喜式』神名帳の «后神天比理乃咩命神社» が洲崎神社にあたるとされていますが、近くの洲宮神社をこれにあてる説もあり、比定には諸説があります。","安房国の一之宮は、洲崎神社とする説と安房神社とする説があります。","頼朝が上陸した場所は、鋸南町の «竜島（猟島）» とされ、上陸地の碑があります。洲崎神社参拝はその後のことです。","浜鳥居は、神が海からやってくる入り口として海に向けて立てられています。海の彼方からの来訪神の信仰を思わせます。","江戸時代の後期には、江戸湾の防備として白河藩（松平定信）が房総側の警備を任され、洲崎周辺にも拠点が設けられたといわれます。"],"look":["御手洗山の石段と社殿","浜鳥居（夕日と富士山）","神社周辺の海岸の岩場","近くの洲崎灯台","海岸の «頼朝上陸伝説» にまつわる案内（竜島は鋸南町）"],"q":["1180年、石橋山の戦いに敗れた頼朝が安房で参拝したのは何という神社？","洲崎明神（洲崎神社）。『吾妻鏡』に参拝の記事があります。"],"myth":"延喜式の比定・一之宮は諸説。江戸湾防備施設の位置の詳細は資料で確認を。","img":["源頼朝","石橋山の戦い","吾妻鏡","洲崎灯台"],"wp":"洲崎神社","rel":{"ev":[],"grave":[]},"ph":[["c:4/47/Susaki-jinja_%28Tateyama%29%2C_haiden-1.jpg",5568,3712,"洲崎神社"],["c:8/87/Susaki-jinja_%28Tateyama%29%2C_shinseki.jpg",5568,3712],["c:7/7c/Susaki-jinja_%28Tateyama%29%2C_shinmon.jpg",5568,3712],["c:7/7a/Susaki-jinja_%28Tateyama%29%2C_otorii.jpg",5562,3702],["c:a/ab/Susaki-jinja_%28Tateyama%29%2C_keidaisha-2.jpg",5568,3712],["c:8/8d/Susaki-jinja_%28Tateyama%29%2C_keidaisha-1.jpg",5568,3712],["c:b/b1/Susaki-jinja_%28Tateyama%29%2C_honden.jpg",5544,3676],["c:b/b1/Susaki-jinja_%28Tateyama%29%2C_hamatorii.jpg",5568,3712]]},{"id":"12_tanjoji","n":"誕生寺（日蓮誕生の地）","yomi":"たんじょうじ","cat":"寺社","y":1276,"era":["kamakura","edo"],"sh":"","rank":"A","ad":"鴨川市小湊","st":"JR外房線 安房小湊駅から歩いて約20分。バスもある","la":35.1225,"lo":140.1906,"hook":"日蓮が生まれたとき、海に鯛が群れ、浜に蓮の花が咲いた——と伝わる漁村の寺。","lead":"«誕生寺» は、日蓮が生まれた場所に建てられたお寺です。日蓮は1222年、この小湊の漁村で生まれました。寺の前の海 «鯛の浦» には、今も鯛が群れていて、国の特別天然記念物になっています。","story":["1222年、安房の小湊。海辺の小さな村で、一人の男の子が生まれました。のちの日蓮です。日蓮は後に、自分のことを «海辺の漁師の子» と、ほこりをもって書いています。えらい家の生まれではない——それが、ふつうの人びとに向き合う日蓮の教えの原点になったのかもしれません。","日蓮の誕生には、ふしぎな話が伝わります。庭に清らかな泉がわき、浜には季節はずれの蓮の花が咲き、海には鯛が群れ集まった——«三奇瑞（さんきずい）» とよばれる伝説です。","日蓮が亡くなってまもない1276年、弟子の «日家» が日蓮の生家の跡に寺を建てた、と寺は伝えます。ところがその場所は、のちの大地震と津波で海にしずんでしまったといわれます。«誕生の地が海の底に？» ——寺は場所を移して再建され、今の地で信仰を受けついできました。","大きな仁王門をくぐると、広い境内の奥に祖師堂がそびえます。江戸時代には、多くの信者の寄進で立派な伽藍が整いました。","寺のすぐ前の海は «鯛の浦»。ふつう深い海にすむマダイが、浅い海面近くに群れるめずらしい場所で、遊覧船から見ることができます。鯛は日蓮の生まれ変わり、とも伝えられ、昔からこの浦で鯛をとることは禁じられてきました。","日蓮はのちに、ふるさとのことを何度も手紙に書いています。«あの浜で育った自分だからこそ、苦しむ人びとの気持ちがわかる»——そんな思いがあったのかもしれません。安房小湊の海と空は、今も日蓮の原風景として、多くの信者をひきつけています。"],"tl":[["1222年","日蓮がこの地で誕生"],["1276年","日家が日蓮の生家跡に寺を開いたと伝わる"],["1498年","明応地震。寺地に被害があったと伝わる"],["1703年","元禄地震と津波で大きな被害を受けたと伝わる"],["江戸時代中期","仁王門・祖師堂などが再建される"],["昭和","鯛の浦のタイ生息地が国の特別天然記念物に"]],"who":[["日蓮","この地で生まれた。日蓮宗の宗祖"],["日家","寺を開いたと伝わる日蓮の弟子"],["小湊の漁民","日蓮の生まれ育った村の人びと"]],"deep":["日蓮の誕生日は «貞応元年2月16日» とされ、この日に «御誕生会» が営まれます。","«三奇瑞» の伝説（泉・蓮華・鯛）は後世の伝記に語られるもので、史実というより信仰の物語です。","鯛の浦（«鯛の浦タイ生息地»）は、マダイが浅い海に群れる珍しい生態で国の特別天然記念物。昔から禁漁とされてきたと伝わります。","最初の寺地は、地震や津波で海中に没したといわれ、今の寺地は移転後の場所です。","日蓮の出自については «漁師の子» とする自身の記述のほか、武士の家系とする後世の伝記もあり、諸説があります。","誕生寺は日蓮宗の大本山で、日蓮の誕生・得度・立教開宗・入滅の地などを結ぶ «日蓮聖人の霊跡» のひとつとして巡礼の目的地になっています。"],"look":["仁王門","祖師堂","誕生水の井戸","鯛の浦遊覧船（寺の前の海）"],"q":["日蓮の誕生にまつわる «三奇瑞» とは、泉と蓮の花とあと一つは？","鯛。海に鯛が群れ集まったと伝わり、今も «鯛の浦» の名が残ります。"],"myth":"三奇瑞・日家の開山・旧寺地の水没は伝承。日蓮の出自は諸説。","img":["日蓮","鯛の浦","日蓮宗","小湊"],"wp":"誕生寺 (鴨川市)","rel":{"ev":[],"grave":[]},"ph":[["c:3/32/Soshidou_in_Tanjoji.jpg",2048,1536,"誕生寺 (鴨川市)"],["c:6/66/Tanjoji_miei_tainai.jpg",2616,1932],["c:7/73/TANJO-DO_in_TANJOJI.jpg",1280,960],["c:7/75/RYUOU-DO.jpg",1280,960],["c:e/e0/OTA-DO.jpg",1280,960],["c:b/b9/Gate_of_Niou_in_Tanjoji.jpg",1280,960],["c:4/4a/HONSHI-DEN-HOTO_in_TANJOJI.jpg",1280,721],["c:6/62/SO-MON_in_TANJOJI.jpg",1024,768]]},{"id":"12_shimousa_kokubunji","n":"下総国分寺跡","yomi":"しもうさこくぶんじあと","cat":"遺跡","y":750,"era":["nara"],"sh":"国指定史跡","rank":"A","ad":"市川市国分3丁目","st":"JR総武線 市川駅または京成本線 国府台駅からバスで «国分» 付近下車、歩いて数分","la":35.7478,"lo":139.9205,"hook":"下総の国府のすぐそばに、奈良の法隆寺と同じ並びの伽藍が建っていた。","lead":"«下総国分寺跡» は、奈良時代に聖武天皇の命で建てられた下総国の国分寺のあとです。金堂と塔が左右に並ぶ «法隆寺式» の配置だったことがわかっています。近くには国分尼寺の跡もあり、どちらも国の史跡です。","story":["奈良時代、下総国の国府は、いまの市川市の国府台にありました。国分寺は、その北東の台地に建てられます。都から来た役人が暮らす国府と、国を守る寺——二つは «地方の都» の両輪でした。","発掘によって、金堂と塔が東西に並び、その後ろに講堂があったことがわかりました。これは奈良の «法隆寺» と同じ並べ方です。«なぜ下総で法隆寺式？» ——全国の国分寺の多くは別の配置なので、下総国分寺はめずらしい例として注目されています。","屋根をかざった瓦には、花のもようを大きくあしらった «宝相華文（ほうそうげもん）» の瓦が使われていました。下総国分寺を代表する美しい瓦で、ほかではあまり見られないものです。","いまの国分寺の境内には、塔の土台（基壇）のあとなどが残り、古い礎石も見られます。現在の寺の本堂は、かつての伽藍があったあたりに建っています。千年以上の時をへだてて、同じ場所で祈りが続いているのです。","北に少し歩くと、国分尼寺の跡もあります。こちらは広場として整備され、建物の位置が示されています。近くの市立考古博物館とあわせて歩くと、古代の下総がぐっと身近になります。","国分寺と国府のある国府台は、東京湾に注ぐ川の水運と、東へのびる古代の道が交わる場所でした。都からの命令や、税として納められる品々がここに集まり、下総の国じゅうへ広がっていったのです。国分寺の塔は、そうした «国の中心» のしるしとして、遠くからも見えたことでしょう。"],"tl":[["741年","聖武天皇が国分寺建立の詔を出す"],["8世紀中ごろ","下総国分寺・国分尼寺が建てられる"],["平安時代","しだいに衰える"],["昭和","発掘調査で法隆寺式の伽藍配置が判明"],["現在","国分寺跡・国分尼寺跡ともに国指定史跡"]],"who":[["聖武天皇","国分寺建立の詔を出した"],["下総国司","国府にいて、国分寺の建設・運営を担った"]],"deep":["全国の国分寺は «東大寺式» や «国分寺式» など、金堂と塔が南北に並ぶものが多く、東西に並ぶ «法隆寺式» の下総国分寺はめずらしい例です。","«宝相華文軒丸瓦» は、中心に大きな花のもようを配した瓦で、下総国分寺の象徴として知られます。","下総国府は国府台（いまの和洋女子大学付近）にあったと考えられ、国分寺はそこから歩ける距離にあります。国府と国分寺の位置関係がわかる例です。","国分尼寺跡では、金堂や講堂のあとが見つかり、史跡公園として整備されています。","周辺には縄文時代の «堀之内貝塚»（国指定史跡）もあり、市川市立考古博物館で縄文から古代までの出土品を見ることができます。","下総国は、いまの千葉県北部と茨城県南西部、東京都・埼玉県の一部にまたがる大きな国でした。その国の «宗教の中心» が、この市川の台地にあったのです。"],"look":["国分寺境内の塔跡（基壇）と礎石","国分尼寺跡の史跡公園","市川市立考古博物館の瓦展示","国府台の台地の地形"],"q":["下総国分寺の伽藍は、奈良のどの寺と同じ配置だった？","法隆寺。金堂と塔が東西に並ぶ «法隆寺式» です。"],"myth":"建物の位置や規模の詳細は発掘成果により更新されることがある。","img":["国分寺","下総国","法隆寺","堀之内貝塚"],"wp":"下総国分寺","rel":{"ev":[],"grave":[]},"ph":[["c:0/08/Shimosa-kokubunji_nandaimon-2.jpg",5200,3434,"下総国分寺"],["c:d/d1/Shimosa-kokubunniji-ato_tou-soseki.jpg",6016,4000],["c:3/35/Shimosa-kokubunniji-ato_koudou-2.jpg",6016,4000],["c:6/67/Shimosa-kokubunniji-ato_kondou-2.jpg",6016,4000],["c:4/4b/Shimosa-kokubunji-ato_tou-2.jpg",6008,3988],["c:2/22/Shimosa-kokubunji-ato_koudou-2.jpg",5960,3912],["c:8/81/Shimosa-kokubunji-ato_hondou-2.jpg",6004,3984],["c:d/d5/Kitashita-kawaragama-ato_zenkei.jpg",6016,4000]]},{"id":"12_nagoji","n":"那古寺（坂東三十三観音の結願所）","yomi":"なごじ","cat":"寺社","y":717,"era":["nara","kamakura","edo"],"sh":"国の重要文化財（銅造千手観音立像）","rank":"A","ad":"館山市那古","st":"JR内房線 那古船形駅から歩いて約15分","la":34.999,"lo":139.841,"hook":"関東を巡る33の観音霊場、その «最後のゴール» は館山湾を見わたすこの寺。","lead":"«那古寺（なごじ）» は、奈良時代に僧 «行基» が開いたと伝わる古いお寺です。関東一円の33の観音霊場をめぐる «坂東三十三観音» の最後の寺（結願寺）で、長い巡礼を終えた人びとがここにたどりつきます。境内からは館山湾が一望できます。","story":["717年、元正天皇が重い病にかかったとき、«行基» がこの地で祈り、観音像をまつった——寺はこう伝えています。海から引き上げた木で観音さまを彫ったともいわれ、海とのつながりを感じさせる由来です。","鎌倉時代、源頼朝が関東の観音霊場をまとめ、«坂東三十三観音» の巡礼が生まれたといわれます。鎌倉の杉本寺から始まり、関東をぐるりとまわって、最後にたどりつくのが那古寺。«やっと結願した»——ここで巡礼の人びとは、長い旅の疲れと安らぎを同時に味わいました。","那古寺は、頼朝や足利尊氏、そして戦国時代の里見氏など、時の実力者たちに大切にされてきました。里見氏は安房の大名として、寺を保護したと伝わります。","1703年の元禄地震では、房総半島南部は大きな被害を受け、那古寺も建物の多くを失いました。いまの観音堂や多宝塔は、そのあと江戸時代の中ごろに再建されたものです。«地震からの復興» の証でもあるのです。","寺宝の «銅造千手観音立像» は鎌倉時代の作で、国の重要文化財。石段をのぼって観音堂の前に立つと、目の前に館山湾が広がります。巡礼者たちが見た «結願の海» を、今も同じ場所から見ることができます。","巡礼を終えた人びとは、那古寺で «結願» のお札を受け、ふるさとへ帰っていきました。江戸時代には多くの庶民が坂東巡礼に出かけ、那古寺の門前は宿や茶屋でにぎわったといわれます。長い旅の終わりに見る館山湾は、どんなにまぶしく見えたことでしょう。"],"tl":[["717年","行基が開いたと伝わる"],["鎌倉時代","坂東三十三観音の結願寺として信仰を集める"],["戦国時代","里見氏の保護を受けたと伝わる"],["1703年","元禄地震で大きな被害"],["江戸時代中期","観音堂・多宝塔などが再建される"]],"who":[["行基","開山と伝わる奈良時代の僧"],["元正天皇","病気平癒の祈願が寺の始まりと伝わる"],["源頼朝","坂東三十三観音の成立に関わったと伝わる"],["里見氏","安房の戦国大名。寺を保護した"]],"deep":["坂東三十三観音は、西国三十三所にならって鎌倉時代に成立したとされます。第1番は鎌倉の杉本寺、第33番が那古寺です。","銅造千手観音立像は鎌倉時代の作とされ、国の重要文化財。関東で鋳造された金銅仏として貴重です。","多宝塔は江戸時代中期の建築で、千葉県の有形文化財。房総の寺院建築を代表するひとつです。","元禄地震（1703年）は房総半島南部を大きく隆起させ、館山周辺の海岸線も変わったといわれます。那古寺の被害と再建は、その記憶を伝えています。","本尊の千手観音像は、行基が海中から得た霊木で彫ったとする伝説があり、海とつながる信仰の姿を示します。","坂東三十三観音の巡礼の距離は、全部で約1300kmにもなるといわれ、江戸時代の人びとは何十日もかけて歩きました。"],"look":["観音堂","多宝塔","境内から見る館山湾","潮音台（見晴らし台）"],"q":["坂東三十三観音の «最後（第33番）» の寺は？","那古寺。巡礼を終える «結願寺» です。"],"myth":"行基の開山・元正天皇の祈願・頼朝による霊場成立は伝承。","img":["坂東三十三箇所","行基","元禄地震","館山湾"],"wp":"那古寺","rel":{"ev":[],"grave":[]},"ph":[["c:c/c1/%E9%82%A3%E5%8F%A4%E5%AF%BA_-_panoramio_%284%29.jpg",4752,3168,"那古寺"],["c:4/45/%E9%82%A3%E5%8F%A4%E5%AF%BA_-_panoramio.jpg",4752,3168],["c:2/2e/Tateyama_Nago-ji_03.jpg",1500,2000],["c:e/e1/Nagoji-Tateyama.jpg",1024,768],["c:8/8d/Gyouki_1.jpg",400,300,"行基"],["c:a/a8/1703_Genroku_earthquake_intensity.png",512,512,"元禄地震"],["c:6/60/Sunosaki_aerial_photo.jpg",1536,1152,"館山湾"]]},{"id":"12_kasamoridera","n":"笠森観音（四方懸造の観音堂）","yomi":"かさもりでら","cat":"寺社","y":1590,"era":["heian","azuchi"],"sh":"国の重要文化財（観音堂）","rank":"A","ad":"長生郡長南町笠森","st":"JR外房線 茂原駅からバスで約25分 «笠森» 下車。車も便利","la":35.408,"lo":140.2414,"hook":"大きな岩の上に、柱だけで浮かぶように建つお堂——四方すべてを懸造にしたのは日本でここだけ。","lead":"«笠森観音（笠森寺）» は、岩山のてっぺんに建つ観音堂で知られるお寺です。お堂は、岩のまわり四方を長い柱で支える «四方懸造（しほうかけづくり）»。このつくりは日本でここだけといわれ、国の重要文化財になっています。","story":["森の中の長い参道をぬけると、突然、目の前に大きな岩がそびえ、その上に木のお堂がのっています。«どうやって建てたの？» と思わず声が出るほど。たくさんの柱が岩を囲んで立ち上がり、お堂を空中にもち上げているのです。","寺の伝えによると、784年、«最澄（伝教大師）» がこの山で霊木から十一面観音を彫り、まつったのが始まりとされます。のちに «後一条天皇» の命でお堂が建てられた、とも伝わります。","京都の清水寺も «懸造» ですが、あちらは崖の片側だけ。笠森観音は岩の «四方» すべてを柱で支えています。«なぜこんな形に？» ——岩そのものを神聖なものとして大切にし、その上に観音さまをまつったからだと考えられています。","いまのお堂は、安土桃山時代ごろに建てられたとされます。75段の階段をのぼって回廊に出ると、房総の山なみが一望でき、まるで空中に立っているような気分になります。","境内の森は «笠森寺自然林» として国の天然記念物。うっそうとした木々に囲まれ、昔から巡礼者たちがここで一息ついてきました。坂東三十三観音の第31番の札所でもあります。","江戸時代、坂東巡礼の人びとはこの岩山のお堂を見上げ、«ここまで来た» と手を合わせました。回廊をぐるりと一周すると、木の床がきしむ音とともに、四方の森が視界いっぱいに広がります。何百年も前の大工たちは、どうやってこの岩の上に柱を立てたのか——考えるだけで胸が高鳴ります。"],"tl":[["784年","最澄が開いたと伝わる"],["1028年","後一条天皇の勅願でお堂が建てられたと伝わる"],["安土桃山時代ごろ","現在の観音堂が建てられたとされる"],["江戸時代","坂東三十三観音第31番として巡礼者でにぎわう"],["昭和","観音堂の解体修理が行われる"]],"who":[["最澄","開山と伝わる平安時代の僧。天台宗の開祖"],["後一条天皇","お堂を建てさせたと伝わる天皇"],["巡礼者たち","坂東三十三観音をめぐる人びと"]],"deep":["«四方懸造» は、岩の四方すべてを柱で支える構造で、日本で唯一の例とされています。","観音堂の建築年代は、解体修理の際に見つかった資料などから安土桃山時代ごろと考えられています（年代には諸説）。","境内の «子授け楠» は、木の根元のすき間をくぐると子どもを授かるといわれ、信仰を集めています。","«笠森寺自然林» は国の天然記念物で、スダジイやタブノキなどの常緑樹が茂る、房総の原生的な森が残されています。","江戸の谷中にあった笠森稲荷の茶屋娘 «笠森お仙» は、鈴木春信の浮世絵で大人気になりました。«笠森» の名と長南の笠森観音とのつながりについては、はっきりしたことはわかっていません。","懸造は、崖や岩の上に長い柱を立てて床を支える建築法で、京都の清水寺の «舞台» や鳥取の三徳山三佛寺投入堂などが有名です。"],"look":["四方懸造の観音堂（下から見上げる）","75段の階段と回廊からの眺め","子授け楠","笠森寺自然林の参道"],"q":["笠森観音の観音堂のつくり方を何という？","«四方懸造»。岩の四方を柱で支えるつくりで、日本唯一とされます。"],"myth":"最澄の開山・後一条天皇の勅願は寺伝。観音堂の建築年代は諸説。","img":["懸造","坂東三十三箇所","最澄","長南町"],"wp":"笠森寺","rel":{"ev":[],"grave":[]},"ph":[["c:8/8c/Daihizan_Kasamoriji_Temple_12.jpg",6000,4000,"笠森寺"],["c:5/50/Kasamoriji%2C_kakezukuri.jpg",4032,3024],["c:9/9c/Daihizan_Kasamoriji_Temple_09.jpg",6000,4000],["c:d/db/Daihizan_Kasamoriji_Temple_05.jpg",6000,4000],["c:4/43/Daihizan_Kasamoriji_Temple_02.jpg",6000,4000],["c:8/85/NDL-DC_1307518_005_1309801_KazusaKasamoriji_crd.jpg",2825,4402],["c:f/f7/Haiden-kakezukuri.jpg",4032,3024,"懸造"],["c:b/b8/%E6%9C%80%E6%BE%84%E5%83%8F_%E4%B8%80%E4%B9%97%E5%AF%BA%E8%94%B5_%E5%B9%B3%E5%AE%89%E6%99%82%E4%BB%A3.jpg",1828,3013,"最澄"]]},{"id":"12_iidaka_danrin","n":"飯高寺（飯高檀林・日蓮宗の学問所）","yomi":"はんこうじ（いいだかだんりん）","cat":"学び","y":1580,"era":["azuchi","edo"],"sh":"国の重要文化財（講堂・鐘楼・鼓楼・総門）","rank":"A","ad":"匝瑳市飯高","st":"JR総武本線 八日市場駅からタクシーで約15分。車が便利","la":35.73,"lo":140.536,"hook":"杉木立の奥に、江戸時代の «お坊さんの大学» がまるごと残っている。","lead":"«飯高寺（はんこうじ）» には、江戸時代に日蓮宗の僧が学んだ «飯高檀林（いいだかだんりん）» の建物が残っています。檀林とは、僧が長い年月をかけて学ぶ学問所のこと。飯高檀林は日蓮宗の檀林の中でも最も古く大きなもののひとつで、今の立正大学のルーツとされています。","story":["深い杉林の坂道をのぼっていくと、大きな茅ぶき屋根の講堂が現れます。ここはかつて、全国から若い僧たちが集まった «学問の寺»。静かな森に、経典を読む声がひびいていたはずです。","飯高檀林は、戦国時代の終わりごろ、1580年に開かれたといわれます。のちに徳川家康の側室で熱心な日蓮宗信者だった «養珠院（お万の方）» の支えも受け、大きく発展しました。«学問なくして信仰なし» ——僧たちは何年も、何十年もかけて仏教の教えを学びました。","檀林での学びは段階ごとに分かれ、一つずつ進んでいく仕組みでした。«まるで今の大学の学年みたい» ——実際、飯高檀林は日本の大学の源流のひとつとも言われます。","明治になると、学校のしくみが変わり、1874年に飯高檀林は閉じられます。しかしその学びは東京に受けつがれ、いまの立正大学へとつながりました。","講堂・鐘楼・鼓楼・総門は国の重要文化財。人の少ない森の中にたたずむ建物群は、ときが止まったかのよう。訪れる人は、江戸の学僧たちの足音を想像しながら、ゆっくり境内を歩きます。","なぜこんな森の奥に学校を？ 町のにぎわいから離れた静かな場所は、学問に打ちこむのにぴったりでした。学僧たちは寮で共に暮らし、朝から晩まで経典を読み、議論を重ねたといいます。ここで学んだ僧たちが全国の寺に散らばり、日蓮宗の教えを広めていきました。"],"tl":[["1580年","飯高檀林が開かれたといわれる"],["江戸時代初期","養珠院（お万の方）らの支援で発展"],["江戸時代","日蓮宗の中心的な学問所として多くの学僧を輩出"],["1874年","檀林が閉じられる"],["現在","講堂・鐘楼・鼓楼・総門が国の重要文化財"]],"who":[["教蔵院日生","檀林を開いたと伝わる僧"],["養珠院（お万の方）","徳川家康の側室。日蓮宗を厚く信仰し、檀林を支えた"],["徳川家康","檀林の保護に関わったと伝わる"],["学僧たち","全国から集まり、長い年月をかけて学んだ"]],"deep":["«檀林» は «栴檀林（せんだんりん）» の略で、学問所を香りのよい栴檀の林にたとえた言葉です。","日蓮宗には関東を中心に多くの檀林がありましたが、飯高檀林はその中でも最古・最大級とされ、«総本山» 的な位置づけでした。","立正大学は、飯高檀林の開設（1580年）を大学の起源としています。","講堂は大きな茅ぶき屋根をもつ建物で、江戸時代の学問所の姿を伝える貴重な遺構です。","養珠院は、紀州藩主・徳川頼宣や水戸藩主・徳川頼房の母で、日蓮宗の寺々を保護したことで知られます。","飯高檀林の建物のうち講堂は、江戸時代前期の建築とされ、大きな空間で多くの学僧が講義を聞いた当時のようすを想像させます。境内の杉並木も見事です。","檀林で学ぶ期間はとても長く、すべての課程を終えるには数十年かかったともいわれます。"],"look":["茅ぶき屋根の講堂","鐘楼と鼓楼","総門","杉木立の参道","境内の案内板で学僧の暮らした寮（学寮）の配置を確認"],"q":["飯高檀林を起源とする、いまの東京の大学は？","立正大学。1580年の飯高檀林の開設を起源としています。"],"myth":"開設年・開設者には諸説。家康の関与は伝承を含む。","img":["檀林","立正大学","養珠院","日蓮宗"],"wp":"飯高寺","rel":{"ev":[],"grave":[]},"ph":[["c:0/0e/Iidaka.jpg",987,735,"飯高寺"],["c:9/9f/Soumon.SosaCity.Chiba.jpg",2048,1536],["c:6/60/Iidaka2.jpg",1000,750],["c:1/1a/Hankouji-syourou.SosaCity.Chiba.jpg",480,640],["c:a/ab/Hankouji-korou.SosaCity.Chiba.jpg",480,640],["c:2/2d/Hankouji-issaikyouzou.SosaCity.Chiba.jpg",640,480],["c:6/64/Hankouji-daimokudou.SosaCity.Chiba.jpg",640,480],["c:c/ce/Kichijoji_gate_plate.jpg",3442,2304,"檀林"]]},{"id":"12_nihonji","n":"鋸山 日本寺（羅漢と大仏）","yomi":"のこぎりやまにほんじ","cat":"寺社","y":1783,"era":["nara","edo"],"sh":"","rank":"A","ad":"安房郡鋸南町元名","st":"JR内房線 浜金谷駅から歩いてロープウェー山麓駅へ（約10分）、山頂駅から境内へ。JR保田駅からも歩ける","la":35.1592,"lo":139.8358,"hook":"江戸の石工が、山肌に1500体の羅漢と日本最大級の大仏を彫った。","lead":"«日本寺» は、鋸山の斜面いっぱいに広がるお寺です。奈良時代に開かれたと伝わり、江戸時代には石工 «大野甚五郎» と弟子たちが、千五百羅漢と高さ約31mの大仏を岩山に彫り上げました。断崖から身をのり出す «地獄のぞき» も有名です。","story":["寺の伝えでは、725年、聖武天皇の命で «行基» がこの山に寺を開いたとされます。«日本寺» という大きな名前は、そのころの格式を物語っているのかもしれません。","江戸時代の中ごろ、この寺に一人の石工がやってきます。«大野甚五郎英令（ひでよし）»。彼は弟子たちとともに、山の岩肌に羅漢さまを一体一体彫っていきました。その数、千五百あまり。21年がかりの大仕事だったといわれます。","羅漢像は、笑う者、考えこむ者、居眠りする者……表情はさまざまです。«会いたい人に似た羅漢が必ずいる» といわれ、道ばたにたたずむ小さな顔を一つずつ見ていくと、時間を忘れてしまいます。","甚五郎たちはさらに、山の岩を彫って巨大な大仏も完成させました。高さ約31m、奈良の大仏よりも大きな石の大仏です。ところが明治のはじめの «廃仏毀釈» で、羅漢の多くが首を落とされ、長い年月で大仏も傷みました。いまの大仏は1969年に修復されたものです。","山の上には、切り立った崖が空に突き出す «地獄のぞき»。そのすぐそばには、昭和に彫られた «百尺観音» も立ちます。石を切り出した山が、そのまま祈りの山になった——それが鋸山の日本寺なのです。","羅漢の道を歩いていると、首のない羅漢や、首をつなぎなおした羅漢に出会います。明治のはじめ、神と仏を分ける政策の中で、仏像が壊される出来事が各地で起きました。修復された顔を見ていると、壊されても守りつづけた人びとの思いが伝わってきます。"],"tl":[["725年","行基が開いたと伝わる"],["1779年","大野甚五郎が羅漢の制作を始めたとされる"],["1783年","大仏が完成したとされる"],["1798年","千五百羅漢がほぼ完成したとされる"],["明治初め","廃仏毀釈で羅漢の多くが傷つけられる"],["1939年","火災で多くの建物を失う"],["1969年","大仏が修復される"]],"who":[["行基","開山と伝わる奈良時代の僧"],["大野甚五郎英令","千五百羅漢と大仏を彫った江戸時代の石工"],["甚五郎の弟子たち","師とともに長い年月をかけて石仏を彫った"]],"deep":["大仏（薬師瑠璃光如来）は高さ約31mで、石の大仏としては日本最大級。像高は奈良の大仏（約15m）の2倍ほどです。","千五百羅漢は、正確には1553体とされることもあり、数え方には幅があります。","廃仏毀釈で首を落とされた羅漢は、のちに修復されたものも多いですが、首のつなぎ目が残るものもあり、近代の宗教政策の爪あとを伝えています。","«百尺観音» は昭和に6年ほどかけて彫られ、戦争や交通事故で亡くなった人びとの供養のためにつくられたといわれます。","日本寺は宗派が何度か変わり、いまは曹洞宗の寺です。","日本寺の境内は広大で、山頂から山腹まで高低差が大きく、見学には2時間ほどみておくと安心です。拝観料が必要です。"],"look":["地獄のぞき","大仏（薬師瑠璃光如来）","千五百羅漢の道","百尺観音","山頂展望台からの東京湾と富士山"],"q":["日本寺の千五百羅漢と大仏を彫った江戸時代の石工は？","大野甚五郎英令。弟子たちと21年がかりで羅漢を彫ったといわれます。"],"myth":"行基開山は寺伝。羅漢の数・制作年は資料により差がある。","img":["鋸山","廃仏毀釈","羅漢","行基"],"wp":"日本寺","rel":{"ev":[],"grave":[]},"ph":[["c:8/8d/Gyouki_1.jpg",400,300,"行基"],["c:3/35/The_port_of_Kanaya.jpg",800,458,"近く: 鋸山 (千葉県)"],["c:a/ac/Nokogiriyama_Tozan_Jidoushado.JPG",2272,1704,"近く: 鋸山登山自動車道"],["c:8/82/Futtsu-Kanaya_IC_202301.jpg",3360,2520,"近く: 富津金谷インターチェンジ"],["c:c/cf/View_of_Nokogiriyama_Ropeway%2C_crossing.jpg",3072,2304,"近く: 鋸山ロープウェー"]]},{"id":"12_nokogiriyama","n":"鋸山の石切場跡（房州石）","yomi":"のこぎりやまのいしきりばあと","cat":"産業","y":1800,"era":["edo","meiji","showa"],"sh":"","rank":"A","ad":"富津市金谷・安房郡鋸南町","st":"JR内房線 浜金谷駅から鋸山ロープウェーで山頂へ。登山道 «車力道» は歩いて約1時間","la":35.1586,"lo":139.8347,"hook":"山がノコギリの歯の形になったのは、人が石を切り出し続けたから。","lead":"«鋸山（のこぎりやま）» は、房総半島の東京湾側にある標高約330mの山です。ここでは江戸時代から昭和まで «房州石» とよばれる石が切り出され、江戸・東京の町づくりに使われました。いまも山には、巨大な石切場の跡が残っています。","story":["遠くから見ると、山の稜線がギザギザ。まるでノコギリの歯のようです。«自然にできた形なの？» ——いいえ、その一部は、何百年もの間、人が石を切り出してできた形だといわれます。","ここで切り出された石は «房州石» とよばれました。やわらかくて加工しやすく、火にも強い。江戸の町では、蔵の土台や塀、石垣、港の護岸などに使われ、船で東京湾をわたって運ばれていきました。","切り出した石を山から下ろすのは大仕事でした。石をのせた車を、細い山道でブレーキをかけながら下ろす仕事を «車力（しゃりき）» といい、女性たちも担ったと伝わります。その道がいまも «車力道» として残り、石の上には車の通ったあとの溝が刻まれています。","石切場の跡は、垂直に切り立った岩壁になっています。まっすぐな切り口は、石工たちがノミで少しずつ石を切り出したしるし。見上げると、あまりの大きさに言葉を失います。","採石は昭和の終わりごろまで続き、やがて役目を終えました。いまは登山やハイキングの人気の山になり、石切場跡は «産業遺産» として見直されています。汗を流して石を切った職人たちの仕事が、山そのものの形として残っているのです。","なぜ房州石は江戸でそれほど求められたのでしょう？ 江戸は火事の多い町でした。石の蔵や塀は火をふせぎ、大切な品物を守ります。房州石は、江戸の人びとのくらしを火から守る石でもあったのです。"],"tl":[["江戸時代中期","本格的な採石が始まったとされる"],["江戸時代","房州石が船で江戸へ運ばれ、町づくりに使われる"],["明治〜昭和","近代の港や建物の建材として需要が続く"],["1962年","鋸山ロープウェーが開業"],["昭和の終わりごろ","採石が終わる"]],"who":[["石工たち","ノミで房州石を切り出した職人"],["車力","切り出した石を運び下ろした人びと。女性も担ったと伝わる"],["金谷の人びと","石の積み出し港として町を支えた"]],"deep":["房州石は、凝灰質の砂岩で、やわらかく加工しやすい一方、風化しやすい面もあります。","«車力道» には、石を運ぶ車が何度も通ったことでできた «わだち» のような溝が残っていて、ハイキングで見ることができます。","石切場跡の垂直の壁には、切り出しの段や道具のあとが残り、どのように石を切ったかを読み解く手がかりになります。","鋸山の南側には日本寺があり、石を切った山で石仏が彫られたこととあわせて、«石の山» の歴史を物語っています。","房州石は、横浜や横須賀など東京湾沿岸の近代の建造物にも使われたといわれ、各地で再評価が進んでいます。","鋸山は内房の海岸にせまる山で、金谷港から船で石を積み出すのに都合のよい場所にありました。石切場と港の近さが、この地で採石が栄えた理由のひとつです。"],"look":["石切場跡の巨大な岩壁","車力道の石畳とわだち","山頂展望台からの東京湾","浜金谷の港"],"q":["鋸山で切り出された石は何とよばれた？","«房州石»。江戸・東京の町づくりに使われました。"],"myth":"車力を女性が担った話は伝承を含む。採石の開始・終了年、利用先の具体例は資料で確認を。","img":["日本寺","房州石","金谷 (富津市)"],"wp":"鋸山","rel":{"ev":[],"grave":[]},"ph":[["c:3/35/The_port_of_Kanaya.jpg",800,458,"近く: 鋸山 (千葉県)"],["c:a/ac/Nokogiriyama_Tozan_Jidoushado.JPG",2272,1704,"近く: 鋸山登山自動車道"],["c:8/82/Futtsu-Kanaya_IC_202301.jpg",3360,2520,"近く: 富津金谷インターチェンジ"],["c:c/cf/View_of_Nokogiriyama_Ropeway%2C_crossing.jpg",3072,2304,"近く: 鋸山ロープウェー"]]},{"id":"12_kururi_jo","n":"久留里城（雨城）","yomi":"くるりじょう","cat":"城","rank":"A","y":1542,"era":["muromachi","edo"],"sh":"","ad":"君津市久留里","st":"JR久留里線 久留里駅から歩いて約35分（山道をのぼる）","la":35.2864,"lo":140.0722,"hook":"城ができてから «3日に1度» 雨が降り続いた――そんな言い伝えから «雨城» とよばれる、房総の山あいの城。","lead":"久留里城は、君津市の山の上にある城あとです。戦国時代には安房の里見氏が北条氏と戦う大事な拠点になり、江戸時代には久留里藩の城になりました。いまの天守は昭和につくられた «模擬天守» で、すぐそばに資料館があります。","story":["房総半島のまんなか、小櫃川（おびつがわ）が大きく曲がる谷に、こんもりした山がそびえています。そのてっぺんが久留里城です。城のはじまりは室町時代、上総の «真里谷武田氏» がきずいたといわれますが、くわしい年代は諸説あります。山と川にかこまれたこの場所は、敵が近づきにくい天然の要塞でした。","«雨城» というすてきな別名には、こんな言い伝えがあります。城ができあがったあと、3日に1度の割合で21日間も雨が降り続いた――。雨にけむる山城は、敵から見えにくかったのかもしれません。«雨がこの城を守ってくれる» 。城の人びとは、そう考えたのでしょうか。","戦国時代のなかごろ、この城の主になったのは安房の «里見義堯（よしたか）» でした。里見氏は、関東を広げていく小田原の北条氏と何度もぶつかります。北条軍に攻めこまれても、久留里城は簡単には落ちませんでした。里見氏にとって、ここは «房総を守る最後のとりで» だったのです。","1590年、豊臣秀吉が北条氏をほろぼすと、関東には徳川家康が入ります。久留里城には徳川の家臣が入り、江戸時代には «久留里藩» の城になりました。とちゅう城主が絶えて城が荒れた時期もありましたが、1742年に «黒田直純» が入ると城は立て直され、明治まで黒田氏が治めました。","江戸時代のはじめ、この藩には «新井白石» の父が仕えていました。白石自身も若いころ久留里藩に仕えましたが、藩の内部の争いにまきこまれ、職を失ってしまいます。のちに将軍を支える大学者になる白石にも、そんな苦しい時代があったのです。いま城あとの資料館では、白石の像が出むかえてくれます。"],"tl":[["室町時代","上総の真里谷武田氏が城をきずいたと伝わる（年代は諸説）"],["16世紀なかごろ","里見義堯が久留里城を本拠の一つとし、北条氏と争う"],["1590年","北条氏がほろび、徳川家康の家臣・大須賀忠政が入る"],["1602年","土屋忠直が入り、久留里藩の土屋氏の時代が始まる"],["1679年","土屋氏が改易（取りつぶし）となる"],["1742年","黒田直純が入り、城を立て直す"],["1872年ごろ","明治の廃城で建物が取りこわされる"],["1979年","本丸あとに模擬天守が建てられる"]],"who":[["里見義堯","安房の戦国大名。久留里城を拠点に北条氏と戦った"],["黒田直純","江戸中期に入った久留里藩主。城を再建し、黒田氏は明治まで続いた"],["新井白石","若いころ久留里藩に仕えた。のちに6代将軍家宣を支えた学者"],["土屋利直","白石の父が仕えた久留里藩主"]],"deep":["«雨城» の名の由来は «築城後、3日に1度、21日間雨が降った» という伝承。地元の資料館でも紹介されている。","いまの天守は1979年の模擬天守で、江戸時代の天守の正確な姿はわかっていない。天守台の石積みは、昔の遺構として残るとされる。","久留里は «名水の里» として知られ、自噴する井戸が町なかに多い。城下町と水のつながりを歩いて感じられる。","新井白石の自伝『折たく柴の記』には、久留里藩で過ごした日々や、藩を追われた事情が書かれている。","里見氏と北条氏の争いでは、1560年代に北条方が久留里城にせまったとされる。房総の戦国史を理解するうえで重要な城。","城のある山は、小櫃川の蛇行に守られた天然の要害。空堀や曲輪（くるわ）の形が山のあちこちに残る。"],"look":["本丸の模擬天守と、その横の天守台あと","久留里城址資料館（城と城下町、新井白石の展示）","新井白石の像","山道の途中の空堀・曲輪のあと","ふもとの城下町と自噴井戸"],"q":["久留里城の別名は？","«雨城（うじょう）»。城ができたあと雨が降り続いたという言い伝えから。"],"koji":[],"myth":"«雨城» の由来は伝承。築城者・築城年は諸説あり。","img":["里見義堯","新井白石","久留里藩"],"wp":"久留里城","rel":{"ev":[],"grave":[]},"ph":[["c:8/83/Kururi_Castle_01.JPG",3648,2736,"久留里城"],["c:7/7d/Ch%C3%A2teau_de_Himeji02.jpg",2592,1944],["c:4/47/Otamagaike.JPG",1600,1200],["c:0/00/The_statue_of_Hakuseki_Arai_in_the_garden_of_Kururi_castle%2C_Chiba_pref.%2C_Japan.jpg",1467,1100],["c:c/c5/%E6%97%A5%E6%9C%AC%E3%81%AE%E5%9F%8E%E8%B7%A1.png",971,940],["c:0/04/%E9%87%8C%E8%A6%8B%E7%BE%A9%E5%A0%AF%E6%9C%A8%E5%83%8F.jpg",1055,1200,"里見義堯"],["c:b/bd/Arai_Hakuseki_-_Japanischer_Gelehrter.jpg",1321,1402,"新井白石"]]},{"id":"12_sekiyado_jo","n":"関宿城（利根川水運の要）","yomi":"せきやどじょう","cat":"城","rank":"A","y":1574,"era":["muromachi","edo"],"sh":"","ad":"野田市三軒家（千葉県立関宿城博物館）","st":"東武線の駅からバスで30分ほど（本数が少ない）。車が便利","la":36.0999,"lo":139.7811,"hook":"«この城を取ることは、一国を取るのと同じ» ――北条氏がそう言うほどほしがった、川の十字路の城。","lead":"関宿城は、千葉県のいちばん北の先、利根川と江戸川が分かれるところにあった城です。戦国時代には北条氏がどうしても手に入れたかった城で、江戸時代には川の交通を見張る大事な場所になりました。いま建つ天守は博物館の建物で、城そのものは «跡» です。","story":["地図で千葉県をみると、北のはしがツノのようにとがっています。そこが関宿。利根川と江戸川が分かれる場所です。昔は電車もトラックもありません。重い荷物は、川を船で運ぶのがいちばんでした。つまり関宿は、関東の «水の道» の交差点。ここを押さえた人が、物の流れを押さえたのです。","城をきずいたのは、室町時代に古河公方（こがくぼう）に仕えた «簗田（やなだ）氏» といわれます。戦国時代、関東を広げていく小田原の北条氏は、この城をねらいました。北条氏康は «関宿を取ることは一国を取るのと同じだ» という意味のことを手紙に書いたといわれています。","簗田氏は何度も北条軍をはね返しましたが、1574年、ついに北条氏政の大軍の前に城を明けわたしました。«川を制する者が関東を制す»。北条氏は関宿を手に入れ、関東の支配をさらに強めていきます。","江戸時代、関宿には徳川家康の異父弟・松平康元が入り、その後も徳川家の信頼があつい大名が城主になりました。幕府は関宿に «関所» を置き、江戸へ向かう船を見張りました。なぜでしょう? 江戸を守るためには、川から武器や怪しい人が入ってくるのを防ぐ必要があったのです。","明治になると城は取りこわされ、さらに川の工事で城あとの多くが堤防や河川敷になってしまいました。いまの白い天守は、1995年に開館した千葉県立関宿城博物館の建物で、江戸時代の記録を参考につくられたものです。最上階からは、利根川と江戸川、そして遠くの山々まで見わたせます。"],"tl":[["1457年ごろ","簗田氏が城をきずいたと伝わる"],["1560年代","北条氏が関宿をめぐって簗田氏と争う"],["1574年","北条氏政の攻撃で、簗田氏が城を明けわたす"],["1590年","徳川家康の異父弟・松平康元が入る"],["1654年","利根川を東へ流す工事（利根川東遷）が大きく進む"],["1669年","久世広之が入り、以後、久世氏が明治まで治める"],["1871年","廃藩置県。やがて城は取りこわされる"],["1995年","千葉県立関宿城博物館が開館"]],"who":[["簗田晴助","古河公方に仕えた武将。関宿城を守り、北条氏と戦った"],["北条氏康・氏政","小田原の戦国大名親子。関宿をねらい続けた"],["松平康元","徳川家康の異父弟。江戸時代最初の関宿城主"],["久世広之","老中。久世氏が関宿藩主として明治まで続く"],["鈴木貫太郎","関宿藩士の家に生まれ関宿で育った。終戦時の総理大臣"]],"deep":["北条氏康の «一国を取るのと同じ» という言葉は、書状の文面として紹介されるが、現代語訳の言い回しは本によってちがう。","関宿の関所は、江戸川を通る船を調べる «川の関所»。陸の箱根の関所とならぶ、江戸の守りの一つだった。","江戸時代の利根川東遷によって、利根川の水が銚子へ流れるようになり、関宿は東北・北関東と江戸を結ぶ水運の中心になった。","博物館の天守は、江戸時代の «御三階櫓» の記録などを参考に再現したもの。本来の城の場所は少しはなれた河川敷付近とされる。","城あと付近には «関宿城址» の碑が立つ。利根川・江戸川の «棒出し» など、川をしずめる工夫の歴史も博物館で学べる。","近くには鈴木貫太郎記念館があり、終戦の決断にかかわった首相のゆかりを知ることができる。"],"look":["千葉県立関宿城博物館の天守最上階からのながめ","博物館の河川・水運の展示","本丸あとの «関宿城址» の碑","江戸川の流頭部（利根川と分かれるところ）","近くの鈴木貫太郎記念館"],"q":["関宿城が大事にされた一番の理由は？","利根川と江戸川が分かれる «水の道の交差点» にあり、船の交通を押さえられたから。"],"koji":[],"myth":"築城年・北条氏康の言葉の細かな言い回しは諸説。博物館の天守は再現建物で、元の位置とは異なる。","img":["関宿藩","簗田晴助","鈴木貫太郎","利根川東遷事業"],"wp":"関宿城","rel":{"ev":[],"grave":[]},"ph":[["c:2/28/Sekiyado_Castle1.JPG",1920,2560,"関宿城"],["c:4/42/Sekiyado_Castle3.jpg",4608,3456],["c:c/c5/%E6%97%A5%E6%9C%AC%E3%81%AE%E5%9F%8E%E8%B7%A1.png",971,940],["c:2/28/%E9%96%A2%E5%AE%BF%E5%9F%8E.jpg",893,577],["c:3/38/Kantaro_Suzuki_suit.jpg",1024,1426,"鈴木貫太郎"],["c:2/20/Hanyu_Aino_River_Starting_Point_Pt1_1.JPG",3264,2448,"利根川東遷事業"]]},{"id":"12_inohana_jo","n":"亥鼻城（千葉城・千葉氏発祥）","yomi":"いのはなじょう","cat":"城","rank":"A","y":1126,"era":["heian","kamakura","muromachi"],"sh":"県指定史跡","ad":"千葉市中央区亥鼻1丁目","st":"千葉都市モノレール 県庁前駅から歩いて約10分","la":35.6037,"lo":140.125,"hook":"«千葉» という名前のルーツはここにある。源頼朝を支えた千葉氏が根をおろした台地。","lead":"亥鼻城は、千葉市のまんなかの台地にある城あとで、«千葉城» ともよばれます。平安時代の終わりに千葉常重がこの地に本拠を移し、ここから «千葉氏» の歴史が始まったとされます。いまお城のような建物は千葉市立郷土博物館で、昔の天守ではありません。","story":["千葉市の市役所から南へ歩くと、木がしげった小高い台地が見えてきます。これが亥鼻（いのはな）。台地の先が «イノシシの鼻» のようにつき出ていたから、ともいわれます。ここにお城の形をした建物がありますが、これは1967年にできた郷土博物館。じつは、中世の城に天守はありませんでした。","1126年、房総の豪族 «千葉常重（つねしげ）» が、この近くに本拠を移したと伝わります。千葉市ではこれを «千葉開府» とよび、町の誕生の年としています。«千葉» という地名を名字にした一族――それが千葉氏です。","常重の子 «千葉常胤（つねたね）» は、1180年、戦いにやぶれて房総へ逃げてきた源頼朝をむかえます。«ここで味方しなければ、源氏の再起はない»。常胤は一族をひきいて頼朝のもとにかけつけました。頼朝は常胤を «父のように» 大事にしたといわれ、千葉氏は鎌倉幕府の有力な御家人になります。","ところで、千葉氏の館はどこにあったのでしょう? じつは、はっきりとはわかっていません。台地の下、いまの千葉神社のあたりに館があったとする説が有力で、亥鼻の台地の城は、戦国時代に使われたとりでだった可能性があります。«千葉氏の城» のイメージと、発掘でわかる事実には、ちがいがあるのです。","15世紀、千葉氏は一族の争いで本家がほろび、本拠は佐倉の本佐倉城へ移ります。亥鼻の地はやがて忘れられていきました。いま台地の上には、千葉常胤の像や «千葉開府» の碑が立ち、博物館では千葉氏と妙見信仰の歴史を学ぶことができます。"],"tl":[["1126年","千葉常重が千葉に本拠を移したと伝わる（千葉開府）"],["1180年","千葉常胤が源頼朝をむかえ、味方になる"],["1185年","平氏がほろび、千葉氏は鎌倉幕府の有力御家人に"],["1455年","一族の争いで千葉氏の本家がほろぶ（享徳の乱のなか）"],["15世紀後半","千葉氏の本拠が本佐倉城へ移る"],["1967年","千葉市立郷土博物館（天守風の建物）ができる"]],"who":[["千葉常重","千葉に本拠を移したとされる人物。千葉開府の祖"],["千葉常胤","常重の子。源頼朝を助け、鎌倉幕府の重臣になった"],["源頼朝","鎌倉幕府を開いた人。房総で千葉氏の力を得た"],["馬加康胤","千葉氏の一族。本家をほろぼし、千葉氏の中心が佐倉へ移るきっかけをつくった"]],"deep":["亥鼻城に天守があった記録はなく、郷土博物館の天守風の建物は «模擬天守» ともよべない、いわば昭和の博物館建築。","千葉氏の館の場所は諸説。台地の下の千葉神社付近とする説が有力で、亥鼻台地の土塁や堀は戦国期のものと考える研究者が多い。","亥鼻城跡は千葉県指定史跡。台地には土塁や堀切のあとが一部残り、中世城郭の雰囲気を感じられる。","千葉常胤は頼朝の挙兵後、奥州合戦などでも活躍し、一族は東北や九州にまで領地を得た。九州にも «千葉氏» の流れがある。","『吾妻鏡』には、頼朝が常胤を重んじたようすが記されている。頼朝挙兵の成功には、房総の武士団の力が欠かせなかった。"],"look":["千葉市立郷土博物館（千葉氏と妙見信仰の展示）","千葉常胤の像","«千葉開府» の記念碑","台地に残る土塁・堀のあと","春の亥鼻公園の桜"],"q":["千葉市が «千葉開府» の年としているのは何年？","1126年。千葉常重が千葉に本拠を移したと伝わる年です。"],"koji":[],"myth":"館の場所・亥鼻台地の城の年代は諸説。«1126年の開府» は伝承にもとづく年。","img":["千葉常胤","千葉氏","千葉市立郷土博物館"],"wp":"亥鼻城","rel":{"ev":[],"grave":[]},"ph":[["c:6/6f/View_of_the_Chiba_City_Folk_Museum_from_Chiba_Prefectural_Government_Office_Main_Building.jpg",3264,2448,"亥鼻城"],["c:6/6f/Historicspot_inohanacastle_monument.jpg",3968,2976],["c:f/f4/%E5%8D%83%E8%91%89%E5%9F%8E.jpg",2448,3264],["c:c/c5/%E6%97%A5%E6%9C%AC%E3%81%AE%E5%9F%8E%E8%B7%A1.png",971,940],["c:c/cd/Inohana7.jpg",1000,750],["c:b/b0/Inohana6.jpg",1000,750],["c:3/37/Inohana5.jpg",1000,750],["c:4/49/Inohana4.jpg",1000,750]]},{"id":"12_chiba_jinja","n":"千葉神社（千葉氏の妙見信仰）","yomi":"ちばじんじゃ","cat":"寺社","rank":"A","y":1000,"era":["heian","kamakura","meiji"],"sh":"","ad":"千葉市中央区院内1丁目","st":"京成千葉中央駅から歩いて約5分、JR千葉駅から歩いて約10分","la":35.6122,"lo":140.1215,"hook":"北極星と北斗七星の神さま «妙見さま»。千葉一族が守り神にした、星のお宮。","lead":"千葉神社は、千葉市の中心にある神社で、«妙見さま» の名で親しまれています。妙見は北極星・北斗七星を神さまにしたもので、中世の千葉氏がとくに大切にしました。今の社殿は1990年に建てられた、屋根が二重になった珍しい社殿です。","story":["夜空で動かない星、北極星。昔の人は «天の中心にいる星» として特別な力を感じました。その星と北斗七星を神さまとしたのが «妙見（みょうけん）» です。千葉神社は、その妙見をまつる «妙見本宮» 。平安時代の1000年に始まったと伝わります。","千葉氏がなぜ妙見を守り神にしたのか。こんな言い伝えがあります。千葉氏の先祖・平良文（よしふみ）が苦しい戦いをしているとき、妙見が現れて勝たせてくれた――。«この神を大切にすれば、一族は栄える»。千葉氏は妙見をあつく信じ、旗や家紋にも星や月をえがきました。","千葉氏の家紋 «月星（つきぼし）» や «九曜（くよう）» は、この妙見信仰から生まれたといわれます。今でも千葉市の市章は、千葉氏の «月星» がもとになっているという説があります。星の神さまは、町の目じるしにまで生きているのです。","江戸時代まで、ここは «北斗山金剛授寺（こんごうじゅじ）» という寺でもありました。神さまと仏さまをいっしょにまつる、昔ふつうだったかたちです。ところが明治のはじめ、神と仏を分けるきまりができ、寺は神社となって «千葉神社» と名前を改めました。","1945年の千葉空襲で、社殿は焼けてしまいました。長い時間をかけて、1990年に新しい社殿が完成します。屋根が二つ重なる «重層社殿» は全国でも珍しいものです。毎年8月には、800年以上続くと伝わる «妙見大祭» が開かれ、町がにぎわいます。"],"tl":[["1000年","北斗山金剛授寺として始まったと伝わる"],["1126年ごろ","千葉氏が千葉に本拠を移し、妙見を守り神としてあつく信仰"],["中世","千葉氏の氏神として栄える"],["1869年ごろ","神仏分離で寺から千葉神社へ"],["1945年","千葉空襲で社殿が焼失"],["1990年","重層社殿が完成"]],"who":[["平良文","千葉氏の先祖とされる武士。妙見に助けられたと伝わる"],["千葉常胤","千葉氏の当主。妙見信仰を一族の柱とした"],["千葉常重","千葉に本拠を移したとされ、妙見をまつったとも伝わる"]],"deep":["妙見信仰は、中国の北極星信仰が仏教・道教とまざって日本に伝わったもの。武士、とくに千葉氏・相馬氏など房総〜東北の一族に広まった。","千葉氏の一族は各地に広がり、相馬氏や東氏なども妙見を信仰した。福島県の相馬野馬追も妙見信仰とかかわりが深い。","«妙見大祭» は8月16日から22日まで行われ、神輿が町をめぐる。800年以上続くと伝わる。","境内には «尊星殿（そんじょうでん）» や、千葉氏ゆかりの末社などがある。星にまつわる «厄除け» の信仰でも知られる。","平良文が妙見に助けられた話は伝承で、史料で確かめられたものではない。一族の由来を語る «縁起» として読むとよい。"],"look":["重層社殿（二重の屋根）","境内の «千葉氏の月星紋» をさがす","尊星殿と末社","8月の妙見大祭","近くの亥鼻城あと・郷土博物館とあわせて歩く"],"q":["千葉神社の «妙見さま» は、もとは何を神さまにしたもの？","北極星と北斗七星。夜空の中心の星を神としてまつったものです。"],"koji":[],"myth":"創建年（1000年）と平良文の話は伝承。市章の由来にも諸説。","img":["妙見菩薩","千葉氏","千葉常胤"],"wp":"千葉神社","rel":{"ev":[],"grave":[]},"ph":[["c:d/df/Chiba-jinja_003.jpg",3264,2448,"千葉神社"],["c:f/f5/Chiba-jinja_Tor_T%C3%BCrmchen.jpg",4592,3448],["c:e/ee/Chiba-jinja_Tor_13.jpg",4592,3448],["c:b/be/Chiba-jinja_Tor_11.jpg",4592,3448],["c:5/51/Chiba-jinja_009.jpg",3264,2448],["c:4/45/Chiba-jinja_008.jpg",3264,2448],["c:3/30/Chiba-jinja_007.jpg",3264,2448],["c:4/4d/Chiba-jinja_006.jpg",3264,2448]]},{"id":"12_usui_jo","n":"臼井城（上杉謙信を退けた城）","yomi":"うすいじょう","cat":"城","rank":"A","y":1566,"era":["kamakura","muromachi"],"sh":"","ad":"佐倉市臼井田","st":"京成本線 京成臼井駅から歩いて約20分","la":35.7255,"lo":140.1917,"hook":"«軍神» 上杉謙信が攻めて、落とせなかった城。印旛沼を見下ろす台地に、その記憶が眠る。","lead":"臼井城は、佐倉市の印旛沼のほとりにある城あとです。1566年、関東へ攻めてきた上杉謙信の大軍を、城の兵が守りぬいたことで知られています。いまは «臼井城址公園» として、空堀や土塁のあとを歩くことができます。","story":["印旛沼を見下ろす台地の上。いまは静かな公園ですが、ここはかつて関東をゆるがした戦いの舞台でした。城を開いたのは、千葉氏の一族 «臼井氏» 。平安時代の終わりから、この地を治めたといわれます。","1479年、江戸城をきずいた太田道灌がこの城を攻めました。城にこもった千葉方の兵はねばり、道灌の弟・太田資忠（すけただ）は、この戦いで命を落としたといわれます。城の近くには、資忠をとむらう «太田図書（ずしょ）の墓» が今も残っています。","そして1566年。«越後の龍» 上杉謙信が、関東の武将たちを引きつれて臼井城にせまりました。城を守るのは千葉氏の家臣・原氏と、北条氏から送られた援軍。数では謙信軍のほうがずっと上です。«もうだめだ» と思った兵も多かったでしょう。","ところが、城は落ちませんでした。城の兵は必死に守り、攻めよせた謙信軍に大きな損害を与えたといわれます。やがて謙信は兵を引きあげました。この戦いで城方の作戦を立てたのは «白井入道浄三» という軍師だった、という話が伝わっていますが、くわしいことは物語的な記録にたよる部分が多く、諸説あります。","戦国時代が終わると、臼井城には徳川家の家臣・酒井家次が入りましたが、まもなく城は使われなくなりました。今の臼井城址公園では、本丸をかこむ空堀や土塁をたどることができます。春は桜、晴れた日には印旛沼のながめ。«謙信を追いかえした城» の上で、戦国の空気を感じてみましょう。"],"tl":[["12世紀ごろ","千葉氏の一族・臼井氏がこの地を治めたと伝わる"],["1479年","太田道灌が臼井城を攻め、弟の太田資忠が戦死したといわれる"],["1566年","上杉謙信が臼井城を攻めるが、落とせず退く"],["1590年","北条氏がほろび、徳川家臣の酒井家次が入る"],["1604年","酒井家次が高崎へ移り、城はやがて廃される"]],"who":[["上杉謙信","越後の戦国大名。1566年に臼井城を攻めたが落とせなかった"],["原胤貞","千葉氏の重臣。臼井城を守った側"],["白井入道浄三","城方の軍師として伝わる人物（伝承の色が濃い）"],["太田道灌","江戸城をきずいた武将。1479年に臼井城を攻めた"],["太田資忠","道灌の弟。臼井城攻めで戦死したといわれる"]],"deep":["1566年の臼井城の戦いは、謙信の関東遠征の大きなつまずきとされる。この後、関東の武将たちの多くが北条方へ傾いたといわれる。","城方の勝利の理由として、城の立地（台地と沼）、北条氏の援軍、軍師の知恵などがあげられるが、どれが決め手かは諸説。","白井入道浄三の活躍は、軍記物などの記述によるところが大きく、史実としての確かさには議論がある。","城あとには、本丸・二の丸をかこむ空堀と土塁が残る。台地の先端を利用した典型的な房総の中世城郭。","太田図書の墓は、臼井城から少しはなれた場所にあり、道灌の弟をとむらったものと伝わる。"],"look":["臼井城址公園の本丸あと","本丸をかこむ空堀と土塁","台地から見下ろす印旛沼","近くの «太田図書の墓»","春の桜"],"q":["1566年、臼井城を攻めて落とせなかった有名な武将は？","上杉謙信。大軍で攻めましたが、城方が守りぬき、謙信は兵を引きました。"],"koji":[],"myth":"白井入道浄三の軍略や戦いの細部は軍記物による部分が多く、諸説あり。","img":["上杉謙信","臼井氏","太田道灌"],"wp":"臼井城","rel":{"ev":[],"grave":[]},"ph":[["c:a/a3/Usui_Castle.jpg",3872,2592,"臼井城"],["c:1/19/Usui_Castle_Hori.jpg",3872,2592],["c:7/7d/Ch%C3%A2teau_de_Himeji02.jpg",2592,1944],["c:c/c5/%E6%97%A5%E6%9C%AC%E3%81%AE%E5%9F%8E%E8%B7%A1.png",971,940],["c:8/88/Uesugi_Kenshin_Portrait_from_Uesugi_Shrine.png",768,1164,"上杉謙信"],["c:4/48/Outa_Doukan.jpg",1020,1344,"太田道灌"]]},{"id":"12_kyu_hotta_tei","n":"旧堀田邸（最後の佐倉藩主の屋敷）","yomi":"きゅうほったてい","cat":"大名屋敷","rank":"A","y":1890,"era":["edo","meiji"],"sh":"国の重要文化財","ad":"佐倉市鏑木町","st":"JR佐倉駅から歩いて約20分、京成佐倉駅から歩いて約25分","la":35.719,"lo":140.222,"hook":"殿さまが «殿さま» でなくなったあと、ふるさとに建てた家。明治の大名家の暮らしが、そのまま残る。","lead":"旧堀田邸は、最後の佐倉藩主・堀田正倫（まさとも）が1890年に建てた屋敷です。大名家の人が明治になってから住んだ家として、とてもよく残っていて、国の重要文化財になっています。広い庭園は国の名勝です。","story":["佐倉の城下町のはずれ、坂をのぼった先に、落ちついた木造の屋敷があります。玄関を入ると、長いろうかと、庭に向かって開いた座敷。ここは «殿さま» だった人が、明治の世に建てた家です。","江戸時代の佐倉藩は、老中を何人も出した名門・堀田家の藩でした。とくに幕末の藩主 «堀田正睦（まさよし）» は、老中としてアメリカとの条約問題にとりくみ、蘭学（西洋の学問）を大切にしました。佐倉には蘭方医・佐藤泰然がひらいた «順天堂» があり、«西の長崎、東の佐倉» といわれたほどです。","正睦のあとをついだのが、正倫です。1871年の廃藩置県で、藩はなくなりました。大名たちの多くは東京に住むよう求められ、正倫も東京で暮らしました。けれど正倫は、ふるさと佐倉を忘れませんでした。«旧藩の人びとのために、何かできないか»。","1890年、正倫は佐倉にこの屋敷を建てて移り住みます。そして、農業をよくするための試験場をつくったり、学校を助けたりしました。«殿さま» ではなくなっても、地域のために力をつくしたのです。屋敷の近くの坂道からは、正倫が見たのと同じ田んぼの広がりが見えます。","屋敷は、座敷棟・居間棟・書斎棟などがつながり、豪華すぎず、でも細部はていねいにつくられています。広い芝生の庭は、遠くの景色を取りこむ «借景» の考え方でつくられたといわれます。明治の «元大名の暮らし» を、ここまでまるごと感じられる場所は多くありません。"],"tl":[["1746年","堀田正亮が佐倉藩主となり、以後堀田家が明治まで治める"],["1838年ごろ","佐藤泰然が佐倉に順天堂をひらく（1843年とする説も）"],["1858年","老中・堀田正睦が条約の勅許を得ようと京へ向かう"],["1871年","廃藩置県で佐倉藩がなくなる"],["1890年","堀田正倫が佐倉にこの屋敷を建てる"],["2006年","主屋などが国の重要文化財に指定"],["2015年","庭園が国の名勝に指定"]],"who":[["堀田正倫","最後の佐倉藩主。この屋敷を建て、地域の農業や教育を支えた"],["堀田正睦","正倫の父（養父ともされる）。幕末の老中で、開国の交渉にかかわった"],["佐藤泰然","佐倉に順天堂をひらいた蘭方医"]],"deep":["屋敷は明治の上流住宅として、座敷・居間・書斎・台所などが機能ごとに分かれた構成。華族の暮らし方がよくわかると評価されている。","正倫は屋敷の近くに «堀田家農事試験場» をつくり、農業技術の改良を進めた。地域の近代化に旧藩主がかかわった例として注目される。","堀田正睦は日米修好通商条約の勅許を得るために京へ上ったが、朝廷の同意は得られず、老中を退くことになった。","佐倉の城下町には、武家屋敷や順天堂記念館など、幕末〜明治の歴史をたどれる場所が多い。旧堀田邸とあわせて歩くとよい。","重要文化財の指定名称は «旧堀田家住宅»、名勝の名称は «旧堀田正倫庭園»。名前がちがうので調べるときは注意。"],"look":["座敷から見る芝生の庭園","長いろうかと、各棟のつながり","明治の照明や建具のデザイン","庭の奥から見下ろす景色（借景）","城下町の武家屋敷・順天堂記念館"],"q":["幕末の佐倉が «東の○○» とよばれたのは、なぜ？","«西の長崎、東の佐倉»。蘭学、とくに西洋医学がさかんだったからです。"],"koji":[{"w":"西の長崎、東の佐倉","m":"蘭学がさかんな町として、長崎とならべて佐倉がたたえられた言葉"}],"myth":"順天堂の開設年は資料により表記が分かれる。","img":["堀田正倫","堀田正睦","佐倉藩","順天堂"],"wp":"旧堀田邸","rel":{"ev":[],"grave":[]},"ph":[["c:2/2b/Hotta_residence4.jpg",1248,936,"旧堀田邸"],["c:1/11/Kyu_Hotta-ke_Jutaku_Zashikito.jpg",4201,3154],["c:f/f5/Kyu_Hotta-ke_Jutaku_Shosaito.jpg",4624,3472],["c:c/c1/Kyu_Hotta-ke_Jutaku_Monbansho.jpg",4624,3472],["c:8/85/Kyu_Hotta-ke_Jutaku_Genkanto.jpg",4093,3073],["c:9/90/Kyu_Hotta-ke_Jutaku_Dozo.jpg",4147,3114],["c:5/5c/Kyu_Hotta-ke_Jutaku_Yudono.jpg",3293,2473],["c:a/a8/Kyu_Hotta-ke_Jutaku_Imato.jpg",2807,2107]]},{"id":"12_tojotei","n":"戸定邸（徳川昭武の屋敷）","yomi":"とじょうてい","cat":"大名屋敷","rank":"A","y":1884,"era":["meiji"],"sh":"国の重要文化財","ad":"松戸市松戸（戸定が丘歴史公園）","st":"JR・新京成 松戸駅から歩いて約10分","la":35.7838,"lo":139.9082,"hook":"パリ万博に «将軍の代理» として出かけた少年は、のちに松戸の丘で写真と庭を愛した。","lead":"戸定邸は、最後の将軍・徳川慶喜の弟、徳川昭武（あきたけ）が松戸に建てた屋敷です。明治のはじめの徳川家の暮らしがよく残る建物として、国の重要文化財になっています。庭園は国の名勝で、隣に «戸定歴史館» があります。","story":["1867年、フランス・パリ。世界中の品物がならぶ万国博覧会に、ちょんまげ姿の少年がいました。14歳の徳川昭武です。兄の将軍・慶喜の «名代（代わり）» として、日本を代表してヨーロッパへ来たのでした。","昭武はパリで勉強を続ける予定でした。ところが翌年、日本では幕府がなくなってしまいます。«すぐ帰国せよ»。昭武はヨーロッパで見た鉄道や写真、西洋の暮らしを胸に、変わりはてた日本へ帰りました。","帰国後、昭武は水戸藩の最後の藩主となり、やがて藩もなくなります。そして1883年に家をゆずって引退すると、江戸川を見下ろす松戸の丘に屋敷を建てました。それが戸定邸です。1884年に主な建物が完成しました。","戸定邸は、外から見ると落ちついた和風の平屋。でも、なかに入ると部屋が次々とつながり、とても広いのに気づきます。ここには、兄の慶喜もたびたび訪れました。兄弟はいっしょに写真をとったり、狩りをしたりしたといわれます。«将軍» と «将軍の代わり» だった二人が、静かに趣味を楽しんだ家なのです。","昭武は写真が大好きで、自分で撮った写真がたくさん残っています。戸定歴史館では、パリ万博の資料や昭武の写真を見ることができます。庭に出ると、芝生の向こうに松戸の町。晴れた日には、遠くに富士山が見えることもあります。"],"tl":[["1853年","徳川昭武が水戸藩主・徳川斉昭の子として生まれる"],["1867年","パリ万国博覧会に将軍の名代として出席"],["1868年","幕府がなくなり、帰国。のち水戸藩主に"],["1883年","家督をゆずり、松戸に移る準備を進める"],["1884年","戸定邸の主な建物が完成"],["1910年","昭武が亡くなる"],["1991年","戸定歴史館が開館"],["2006年","戸定邸が国の重要文化財に指定"]],"who":[["徳川昭武","戸定邸の主。パリ万博に行った慶喜の弟"],["徳川慶喜","最後の将軍。弟の戸定邸をたびたび訪れた"],["徳川斉昭","昭武・慶喜の父。水戸藩主"],["渋沢栄一","昭武のパリ行きに随行した。のちの実業家"]],"deep":["パリ万博の使節団には、のちに «日本の資本主義の父» とよばれる渋沢栄一が随行していた。昭武と渋沢の縁はその後も続いた。","戸定邸は、明治前期の徳川家の住まいとして、ほぼ当時のまま残る数少ない例。部屋数が多く、棟が雁行してつながる。","庭園は «旧徳川昭武庭園» として国の名勝。西洋風の芝生と日本庭園の考え方がまじった、明治らしい庭とされる。","昭武の写真は、明治の松戸の風景や家族の姿を記録した貴重な資料でもある。","«戸定（とじょう）» の地名は、中世の城（とりで）に関係するという説があるが、確かではない。"],"look":["戸定邸の座敷と長いろうか","芝生の庭園と、遠くのながめ","戸定歴史館のパリ万博・写真の展示","慶喜と昭武の写真","春の «戸定が丘歴史公園» の花"],"q":["徳川昭武が14歳で出かけた外国の大イベントは？","1867年のパリ万国博覧会。兄の将軍・慶喜の代わりに出席しました。"],"koji":[],"myth":"地名 «戸定» の由来は諸説。","img":["徳川昭武","徳川慶喜","パリ万国博覧会 (1867年)"],"wp":"戸定邸","rel":{"ev":[],"grave":[]},"ph":[["c:7/7f/Tojo_tei_2009.jpg",3420,2326,"戸定邸"],["c:4/41/%E8%A1%A8%E7%8E%84%E9%96%A2%E3%82%88%E3%82%8A%E5%8F%97%E4%BB%98%E3%81%AB%E5%85%A5%E3%82%8B.jpg",3200,1800],["c:b/b9/%E6%B8%A1%E3%82%8A%E5%BB%8A%E4%B8%8B%E3%82%88%E3%82%8A%E4%B8%AD%E5%BA%AD%E3%82%92%E8%87%A8%E3%82%80.jpg",3200,1800],["c:b/b0/%E6%B5%B4%E5%AE%A4%28%E5%AE%B6%E6%97%8F%E3%81%A8%E6%9D%A5%E5%AE%A2%E8%80%85%E7%94%A8%29.jpg",3200,1800],["c:9/99/%E5%86%85%E8%94%B5%E3%81%A8%E4%B8%AD%E5%BA%AD.jpg",3200,1800],["c:d/d5/%E6%B9%AF%E6%AE%BF%E3%81%AE%E5%91%A8%E5%9B%B2.jpg",3200,1799],["c:2/26/%E8%A1%A8%E5%BA%A7%E6%95%B7%E6%A3%9F%28%E8%A5%BF%E3%83%BB%E5%8D%97%E5%81%B4%E3%81%AB%E5%BA%AD%E5%9C%92%29.jpg",7494,1400],["c:a/a3/%E6%A2%85%E5%9C%92%E5%85%A5%E3%82%8A%E5%8F%A3%E4%BB%98%E8%BF%91%28%E3%83%91%E3%83%8E%E3%83%A9%E3%83%9E%29.jpg",7491,1400]]},{"id":"12_dairizuka","n":"内裏塚古墳（南関東最大級の前方後円墳）","yomi":"だいりづかこふん","cat":"遺跡","rank":"A","y":450,"era":["kofun"],"sh":"","ad":"富津市二間塚","st":"JR内房線 青堀駅から歩いて約15分","la":35.3183,"lo":139.8656,"hook":"長さ約144m。東京湾のほとりに眠る、南関東でいちばん大きいクラスの王の墓。","lead":"内裏塚古墳は、富津市にある5世紀の前方後円墳です。全長は約144mあり、千葉県でいちばん大きく、南関東でも最大級です。まわりには «内裏塚古墳群» とよばれるたくさんの古墳があり、この地に強い力をもつ一族がいたことがわかります。","story":["富津の町を歩いていると、住宅のあいだに、木におおわれた大きな丘があらわれます。これが内裏塚古墳。上から見ると、鍵穴のような «前方後円墳» の形をしています。長さはおよそ144m。サッカー場より長い、王の墓です。","つくられたのは5世紀のなかごろと考えられています。大阪の大きな古墳がつくられたのと同じころです。«なぜ、こんな房総の海べに、これほど大きな古墳が?» 答えのヒントは、目の前の東京湾にあります。","昔、畿内（いまの近畿地方）から東へ向かう人びとは、三浦半島から海をわたって房総へ入る道を使ったと考えられています。富津は、その上陸口の一つ。海の道を押さえた一族が、大きな力をもち、畿内の王権と結びついていたのではないか、と考えられています。","明治時代の1906年、古墳の後円部で石室が見つかり、刀や矢じり、玉などが出てきました。ここにねむっていたのは誰なのでしょう。この地を治めた «須恵国造（すえのくにのみやつこ）» の祖先の墓とみる説がありますが、名前まではわかりません。","古墳をつくるには、どれほどの人手が必要だったのでしょう。土を掘り、運び、つき固め、斜面に石をしきつめる。何百人もの人が、何年もかけて働いたと考えられます。王の墓は、王の力をまわりの人びとに見せつける «記念碑» でもありました。海から富津の浜に近づく船の上からも、この大きな丘はよく見えたかもしれません。","内裏塚のまわりには、そのあとも100年以上にわたって古墳がつくられ続けました。«内裏塚古墳群» です。王が亡くなるたびに、あとをついだ者が新しい墓をきずいていったのでしょう。いま古墳の上には神社があり、静かな森になっています。"],"tl":[["5世紀なかごろ","内裏塚古墳がつくられたと考えられる"],["5〜7世紀","まわりに多くの古墳がきずかれ、内裏塚古墳群となる"],["1906年","後円部で石室が見つかり、副葬品が出土"],["近年","古墳群の調査・保存が進む"]],"who":[["須恵国造","この地域を治めたとされる豪族。内裏塚の被葬者をその祖先とみる説がある"],["ヤマト王権","畿内の王権。内裏塚の一族とつながりがあったと考えられる"]],"deep":["全長約144mは千葉県最大の古墳。5世紀の東日本では、群馬の太田天神山古墳などにつぐ規模とされる。","後円部には竪穴式の石室が見つかっており、鉄の刀・剣・矢じり、玉類などが出土したと報告されている。","内裏塚古墳群は、5世紀から7世紀にかけて前方後円墳・円墳・方墳がつくられ、首長の系譜を考える手がかりになっている。","«内裏塚» の名は、天皇の住まい «内裏» と結びつけた伝説に由来するとされるが、実際の被葬者とは関係がない。","近くの富津市の資料館などで、古墳群の出土品や調査のようすを知ることができる。","古墳の多くは周囲に堀（周溝）をめぐらせていた。内裏塚でも堀のあとが確認されており、本来はいま見えるよりひとまわり大きな区画だった。"],"look":["前方後円墳の形がわかる墳丘のまわり","後円部の上の神社","周辺の古墳群（小さな古墳が点在）","近くの古墳群の案内板","青堀駅から古墳群を歩いてめぐるコース"],"q":["内裏塚古墳の全長はおよそ何m？","約144m。千葉県でいちばん大きな古墳です。"],"koji":[],"myth":"被葬者（須恵国造の祖先など）は推定。«内裏» の名にまつわる伝説は史実ではない。","img":["内裏塚古墳群","前方後円墳","国造"],"wp":"内裏塚古墳","rel":{"ev":[],"grave":[]},"ph":[["c:9/94/Dairizuka-kofun_zenkei.JPG",5996,3970,"内裏塚古墳"],["c:5/54/Dairizuka-kofun_funcho.JPG",6016,4000],["c:0/0d/Dairizuka-kofun_enkei.JPG",6016,4000],["c:4/46/D-Inariyamakohun1.jpg",3296,2472,"内裏塚古墳群"],["c:c/c3/NintokuTomb_Aerial_photograph_2007.jpg",1000,982,"前方後円墳"],["c:8/8b/Kuni-no-miyatsuko_of_ancient_Japan.jpg",2730,1820,"国造"]]},{"id":"12_kanareizuka","n":"金鈴塚古墳（金の鈴の出た古墳）","yomi":"きんれいづかこふん","cat":"遺跡","rank":"A","y":600,"era":["kofun","asuka"],"sh":"県指定史跡","ad":"木更津市長須賀","st":"JR木更津駅から歩いて約20分","la":35.3858,"lo":139.9294,"hook":"石室の奥で、小さな金の鈴がひかった――。古墳時代の最後をかざる、房総の «黄金の墓»。","lead":"金鈴塚古墳は、木更津市にある古墳時代の終わりごろの前方後円墳です。1950年の発掘で、金の鈴や、金や銅でかざった刀など、たくさんのすばらしい品が見つかりました。出土品は国の重要文化財で、木更津市郷土博物館金のすずで見られます。","story":["1950年、戦争が終わってまだ5年。木更津の町なかにある古墳で、大がかりな発掘が始まりました。土をどけ、石室の中へ入ると、そこには信じられない光景がありました。金色にかがやく小さな鈴、金でかざられた大刀、馬の飾り――。","見つかった金の鈴は5つ。«金鈴塚» という名前は、この発見から生まれました。それまで «二子塚» などとよばれていた古墳は、いっきに有名になります。«こんなにすごい品が、どうしてここに?»","古墳がつくられたのは6世紀の終わりから7世紀のはじめごろ。全国で前方後円墳がつくられなくなる直前です。この地の豪族は、ヤマト王権と強く結びつき、朝鮮半島から伝わった技術でつくられた品も手に入れていたと考えられます。","金の鈴は、ほんの小指の先ほどの大きさです。どうやって使われたのでしょう。衣服や道具に下げて、動くたびに澄んだ音を鳴らしたのかもしれません。音は、神さまや死者の世界とつながる力をもつと考えられていました。王のそばで鳴っていた小さな鈴の音を、想像してみてください。","とくに目をひくのが、たくさんの «飾り大刀» 。柄の先を金銅でかざった刀が、ずらりと納められていました。一つの古墳からこれほど多くの飾り大刀が出た例は、全国でもめずらしいといわれます。ここにねむる人は、どれほどの力をもっていたのでしょう。","残念ながら、古墳の墳丘の多くは、その後の開発などで失われました。いまは石室のある部分が残されています。出土品は国の重要文化財となり、博物館で大切に守られています。小さな金の鈴を見つめると、1400年前の豪族の声が聞こえてきそうです。"],"tl":[["6世紀末〜7世紀初め","金鈴塚古墳がつくられたと考えられる"],["1950年","早稲田大学などによる発掘で、金の鈴など多数の品が出土"],["1950年代","出土品が国の重要文化財に指定される"],["現在","出土品を木更津市郷土博物館金のすずで展示"]],"who":[["滝口宏","考古学者。金鈴塚古墳の発掘を指導した"],["馬来田国造","木更津周辺を治めたとされる豪族。被葬者をその一族とみる説がある"]],"deep":["前方後円墳の全長は約90mとされ、この地域の終末期の前方後円墳として代表的な存在。","出土品には金鈴のほか、金銅装の飾り大刀、馬具、鏡、玉、須恵器などがあり、とくに飾り大刀の多さが際立つ。","石室は横穴式石室。複数の人が葬られた可能性が指摘されている。","房総では6〜7世紀に大きな古墳が多くつくられ、ヤマト王権が東国を重視したことの表れとみる考えもある。","被葬者は不明。周辺を治めた国造の一族とする見方が一般的だが、名前はわからない。","発掘は戦後まもない時期に行われ、地元の人びとの協力も大きかった。出土品の保存のため、のちに専用の保存館がつくられ、今の博物館につながっている。"],"look":["古墳あとの石室部分","木更津市郷土博物館金のすずの金鈴","ずらりとならぶ飾り大刀の展示","馬具など、豪族の暮らしがわかる品"],"q":["金鈴塚古墳の名前の由来になった出土品は？","金の鈴。1950年の発掘で5つ見つかりました。"],"koji":[],"myth":"被葬者は推定。全長などの数値は資料によって多少ちがう。","img":["木更津市郷土博物館金のすず","横穴式石室"],"wp":"金鈴塚古墳","rel":{"ev":[],"grave":[]},"ph":[["c:9/9d/Kinreizuka-1.jpg",3296,2472,"金鈴塚古墳"],["j:4/4f/%E9%87%91%E9%88%B4%E5%A1%9A%E5%8F%A4%E5%A2%B3_%E5%87%BA%E5%9C%9F%E5%93%81.JPG",5554,3692],["c:7/73/Kinreizuka-3.jpg",2472,3296],["c:7/7e/Kinreizuka-2.jpg",2472,3296],["c:8/8d/Kisarazu_city_folk_museum_Kin_no_Suzu.jpg",2304,1728,"木更津市郷土博物館金のすず"],["c:5/59/Monjuin_Nishi_Kofun%2C_sendou-1.jpg",6002,3978,"横穴式石室"]]},{"id":"12_tonozuka","n":"殿塚・姫塚古墳（芝山はにわ）","yomi":"とのづか・ひめづかこふん","cat":"遺跡","rank":"A","y":570,"era":["kofun"],"sh":"国指定史跡","ad":"山武郡横芝光町中台","st":"車が便利。JR総武本線 横芝駅から車で約10分","la":35.67,"lo":140.465,"hook":"ひげの武人、胸を張る女性、馬――。古墳のまわりに «行列» のようにならんでいたはにわたち。","lead":"殿塚・姫塚は、横芝光町にある6世紀の前方後円墳で、«芝山古墳群» の中心です。1956年の発掘で、人や馬の形のはにわがもとの場所にならんだまま見つかり、日本中をおどろかせました。はにわは芝山町の博物館で見ることができます。","story":["九十九里浜から少し内陸へ入った台地に、二つの古墳がならんでいます。大きいほうが «殿塚»、小さいほうが «姫塚»。まるで殿さまとお姫さまのような名前ですが、これは後の時代の人がつけたよび名です。","1956年、ここで発掘が行われました。土の中から次々と現れたのは、人や馬の形をした «形象はにわ» 。しかも、ばらばらではなく、古墳のまわりに列をつくってならんでいたのです。«まるで、お葬式の行列みたいだ»。はにわが当時のならびのまま見つかった例は、めったにありません。","はにわは、赤みがかった素焼きの土でできています。目は小さな穴、口も穴。それなのに、にっこり笑っているように見えたり、きりっとしているように見えたりします。武人、農夫のような人、琴をひく人、馬をひく人――。はにわの一体一体に、古墳時代の «村の人びと» の姿が重なります。","とくに有名なのが、あごに長いひげをたくわえ、つばの広い帽子をかぶった男性のはにわです。«ひげの武人» ともよばれ、その顔つきから «外国から来た人では?» と考える人もいます。本当のところはわかりませんが、見る人の想像をかきたてる顔です。","はにわたちは、何のためにならべられたのでしょう。亡くなった王の «お葬式» を再現した、王が生きていたころの «儀式» を表した、など、いくつもの説があります。はにわの列は、1400年以上前の人びとの思いをいまに伝えるメッセージなのです。","出土したはにわは、近くの芝山仁王尊・観音教寺にある «芝山古墳・はにわ博物館» に展示されています。毎年秋には «はにわ祭» が開かれ、古代の衣装をまとった人びとが行列をします。古墳の上を歩き、博物館ではにわと目を合わせてみましょう。"],"tl":[["6世紀後半","殿塚・姫塚がつくられたと考えられる"],["1956年","早稲田大学などによる発掘で、はにわ列が見つかる"],["1958年","芝山古墳群として国の史跡に指定"],["現在","はにわは芝山古墳・はにわ博物館などで展示"]],"who":[["滝口宏","考古学者。殿塚・姫塚の発掘を指導した"],["古墳の主","この地域の豪族と考えられるが、名前は不明"]],"deep":["殿塚は全長約88m、姫塚は全長約58mの前方後円墳とされる。二つがならぶ配置も見どころ。","姫塚でははにわが墳丘の一方の側に列をなしていたことがわかり、はにわ配置の研究に大きな影響を与えた。","«ひげの武人» のはにわについては、外来の人を表したとする説があるが、根拠は顔の表現のみで、確かなことはいえない。","はにわ列の意味は、葬送儀礼説・首長権継承儀礼説・生前の儀式説などがあり、決着していない。","出土はにわの一部は、芝山町の博物館のほか、研究機関にも保管されている。","芝山古墳群には殿塚・姫塚のほかにも多くの古墳があり、周辺の台地には古墳時代の集落あともある。地域全体で当時の社会を考えられる。"],"look":["殿塚と姫塚、二つの前方後円墳","古墳の案内板のはにわ配置図","芝山古墳・はにわ博物館の «ひげの武人»","秋の «はにわ祭»"],"q":["殿塚・姫塚のはにわの発見が大事だったのはなぜ？","人や馬のはにわが、当時ならべられた場所のまま、列になって見つかったからです。"],"koji":[],"myth":"«殿»«姫» は後世のよび名。はにわ列の意味、«ひげの武人» の出自は諸説。","img":["埴輪","観音教寺"],"wp":"芝山古墳群","rel":{"ev":[],"grave":[]},"ph":[["c:d/dc/Tonozuka.JPG",2048,1536,"芝山古墳群"],["c:7/7d/Ch%C3%A2teau_de_Himeji02.jpg",2592,1944],["c:e/e4/%E5%A1%9A%E5%BB%BB%E3%82%8A%E5%8F%A4%E5%A2%B3_-_panoramio.jpg",1280,960,"埴輪"],["c:a/ab/Kannonkyo-ji_Nio-mon.JPG",2048,1536,"観音教寺"]]},{"id":"12_horinouchi","n":"堀之内貝塚","yomi":"ほりのうちかいづか","cat":"遺跡","rank":"A","y":-2000,"era":["jomon"],"sh":"国指定史跡","ad":"市川市北国分町","st":"北総線 北国分駅から歩いて約15分","la":35.7486,"lo":139.9275,"hook":"林のなかの地面に、白い貝がらがちらばる。約4000年前の縄文人の «ごみ捨て場» が、教科書の «ものさし» になった。","lead":"堀之内貝塚は、市川市にある縄文時代の大きな貝塚です。貝がらが馬のひづめのような形（馬蹄形）に積もっていて、ここで見つかった土器は «堀之内式土器» と名づけられ、縄文時代後期の土器の年代を決める «ものさし» になっています。国の史跡で、となりに市立市川考古博物館があります。","story":["市川の住宅地を北へ進むと、こんもりとした林に入ります。足もとをよく見ると、白いかけらがあちこちに。貝がらです。ここは、約4000年前の縄文人が暮らしたむらのあと、堀之内貝塚です。","縄文時代、いまの東京湾は今よりずっと内陸まで入りこんでいました。市川のあたりは海に近く、人びとはハマグリやアサリ、シジミなどをたくさんとって食べました。食べ終わった貝がらを決まった場所に捨て続けた結果、貝がらの山ができたのです。«ごみ捨て場» といいますが、そこには亡くなった人がほうむられることもありました。","堀之内貝塚は、貝がらの積もったところが、むらのまわりを «U字» にかこむように広がっています。まんなかには広場があったと考えられ、人びとはそのまわりに家を建てていました。«みんなで広場をかこんで暮らす»。縄文のむらの形が、貝塚の形からわかるのです。","この貝塚は、明治時代から多くの研究者が調べてきました。ここで出た土器には、はっきりした特ちょうがあり、«堀之内式» と名前がつけられました。ほかの遺跡で同じような土器が出れば、«あ、これは堀之内式と同じころだ» とわかる。つまり、ここが時代をはかる «ものさし» になったのです。","いま貝塚は林のなかの公園として守られ、となりの市立市川考古博物館で、土器や骨角器（骨や角でつくった道具）、貝塚の断面などを見ることができます。林を歩き、足もとの貝がらを見つけたら、4000年前の夕ごはんを思いうかべてみてください。"],"tl":[["約4000年前","縄文時代後期を中心にむらがいとなまれる"],["明治時代","研究者たちによる調査が始まる"],["大正〜昭和","出土土器が «堀之内式» として型式の基準に"],["1964年","国の史跡に指定"],["1972年","市立市川考古博物館が開館"]],"who":[["縄文時代の人びと","貝や魚、木の実をとり、広場をかこむむらで暮らした"],["山内清男","縄文土器の型式研究を進めた考古学者。堀之内式など型式による編年を整えた"]],"deep":["堀之内式土器は縄文後期前葉の標式土器。すっきりした形と、線で描いた文様が特ちょうで、関東を中心に広い範囲で見つかる。","馬蹄形貝塚は東京湾東岸に多く、市川・千葉周辺は日本有数の貝塚密集地帯。千葉市の加曽利貝塚もその一つ。","貝塚の中は貝がらのカルシウムで土が酸性にならず、骨が残りやすい。そのため人骨や動物の骨、骨角器がよく見つかる。","貝の種類の変化から、当時の海岸線や環境の変化を読みとる研究もある。","«堀之内» の名は地名から。考古学では、はじめて特ちょうが確認された遺跡の名前を土器の型式名にすることが多い。"],"look":["林の地表に見える貝がら","貝塚の範囲がわかる案内板","市立市川考古博物館の堀之内式土器","貝塚の断面展示","周辺の縄文〜古代の出土品"],"q":["堀之内貝塚の土器が «ものさし» とよばれるのはなぜ？","特ちょうのはっきりした «堀之内式土器» として、ほかの遺跡の年代をくらべる基準になったからです。"],"koji":[],"myth":"","img":["堀之内式土器","貝塚","市立市川考古博物館"],"wp":"堀之内貝塚","rel":{"ev":[],"grave":[]},"ph":[["c:6/63/Horinouchi_Shell_Mound%2C_gaikan-3.jpg",5568,3712,"堀之内貝塚"],["c:1/12/Horinouchi_Woman_%28Detail%29.jpg",6000,4000],["c:1/1f/Horinouchi_Shell_Mound_-_Detail.jpg",6000,4000],["c:0/01/Horinouchi_Shell_Mound%2C_tateana-tatemono.jpg",5568,3712],["c:f/fa/Horinouchi_Shell_Mound%2C_gaikan-1.jpg",5568,3712],["c:5/57/Horinouchi_Shell_Midden.jpg",6000,4000],["j:a/a6/%E5%A0%80%E4%B9%8B%E5%86%852%E5%BC%8F%E5%9C%9F%E5%99%A8.JPG",5157,3391],["c:8/83/Conchero_Arguin.jpg",2048,1536,"貝塚"]]},{"id":"12_ubayama","n":"姥山貝塚（竪穴住居の家族骨）","yomi":"うばやまかいづか","cat":"遺跡","rank":"A","y":-2500,"era":["jomon"],"sh":"国指定史跡","ad":"市川市柏井町","st":"JR武蔵野線 船橋法典駅から歩いて約25分","la":35.7414,"lo":139.9661,"hook":"一つの家の床から、大人と子ども5人の骨――。縄文のむらで、いったい何が起きたのか。","lead":"姥山貝塚は、市川市にある縄文時代の大きな貝塚です。1926年の発掘で、日本ではじめて竪穴住居のあとが丸ごと調べられました。ある家のあとからは5人分の人骨がいっしょに見つかり、いまも «なぜ?» という謎をなげかけています。国の史跡です。","story":["1926年、市川の台地で大がかりな発掘が行われました。大学の研究者たちが土をていねいにとりのぞいていくと、地面に丸いくぼみがあらわれます。柱のあな、炉のあと――。それは縄文人が暮らした «竪穴住居» のあとでした。","それまで、竪穴住居のあとを最後まで調べきった例は、日本にはありませんでした。«縄文人の家は、こんな形だったのか»。姥山貝塚は、縄文人の住まいの姿をはっきり示した、記念すべき遺跡になったのです。","竪穴住居は、地面を丸く掘りさげて床をつくり、柱を立てて屋根をかけた家です。まんなかには火をたく炉があり、冬でも中は意外とあたたかかったといわれます。家族はこの炉をかこんで、貝や魚、木の実を料理し、眠りました。姥山の台地には、こうした家がいくつも建ちならび、大きな貝塚がそれをかこんでいました。","そして研究者たちをおどろかせたのが、ある住居あとの床から見つかった、5人分の人骨でした。大人の男女と子どもたち。まるで家のなかで、そのまま息をひきとったかのように横たわっていました。«家族だったのだろうか» «なぜいっしょに亡くなったのか»。","答えはまだ出ていません。食中毒、病気のはやり、家の事故など、いくつもの説があります。ふつう縄文人は亡くなった人を貝塚などにほうむりました。家の中にいっしょにいたのは、何か特別なことが起きたしるしなのかもしれません。5人の骨は、4000年以上前のむらの悲しい出来事を、静かに伝えています。","姥山貝塚はいま、公園として保存されています。広い芝生の下には、たくさんの住居あとや貝の層がねむっています。見学のときは、この地で暮らし、ここでねむった人びとに思いをはせ、静かに歩きたい場所です。"],"tl":[["約5000〜4000年前","縄文時代中期〜後期にむらがいとなまれる"],["明治時代","貝塚として知られ、調査が行われる"],["1926年","竪穴住居あとの全体が調べられ、5人の人骨が見つかる"],["1967年","国の史跡に指定"]],"who":[["縄文時代の人びと","この台地にむらをつくり、貝や木の実をとって暮らした"],["松村瞭","東京帝国大学の人類学者。1926年の調査にかかわった"]],"deep":["姥山貝塚も東京湾東岸に多い馬蹄形貝塚の一つ。縄文中期から後期にかけて長くむらが続いた。","1926年の調査は、竪穴住居を平面的に掘りあげた日本で最初期の例とされ、住居研究の出発点になった。","5体の人骨が出た住居については、同時に死亡したのか、時期をずらして葬られたのかも議論がある。","フグ毒などの食中毒説がよく紹介されるが、確かめる方法はなく推測の域を出ない。","多くの人骨が出たことから、縄文人の身長や病気、年齢構成などを調べる人類学研究の重要な資料になった。","台地の上の貝塚は長い年月をかけて積もったもので、どの家が同じ時期に建っていたのかを見きわめるのは難しい。むらの人数の推定にも幅がある。"],"look":["公園になった貝塚の広がり","住居あとの位置を示す表示","案内板の発掘当時の写真","市立市川考古博物館の出土品（あわせて見学）"],"q":["姥山貝塚が日本の考古学で «はじめて» だったことは？","竪穴住居のあとを丸ごと調べきったこと（1926年）。縄文人の家の姿がはっきりしました。"],"koji":[],"myth":"5人がいっしょに亡くなった理由（食中毒など）は推測で、諸説あり。","img":["竪穴建物","貝塚"],"wp":"姥山貝塚","rel":{"ev":[],"grave":[]},"ph":[["c:6/64/Ubayama20120519.jpg",800,451,"姥山貝塚"],["c:5/5a/Yoshinogari-iseki_tateanashiki-juukyo.JPG",6016,4000,"竪穴建物"],["c:8/83/Conchero_Arguin.jpg",2048,1536,"貝塚"]]},{"id":"12_nagareyama_kondo","n":"流山 近藤勇陣屋跡（新選組局長 最後の地）","yomi":"ながれやま こんどういさみじんやあと","cat":"幕末","rank":"A","y":1868,"era":["edo"],"sh":"","ad":"流山市流山2丁目","st":"流鉄流山線 流山駅から歩いて約5分","la":35.8561,"lo":139.9019,"hook":"«大久保大和» と名を変え、ひとりで敵陣へ。新選組局長・近藤勇が自由だった最後の場所。","lead":"流山の近藤勇陣屋跡は、1868年、新選組局長・近藤勇が最後に陣をおいた場所です。ここで新政府軍に囲まれた近藤は自ら出頭し、やがて板橋で処刑されました。陣屋に使われた酒造家の建物は残っておらず、今は碑が立つ «跡» です。","story":["1868年のはじめ、京都の鳥羽・伏見の戦いで旧幕府軍はやぶれました。江戸にもどった近藤勇たちは «甲陽鎮撫隊» をつくって甲州へ向かいますが、ここでもやぶれます。«まだ終わらない»。近藤と土方歳三は兵を集めなおし、江戸川ぞいの流山にやってきました。","近藤たちが本陣にしたのは、流山の酒造家 «長岡屋» の建物だったと伝わります。流山はみりんづくりで栄えた川の町。近くの寺や広場で、兵の訓練が行われたともいわれます。けれど、流山にいたのはわずか数日でした。","4月のはじめ（旧暦）、新政府軍が流山をとりかこみました。戦えば町が戦場になり、兵も町の人も大勢が命を落とします。近藤は «大久保大和» という名で、ひとり新政府軍の陣へ出向きました。なぜ出頭したのか――。町を守るため、時間をかせぐため、ごまかしきれると考えたため……さまざまな説があります。","土方歳三は、近藤を助けようと江戸へ走り、勝海舟らに助けを求めたといわれます。しかし近藤の正体は見やぶられ、4月25日、板橋で処刑されました。35歳でした。ここで別れた近藤と土方は、二度と会うことはありませんでした。","いま陣屋跡には «近藤勇陣屋跡» の碑が立ち、毎年多くの新選組ファンが訪れます。ここは、ある時代の終わりに、一人の人間が大きな決断をした場所です。近くの流山の町なみや江戸川の土手も歩き、当時の空気を想像してみましょう。"],"tl":[["1868年1月","鳥羽・伏見の戦いで旧幕府軍がやぶれる"],["1868年3月","甲陽鎮撫隊が甲州勝沼の戦いでやぶれる"],["1868年4月初め（旧暦）","近藤勇らが流山に陣をおく"],["同じころ","新政府軍に囲まれ、近藤が «大久保大和» として出頭"],["1868年4月25日（旧暦）","近藤勇が板橋で処刑される"],["1869年","土方歳三が箱館で戦死"]],"who":[["近藤勇","新選組局長。流山で出頭し、板橋で処刑された"],["土方歳三","新選組副長。近藤と流山で別れ、のち箱館で戦死"],["勝海舟","旧幕府の重臣。土方が近藤の助命を頼んだとされる"],["長岡屋","近藤らが本陣にしたと伝わる流山の酒造家"]],"deep":["近藤が名乗った «大久保大和» は、それ以前から使っていた変名。新政府軍の中に近藤の顔を知る者がいたため正体が発覚したといわれる。","出頭の理由は諸説。«戦わずに町を守った» という話は後に広まったもので、当時の近藤の考えを直接示す史料は少ない。","流山の陣屋にいた期間は数日とされる。兵の数は200人ほどともいわれるが、資料によってちがう。","近藤の首は京都の三条河原でさらされたとされ、墓・供養塔は東京・板橋、三鷹、会津などにある。","流山は江戸川水運で栄え、白みりんの産地として知られた。近藤が来たころも商家が立ちならぶ町だった。"],"look":["«近藤勇陣屋跡» の碑","流山の旧街道の町なみ","江戸川の土手（当時の水運を想像）","流山市立博物館の関連展示"],"q":["流山で出頭したとき、近藤勇が名乗った名前は？","«大久保大和»。正体を隠していましたが、やがて見やぶられました。"],"koji":[],"myth":"出頭の理由、土方と勝海舟のやりとり、兵の数などは諸説。ドラマ・小説の描写は創作を含む。","img":["土方歳三","新選組","甲州勝沼の戦い"],"wp":"近藤勇","rel":{"ev":[],"grave":[]},"ph":[["c:b/b2/Kondo_Isami02.jpg",658,954,"近藤勇"],["c:1/18/Grave_of_Isami_Kondou.jpg",2160,3840],["c:9/90/Matudaira_Katamori.jpg",993,1548],["c:b/b1/KoshuKatsunuma.jpg",1600,766],["c:5/56/Kondo_Isami.jpg",900,1348],["c:0/07/%E5%A4%AA%E6%94%BF%E5%AE%98%E6%97%A5%E8%AA%8C%E6%85%B6%E5%BF%9C4%E5%B9%B4%E9%96%8F4%E6%9C%88%E5%A4%A7%E4%B9%85%E4%BF%9D%E5%A4%A7%E5%92%8C%EF%BC%88%E8%BF%91%E8%97%A4%E5%8B%87%EF%BC%89%E6%B5%81%E5%B1%B1%E6%8D%95%E7%B8%9B.png",792,631],["c:d/d9/Kondo-jinja.jpg",730,548],["c:e/ee/Hijikata_Toshizo.jpg",528,924,"土方歳三"]]},{"id":"12_koganemaki","n":"小金牧（幕府の野馬の牧）","yomi":"こがねまき","cat":"産業","rank":"A","y":1725,"era":["edo","meiji"],"sh":"国指定史跡","ad":"鎌ケ谷市中沢（下総小金中野牧跡・捕込）","st":"東武アーバンパークライン 鎌ヶ谷駅から歩いて約25分","la":35.77,"lo":140.005,"hook":"«初富»«二和»«三咲»……千葉の地名が «数字» で並ぶのはなぜ? 答えは、幕府の馬の牧場にある。","lead":"小金牧は、江戸幕府が下総の台地に設けた広い馬の放牧場です。野生に近い馬 «野馬（のま）» を放し、軍馬などに使う馬を育てました。鎌ケ谷市には、馬を追いこんで捕まえた «捕込（とっこめ）» と土手が残り、«下総小金中野牧跡» として国の史跡になっています。","story":["いまの松戸・柏・鎌ケ谷・船橋あたりの台地は、江戸時代、見わたすかぎりの草原でした。そこを走り回っていたのは、何百頭もの馬。幕府はこの台地を «小金牧» とよび、馬を放し飼いにして育てていました。","放し飼いといっても、馬が村の畑に入ってしまっては大変です。そこで人びとは、牧のまわりに長い土手をきずきました。«野馬土手» です。高さは人の背たけほど。いまも住宅地や林のなかに、ところどころ土手が残っています。","年に一度、馬を集める «野馬捕り» が行われました。近くの村人が大勢かり出され、草原にちらばった馬を追い立てて、土手でかこんだ «捕込» に追いこみます。よい馬が選ばれて、江戸へ送られました。«馬を追う声が台地にひびいた»。まるでお祭りのようなにぎわいだったといわれます。","8代将軍・徳川吉宗は、1725年と1726年にこの小金原で大がかりな «鹿狩り» を行いました。武士たちの訓練をかねた一大イベントです。その後の将軍も、ここで鹿狩りをしています。小金牧は、将軍の権威を見せる舞台でもあったのです。","明治になると、牧はその役目を終えます。職を失った江戸の人びとが開墾に送りこまれ、開墾された順番に «初富（はつとみ）» «二和（ふたわ）» «三咲» «豊四季» «五香» «六実» «七栄» «八街» ……と名前がつけられました。今も駅名や地名に残る «数字の地名» は、小金牧の開墾の記憶なのです。"],"tl":[["江戸時代初め","幕府が下総の台地に牧を整える"],["1725年・1726年","徳川吉宗が小金原で鹿狩りを行う"],["江戸時代","野馬奉行のもとで野馬捕りが行われる"],["1869年","明治政府のもとで牧の開墾が始まる"],["明治初め","開墾地に «初富»«二和»«三咲» などの地名がつけられる"],["2007年","鎌ケ谷市の捕込などが «下総小金中野牧跡» として国の史跡に"]],"who":[["徳川吉宗","8代将軍。小金原で大規模な鹿狩りを行った"],["綿貫氏","代々、野馬奉行として小金牧を管理した家"],["明治の開墾者たち","牧の跡地を開墾し、新しい村をつくった"]],"deep":["小金牧は、高田台牧・上野牧・中野牧・下野牧・印西牧などの牧から成っていた。佐倉周辺の «佐倉牧» とあわせて下総は幕府の馬の一大産地だった。","捕込は土手で囲んだ区画で、馬を追いこんで選別した施設。鎌ケ谷市中沢の捕込は形がよく残る貴重な遺構。","明治の開墾地名は開墾の順番にちなむとされ、初富（鎌ケ谷）、二和・三咲（船橋）、豊四季（柏）、五香・六実（松戸）、七栄（富里）、八街（八街市）、九美上（香取）、十倉（富里）、十余一・十余二・十余三（白井・柏・成田など）と続く。","開墾は東京の窮民対策として始まったが、土地がやせていたうえ、制度もうまくいかず、多くの人が苦労したとされる。","野馬土手は開発で多くが失われたが、各地の緑地にあとが残る。自治体が保存と案内に取り組んでいる。"],"look":["鎌ケ谷市の «捕込» あとの土手","住宅地や林に残る野馬土手","鎌ケ谷市郷土資料館の展示","駅名・地名の «数字の地名» さがし"],"q":["«初富»«二和»«三咲» など、数字が入った地名の由来は？","明治に小金牧などの跡地を開墾した順番にちなんだ名前です。"],"koji":[],"myth":"開墾地名の順番・由来の細部には異説もある。","img":["野馬土手","徳川吉宗","佐倉牧"],"wp":"小金牧","rel":{"ev":[],"grave":[]},"ph":[["c:d/dc/MET_DP149423.jpg",3667,1873],["c:8/80/%E4%B8%8A%E9%87%8E%E7%89%A7%E9%AB%98%E7%94%B0%E5%8F%B0%E7%89%A7%E8%A9%B3%E7%B4%B0%E5%9B%B3.jpg",2000,2500],["c:2/24/S3p15106-%E9%87%8E%E9%A6%AC%E5%A0%80.jpg",1200,1500],["c:8/80/Kogane_shimonomaki.png",1298,1121],["c:f/f6/%E5%B0%8F%E9%87%91%E7%89%A7%E4%B8%AD%E9%87%8E%E7%89%A7.png",1172,1142],["c:0/0a/Koganemaki_inzaimaki.PNG",1519,868],["c:9/9f/Nomadshounai.png",1075,1098],["c:4/4b/Kaminomaki.png",828,1130]]},{"id":"12_noda_shoyu","n":"野田の醤油醸造（キッコーマン）","yomi":"のだのしょうゆじょうぞう","cat":"産業","rank":"A","y":1661,"era":["edo","meiji","taisho"],"sh":"","ad":"野田市野田","st":"東武アーバンパークライン 野田市駅から歩いてすぐ〜約10分","la":35.954,"lo":139.868,"hook":"町に入ると、ふわりと香る醤油のにおい。江戸の台所を支えた «しょうゆの町» 野田。","lead":"野田は、江戸時代から醤油づくりで栄えた町です。利根川と江戸川にはさまれ、大豆や小麦、塩を船で集め、できた醤油を江戸へ運びました。醸造家たちが大正時代に一つの会社にまとまり、それが今のキッコーマンにつながっています。","story":["野田市駅を降りると、どこからか香ばしいにおいがただよってきます。醤油のにおいです。野田は、江戸時代から300年以上、醤油をつくり続けてきた町。«野田の醤油» は、江戸の人びとの台所に欠かせないものでした。","野田で醤油づくりが始まったのは、戦国時代とも、江戸時代のはじめともいわれます。1661年、高梨兵左衛門が醤油づくりを始めたと伝わり、やがて茂木家なども加わって、たくさんの醸造家が集まりました。なぜ野田だったのでしょう?","答えは «川» です。野田は利根川と江戸川にはさまれた町。関東の平野でとれた大豆や小麦、銚子や行徳の塩を船で集めることができ、できた醤油は江戸川をくだって、1日ほどで江戸に届きました。材料も、お客さんも、川がつないでくれたのです。","江戸の人びとは、それまで関西から来る «下りもの» の醤油を使っていました。けれど江戸の町が大きくなると、関東の «濃口醤油» が好まれるようになります。野田と銚子は、関東の醤油の二大産地になりました。","1917年、野田の茂木家・高梨家などの一族8家が集まり、«野田醤油株式会社» をつくりました。これがのちのキッコーマンです。その後、1927年から翌年にかけて、働く人たちが待遇の改善を求める大きな労働争議も起きました。いまも町には、古い醸造家の屋敷や、工場の見学施設があり、醤油の香りとともに歴史を感じることができます。"],"tl":[["1661年","高梨兵左衛門が醤油づくりを始めたと伝わる"],["江戸時代後期","野田が銚子とならぶ関東の醤油の大産地となる"],["1917年","野田の醸造家8家が合同し、野田醤油株式会社を設立"],["1927〜1928年","野田醤油で大規模な労働争議が起きる"],["1964年","社名をキッコーマン醤油に変更（1980年にキッコーマン）"]],"who":[["高梨兵左衛門","野田で醤油づくりを始めたと伝わる醸造家"],["茂木佐平治","茂木家の醸造家。«亀甲萬» の商標で知られる"],["茂木七左衛門","茂木家の醸造家。野田の醤油業をひっぱった"]],"deep":["«キッコーマン» の名は、茂木佐平治家の商標 «亀甲萬（きっこうまん）» から。亀の甲羅の六角形に «萬» の字を入れたマーク。","野田醤油の労働争議は約200日以上続いた、戦前の日本でもっとも長い争議の一つとされる。","野田には宮内庁に納める醤油をつくる «御用蔵» があり、昔ながらの木桶で醤油がつくられている。","高梨家の屋敷は «上花輪歴史館» として公開され、庭園は国の名勝。醸造家の暮らしを知ることができる。","野田の醤油づくりの始まりについては、戦国時代に飯田市郎兵衛が始めたとする伝承もあり、諸説ある。"],"look":["キッコーマンもの知りしょうゆ館（工場見学）","御用蔵の外観","上花輪歴史館（高梨家の屋敷と庭園）","野田市郷土博物館・市民会館（旧茂木佐平治邸）","町なかの醸造家の古い建物"],"q":["キッコーマンという名前は、何から来ている？","茂木佐平治家の醤油の商標 «亀甲萬（きっこうまん）» からです。"],"koji":[],"myth":"醤油づくりの始まり（1661年・高梨兵左衛門など）は伝承で諸説あり。","img":["醤油","上花輪歴史館","野田争議"],"wp":"キッコーマン","rel":{"ev":[],"grave":[]},"ph":[["c:2/26/Kikkoman_headoffice_ac.jpg",5816,3867,"キッコーマン"],["c:8/8d/Whale_Sarami_%26_Soy_sauce.jpg",4000,3000],["c:9/9b/Walk_from_Toranomon_to_Ginza_%2871075%29.jpg",4080,3072],["c:1/19/Noda_Keyakino_Hall_ac_%281%29.jpg",5947,3954],["c:0/05/Kikko_noda_1950.jpg",1280,2657],["c:e/e9/Kikkoman_soysauce.jpg",883,1024],["c:6/63/Soy_sauce_2.jpg",1062,889,"醤油"],["c:1/17/Tsuneko-Akamatsu-2.jpg",486,705,"野田争議"]]},{"id":"12_inubosaki","n":"犬吠埼灯台","yomi":"いぬぼうさきとうだい","cat":"近代","rank":"A","y":1874,"era":["meiji"],"sh":"国の重要文化財","ad":"銚子市犬吠埼","st":"銚子電鉄 犬吠駅から歩いて約7分","la":35.7075,"lo":140.8687,"hook":"関東でいちばん早く朝日がのぼる岬に、明治7年から光をともし続ける白いレンガの塔。","lead":"犬吠埼灯台は、銚子市の太平洋につき出た岬に立つ灯台です。1874年に初めて光をともし、イギリス人技師ブラントンが設計しました。日本でつくったレンガで建てられた、明治の灯台の代表で、2020年に国の重要文化財になりました。今ものぼることができる «のぼれる灯台» です。","story":["銚子の東のはし、犬吠埼。目の前は太平洋、足もとでは岩に波がくだけ、白いしぶきが上がります。このあたりの海は、黒潮と親潮がぶつかる潮の流れの複雑なところ。昔から船の遭難が多く、船乗りにとっては «こわい海» でした。","明治のはじめ、日本は外国と貿易を始め、たくさんの船が日本の近くを通るようになりました。«夜でも安全に船が進めるように、岬に灯台を»。政府はイギリスから技師 «リチャード・ヘンリー・ブラントン» をまねき、全国に灯台を建てていきます。犬吠埼の灯台も、その一つでした。","問題は材料でした。高い塔をつくるにはたくさんのレンガがいります。当時、質のよいレンガは外国から買うのがふつうでした。けれど犬吠埼では、国内でつくったレンガを使うことになりました。職人たちは試行錯誤しながらレンガを焼き、約19万枚ともいわれるレンガで塔をつみあげました。","1874年11月15日、灯台に初めて光がともりました。暗い海にまっすぐのびる光の帯。«ああ、これで岬が見える»。遠くの船の人びとは、どんなに心強く思ったことでしょう。それから150年近く、灯台は台風の日も、戦争のときも、ほとんど休まず海を照らしてきました。","灯台の中のらせん階段は99段。のぼりきると、目の前には水平線がぐるりと広がります。地球が丸く見えるといわれるほどの大パノラマです。お正月には、平地では日本でいちばん早い初日の出を見ようと、多くの人が集まります（離島や山頂を除く）。"],"tl":[["1872年","灯台の建設が始まる（着工時期は資料により表記が分かれる）"],["1874年11月15日","犬吠埼灯台が初めて点灯"],["1945年","戦争中、空襲などで被害を受ける"],["2020年","国の重要文化財に指定"],["2024年","初点灯から150年をむかえる"]],"who":[["リチャード・ヘンリー・ブラントン","イギリス人技師。日本各地の灯台を設計し «日本の灯台の父» とよばれる"],["中沢孫右衛門","国産レンガの製造にかかわったと伝わる人物"]],"deep":["高さは地上から約31m。日本に十数基ある «のぼれる灯台» の一つ。","使われたレンガは国産で、約19万3000枚といわれる。国産レンガでつくられた洋式灯台として早い時期の例。","灯台には大型の «第1等フレネル式レンズ» が使われている。レンズの展示は隣の資料展示館で見られる。","犬吠埼の周辺は白亜紀の地層が見られる場所として、国の天然記念物 «犬吠埼の白亜紀浅海堆積物» に指定されている。","«犬吠» の地名は、源義経の愛犬がこの岬で鳴き続けたからという伝説があるが、もちろん伝説にすぎない。"],"look":["灯台の99段のらせん階段と展望","灯台資料展示館のフレネルレンズ","岬の岩場と白亜紀の地層","初日の出スポット","銚子電鉄の犬吠駅"],"q":["犬吠埼灯台のらせん階段は何段？","99段。のぼると太平洋が一望できます。"],"koji":[],"myth":"«犬吠» の地名の由来（義経の犬など）は伝説。レンガ枚数・製造者は資料による。","img":["リチャード・ヘンリー・ブラントン","犬吠埼","フレネルレンズ"],"wp":"犬吠埼灯台","rel":{"ev":[],"grave":[]},"ph":[["c:a/a5/Cape_Inubo_06.jpg",2592,3888,"犬吠埼灯台"],["c:d/dc/%E7%8A%AC%E5%90%A0%E5%9F%BC%E7%81%AF%E5%8F%B0%E3%81%8B%E3%82%89%E3%81%AE%E9%A2%A8%E6%99%AF_-_panoramio_%281%29.jpg",5184,3456],["c:6/62/%E7%8A%AC%E5%90%A0%E5%9F%BC%E7%81%AF%E5%8F%B0%E3%81%8B%E3%82%89%E3%81%AE%E9%A2%A8%E6%99%AF_-_panoramio.jpg",5184,3456],["c:9/96/%E7%8A%AC%E5%90%A0%E5%9F%BC_-_panoramio_%284%29.jpg",4752,3168],["c:f/ff/Inub%C5%8Dsaki_Lighthouse_under_the_full_of_stars_-_Cape_Inub%C5%8D_-_Ch%C5%8Dshi%2C_Chiba_-_Japan_-_8_June_2013.jpg",4928,3280],["c:f/f4/Inubousaki_lighthouse_vs_white_post_%289008542126%29.jpg",3224,4844],["c:9/93/InubosakiLighthouseGate.JPG",3000,4000],["c:6/67/InubosakiLighthouseFoghorn.JPG",4000,3000]]},{"id":"12_daiichi_kaiho","n":"第一海堡（東京湾要塞）","yomi":"だいいちかいほ","cat":"近代","rank":"A","y":1890,"era":["meiji","taisho","showa"],"sh":"","ad":"富津市富津（富津岬の沖）","st":"上陸は原則できない。JR青堀駅からバスで富津公園へ行き、富津岬の展望台から見る","la":35.3142,"lo":139.7856,"hook":"海の上に、人の手で島をつくった。首都を守るため、明治の人びとが東京湾にきずいた «人工の島の砦»。","lead":"第一海堡は、明治時代に東京湾の入口を守るため、富津岬の沖の海の中につくられた人工島の砲台です。1881年に工事が始まり、1890年に完成しました。いまは許可がないと上陸できず、富津岬の展望台から見ることができます。","story":["富津岬の先にある展望台にのぼると、海の向こうに小さな島が見えます。まっすぐな岸、四角い形。自然の島ではありません。明治の人びとが、海に石と土を積みあげてつくった «第一海堡（かいほ）» です。","明治のはじめ、日本は外国の軍艦が東京湾に入ってくることを心配していました。幕末には黒船が江戸湾にやってきて、人びとをおどろかせたばかりです。«東京を守るには、湾の入口をふさぐしかない»。いちばんせまくなる富津と観音崎のあいだに、砲台をならべる計画が立てられました。","でも、海のまんなかには陸地がありません。そこで考えられたのが、海に島をつくることでした。石を運び、海底に積みあげ、まわりを石垣でかためる。波や潮の流れとたたかう、大変な工事でした。1881年に始まった工事は、完成までに9年ほどかかりました。","できあがった島の上には、砲台や弾薬をしまう部屋、兵士が寝とまりする建物がつくられました。まわりはすべて海。水も食べものも、船で運んでくるしかありません。潮風と波の音のなか、兵士たちは来るかもしれない敵の軍艦にそなえて、毎日見張りを続けたのです。","第一海堡には大砲がそなえられ、のちに第二・第三の海堡もつくられました。けれど1923年の関東大震災で、海堡は大きな被害を受けます。とくに第三海堡はくずれ、そののち取りのぞかれました。第一海堡は形を残し、戦争が終わるまで東京湾の守りの一部であり続けました。","実際に敵の船と戦うことはないまま、戦後、海堡は役目を終えました。いま島は立入禁止で、ふだんは上陸できません（限定の上陸ツアーが行われたこともあります）。展望台から、青い海にうかぶ小さな島をながめて、明治の人びとが «海に島をつくる» と決めたときの気持ちを想像してみましょう。"],"tl":[["1853年","ペリーの黒船が江戸湾に来航"],["1881年","第一海堡の工事が始まる"],["1890年","第一海堡が完成"],["1890年代〜1920年代","第二海堡・第三海堡がつくられる"],["1923年","関東大震災で海堡が被害を受ける"],["1945年","終戦。海堡は役目を終える"]],"who":[["明治の陸軍","東京湾要塞の一部として海堡を計画・建設した"],["工事にたずさわった人びと","石材を運び、海の中に島をきずいた"]],"deep":["東京湾要塞は、観音崎・富津・猿島などに砲台をならべ、湾口を守るしくみ。海堡はその海上部分にあたる。","第一海堡の面積は約2〜3ha程度とされ、周囲を石積みで固めた人工島。","第二海堡は1914年、第三海堡は1921年に完成したとされる。第三海堡は震災で崩れ、航路の安全のため撤去が進められた。","第一海堡は国有地で、管理者の許可なく上陸することはできない。","第一海堡では、戦後に残った砲台や兵舎の基礎、石積みの護岸などが確認されており、明治の土木技術を知る遺構として注目されている。","富津岬と第一海堡のあいだは浅瀬で、岬の先から島まではそれほど遠くない。岬の地形を利用して、湾口をせばめるように砲台を配置する考え方だった。"],"look":["富津岬の展望台（明治百年記念展望塔）からの第一海堡","富津公園に残る旧陸軍の施設のあと","晴れた日の対岸・観音崎方面のながめ"],"q":["第一海堡は何でできた島？","人工島。海の中に石と土を積み、石垣で固めてつくりました。"],"koji":[],"myth":"上陸ツアーの実施状況は年によってかわる。","img":["東京湾要塞","第二海堡","第三海堡","富津岬"],"wp":"第一海堡","rel":{"ev":[],"grave":[]},"ph":[["c:2/20/Tokyo_Bay_Fort_No._2_Lighthouse.jpg",4853,3235],["c:2/2f/Ruin_of_Tokyo_Bay_Fort_No._2.jpg",5472,3648],["c:9/94/Second_Sea_Fort_aerial_photograph.jpg",3985,2989],["c:f/ff/Sea_Fort_No2_of_Tokyo_Bay_20200113_153629.jpg",4608,2592],["c:9/96/Tokyo_Bay_Fort_No.1.jpg",2505,2171],["c:7/76/Fort_No.1_in_Tokyo_Bay_fortress.JPG",1411,903],["c:2/2e/Fort_No1_tokyobay_mlit1974.jpg",932,699],["c:4/4f/Fort_No2_tokyobay_mlit1988.jpg",828,621]]},{"id":"12_akayama_go","n":"赤山地下壕跡","yomi":"あかやまちかごうあと","cat":"昭和","rank":"A","y":1944,"era":["showa"],"sh":"","ad":"館山市宮城","st":"JR内房線 館山駅から車で約10分（バスと徒歩でも行ける）","la":34.9776,"lo":139.8356,"hook":"小さな山の中に、全長約1.6kmの暗い迷路。ヘルメットをかぶって、戦争の記憶の中へ入る。","lead":"赤山地下壕跡は、館山市の «赤山» という小さな山の中に掘られた、太平洋戦争のころの地下壕です。全長は約1.6kmあり、近くにあった館山海軍航空隊とかかわる施設だったと考えられています。一部が公開され、ヘルメットをかぶって見学できます。","story":["館山の町から少しはなれた、田んぼのなかの小さな山。入口で受付をすませ、ヘルメットと懐中電灯を借りて一歩中へ入ると、ひんやりとした空気がからだをつつみます。ここは «赤山地下壕»。山の中に、何本もの通路が迷路のようにのびています。","このあたりには、1930年に開かれた «館山海軍航空隊» がありました。戦争がはげしくなると、空からの攻撃にそなえて、大事な施設を地下へ移す必要が出てきました。赤山の地下壕は、そうした目的で掘られたと考えられています。","通路のかべをよく見ると、ツルハシで掘ったあとがのこっています。ここは、かたい岩ではなく、比較的やわらかい地層。«人の手で、これだけの長さを掘ったのか»。そう思うと、ここで働いた人たちの苦労がしのばれます。","壕の中を進むと、通路が枝分かれし、ところどころに広い部屋のような空間があらわれます。天井は高いところもあれば、頭をかがめたくなるほど低いところも。明かりを消せば、一寸先も見えない真っ暗やみです。空襲のサイレンが鳴るたび、人びとはこの暗やみの中に身をひそめたのでしょうか。","じつは、いつ誰が掘りはじめたのか、何に使われたのかについては、はっきりしない点が多いのです。終戦のときに多くの記録が処分されたためです。戦闘指揮所、病院、発電所、兵器の倉庫……地元の聞き取りなどから、さまざまな使い道があったと考えられています。","館山市は、戦争の記憶を伝える場所として地下壕を整備し、見学できるようにしました。暗い通路を歩くと、戦争のなかで人びとがどんな思いで暮らしていたのか、考えずにはいられません。ここは、平和の大切さを静かに語りかける場所です。"],"tl":[["1930年","近くに館山海軍航空隊が開かれる"],["1930年代後半〜1940年代","赤山の地下壕が掘られる（時期は諸説）"],["1945年","終戦。地下壕は使われなくなる"],["2000年代","館山市が整備し、一般公開を始める"]],"who":[["館山海軍航空隊","近くにあった海軍の航空隊。地下壕とのかかわりが考えられている"],["掘削にかかわった人びと","地下壕を掘った兵士や作業員たち"],["地元の人びと","戦後、聞き取りや保存運動で記憶を伝えてきた"]],"deep":["全長は約1.6kmとされ、公開されているのはその一部。内部は通路と部屋状の空間が組み合わさっている。","掘削の開始時期については、1930年代後半とする説と、戦争末期とする説などがあり、確定していない。","用途は、航空隊の司令部・病院・発電所・倉庫などが考えられているが、公的記録が乏しく、証言による部分が大きい。","壕の地層は房総半島南部の比較的やわらかい堆積岩で、手掘りで長い通路を掘ることができた。","赤山の近くには «掩体壕（えんたいごう）» という、飛行機を空襲から守るためのコンクリートの格納庫も残っている。","壕内は一年中気温がほぼ一定で、夏はすずしく冬はあたたかい。見学のときは足もとが悪い場所もあるので、歩きやすい靴で行くのがよい。"],"look":["地下壕内部の通路と部屋","壁に残る掘削のあと","入口の案内展示","近くの掩体壕"],"q":["赤山地下壕の全長はおよそ何km？","約1.6km。その一部をヘルメットをかぶって見学できます。"],"koji":[],"myth":"掘削時期・用途は諸説。公開日・料金は変わることがあるので事前に確認を。","img":["館山海軍航空隊","掩体壕","防空壕"],"wp":"赤山地下壕跡","rel":{"ev":[],"grave":[]},"ph":[["c:4/42/Akayama_Underground_Tunnels_1.jpg",5472,3648,"赤山地下壕跡"],["c:6/6c/%E8%B5%A4%E5%B1%B1%E5%9C%B0%E4%B8%8B%E5%A3%95%E5%86%85%E9%83%A8.jpg",5184,3456],["c:1/1d/Akayama_Underground_Tunnels_4.jpg",5472,3648],["c:c/c9/Tateyama_city_Toyotsu_Hall.jpg",3535,2651],["c:f/f8/Typhoon_Takes_Off_from_RAF_Coningsby_as_Part_of_Op_Ellamy_MOD_45152517.jpg",3000,1805,"掩体壕"]]},{"id":"12_tateyama_kaigun","n":"館山海軍航空隊跡","yomi":"たてやまかいぐんこうくうたいあと","cat":"昭和","rank":"A","y":1930,"era":["showa"],"sh":"","ad":"館山市宮城","st":"JR内房線 館山駅から車で約10分。基地の中は原則見学できない","la":34.986,"lo":139.829,"hook":"«空の海軍» の若者たちが飛び立った館山の海。戦争が終わったあと、ここにアメリカ軍が上陸した。","lead":"館山海軍航空隊は、1930年に館山につくられた海軍の航空部隊です。多くのパイロットが訓練を受け、戦争中は東京湾を守る役目もになっていました。今はその場所に海上自衛隊の館山航空基地があり、ふだんは中に入れません。","story":["館山湾は、波がおだやかで、遠浅の海が広がる美しい湾です。1930年、この海べに海軍の航空隊がつくられました。«館山海軍航空隊»。当時、飛行機はまだ新しい兵器で、海軍は海から飛び立つ水上機や、陸上の飛行場を使う飛行機のパイロットを育てようとしていました。","訓練は、とてもきびしいものでした。まだ性能のよくない飛行機で、海の上をとぶ。事故で命を落とす若者もいました。«一人前のパイロットになるまで、何年もかかる»。多くの若者が、ここで空の技術を学び、やがて戦場へ向かっていきました。","太平洋戦争が始まると、館山は東京湾の入口を守る大事な基地になりました。まわりには、飛行機を空襲からかくすための «掩体壕» や、山をくりぬいた地下壕がつくられました。戦争の終わりが近づくと、若いパイロットたちの中には、特攻に向かった人もいました。","1945年8月、戦争が終わります。そして9月はじめ、館山にアメリカ軍の部隊が上陸しました。本土に上陸した占領軍の最初の部隊の一つで、館山では短い期間ですが、アメリカ軍が直接町を治める «直接軍政» がしかれたといわれます。町の人びとは、不安な気持ちで兵士たちをむかえたことでしょう。","いま、航空隊のあとには海上自衛隊の館山航空基地があり、ヘリコプターが海の安全を守っています。まわりには、掩体壕や赤山地下壕などの戦争遺跡が残り、地元では «戦争遺跡をめぐる» 見学会も行われています。ここで飛び立った人びと、帰らなかった人びとをしのびつつ、歩いてみましょう。"],"tl":[["1930年","館山海軍航空隊が開かれる"],["1941年","太平洋戦争が始まり、東京湾防衛の拠点となる"],["1945年8月","終戦"],["1945年9月","アメリカ軍が館山に上陸し、一時的に直接軍政がしかれたといわれる"],["戦後","跡地は海上自衛隊の館山航空基地となる"]],"who":[["館山海軍航空隊の隊員たち","この地で訓練を受け、戦地へ向かったパイロットや整備員"],["アメリカ軍の占領部隊","1945年9月に館山へ上陸した"],["館山の人びと","戦中・戦後の基地の町で暮らし、記憶を伝えてきた"]],"deep":["館山海軍航空隊は、横須賀についで早い時期につくられた海軍の実用機の航空隊の一つとされる。","館山への米軍上陸は1945年9月3日ごろとされ、4日間ほど直接軍政がしかれたという話が地元で伝えられている。細部には諸説がある。","周辺には、コンクリート製の掩体壕、赤山地下壕、砲台あとなど、多くの戦争遺跡が集中している。","館山市は «戦争遺跡保存» に積極的な自治体として知られ、市民による調査・ガイド活動もさかん。","海上自衛隊の館山航空基地では、年に一度ほど基地の一般公開が行われることがある。"],"look":["基地の外から見る滑走路と館山湾","宮城地区の掩体壕","赤山地下壕跡","館山湾（«鏡ケ浦»）の景色"],"q":["戦後、館山に上陸したのはどこの国の軍隊？","アメリカ軍。1945年9月に上陸し、短い期間、直接軍政がしかれたといわれます。"],"koji":[],"myth":"米軍の直接軍政の期間・内容の細部は諸説。基地内は原則非公開。","img":["館山航空基地","赤山地下壕跡"],"wp":"館山海軍航空隊","rel":{"ev":[],"grave":[]},"ph":[["c:9/97/Tateyama_airbase_aerial_photograph_1947.jpg",962,722],["c:9/98/Tateyama_Air_Base_Aerial_photo.jpg",3116,2337,"館山航空基地"],["c:4/42/Akayama_Underground_Tunnels_1.jpg",5472,3648,"赤山地下壕跡"]]},{"id":"12_rodrigo","n":"ドン・ロドリゴ漂着地（御宿・日西墨交流の始まり）","yomi":"どん・ろどりごひょうちゃくち","cat":"事件","rank":"A","y":1609,"era":["edo"],"sh":"","ad":"夷隅郡御宿町岩和田（メキシコ記念公園）","st":"JR外房線 御宿駅から車で約5〜10分","la":35.1849,"lo":140.3676,"hook":"嵐の夜、見知らぬ異国の船がくだけた。海女たちは冷えきった船乗りを、自分のからだで温めたと伝わる。","lead":"1609年、フィリピンからメキシコへ向かっていたスペインの船が、嵐のため御宿の岩和田の海岸で座礁しました。村の人びとは300人をこえる乗組員を助け、これが日本とスペイン・メキシコの交流の始まりとされています。丘の上には記念塔が立つ «メキシコ記念公園» があります。","story":["1609年の秋、太平洋は大あれでした。フィリピンのマニラから、メキシコのアカプルコへ向かうスペインの大型船 «サン・フランシスコ号»。乗っていたのは、フィリピンの臨時総督をつとめた «ドン・ロドリゴ・デ・ビベロ» です。船は嵐にもまれ、岩和田の岩場にたたきつけられました。","夜が明けると、浜辺には、ずぶぬれでふるえる外国人たちがいました。言葉も通じません。«助けるべきか、それとも……»。村人たちは迷わず手をさしのべました。着物を与え、食べものを分け、冷えきったからだを温めました。海女たちが自分のからだで船乗りを温めたという話も伝わっています。","船に乗っていた人のうち、およそ300人あまりが助かり、50人ほどが亡くなったといわれます。村は小さな漁村で、自分たちの食べものも決して多くはありませんでした。それでも、村人たちは救助した人びとを1か月以上も世話したといわれます。","知らせを受けた大多喜城主・本多忠朝はロドリゴを保護し、やがてロドリゴは江戸で将軍・徳川秀忠に、駿府で徳川家康に会いました。家康はスペイン領のメキシコとの貿易に関心をもっており、ロドリゴとも話し合いをしたといわれます。1610年、ロドリゴは家康が用意した船でメキシコへ帰りました。","それから300年以上たった1928年、岩和田の丘に «日西墨三国交通発祥記念之碑» が建てられました。いまはメキシコ記念公園として整備され、太平洋を見下ろしています。嵐の夜の小さな村の親切が、海の向こうの国との長い友情につながったのです。"],"tl":[["1609年","サン・フランシスコ号が岩和田の海岸で座礁"],["1609年","大多喜城主・本多忠朝がロドリゴを保護"],["1609年","ロドリゴが徳川秀忠・徳川家康と会見"],["1610年","ロドリゴが日本でつくられた船でメキシコへ帰る"],["1928年","«日西墨三国交通発祥記念之碑» が建てられる"],["現在","メキシコ記念公園として整備され、交流行事も行われる"]],"who":[["ロドリゴ・デ・ビベロ","フィリピンの臨時総督をつとめたスペイン人。御宿で救助された"],["本多忠朝","大多喜城主。ロドリゴを保護した"],["徳川家康","大御所。ロドリゴと会い、メキシコとの交易に関心を示した"],["岩和田の村人たち","遭難した乗組員を救助し、世話をした"]],"deep":["乗組員は約370人とされ、そのうち約317人が救助され、約50人が亡くなったといわれる。数字は資料によって多少ちがう。","ロドリゴの帰国には、ウィリアム・アダムス（三浦按針）が伊東で建造した船が使われたとされる。","ロドリゴは帰国後、日本での体験を記録に残しており、当時の日本社会を知る外国人の史料として知られる。","ロドリゴ一行の帰国船には日本人の商人らも同乗し、太平洋を横断してメキシコに渡ったとされる。","御宿町はメキシコのアカプルコ市と姉妹都市になっており、救助の歴史が現代の交流につながっている。"],"look":["メキシコ記念公園の記念塔","丘の上から見下ろす岩和田の海","田尻の浜（座礁地付近）","御宿町歴史民俗資料館の関連展示"],"q":["1609年に御宿で座礁した船に乗っていたスペイン人の名前は？","ドン・ロドリゴ・デ・ビベロ。フィリピンの臨時総督をつとめた人です。"],"koji":[],"myth":"海女が体で温めた話は伝承。救助人数・死者数は資料で差がある。","img":["本多忠朝","ウィリアム・アダムス","御宿町"],"wp":"ロドリゴ・デ・ビベロ","rel":{"ev":[],"grave":[]},"ph":[["c:0/06/Honda_Tadatomo.jpg",1396,1396,"本多忠朝"],["c:4/4c/William-Adams-before-Shogun-Tokugawa-Ieyasu.png",936,1461,"ウィリアム・アダムス"],["c:5/52/Moon-Desert_Onjuku.jpg",3072,2304,"御宿町"]]},{"id":"12_ohara_yugaku","n":"大原幽学遺跡（長部村・日本初の協同組合）","yomi":"おおはらゆうがくいせき","cat":"学び","rank":"A","y":1838,"era":["edo"],"sh":"国指定史跡","ad":"旭市長部","st":"JR総武本線 干潟駅から車で約10分","la":35.745,"lo":140.618,"hook":"«みんなで少しずつお金を出しあい、村の未来を守ろう»。ヨーロッパより早く生まれたといわれる、農民たちの協同組合。","lead":"大原幽学は、江戸時代の終わりに下総の長部村（いまの旭市）で、農民に生き方と農業のくふうを教えた人です。村人たちと «先祖株組合» をつくり、これは世界でも早い農業協同組合といわれます。幽学の旧宅や、村人と整えた田畑のあとが国の史跡として残っています。","story":["江戸時代の終わりごろ、下総の長部村は荒れていました。ききんや重い年貢で、村人の暮らしは苦しく、ばくちや争いごともたえません。«このままでは村がなくなってしまう»。そんな村に、一人の旅の学者がやってきました。大原幽学です。","幽学は、自分は尾張の武士の家に生まれたと語りましたが、若いころのことはよくわかっていません。各地を旅して学問を学び、«人が正しく生きる道» を説く «性学（せいがく）» という教えを始めました。むずかしい理屈ではなく、家族を大切にし、まじめに働き、村のみんなで助けあう――そんな生活の知恵でした。","1838年、幽学は村人たちと «先祖株組合» をつくりました。組合員は自分の田畑の一部を出しあい、そこからの収入を積み立てます。«先祖からの田畑を、子や孫に確実に残すために»。家がつぶれそうになったときは、この積立で助けました。イギリスのロッチデールで協同組合ができた1844年よりも早いことから、«世界初の農業協同組合» ともいわれます。","幽学は、田んぼの形を整えて使いやすくする «耕地整理» や、家の建て方、子どもの教育の方法まで教えました。村は少しずつよみがえり、ほかの村からも教えを受けに来る人がふえました。ところが、多くの人が集まることを、幕府はあやしく思います。幽学は取り調べを受け、長い裁判の末に、罰を受けることになりました。","1858年、長部村にもどった幽学は、自ら命を絶ちました。教えを守ってきた人びとへの責任を、自分なりに果たそうとしたのかもしれません。いま長部には、幽学が自分で設計したといわれる旧宅や、整えられた田畑のあとが残り、大原幽学記念館で、その生き方と村の人びとの努力を知ることができます。"],"tl":[["1797年","大原幽学が生まれる（出身は尾張と伝わる）"],["1830年代","下総の村々で教えを広め、長部村に住みつく"],["1838年","先祖株組合をつくる"],["1840年代","耕地整理や教育など、村の立て直しを進める"],["1850年代","幕府の取り調べを受け、処罰される"],["1858年","長部村で亡くなる（自害）"],["1952年","旧宅などが «大原幽学遺跡» として国の史跡に"]],"who":[["大原幽学","長部村で性学を教え、先祖株組合をつくった指導者"],["遠藤伊兵衛","長部村の名主。幽学をまねき、改革を支えた"],["長部村の人びと","幽学の教えを受け、組合と村の立て直しにとりくんだ"]],"deep":["先祖株組合は、各家が土地の一部を «先祖株» として出しあい、その利益を積み立てて家の存続を支えるしくみ。「協同組合の先駆け」とされる。","ロッチデール公正先駆者組合（1844年）は近代協同組合の出発点とされるが、先祖株組合はそれより早い。ただし «世界初» の評価には、定義による議論もある。","幽学の旧宅は、幽学自身が設計したと伝わる。簡素で合理的なつくりが特ちょう。","幕府が問題にしたのは、多くの人が集まる «教団» のような活動や、無届けの行動だったとされる。裁判は長く続いた。","出自については、尾張藩士の家に生まれたという本人の語り以外に確かな史料が少なく、諸説ある。"],"look":["大原幽学旧宅","整えられた田畑のあと（耕地整理の遺構）","大原幽学記念館の展示","幽学の墓"],"q":["大原幽学が村人とつくった、協同組合の先がけとされるしくみの名前は？","«先祖株組合»。土地の一部を出しあい、その利益を積み立てて家を守るしくみです。"],"koji":[],"myth":"出自（尾張藩士の家）は本人の語りで、確証は少ない。«世界初» の評価は定義による。","img":["協同組合","旭市"],"wp":"大原幽学","rel":{"ev":[],"grave":[]},"ph":[["c:2/21/%C5%8Chara_Y%C5%ABgaku%27s_Birthplace.jpg",1280,960],["c:a/a6/Grave_of_%C5%8Chara_Y%C5%ABgaku_in_Nagoya.jpg",960,1280],["c:2/2c/Michinoeki_asahi.jpg",4032,3024,"旭市"]]},{"id":"12_sogo","n":"宗吾霊堂（佐倉惣五郎）","yomi":"そうごれいどう","cat":"伝承","rank":"A","y":1653,"era":["edo"],"sh":"","ad":"成田市宗吾1丁目","st":"京成本線 宗吾参道駅から歩いて約15分","la":35.749,"lo":140.266,"hook":"«村のために、将軍へじかに訴える»。命をかけた名主の物語が、江戸の人びとの心をゆさぶった。","lead":"宗吾霊堂は、成田市にある東勝寺というお寺で、江戸時代の «義民» 佐倉惣五郎をまつっています。惣五郎は、重い年貢に苦しむ村人のため将軍に直訴し、処刑されたと伝えられます。この話は歌舞伎になって大人気となり、惣五郎は «宗吾さま» として信仰されるようになりました。","story":["江戸時代のはじめ、下総の佐倉藩。公津村の名主・惣五郎は、村人たちの苦しみを見ていました。年貢は重く、払えない家は田畑を手放すしかありません。«このままでは村がほろびる»。惣五郎は、仲間とともに藩や江戸の役所に訴えましたが、聞き入れてもらえませんでした。","物語では、惣五郎は最後の手段に出ます。上野の寛永寺にお参りに来た4代将軍・徳川家綱の行列の前にとびだし、訴えの文書をさしだしたのです。«直訴» は、身分のきびしい江戸時代には、命を失うほどの重い罪でした。","訴えはとどき、年貢は軽くなったといわれます。しかし惣五郎は罪に問われ、処刑されました。物語では、妻や幼い子どもたちまで命をうばわれたと語られます。«なぜ、そこまで»。人びとは惣五郎の勇気と悲しい最期に涙しました。","ただし、この物語のどこまでが本当かは、はっきりしていません。惣五郎という名主が公津村にいたことは記録から確かめられていますが、将軍への直訴や処刑のくわしい話は、江戸時代の後半に書かれた物語や、1851年に上演された歌舞伎『東山桜荘子（ひがしやまさくらそうし）』などで広まったものです。","いっぽうで、佐倉藩主の堀田家は、18世紀に惣五郎の霊をなぐさめる供養を行い、«宗吾道閑居士» という名を贈ったといわれます。こうして惣五郎は «宗吾さま» とよばれ、民衆の守り神になりました。いまの宗吾霊堂には、多くの人がお参りし、惣五郎一家の墓や、物語を人形で表した «御一代記館» があります。"],"tl":[["17世紀なかごろ","公津村の名主・惣五郎が年貢の軽減を訴えたと伝わる"],["1653年","惣五郎が処刑されたと伝わる（年は伝承）"],["1752年","惣五郎の百回忌にあたり、佐倉藩主の堀田氏が供養を行ったと伝わる"],["1851年","歌舞伎『東山桜荘子』が上演され、大評判になる"],["明治以降","自由民権運動などで «義民» のシンボルとされる"]],"who":[["佐倉惣五郎","公津村の名主。村人のため直訴したと伝わる義民"],["徳川家綱","4代将軍。物語で惣五郎が直訴した相手とされる"],["堀田正亮","佐倉藩主。惣五郎を供養したと伝わる"],["堀田正信","物語の時代の佐倉藩主とされる人物"]],"deep":["惣五郎の実在は、公津村の名寄帳（土地台帳）に «惣五郎» の名があることなどから確かめられているが、直訴の史実性は疑問視されている。","物語が広まったのは、江戸時代後期の実録本『地蔵堂通夜物語』や、歌舞伎『東山桜荘子』によるところが大きい。","当時の佐倉藩主・堀田正信は、のちに幕府を批判する意見書を出して改易された人物で、物語と結びつけて語られることがある。","明治時代には自由民権運動の人びとが惣五郎を «民衆のために立ちあがった英雄» としてたたえた。","宗吾霊堂は正式には «鳴鐘山東勝寺»。真言宗豊山派の寺院。"],"look":["宗吾霊堂の本堂","惣五郎一家の墓","物語を人形で表した «宗吾御一代記館»","参道の門前町"],"q":["佐倉惣五郎の物語を広めた歌舞伎の題名は？","『東山桜荘子』。1851年に上演され、大人気になりました。"],"koji":[{"w":"義民","m":"自分の身をぎせいにして、人びとのために立ちあがった人"}],"myth":"直訴・処刑・家族の処刑などの物語は、後世の実録本・歌舞伎による部分が大きく、史実としては不確か。","img":["宗吾霊堂","義民"],"wp":"佐倉惣五郎","rel":{"ev":[],"grave":[]},"ph":[["c:5/5c/%E4%BD%90%E5%80%89%E6%83%A3%E4%BA%94%E9%83%8E.jpg",451,398,"佐倉惣五郎"],["c:e/e5/Kodanji_Ichikawa_IV_and_Kikujir%C5%8D_Onoe_II.jpg",3496,2548],["c:d/dd/Toshoji-temple_dai-hondo%2Csogo_reido%2Cnarita-city%2Cjapan.jpg",3750,2501],["c:b/be/%E6%B5%AA%E6%9B%B2%E5%B8%AB%E6%98%A5%E6%97%A5%E4%BA%AD%E6%B8%85%E5%90%89%E3%81%AE%E5%AF%84%E9%80%B2%E3%81%AB%E3%82%88%E3%82%8B%E7%9F%B3.jpg",480,640],["c:8/81/3%E4%BB%A3%E7%9B%AE%E7%A5%9E%E7%94%B0%E4%BC%AF%E5%B1%B1%E3%81%AB%E3%82%88%E3%82%8B%E5%AF%84%E9%80%B2%E3%81%AE%E7%9F%B3%E3%80%82%E5%AE%97%E5%90%BE%E9%9C%8A%E5%A0%82%EF%BC%88%E5%AE%97%E5%90%BE%E8%A6%AA%E5%AD%90%E3%81%AE%E5%A2%93%EF%BC%89%E3%81%AB%E3%81%A6%E3%80%82.jpg",480,640],["c:a/ae/NDL-DC_762376_0124_0026crd-KiuchiSogoro.jpg",620,419]]},{"id":"12_sanrizuka","n":"三里塚（成田空港闘争の地）","yomi":"さんりづか","cat":"昭和","rank":"A","y":1966,"era":["showa","heisei"],"sh":"","ad":"成田市三里塚御料（三里塚記念公園）","st":"JR・京成 成田駅からバスで約20分","la":35.7383,"lo":140.394,"hook":"«ふるさとの土地を、空港にするな»。日本の空の玄関をめぐって、長くはげしい対立が続いた土地。","lead":"三里塚は、成田空港（新東京国際空港）がつくられた地域です。1966年に空港の建設が決まると、土地を守ろうとする農民や支援者たちと国との間で長く激しい対立が起こりました。多くの人が傷つき、命を落とした人もいます。いまは «成田空港 空と大地の歴史館» などで、その歴史を学ぶことができます。","story":["三里塚は、明治時代から皇室の «下総御料牧場» があった場所です。桜並木の続く牧場は、人びとのいこいの場でした。まわりには、戦後に開拓に入った人たちや、先祖代々の田畑をたがやす農家が暮らしていました。","1966年、国は、ここに新しい国際空港をつくると決めました。«飛行機の時代になり、羽田空港だけでは足りない»。しかし、地元の人びとにとっては、あまりに突然の決定でした。«私たちの土地のことを、なぜ相談もなく決めるのか»。農民たちは «三里塚芝山連合空港反対同盟» をつくり、反対運動を始めます。","運動には、各地から学生や支援者が加わり、対立はどんどんはげしくなりました。1971年には、土地を収用するための強制代執行が行われ、そのなかで警察官3人が亡くなる事件も起きました。反対する側にも、亡くなった人や重いけがを負った人がいます。","1978年、空港はようやく開港しました。予定より長くおくれ、その直前には管制塔が占拠される事件も起きています。空港ができたあとも対立は続きましたが、1990年代に入ると、国と反対同盟の一部とが話し合う «成田空港問題シンポジウム» や «円卓会議» が開かれ、国は強制的なやり方について謝罪しました。","三里塚の歴史は、«国の大きな計画» と «一人ひとりの暮らし» をどう両立させるかという問いを、いまも投げかけています。芝山町の «成田空港 空と大地の歴史館» では、さまざまな立場の人の声を伝えています。ここを訪ねるときは、亡くなった方々と、ふるさとを失った人びとの思いに心をよせたいものです。"],"tl":[["1875年","下総牧羊場が開かれ、のち宮内省の下総御料牧場となる"],["1966年","新東京国際空港を三里塚・芝山地区につくることが閣議決定される"],["1971年","強制代執行。東峰十字路事件で警察官3人が死亡"],["1978年","管制塔占拠事件の後、新東京国際空港が開港"],["1991〜1994年","成田空港問題シンポジウム・円卓会議が開かれる"],["2004年","空港が民営化され成田国際空港株式会社に"],["2011年","成田空港 空と大地の歴史館が開館"]],"who":[["三里塚芝山連合空港反対同盟","土地を守るため空港建設に反対した地元農民らの組織"],["戸村一作","反対同盟の委員長を長くつとめた"],["国・空港公団","空港の建設を進めた側"],["地元の人びと","賛成・反対、さまざまな立場でこの問題に向きあった"]],"deep":["空港の建設地は、当初は富里周辺が候補とされたが、反対が強く、1966年に三里塚・芝山地区へ変更された。","下総御料牧場は空港建設にともない、栃木県へ移転した。三里塚記念公園には牧場時代の貴賓館などが残る。","1971年9月の東峰十字路事件では、警備の警察官3人が亡くなった。反対運動の側でも、代執行の過程などで亡くなった人がいる。","シンポジウム・円卓会議を経て、国は強制的な手法を反省し、話し合いによる解決を約束した。対立の «平和的解決» の例として研究されている。","空港の敷地内や周辺には、いまも空港に土地を譲っていない農家があるなど、問題は完全には終わっていない。"],"look":["三里塚記念公園（御料牧場の記念館・貴賓館）","成田空港 空と大地の歴史館（芝山町）","空港周辺の農村風景","春の三里塚の桜"],"q":["1966年、成田空港の建設地として決まったのはどこ？","成田市の三里塚と芝山町の地区。はじめは富里が候補でしたが、変更されました。"],"koji":[],"myth":"","img":["成田国際空港","下総御料牧場","東峰十字路事件"],"wp":"三里塚闘争","rel":{"ev":[],"grave":[]},"ph":[["c:7/76/YokoboriSteelTower.png",4608,3463],["c:f/fc/SoratodaichinorekishikanZenkei.jpg",4514,3386],["c:6/6c/Plum_trees_and_control_tower.jpg",4032,3024],["c:9/99/Narita_International_Airport_Aerial_photograph_1989.jpg",9064,7760],["c:9/96/NaritaAirportTachiki.jpg",3456,5184],["c:0/08/NaritaAirportSyokoFlg.jpg",5184,3456],["c:f/f0/NaritaAirportHelmet.jpg",5184,3456],["c:3/36/NaritaAirportDoramukan.jpg",3317,4423]]},{"id":"12_inbanuma","n":"印旛沼（田沼・天保の掘割普請）","yomi":"いんばぬま","cat":"産業","rank":"A","y":1782,"era":["edo","showa"],"sh":"","ad":"佐倉市臼井田（佐倉ふるさと広場）","st":"京成本線 京成臼井駅から歩いて約25分","la":35.735,"lo":140.214,"hook":"沼の水を東京湾へ流せ――。田沼意次も、水野忠邦も挑み、そして失敗した、江戸時代の «大工事»。","lead":"印旛沼は、千葉県北部にある大きな沼です。江戸時代、洪水をふせぎ新しい田んぼをつくるため、沼から東京湾まで水路を掘る工事が何度も試みられましたが、どれも完成しませんでした。夢がかなったのは、昭和の戦後になってからでした。","story":["佐倉の «ふるさと広場» に立つと、オランダ風の風車のむこうに、広い水面が広がっています。印旛沼です。のどかな景色ですが、この沼は昔、たびたび大水をおこし、まわりの村を苦しめてきました。利根川の水が逆流してくると、沼の水があふれ、田畑が水びたしになったのです。","«沼の水を、西の東京湾へ流せばいい»。江戸時代の中ごろ、地元の名主がそう考え、掘割（水路）の工事を願い出ました。しかし、台地をけずって長い水路を掘るのは大変なこと。工事はお金が足りずに失敗しました。","次に挑んだのが、老中・田沼意次です。1782年、幕府は大きなお金をかけて工事を始めました。水路ができれば、洪水がなくなるだけでなく、沼をうめて新しい田んぼもつくれます。商人の力も借りた、田沼らしい大計画でした。しかし1786年、利根川の大洪水で工事現場はめちゃくちゃになり、同じ年に田沼が失脚して、工事は中止になりました。","さらに1843年、天保の改革を進めていた老中・水野忠邦も、この工事にとりかかります。今度は五つの藩に工事を命じました。«御手伝普請» です。藩の武士や、集められた人びとが、泥にまみれて土を掘りました。しかし、この年のうちに水野が失脚し、工事はまたも止まってしまいます。«印旛沼の工事をすると老中が失脚する» と、うわさされたほどです。","江戸時代の人びとの夢は、戦後の昭和になって実現しました。1946年から始まった印旛沼開発事業で、花見川を通して東京湾へ水を流す水路と、大きなポンプ場がつくられ、1969年に完成しました。いま沼の水は、田んぼや工場、そして人びとの水道の水として使われています。"],"tl":[["1724年","平戸村の名主・染谷源右衛門らが掘割工事を試みるが失敗"],["1782年","田沼意次のもとで掘割工事が始まる"],["1786年","利根川の大洪水と田沼の失脚で工事中止"],["1843年","水野忠邦のもと、五つの藩に工事を命じる（天保の印旛沼掘割普請）"],["1843年","水野忠邦が失脚し、工事中止"],["1946年","戦後の印旛沼開発事業が始まる"],["1969年","印旛沼開発事業が完成"]],"who":[["染谷源右衛門","平戸村の名主。享保のころ掘割工事を願い出た"],["田沼意次","老中。天明期に掘割工事を進めた"],["水野忠邦","老中。天保の改革のなかで掘割工事を命じた"],["鳥居耀蔵","水野のもとで天保の工事の担当にかかわったとされる"]],"deep":["天保の工事で御手伝普請を命じられたのは、庄内藩・沼津藩・鳥取藩・秋月藩・貝淵藩の5藩とされる。","天保の工事では、とくに «高台（たかだい）» とよばれる台地を掘る区間が難所で、工事は大変な苦労をともなった。","戦後の開発で、西印旛沼と北印旛沼に分かれ、沼の面積は干拓により大きく減った。","沼の水を花見川へ流す «大和田排水機場» などの施設が、江戸時代の構想を現代の技術で実現した。","佐倉ふるさと広場の風車は、オランダとの交流を記念してつくられたもので、江戸時代の工事とは直接の関係はない。"],"look":["佐倉ふるさと広場のオランダ風車と沼のながめ","印旛沼のサイクリングロード","花見川ぞいの水路","沼周辺の水辺の自然"],"q":["江戸時代、印旛沼の掘割工事にとりかかった二人の老中は？","田沼意次と水野忠邦。どちらも工事の途中で失脚し、完成しませんでした。"],"koji":[],"myth":"«工事をすると老中が失脚する» はうわさ話。","img":["田沼意次","水野忠邦","花見川"],"wp":"印旛沼","rel":{"ev":[],"grave":[]},"ph":[["c:6/6b/Lake_Inba.JPG",4608,3456,"印旛沼"],["c:6/6e/Nishi_inbnuma.JPG",4000,3000],["c:b/b7/Kita_inbanuma.JPG",4000,3000],["c:b/b6/Inbanuma_aerial_shoot.jpg",3648,2736],["c:2/26/Tanuma_Okitsugu2.jpg",636,642,"田沼意次"],["c:a/ab/Mizuno_Tadakuni.jpg",1037,876,"水野忠邦"]]},{"id":"12_tone_unga","n":"利根運河","yomi":"とねうんが","cat":"近代","rank":"A","y":1890,"era":["meiji","taisho","showa"],"sh":"","ad":"流山市東深井（運河駅周辺）","st":"東武アーバンパークライン 運河駅から歩いてすぐ","la":35.915,"lo":139.903,"hook":"オランダ人技師が設計した、日本初の本格的な西洋式運河。利根川と江戸川を «近道» で結んだ。","lead":"利根運河は、利根川と江戸川を結ぶために明治時代につくられた運河です。オランダ人技師ムルデルが設計し、1890年に完成しました。全長は約8.5kmで、船の旅を大きく短くしましたが、鉄道の発達で役目を終えました。今は水と緑の散歩道として親しまれています。","story":["東武線の «運河駅»。めずらしい駅名ですが、そのとおり、駅のすぐそばを運河が流れています。この運河は、明治の人びとが «もっと早く、もっと安全に» 船を通すためにつくったものです。","江戸時代から、銚子などから東京へ荷物を運ぶ船は、利根川をさかのぼり、関宿で江戸川に入って下っていました。大きく遠回りするうえ、川の水が少ないと船が通れないこともありました。«利根川と江戸川を、途中で近道できないか»。地元の人びとが声をあげ、運河をつくる計画が動きだしました。","設計をまかされたのは、オランダ人の技師 «ムルデル» です。オランダは水の国。運河づくりの技術は世界でもトップクラスでした。ムルデルは土地を歩いて調べ、利根川と江戸川がいちばん近づくこの場所に、約8.5kmの運河を計画しました。","運河を掘るのは、機械のない時代の大仕事でした。たくさんの人がスコップやもっこを使って土を掘り、運び、土手をつき固めました。川との出入口では水の高さや流れにも気をくばり、船が安全に通れるようにくふうされました。ムルデルは現場に立ち、日本の技術者や作業員たちといっしょに工事を進めたのです。","工事は1888年に始まり、1890年に完成します。運河の開通で、東京までの船の旅は大きく短くなりました。多いときには1年に3万数千隻もの船が通ったといわれます。運河のまわりには船宿や茶店ができ、にぎわいました。しかし、やがて鉄道が通るようになると、船で物を運ぶ時代は終わりをむかえます。","いま運河の水辺は、桜並木や散歩道になり、鳥や魚の姿も見られます。土手の上には、ムルデルの功績をたたえる記念碑が立っています。«西洋の技術と、地元の人びとの願い» が形になった運河を、ゆっくり歩いてみましょう。"],"tl":[["江戸時代","利根川から関宿を回って江戸川へ入る水運が発達"],["1887年","運河をつくる会社（利根運河株式会社）が設立される"],["1888年","工事が始まる"],["1890年","利根運河が完成・開通"],["明治後期","多くの船が行き交いにぎわう"],["昭和初期","鉄道の発達などで利用が減り、のちに国の管理に移る"]],"who":[["ムルデル","オランダ人技師。利根運河を設計・指導した"],["広瀬誠一郎","運河建設を推進した人物の一人"],["利根運河株式会社","運河をつくり、経営した民間会社"]],"deep":["利根運河は日本で初めての本格的な西洋式運河とされ、土木学会選奨土木遺産にも選ばれている。","ムルデル（A.T.L.ローウェンホルスト・ムルデル）はオランダから来日した «お雇い外国人» の技師の一人で、日本各地の治水にもかかわった。","運河の開通で、銚子から東京への船の航路は約40km短くなったとされる。","運河は民間会社が建設・経営したが、利用の減少と洪水の被害などにより、1941年に国が買い取ったとされる。","運河の土手に立つ «ムルデルの碑» は、完成にかかわった技師をたたえるもの。","運河の周辺は «利根運河水辺公園» などとして整備され、野鳥観察や散策の場になっている。春の桜の時期はとくににぎわう。"],"look":["運河駅すぐの運河の水辺","ムルデルの記念碑","運河ぞいの桜並木と散歩道","利根川・江戸川との合流部"],"q":["利根運河を設計したのは、どこの国の技師？","オランダ。運河の国の技術が使われました。"],"koji":[],"myth":"通航船数・航路短縮距離などの数値は資料によって多少ちがう。","img":["お雇い外国人","江戸川 (関東)"],"wp":"利根運河","rel":{"ev":[],"grave":[]},"ph":[["j:b/b0/Nagareyama_Tone_Canal_In_Spring_1.JPG",3264,2448,"利根運河"],["c:e/e6/Unga_bridge_over_the_Tone_canal_20211014.jpg",4032,3024],["c:4/4a/Tone-canal%2Cnoda-city%2Cjapan.JPG",1600,1200],["c:3/35/ToneUnga.png",996,562],["c:2/21/Chiba_Prefectural_Railways_Noda_Line.JPG",512,306]]},{"id":"12_ogahasu","n":"大賀ハス（検見川 落合遺跡の古代ハス）","yomi":"おおがはす","cat":"学び","rank":"A","y":1951,"era":["yayoi","showa"],"sh":"県指定天然記念物（検見川の大賀蓮）","ad":"千葉市花見川区（東京大学検見川総合運動場・落合遺跡）","st":"JR総武線 新検見川駅から歩いて約15〜20分（発掘地は大学の敷地内）。花を見るなら千葉都市モノレール 千葉公園駅すぐの千葉公園","la":35.666,"lo":140.076,"hook":"2000年以上ねむっていたハスの実が、戦後の千葉で目をさまし、ピンクの花を咲かせた。","lead":"1951年、千葉市の検見川にある遺跡の泥の中から、とても古いハスの実が見つかりました。植物学者の大賀一郎博士がこの実を育てると、翌年、みごとな花が咲きました。«大賀ハス» とよばれるこのハスは、今では千葉市の花になり、世界中に株分けされています。","story":["話は戦後まもないころにさかのぼります。検見川の東京大学の農場（今の総合運動場）で、泥炭層（植物がくさらずに積もった黒い土）を掘っていたところ、丸木舟やかいが出てきました。ここは大昔、湿地や池だった場所。«丸木舟があるなら、そのころの植物の実も眠っているかもしれない»。そう考えたのが、ハスの研究を続けていた大賀一郎博士でした。","1951年春、博士は地元の中学生や市民の協力を得て、発掘を始めます。ところが、なかなか見つかりません。調査が終わりに近づいたころ、ついに1粒のハスの実が見つかったと伝わります。その後さらに2粒。合わせて3粒の小さな実が、何千年もの眠りから掘り出されました。","«本当に芽が出るのだろうか?» ハスの実はとても固い皮に守られていて、水も空気もほとんど通しません。だからこそ長いあいだ生き残れたのですが、そのままでは芽が出ません。博士は皮に少し傷をつけて水にひたし、3粒のうち1粒が育ちました。そして1952年の夏、うすいピンクの花がひらきます。«古代のハスが咲いた!» というニュースは、海外の新聞でも紹介されました。","実の年代について博士は «2000年以上前» と発表しました。いっしょに出た丸木舟などの年代測定をもとにした考えです。ただし、実そのものの年代や、何時代のものかについては今も議論があります。それでも、焼け野原から立ち直ろうとしていた人々にとって、長い眠りからよみがえった花は大きな希望になりました。","その後、大賀ハスは千葉公園をはじめ全国の池や、アメリカ・中国など海外にも株分けされ、友好のしるしにもなりました。千葉市は大賀ハスを市の花に選んでいます。花がひらくのは初夏の朝。昼すぎには閉じてしまうので、見に行くなら早起きがコツです。"],"tl":[["1947〜1948年ごろ","検見川の泥炭層から丸木舟などが見つかる（落合遺跡）"],["1951年春","大賀一郎博士らの発掘で古いハスの実3粒が見つかる"],["1952年夏","そのうち1粒が育って花を咲かせる"],["1954年","«検見川の大賀蓮» として千葉県の天然記念物に"],["1993年","千葉市の花に選ばれる"],["現在","千葉公園などで毎年初夏に花が見られる"]],"who":[["大賀一郎","植物学者。«ハス博士» とよばれ、実を掘り出して育てた"],["発掘に協力した地元の人々","中学生や市民がボランティアで泥を掘ったと伝わる"],["大賀ハスを育てた人々","株分けを受け、全国・海外に広めた研究者や市民"]],"deep":["ハスの実が長生きなのは、とても固い «果皮» が水と空気を通さず、中の種を休眠させるからです。芽を出させるには皮に傷をつける必要があり、博士もそうしたといわれます。","年代測定: 当時の新しい技術だった放射性炭素年代測定で、いっしょに出た木材などが調べられました。ただし実そのものを直接測ったわけではないため、«2000年前» という数字には慎重な見方もあります。","落合遺跡の丸木舟は、泥炭層のおかげでくさらずに残りました。同じ地層からハスの実が出たことが、«古代のハス» と考えられた根拠です。","大賀ハスは花びらがややほっそりした一重咲き。のちに «大賀ハス» の株から、各地で名前をつけた品種も生まれました。","株分けは国際交流にも使われ、アメリカや中国などへ送られました。«友好のハス» として植えられている場所もあります。","発掘地は大学の運動場の中にあり、記念の碑が建てられています。見学の可否は施設のルールに従う必要があります。"],"look":["千葉公園のハス池（初夏の朝が見ごろ）","検見川の発掘地にある記念碑（大学の敷地内。見学はルールを確認）","千葉市内の各地に植えられた大賀ハス","花のあとにできる «はちす（蜂の巣）» のような花たく"],"q":["大賀ハスの花が見られるのは一日のうち、いつごろ?","朝です。早朝にひらき、昼すぎには閉じてしまいます。"],"koji":[{"w":"泥中の蓮（でいちゅうのはす）","m":"泥の中から清らかな花を咲かせるハスのように、よくない環境でも心を清く保つこと"}],"myth":"実の年代（«2000年以上前»）は同じ地層の遺物をもとにした推定で、諸説あり。発見の細かい日付や発見者の話も伝え方に幅がある。","img":["大賀一郎","千葉公園","ハス"],"wp":"大賀ハス","rel":{"ev":[],"grave":[]},"ph":[["c:5/50/%E3%83%8F%E3%82%B9%EF%BC%93.JPG",960,1280,"大賀ハス"],["c:e/ea/The_birthplace_of_Oga_Lotus.jpg",3264,2448],["c:3/32/Hiraike-park_%28%E5%B9%B3%E6%B1%A0%E5%85%AC%E5%9C%92_%E5%A4%A7%E8%B3%80%E3%83%8F%E3%82%B9%29%E5%85%B5%E5%BA%AB%E7%9C%8C%E5%8A%A0%E6%9D%B1%E5%B8%82%E6%9D%B1%E5%8F%A4%E7%80%AC_8150.jpg",1728,2304],["c:c/c0/2014-07-01_Hiraike-park_%28%E5%B9%B3%E6%B1%A0%E5%85%AC%E5%9C%92_%E5%A4%A7%E8%B3%80%E3%83%8F%E3%82%B9%29%E5%85%B5%E5%BA%AB%E7%9C%8C%E5%8A%A0%E6%9D%B1%E5%B8%82%E6%9D%B1%E5%8F%A4%E7%80%AC_8164.jpg",2304,1728],["c:d/d9/Tiba_Koen-3.JPG",2048,1536],["c:8/82/Ichiro_Oga_01.jpg",710,1070,"大賀一郎"],["c:7/78/Chiba_Park_with_monorail.jpg",2961,2013,"千葉公園"],["c:7/7a/GyodaAncientlotus.jpg",4032,3024,"ハス"]]},{"id":"12_konyo","n":"昆陽神社（青木昆陽の甘藷試作地）","yomi":"こんようじんじゃ","cat":"学び","rank":"A","y":1735,"era":["edo"],"sh":"県指定史跡（昆陽先生甘藷試作地）","ad":"千葉市花見川区幕張町4丁目","st":"JR総武線 幕張駅・京成幕張駅から歩いて約5〜10分","la":35.656,"lo":140.042,"hook":"飢えから人々を救うため、江戸の学者がここでサツマイモを植えた。いま彼は «芋神さま» としてまつられている。","lead":"江戸時代の学者・青木昆陽は、飢饉に強い食べ物としてサツマイモに目をつけ、幕張の村で試しに植えさせました。これがうまくいき、サツマイモは関東に広まります。昆陽神社は、その昆陽をまつる小さな神社です。","story":["1732年、西日本を中心に «享保の大飢饉» がおそいました。イナゴなどの害で米がとれず、たくさんの人が亡くなります。ところが、サツマイモを育てていた地域では、わりあい飢えがおさえられたといわれます。«米がだめでも、イモがあれば人は生きられるのではないか?»","そう考えたのが、江戸の町人出身の学者・青木昆陽でした。昆陽はサツマイモの育て方や効き目をまとめた『蕃薯考』を書き、町奉行の大岡忠相を通じて将軍・徳川吉宗の目にとまります。吉宗は «ためしに育ててみよ» と命じました。","試作の場所に選ばれたのが、江戸の小石川薬園、そして下総国の馬加村（いまの幕張）と、上総国の不動堂村（いまの九十九里町）でした。1735年、昆陽は種イモを村に持ちこみ、村人たちと畑をつくりました。«南の国のイモが、関東の寒さで育つのか?» 最初はうたがう声もあったでしょう。","しかし秋、畑にはたくさんのイモが実りました。サツマイモはやせた土地でもよく育ち、関東の台地にぴったりだったのです。のちに天明の飢饉がおきたとき、この辺りでは飢えに苦しむ人が少なかったと伝わり、村人たちは昆陽への感謝を忘れませんでした。","こうして昆陽は神さまになりました。幕張の秋葉神社の境内には昆陽神社があり、«芋神さま» として親しまれています。すぐそばには試作地の碑が建ち、千葉県の史跡になっています。昆陽はのちにオランダ語も学び、蘭学の先がけの一人にもなりました。"],"tl":[["1698年","青木昆陽、江戸・日本橋の魚問屋に生まれる"],["1732年","享保の大飢饉"],["1735年","『蕃薯考』が認められ、幕張・九十九里・小石川でサツマイモを試作"],["1739年ごろ","昆陽、幕府の書物御用となり、のちオランダ語を学ぶ"],["1769年","昆陽没。目黒の墓は «甘藷先生墓» とよばれる"],["1780年代","天明の飢饉。サツマイモが人々を助けたと伝わる"]],"who":[["青木昆陽","学者。サツマイモの試作を進め «甘藷先生» とよばれる"],["徳川吉宗","8代将軍。試作を命じた"],["大岡忠相","町奉行。昆陽を吉宗に推したといわれる"],["馬加村の村人たち","畑をつくり、イモを育てた"]],"deep":["«甘藷» はサツマイモのこと。中国から琉球・薩摩を経て広まったので «唐芋»«琉球芋» ともよばれました。関東で «サツマイモ» の名が定着したのはこのころといわれます。","昆陽より前に、薩摩や九州ではすでにサツマイモが栽培されていました。昆陽の功績は «発見» ではなく、関東へ広げるきっかけを作ったことにあります。","試作地は幕張と九十九里町の2か所が千葉県内の候補地として知られ、九十九里町にも記念の碑があります。","昆陽はのちに野呂元丈とともにオランダ語を学び、その教えを受けた前野良沢は『解体新書』の翻訳の中心になりました。サツマイモと蘭学がつながっているのがおもしろいところです。","目黒不動（瀧泉寺）の近くにある昆陽の墓は «甘藷先生墓» として国の史跡。毎年10月には «甘藷まつり» が行われます。","幕張の試作地の地名 «馬加» は、昔の村の名前。のちに «幕張» の字があてられたといわれます。"],"look":["昆陽神社（秋葉神社の境内）","«昆陽先生甘藷試作地» の碑","近くの住宅地に残る台地の地形（イモに向いた土地）"],"q":["青木昆陽が書いた、サツマイモをすすめる本の名前は?","『蕃薯考（ばんしょこう）』。育て方や飢饉への効き目をまとめました。"],"koji":[],"myth":"天明の飢饉で幕張付近に餓死者が出なかったという話は言い伝え。大岡忠相の推挙のいきさつも伝え方に幅がある。","img":["サツマイモ","享保の大飢饉"],"wp":"青木昆陽","rel":{"ev":[],"grave":[]},"ph":[["c:e/e5/Aoki_Konyo1.jpg",1369,1860,"青木昆陽"],["c:6/6b/Grave_of_Konyo_AOKI.jpg",1240,1382],["c:2/20/Konyo_akiba_shrine.jpg",800,600],["c:a/a4/Ipomoea_batatas.jpg",300,239,"サツマイモ"],["c:d/d8/%E4%BB%8F%E5%BF%83%E5%AF%BA%EF%BC%88%E4%BD%90%E8%B3%80%E5%B8%82%E5%A4%A7%E8%B2%A1%EF%BC%89%E3%81%AE%E4%BA%AB%E4%BF%9D%E3%81%AE%E9%A3%A2%E9%A5%89%E4%BE%9B%E9%A4%8A%E5%A1%94%E3%80%8C%E6%9C%AC%E5%B7%9E%E5%BA%B6%E6%B0%91%E9%A4%93%E6%AD%BB%E7%B4%AF%E8%91%AC%E4%B9%8B%E5%A2%93%E3%80%8D.jpg",3600,4800,"享保の大飢饉"]]},{"id":"12_funabashi_musen","n":"船橋無線塔跡（ニイタカヤマノボレ）","yomi":"ふなばしむせんとうあと","cat":"昭和","rank":"A","y":1941,"era":["taisho","showa"],"sh":"","ad":"船橋市行田1丁目（行田公園）","st":"東武アーバンパークライン 塚田駅から歩いて約15分、またはJR西船橋駅からバス","la":35.715,"lo":139.964,"hook":"上から見ると、団地の道がきれいな円をえがいている。そこにはかつて、海の向こうまで電波を飛ばす巨大な塔が立っていた。","lead":"大正時代、海軍は船橋の台地に大きな無線の送信所をつくりました。まん中には高さ180mをこえる鉄の塔が立ち、遠くの海の船に電報を送りました。太平洋戦争が始まる前の «ニイタカヤマノボレ» の暗号電報も、ここから送られたという説があります。塔はもうありませんが、行田公園と団地の丸い道に、その形が残っています。","story":["大正のはじめ、日本海軍は遠くの海にいる軍艦と連絡をとる方法を探していました。そこで選ばれたのが、広く平らな船橋の台地です。ここに «船橋無線電信所» がつくられ、中央には高さ約180mの主塔、そのまわりには円をえがくように何本もの塔が立ちました。«あの高い塔は何だ?» と、近くの村の人たちはきっと見上げたことでしょう。","1923年9月1日、関東大震災がおこります。東京の通信がとだえるなか、船橋の送信所から震災の知らせが海外へ送られたと伝わります。この電報がきっかけで、外国からの救援が動き出したともいわれます。","時代は昭和。1941年12月、日本はアメリカとの戦争に向かっていました。連合艦隊に送られた暗号 «ニイタカヤマノボレ一二〇八» は «12月8日に開戦せよ» という意味です。この電報がどこから送られたかについては、船橋のほかに長崎県の針尾送信所などをあげる説もあり、はっきりしていません。«船橋から送られた» という話は、地元で長く語られてきました。","戦争が終わると、送信所はアメリカ軍に使われ、のちに日本へ返されました。役目を終えた巨大な塔は1970年代はじめにとりこわされます。跡地は円形のまま公園や団地になり、いま空から見ると、円い道や区画がくっきり浮かび上がります。","行田公園には、無線塔の記念碑が立っています。この場所から出た電波は、人々を救う知らせにも、戦争の始まりの合図にもなったかもしれません。«同じ電波が、何を運んだのか?» 公園を歩きながら考えてみると、平和の大切さが見えてきます。"],"tl":[["1915年ごろ","海軍の船橋無線電信所が完成（大正のはじめ）"],["1923年9月1日","関東大震災。震災の第一報を海外へ送ったと伝わる"],["1941年12月","«ニイタカヤマノボレ一二〇八» 電報（送信地は諸説）"],["1945年以降","戦後、アメリカ軍が使用"],["1970年代はじめ","主塔がとりこわされる"],["現在","跡地は行田公園と円形の団地に"]],"who":[["日本海軍","送信所をつくり、艦隊との通信に使った"],["連合艦隊","開戦を知らせる暗号電報を受けた"],["地元の人々","巨大な塔を見上げて暮らし、記憶を語りついだ"]],"deep":["送信所の敷地は直径約800mほどの円形だったといわれ、その形が今の行田団地や道路にそのまま残っています。地図アプリの航空写真でよくわかります。","主塔の高さは約180m。当時の日本ではとびぬけて高い建造物で、遠くからも見えたといわれます。","«ニイタカヤマ» は当時日本領だった台湾の最高峰（今の玉山）。«一二〇八» は日付の12月8日を表します。","電報の送信地については、船橋・針尾（長崎県）・東京の海軍省など複数の説があります。史料で一つに決めきれないことを知っておきましょう。","長崎県の針尾送信所の3本の塔は現存し、国の重要文化財です。船橋の塔が残っていれば、と惜しむ声もあります。","跡地の近くには海上自衛隊の送信所など、通信関係の施設が今もあります（関係者以外立入禁止）。"],"look":["行田公園の無線塔記念碑","公園と団地をつつむ円形の道（歩くと大きさを実感できる）","航空写真で見る円形の区画"],"q":["«ニイタカヤマノボレ一二〇八» の «一二〇八» は何を表す?","開戦の日付（12月8日）です。"],"koji":[],"myth":"«ニイタカヤマノボレ» が船橋から送られたかは諸説。震災の第一報の送信も伝え方に幅がある。完成年や塔の高さは資料によって少しずつちがう。","img":["行田公園","針尾送信所","ニイタカヤマノボレ一二〇八"],"wp":"船橋無線塔","rel":{"ev":[],"grave":[]},"ph":[["c:1/1c/Funabashi_Gyouda-Park_Air_1989%28cropped%29.jpg",1632,1294,"行田公園"],["c:7/77/Hario_Radio_Tower_-_Oct_2%2C_2008.jpg",800,600,"針尾送信所"],["c:8/82/Nishi-Funabashi_Station_north_2024.jpg",4993,3328,"近く: 西船橋駅"],["c:5/5a/Keisei_Nishifuna_Station_2_2024.jpg",5184,3456,"近く: 京成西船駅"],["c:b/be/Higashi-Nakayama-Sta-N_202104.jpg",4032,3024,"近く: 東中山駅"],["c:c/cb/Tobinodai_Historic_Site_Park_Restored_Roana%EF%BC%88Fire-Pit%EF%BC%89_20250209.jpg",4032,3024,"近く: 飛ノ台貝塚"],["c:2/21/ChibaFunabashiKatsusikaSyougakkou.JPG",2048,1536,"近く: 船橋市立葛飾小学校"],["c:6/64/Tomyo-ji_%28Funabashi%29.JPG",3648,2736,"近く: 東明寺 (船橋市)"]]},{"id":"12_sakura_maki","n":"佐倉牧（取香牧・内野牧）","yomi":"さくらまき","cat":"産業","rank":"A","y":1700,"era":["edo","meiji"],"sh":"","ad":"成田市取香（取香牧のあたり）","st":"JR・京成 成田駅からバスで約20〜30分。牧の跡は広い範囲に点在するので車が便利","la":35.77,"lo":140.37,"hook":"成田空港の滑走路のあたりは、かつて野生に近い馬が駆けまわる、幕府の巨大な牧場だった。","lead":"江戸時代、下総国の台地には幕府の «牧（まき）» が広がり、馬がほぼ放し飼いで育てられていました。佐倉牧は «佐倉七牧» とよばれる7つの牧の集まりで、取香牧や内野牧などがありました。明治になると牧は開墾され、今の町の名前にその名残があります。","story":["下総の台地は、水が得にくく田んぼにしにくい土地でした。そのかわり草はよく茂ります。そこで古くから馬を育てる牧場が置かれ、戦国時代には千葉氏の牧があったともいわれます。江戸幕府はこれを引きつぎ、将軍の馬や軍馬を育てる直轄の牧にしました。","佐倉牧の馬は «野馬（のま）» とよばれ、ほとんど人の手をかけずに自然の中で暮らしていました。畑を荒らされないよう、村と牧のあいだには土手や堀がめぐらされます。«馬が村に入ってこないように» という工夫です。","年に一度、村人たちが大勢集められ、広い原っぱの野馬を追いこむ «野馬捕り» が行われました。追いこむ先は «捕込（とっこめ）» という土手で囲んだ場所。そこで良い馬が選ばれて江戸へ送られ、残りは村人に払い下げられたといいます。«それ、そっちへ行ったぞ!» と声をかけあう、にぎやかな行事だったでしょう。","明治になると、牧は役目を終えます。新政府は、東京で仕事を失った人々をここに移して畑にひらかせました。開墾した順に番号の名前がつけられ、初富・二和・三咲・豊四季・五香・六実・七栄・八街・九美上・十倉・十余一・十余二・十余三という地名が生まれました。開墾はとても苦しく、多くの人が去ったとも伝わります。","取香牧の一部は、のちに «下総御料牧場» になり、さらに戦後は成田空港に生まれ変わります。«馬の牧場» から «空の玄関» へ。台地の歴史はまるでリレーのようにつながっています。"],"tl":[["戦国時代","千葉氏の牧があったといわれる"],["江戸時代","幕府直轄の «佐倉七牧» として運営"],["1869年","明治政府が牧の開墾を始める"],["明治のはじめ","開墾地に初富・二和・三咲…などの地名がつく"],["1875年","取香に牧羊場などがつくられ、のちの下総御料牧場へ"],["1978年","新東京国際空港（成田空港）が開港"]],"who":[["江戸幕府","牧を直轄にして馬を育てた"],["牧士（もくし）","地元の有力者が務めた牧の管理役"],["野馬捕りの村人たち","毎年かり出されて野馬を追いこんだ"],["明治の開墾者たち","東京から移り住み、牧を畑にかえた"]],"deep":["佐倉七牧は、油田牧・矢作牧・取香牧・内野牧・高野牧・柳沢牧・小間子牧の7つとされます。現在の成田・富里・八街・印西・香取など広い範囲にまたがっていました。","«佐倉牧» の名は佐倉藩の支配だったからではなく、地域の名前からきたものです。管理は幕府の役人と地元の牧士が行いました。","村と牧のあいだの «野馬除土手（のまよけどて）» は、今も林の中などに土の高まりとして残っていることがあります。","開墾の地名は、東京に近い小金牧から番号がつけられ、佐倉牧の八街・十倉・十余三などへ続きます。«十余三» は «13番目» の意味です。","八街は明治以降に落花生の産地として有名になりました。牧の乾いた土がかえって落花生に向いていたのです。","牧で育った馬は小柄だったといわれ、明治以降は外国の馬と交配して馬の改良が進められました。"],"look":["各地に残る野馬除土手（林の中の土の高まり）","三里塚記念公園（取香牧の流れをくむ御料牧場の記念館）","«八街»«十余三» などの番号地名"],"q":["野馬を追いこんで捕まえるための囲いを何という?","«捕込（とっこめ）»。土手で囲んだ場所に馬を追いこみました。"],"koji":[],"myth":"戦国期の千葉氏の牧との連続性は推定。野馬捕りのやり方や、開墾で去った人の数は資料によって幅がある。","img":["小金牧","下総御料牧場","八街市"],"wp":"佐倉牧","rel":{"ev":[],"grave":[]},"ph":[["c:e/e5/Embankment_of_the_wall_of_the_grazing_land_of_the_horse%2CNoma-dote%2CKatori-city%2CJapan.JPG",3872,2592,"佐倉牧"],["c:c/cd/%E5%9D%82%E6%9D%B1%E5%9C%B0%E6%96%B9%E3%81%AE%E7%89%A7%E5%A0%B4%E3%81%A8%E8%A1%97%E9%81%93.jpg",2222,2238],["c:7/72/Shimofusa_Imperial_Stock_Farm.JPG",566,304,"下総御料牧場"],["c:5/5d/Dry-up-peanuts%2Cbotti%2Cyachimata-city%2Cjapan.JPG",4000,3000,"八街市"]]},{"id":"12_tsurugaya","n":"鶴谷八幡宮（安房国総社）","yomi":"つるがやはちまんぐう","cat":"寺社","rank":"A","y":1200,"era":["heian","kamakura","edo"],"sh":"","ad":"館山市八幡","st":"JR内房線 館山駅から歩いて約20分、またはバス","la":35.0015,"lo":139.868,"hook":"秋のひとときだけ、安房じゅうの神輿がここに集まる。千年の «国司祭» の舞台。","lead":"鶴谷八幡宮は、安房国（今の房総半島の南部）の «総社» とされる神社です。総社とは、国じゅうの神さまをまとめておまいりできるように置かれた神社のこと。毎年秋の «やわたんまち» では、周りの村から神輿や山車が集まり、たいへんなにぎわいになります。","story":["奈良・平安時代、国の役人（国司）は赴任すると、国じゅうの神社をおまいりしなければなりませんでした。でも国は広い。«全部回るのはたいへんだ» ということで、国府の近くに神々をまとめてまつる «総社» がつくられました。安房国の総社にあたるのが、この鶴谷八幡宮だといわれます。","もともと社は、安房国の国府があったと考えられる府中（今の南房総市）の近くにあり、のちに今の場所へ移ったと伝わります。海の近くのこの地は、港町としても大切な場所でした。","鎌倉時代には、安房に上陸して再起した源頼朝とのつながりが語られ、戦国時代には安房を治めた里見氏があつく信仰しました。«海と戦（いくさ）の守り神» として、武士にも漁師にも頼りにされてきたのです。","江戸時代になると、秋の祭礼 «安房国司祭» が今の形に整っていきます。«国司祭» という名前には、国司が神々をまつった総社の祭りという意味がこめられています。地元では親しみをこめて «やわたんまち（八幡の町＝八幡の祭り）» とよびます。","祭りの日、周りの神社から神輿がかけつけ、境内で勢いよくもみ合います。山車やお船が町をねり歩き、夜まで太鼓の音がひびきます。«あっちの村の神輿が来たぞ!» と子どもたちが走り出す、安房の人々にとって一年で特別な二日間です。"],"tl":[["平安時代","安房国の総社として府中付近にまつられていたといわれる"],["鎌倉時代ごろ","今の館山市八幡の地へ移ったと伝わる"],["戦国時代","里見氏があつく信仰する"],["江戸時代","安房国司祭が今の形に整っていく"],["現在","毎年9月に «やわたんまち» が行われる"]],"who":[["安房国の国司","総社で国の神々をまつった"],["源頼朝","安房から再起した。社とのゆかりが伝わる"],["里見氏","戦国時代の安房の領主。社を保護した"],["氏子の人々","祭りを受けつぎ、神輿や山車を出す"]],"deep":["«総社» は平安時代の後半から各地に置かれました。国司の神社めぐりを簡単にするための仕組みで、国府の近くにあるのがふつうです。","安房国は718年に上総国から分かれてできた、とても小さな国です。いちど上総に戻され、757年にふたたび独立しました。","安房国司祭は千葉県の無形民俗文化財に指定されています。集まる神輿の数や順番には、それぞれの村の決まりがあります。","社が府中から移った時期や理由ははっきりしません。«鎌倉時代»«戦国時代» など説が分かれます。","社名の «鶴谷» の由来にも諸説があり、確かなことはわかっていません。","境内の建物は何度も建てかえられており、江戸時代以降のものが中心です。","安房国司祭は、周りの神社の神輿が総社に集まる形の祭りで、国司の時代の «総社» のしくみを今に伝える例として注目されています。"],"look":["本殿と拝殿","秋の安房国司祭（やわたんまち）で集まる神輿","境内のご神木","館山の町なかとのつながり（祭りの道すじ）"],"q":["国じゅうの神々をまとめておまいりできる神社を何という?","«総社（そうじゃ）»。国司の参拝を楽にするためにつくられました。"],"koji":[],"myth":"府中からの移転時期、頼朝とのゆかり、社名の由来はいずれも伝承・諸説。","img":["安房国","総社","館山市"],"wp":"鶴谷八幡宮","rel":{"ev":[],"grave":[]},"ph":[["c:5/57/Tsurugaya-hachimangu%2C_haiden.JPG",5990,3960,"鶴谷八幡宮"],["c:7/7e/Tsurugaya-hachimangu%2C_yohaijo.JPG",6016,4000],["c:5/5c/Tsurugaya-hachimangu%2C_shaden.JPG",5976,3938],["c:5/5e/Tsurugaya-hachimangu%2C_otorii.JPG",5428,3607],["c:f/fe/Tsurugaya-hachimangu%2C_honden.JPG",6004,3984],["c:6/60/Tsurugaya-hachimangu%2C_entrance.JPG",6010,3992],["c:b/b2/Tsurugaya-hachimangu%2C_chokoku.JPG",5728,3816],["c:5/5e/Tsurugaya-hachimangu%2C_Wakamiya-hachiman-sha.JPG",6008,3988]]},{"id":"12_awa_kokubunji","n":"安房国分寺跡","yomi":"あわこくぶんじあと","cat":"遺跡","rank":"A","y":760,"era":["nara","heian"],"sh":"","ad":"館山市国分","st":"JR内房線 館山駅からバスまたは車で約10分","la":34.976,"lo":139.845,"hook":"日本でいちばん小さな国のひとつ・安房にも、天皇の願いをこめた国分寺が建てられた。","lead":"奈良時代、聖武天皇は国ごとに «国分寺» を建てるよう命じました。安房国分寺はそのひとつで、館山市の国分にありました。当時の建物は残っていませんが、発掘で金堂の土台（基壇）が見つかり、今は同じ場所に国分寺というお寺が続いています。","story":["741年、聖武天皇は «国分寺建立の詔（みことのり）» を出しました。病気の流行や災害、反乱があいつぎ、«仏の力で国を守りたい» と願ったのです。全国の国ごとに、僧の寺（国分寺）と尼の寺（国分尼寺）を建てることになりました。","ところが安房国には事情がありました。安房は718年に上総国から分かれてできたのですが、741年にいったん上総に戻され、757年にふたたび独立します。«国がないのに国分寺は建てられない»。そのため安房国分寺は、ほかの国より遅れて建てられたと考えられています。","発掘調査では、金堂と考えられる建物の基壇や、瓦などが見つかりました。ほかの国の大きな国分寺にくらべると、こぢんまりとした規模だったようです。それでも、海に近い安房の平野に瓦ぶきの堂が建ったとき、人々は «都の寺だ» と目を見はったことでしょう。","時がたつにつれ、国分寺は国の保護を失い、各地で荒れていきました。安房国分寺も古い建物はなくなりましたが、同じ場所に寺が受けつがれ、今も «国分寺» の名前が残っています。町名の «国分» も、ここに国分寺があった証拠です。","«なぜ小さな国にも寺が必要だったのか?» それは、国分寺が «国の役所とセットの国家の寺» だったからです。安房国分寺跡は、小さな国でも都と同じしくみで治めようとした、奈良時代の国づくりの姿を今に伝えています。"],"tl":[["718年","安房国が上総国から分かれて成立"],["741年","聖武天皇が国分寺建立の詔を出す。同じ年、安房は上総に併合される"],["757年","安房国がふたたび独立"],["奈良時代後半ごろ","安房国分寺が建てられたと考えられる"],["昭和後期","発掘調査で金堂の基壇などが見つかる"],["現在","同じ場所に国分寺が続き、跡地が保存されている"]],"who":[["聖武天皇","国分寺建立の詔を出した"],["光明皇后","聖武天皇の皇后。国分寺・国分尼寺の建立をすすめたといわれる"],["安房国の国司","国分寺の建立と運営にあたった"]],"deep":["安房国分寺は、国分寺の多くが «七重塔» をもつのに対し、塔の跡がはっきり見つかっていません。規模が小さかったためとも、調査がまだ及んでいないためとも考えられます。","建てられた時期は、安房がふたたび独立した757年より後という見方が一般的です。ただし正確な年代を記した史料はありません。","安房国分尼寺の場所はわかっていません。全国でも尼寺の場所が確かでない国はいくつかあります。","国府は今の南房総市府中あたりと考えられていますが、国府の遺構はまだはっきり見つかっていません。国分寺との位置関係も研究課題です。","安房は «日本の国のなかでも特に小さい国» の一つで、面積は今の千葉県南部の一部にすぎません。","出土した瓦の文様から、上総国分寺など周りの国との関係を読み取ろうとする研究があります。"],"look":["現在の国分寺の境内と金堂跡の位置","基壇跡を示す表示","周りの «国分» の地名"],"q":["聖武天皇が国分寺を建てるよう命じたのは何年?","741年です。"],"koji":[],"myth":"建立年代、寺の規模、塔の有無は発掘成果にもとづく推定で諸説あり。史跡の指定区分は要確認。","img":["国分寺","聖武天皇","安房国"],"wp":"安房国分寺","rel":{"ev":[],"grave":[]},"ph":[["c:d/d4/Awa_Kokubunji_%28Tateyama%29%2C_hondo.JPG",5233,3436,"安房国分寺"],["c:4/4a/Awa_Kokubunji_%28Tateyama%29%2C_soseki.JPG",6016,4000],["c:0/07/Awa_Kokubunji_%28Tateyama%29%2C_sanmon.JPG",5954,3906],["c:a/ac/Awa_Kokubunji_%28Tateyama%29%2C_kondo-ato.JPG",6016,4000],["c:7/7f/Awa_Kokubunji_%28Tateyama%29%2C_giminhi.JPG",5960,3916],["j:5/53/%E5%AE%89%E6%88%BF%E5%9B%BD%E5%88%86%E5%AF%BA%E5%87%BA%E5%9C%9F%E7%93%A6_%28%E5%8F%B2%E8%B7%A1%E4%B8%8A%E7%B7%8F%E5%9B%BD%E5%88%86%E5%B0%BC%E5%AF%BA%E8%B7%A1%E5%B1%95%E7%A4%BA%E9%A4%A8%E5%B1%95%E7%A4%BA%29.JPG",3651,3024],["c:3/3f/Emperor_Shomu.jpg",1876,3132],["c:a/a0/Bitchu_Kokubunji%2C_zenkei.jpg",6010,3990,"国分寺"]]},{"id":"12_futtsu_battery","n":"富津元洲堡塁砲台跡","yomi":"ふっつもとすほるいほうだいあと","cat":"近代","rank":"A","y":1890,"era":["meiji","taisho","showa"],"sh":"","ad":"富津市富津（県立富津公園内）","st":"JR内房線 青堀駅からバスで約10〜15分、富津公園下車","la":35.312,"lo":139.795,"hook":"東京湾がいちばんせまくなる富津岬。ここには、首都を守るための大砲がずらりと並んでいた。","lead":"明治時代、日本は外国の軍艦から首都・東京を守るため、東京湾の入り口に砲台を次々とつくりました。これを «東京湾要塞» といいます。富津岬の元洲堡塁砲台はその一つで、今は富津公園の中に、砲台や弾薬庫の跡が残っています。","story":["幕末、ペリーの黒船が浦賀にあらわれたとき、江戸の人々は «あんな大きな船が湾に入ってきたら、江戸はひとたまりもない» とおそれました。明治になると政府は本気で東京湾の守りを固めます。目をつけたのが、三浦半島の観音崎と房総半島の富津岬のあいだ。ここは湾がいちばんせまくなる «のど» のような場所です。","富津岬の先には、海の中に人工の島をつくり砲台を置く «海堡（かいほ）» の工事も始まりました。第一海堡は富津岬の沖に築かれ、10年ほどかけて完成したといわれます。陸の岬にも砲台がつくられ、その一つが元洲堡塁砲台でした。","砲台は、外から見えにくいように土を盛って隠し、大砲をすえる «砲座»、弾薬をしまう «弾薬庫»、兵士の通路などが組み合わされていました。レンガやコンクリートの壁は、敵の砲弾に耐えるようにがんじょうにつくられています。«ここから撃てば、湾に入る船は逃げられない»。兵士たちはそんな思いで海をにらんでいたのでしょう。","しかし、兵器の進歩はとても速いものでした。大砲の射程がのび、やがて飛行機の時代になると、湾口の砲台の役割は小さくなっていきます。1923年の関東大震災では、東京湾の要塞も大きな被害を受けました。第二次世界大戦の終わりとともに、要塞はその役目を終えます。","今、元洲堡塁砲台跡は松林に囲まれた公園の一角にあり、砲座や弾薬庫の跡が静かに残っています。すぐ近くの展望台からは、第一海堡や対岸の三浦半島が見えることも。かつて大砲が向けられた海は、今は釣り船や大型船が行きかう、おだやかな海です。"],"tl":[["1853年","ペリー来航。東京湾の守りが大きな課題になる"],["1880年代","東京湾の入り口に砲台・海堡の建設が進む"],["1890年ごろ","富津沖の第一海堡が完成"],["明治中ごろ","富津岬に元洲堡塁砲台などが整備される"],["1923年","関東大震災で東京湾の要塞が被害を受ける"],["1945年","終戦とともに要塞が役目を終える"],["現在","富津公園の中で砲台跡を見学できる"]],"who":[["明治政府・陸軍","首都防衛のため東京湾要塞を築いた"],["砲台を守った兵士たち","岬に住みこみ、海を見張った"],["工事に関わった人々","海を埋め立て、土を運び、砲台や海堡をつくった"]],"deep":["«堡塁（ほるい）» は、土やレンガで固めた小さな陣地のこと。元洲堡塁は、大砲をすえた砲台と兵士の守りの陣地を組み合わせたものです。","東京湾には3つの海堡がつくられました。第一海堡は明治、第二海堡は大正のはじめ、第三海堡は大正に完成しましたが、第三海堡は関東大震災で大きく壊れ、のちに撤去されました。","第一・第二海堡は今も海に残っていますが、ふだんは立ち入りが制限されています。第二海堡は見学ツアーが行われたことがあります。","観音崎（神奈川県）と富津岬のあいだはおよそ7km。当時の大砲なら両側から湾全体をねらえる距離でした。","要塞の地図や写真は軍事機密で、要塞の近くでの撮影やスケッチは禁止されていました。«要塞地帯» の立て札が各地に立っていたといいます。","砲台跡は古い構造物なので、崩れやすい場所には近づかないようにしましょう。"],"look":["砲座の跡（大砲をすえた丸いくぼみ）","弾薬庫の跡（レンガやコンクリートの壁）","富津岬の展望台（明治百年記念展望塔）から見る第一海堡","対岸の三浦半島・観音崎"],"q":["海の中に人工の島をつくり、大砲を置いた要塞を何という?","«海堡（かいほ）»。東京湾には第一〜第三海堡がつくられました。"],"koji":[],"myth":"元洲堡塁砲台の着工・完成年、備えた大砲の種類と数は資料によって異なるため、ここでは幅をもたせて記した。","img":["第一海堡","富津岬"],"wp":"東京湾要塞","rel":{"ev":[],"grave":[]},"ph":[["c:d/df/Kenzaki_battery_-01.jpg",2592,1944],["c:7/77/Ruins_of_Stronghold_of_Tokyo_bay%2C_at_Taibusa_cape%2C_Minami-Bousou%2C_Chiba.jpg",2048,1536],["c:2/2e/Fort_No1_tokyobay_mlit1974.jpg",932,699],["c:4/4f/Fort_No2_tokyobay_mlit1988.jpg",828,621],["c:8/8c/Fort_No3_tokyobay_mlit1983.jpg",538,404],["c:f/f2/Futsu_misaki.JPG",3488,2616,"富津岬"]]},{"id":"12_yamasa","n":"銚子の醤油醸造（ヤマサ醤油）","yomi":"ちょうしのしょうゆじょうぞう（やまさしょうゆ）","cat":"産業","rank":"A","y":1645,"era":["edo","meiji"],"sh":"","ad":"銚子市新生町2丁目","st":"JR総武本線・成田線 銚子駅から歩いて約10分","la":35.734,"lo":140.832,"hook":"紀州から海をこえてやって来た一族が、銚子の町を «しょうゆの町» に変えた。","lead":"銚子は、野田とならぶ関東のしょうゆの産地です。ヤマサ醤油は江戸時代の1645年、紀州（今の和歌山県）から来た濱口儀兵衛が始めたといわれます。利根川の水運で江戸へ運ばれたしょうゆは、そばや天ぷら、すしなど江戸の味をささえました。","story":["江戸時代のはじめ、紀州の漁師たちは、魚を追って房総の海まで来ていました。黒潮にのれば、紀州と房総は «海の道» でつながっていたのです。やがて銚子に移り住む人がふえ、紀州の湯浅に伝わるしょうゆづくりの技も持ちこまれました。","紀州・広村出身の濱口儀兵衛もその一人です。1645年、銚子でしょうゆの醸造を始めたと伝わります。«銚子なら、うまいしょうゆがつくれる»。夏すずしく冬あたたかい気候、しめった海風、そして近くでとれる大豆と小麦。こうじ菌がよく働く、しょうゆづくりにぴったりの土地でした。","さらに大事だったのが利根川です。銚子でつくったしょうゆは舟に積まれ、利根川と江戸川を通って、江戸まで運ばれました。人口百万の大都会・江戸では、関西から届く «下りしょうゆ» にかわって、関東の濃口しょうゆが人気になっていきます。そば、天ぷら、うなぎのかば焼き…。江戸の味は銚子のしょうゆがささえたのです。","幕末には、ヤマサのしょうゆは幕府から «最上醤油» の称号を受けたといわれます。このころの当主が7代目の濱口梧陵です。梧陵は故郷の広村で1854年の大津波にあい、稲むらに火をつけて村人を高台へ導いたという話で知られます。のちに私財で大きな堤防を築き、この話は «稲むらの火» として教科書にものりました。","今も銚子の町には、しょうゆのにおいがただよいます。工場の近くには見学施設があり、しょうゆづくりの歴史やしくみを学べます。«なぜ銚子でしょうゆ?» その答えは、紀州の人々の海の道と、利根川という川の道にありました。"],"tl":[["1645年","紀州出身の濱口儀兵衛が銚子でしょうゆづくりを始めたと伝わる"],["江戸時代","利根川の水運で江戸へしょうゆを運ぶ"],["1854年","7代目・濱口梧陵が故郷の広村で津波にあう（«稲むらの火» の話）"],["1864年","幕府から «最上醤油» の称号を受けたといわれる"],["1885年","濱口梧陵、旅先のニューヨークで亡くなる"],["現在","銚子で醸造が続き、見学施設で歴史を紹介"]],"who":[["濱口儀兵衛（初代）","紀州から銚子に来て、しょうゆづくりを始めた"],["濱口梧陵","7代目。«稲むらの火» の主人公のモデル。社会事業にも力をつくした"],["紀州の漁民たち","海をこえて房総に移り、技術や文化を伝えた"],["利根川の船頭たち","しょうゆを江戸まで運んだ"]],"deep":["銚子には紀州から移ってきた人々の足あとが多く、方言や地名、神社にも紀州とのつながりが見られます。«紀州と銚子は兄弟» とよばれることもあります。","しょうゆの原料は大豆・小麦・塩。こうじをつくり、塩水とまぜた «もろみ» を長い時間ねかせて発酵させます。温度と湿気が味を左右します。","銚子にはヤマサのほかにヒゲタ醤油もあり、ヒゲタはさらに古い江戸時代はじめの創業とされます。","«稲むらの火» は小泉八雲が梧陵をモデルに英語で書いた話がもとになり、のちに国語の教科書に採用されました。話の細部には実際とちがう脚色があります。","梧陵は私財を投じて広村に堤防（広村堤防）を築きました。この堤防は昭和の南海地震の津波から村を守ったといわれ、国の史跡になっています。","ヤマサの «ヤマ» は «へ» の字形のしるし、«サ» はカタカナ。商標は江戸時代から使われてきたといわれます。"],"look":["しょうゆの見学施設（工場の歴史展示）","銚子駅から工場まわりの町並み","利根川の河口（しょうゆを運んだ水の道）"],"q":["濱口梧陵が津波から村人を救った話は、何という題名で知られている?","«稲むらの火»。稲の束に火をつけて人々を高台へ導いた話です。"],"koji":[],"myth":"創業年は家の伝えによる。«最上醤油» の称号の年、«稲むらの火» の細部（刈り取った稲か稲わらかなど）には諸説・脚色がある。","img":["濱口梧陵","稲むらの火","ヒゲタ醤油","醤油"],"wp":"ヤマサ醤油","rel":{"ev":[],"grave":[]},"ph":[["c:4/46/Yamasa_Corporation_head_office.JPG",1802,1332,"ヤマサ醤油"],["c:a/a8/%E6%9C%89%E6%A9%9F_%28231913738%29.jpg",3504,2336],["c:d/de/Yamasa_Sh%C5%8Dyu_%281919%29_poster_by_Hisui_Sugiura.jpg",733,1135],["c:b/b4/Yamasa_Otto_Deutz_AG.png",800,600],["c:f/f4/Hamaguchi_Goryo.jpg",730,1129,"濱口梧陵"],["c:c/c6/Higeta_shoyu.jpg",800,439,"ヒゲタ醤油"],["c:6/63/Soy_sauce_2.jpg",1062,889,"醤油"]]},{"id":"12_shimousa_goryo","n":"下総御料牧場跡（三里塚記念公園）","yomi":"しもうさごりょうぼくじょうあと","cat":"近代","rank":"A","y":1885,"era":["meiji","showa"],"sh":"","ad":"成田市三里塚御料","st":"JR・京成 成田駅からバスで約20〜30分、三里塚下車","la":35.763,"lo":140.389,"hook":"皇室の馬や牛を育てた «御料牧場» は、成田空港の誕生とともに栃木へ旅立った。","lead":"三里塚には明治時代から、皇室のための牧場 «下総御料牧場» がありました。西洋の馬や羊、牛を育て、日本の牧畜の手本となった場所です。成田空港をつくることになったため牧場は1969年に栃木県へ移り、その一部が三里塚記念公園として残っています。","story":["明治のはじめ、日本の政府は «西洋に負けない国づくり» を急いでいました。そこで注目されたのが牧畜です。«羊を育てて毛織物をつくり、強い馬を育てたい»。内務卿の大久保利通は、江戸時代に幕府の牧だった取香・三里塚の広い台地に目をつけ、牧羊場などを開かせました。","牧場ではアメリカ人の技術者が招かれ、西洋式の飼い方が教えられました。外国から羊や馬、牛がつれてこられ、日本人の職員たちは言葉も習慣もちがう動物たちに苦労しながら、新しい技術を身につけていきました。","1885年ごろから牧場は宮内省（今の宮内庁）の管理となり、«下総御料牧場» とよばれるようになります。ここで育った馬は、皇室の儀式の馬車を引くこともありました。牧場で作られた牛乳やバター、ハムなどは皇室の食卓にものぼったといわれます。","春になると、牧場の周りの桜並木がいっせいに花を咲かせ、三里塚は桜の名所として知られました。«三里塚の桜を見に行こう» と、遠くから人々が訪れたといいます。牧場は地域の人々にとっても自慢の場所でした。","ところが戦後、新しい国際空港を三里塚につくることが決まります。牧場は1969年に栃木県の高根沢町へ移転し、この地で約90年続いた歴史を閉じました。空港建設をめぐっては、土地を守ろうとする農家の人々と国との間で長く激しい対立も起きました。記念公園に残る貴賓館や記念館は、牧場の記憶と、この土地が歩んだ複雑な歴史を静かに伝えています。"],"tl":[["1875年","大久保利通の発案で、取香・三里塚に牧羊場などが開かれる"],["1880年代","宮内省の管理となり、下総御料牧場とよばれる"],["明治〜昭和","皇室の馬や家畜を育て、日本の牧畜の手本に"],["1966年","新東京国際空港を三里塚周辺につくることが決まる"],["1969年","御料牧場が栃木県高根沢町へ移転"],["1978年","新東京国際空港（成田空港）開港"]],"who":[["大久保利通","内務卿。牧場の開設をすすめた"],["アップ・ジョーンズ","アメリカ人技術者。牧羊の指導にあたった"],["牧場の職員たち","西洋の家畜の育て方を学び、広めた"],["三里塚の農家の人々","空港建設で暮らしが大きく変わった"]],"deep":["牧場の土地は、江戸時代の幕府の牧（佐倉牧の取香牧など）を受けついだものです。«馬の土地» の歴史は江戸時代から続いていました。","記念公園の «貴賓館» は、皇族や来賓が牧場を訪れたときに使った建物とされ、明治期の洋風建築の雰囲気を残しています。","記念館では、牧場の歩みや、使われた道具・写真などが紹介されています。","御料牧場で育てられたサラブレッドの中には、競馬の歴史に名を残した馬もいたといわれます。","空港建設をめぐる対立（«三里塚闘争» とよばれることもある）では、けが人や亡くなった人も出ました。この地の歴史を語るとき、その重さにも目を向ける必要があります。","移転後の御料牧場（栃木県）は、今も皇室の行事に使う馬や、牛乳・卵などをつくっています。"],"look":["貴賓館（明治の雰囲気を残す建物）","御料牧場記念館の展示","春の桜並木","公園の近くを離着陸する飛行機"],"q":["下総御料牧場は、成田空港建設のため何年にどこへ移った?","1969年、栃木県の高根沢町へ移りました。"],"koji":[],"myth":"宮内省移管の正確な年や、牧場で育った馬の話は資料によって幅がある。空港問題は立場によって見方が大きく分かれる。","img":["三里塚","御料牧場","成田国際空港"],"wp":"下総御料牧場","rel":{"ev":[],"grave":[]},"ph":[["c:7/72/Shimofusa_Imperial_Stock_Farm.JPG",566,304,"下総御料牧場"],["c:7/74/Nakayama_KankoChizu.jpg",2783,1777],["c:7/72/%E5%A4%A7%E4%B9%85%E4%BF%9D%E5%8D%BF%E7%89%A7%E7%BE%8A%E5%A0%B4%E9%81%B8%E5%AE%9A%E3%81%AE%E7%A2%91.jpg",2030,2079],["c:c/cb/Sanrizuka-park%2Cold-sanrizuka-goryou-farm%2Cnarita-city%2Cjapan.JPG",1600,1200],["c:a/a7/Old-sanrizuka-goryou-farm-office%2Cnarita-city%2Cjapan.JPG",1600,1200],["c:8/84/Old-sanrizuka-goryou-farm%2Cold-house-for-honored-guests%2Cnarita-city%2Cjapan.JPG",1600,1200],["c:2/2a/Goryo_Farm%2C_July_2022.jpg",4608,3456,"御料牧場"],["c:8/80/Narita_International_Airport_Terminal_1.JPG",3872,2592,"成田国際空港"]]},{"id":"12_hishikawa","n":"菱川師宣記念館（見返り美人の故郷）","yomi":"ひしかわもろのぶきねんかん","cat":"学び","rank":"A","y":1690,"era":["edo"],"sh":"","ad":"安房郡鋸南町吉浜","st":"JR内房線 保田駅から歩いて約15分","la":35.137,"lo":139.843,"hook":"ふりかえる一瞬の美しさをえがいた «見返り美人»。その絵師は、房総の小さな漁村から江戸へ出た。","lead":"菱川師宣は «浮世絵の祖» とよばれる江戸時代の絵師です。代表作 «見返り美人図» は切手にもなりました。師宣は安房国の保田（今の鋸南町）に生まれ、江戸で絵の道を切りひらきました。故郷の鋸南町には、その生涯と作品を紹介する記念館があります。","story":["師宣は、保田の縫箔師（ぬいはくし）の家に生まれたといわれます。縫箔とは、着物に金や銀の箔をはったり、刺しゅうをしたりする仕事。«どんな模様にすれば、着物がいちばん美しく見えるか?» 幼いころから、そんな父の仕事を見て育ったのでしょう。","やがて師宣は江戸へ出て、絵を学びました。当時の絵は、お寺やお城、身分の高い人のためのものが中心。しかし師宣は、町の人々の暮らしや遊び、流行の着物を着た女性たちをいきいきとえがきました。それを木版で刷れば、たくさんの人が安く絵を楽しめます。師宣の挿絵入りの本や一枚刷りの絵は大人気になりました。","こうして生まれた «浮世の姿をうつす絵» が、のちに «浮世絵» とよばれるようになります。北斎や広重が活躍するのは、このずっとあとのこと。師宣が浮世絵の «はじまりの人» とされるのはそのためです。","«見返り美人図» は、版画ではなく、師宣が筆でえがいた肉筆画です。歩きながらふとふりかえる女性。帯の結び方や着物のもようには、縫箔の家に育った師宣ならではの目が光っています。この絵は1948年に切手の図柄になり、多くの人に知られるようになりました（原画は東京国立博物館の所蔵）。","師宣は故郷を忘れなかったと伝わり、保田の寺に梵鐘を寄進したという話が残ります。鋸南町の記念館では、師宣の版本や浮世絵の歴史を紹介しています。«江戸のスターの原点は房総の漁村にあった»。そう思うと、保田の海の景色もちがって見えてきます。"],"tl":[["江戸時代はじめ","安房国保田の縫箔師の家に生まれる（生年ははっきりしない）"],["1670年代","江戸で挿絵本の絵師として名が知られる"],["1680〜90年代","«見返り美人図» などをえがく"],["1694年","師宣没"],["1948年","«見返り美人» が切手の図柄になる"],["1985年","鋸南町に菱川師宣記念館が開館"]],"who":[["菱川師宣","絵師。浮世絵の祖とよばれる"],["菱川吉左衛門","師宣の父といわれる縫箔師"],["菱川派の弟子たち","師宣の画風を受けつぎ、工房で作品をつくった"]],"deep":["«見返り美人図» は師宣の肉筆画で、東京国立博物館が所蔵しています。記念館で見られるのは複製や関連資料が中心です。","師宣の初期の仕事は、本の挿絵でした。のちに挿絵が独立して一枚の絵として売られるようになり、これが浮世絵版画の出発点になったといわれます。","師宣の工房では、弟子たちが分担して作品をつくりました。そのため «師宣作» とされる絵の中には、弟子の手が入ったものもあると考えられています。","1948年の切手趣味週間の切手に «見返り美人» が選ばれ、のちに切手収集ブームの象徴になりました。","師宣の生年ははっきりしません。«1618年ごろ» など諸説あり、確定していません。","墓や梵鐘など、保田に残る師宣ゆかりの話は地元の伝えによるものが多いです。"],"look":["菱川師宣記念館の展示（版本・浮世絵の歴史）","道の駅にある記念館の周り","保田の海と町並み","師宣ゆかりと伝わる寺"],"q":["«見返り美人図» の原画を所蔵しているのはどこ?","東京国立博物館です。"],"koji":[],"myth":"生年、寺への梵鐘寄進の年、墓所は伝承・諸説あり。","img":["見返り美人図","浮世絵","鋸南町"],"wp":"菱川師宣","rel":{"ev":[],"grave":[]},"ph":[["c:8/8e/Self-portrait_by_Hishikawa_Moronobu.jpg",809,978,"菱川師宣"],["c:4/4d/Birth_place_of_Hishikawa_Moronobu_02.jpg",4032,3024],["c:7/7f/Beauty_looking_back.jpg",543,1125],["c:e/ea/Moronobu_b-w_shunga.jpg",580,391],["c:4/4b/MASANOBU-Theater.jpg",1291,902,"浮世絵"],["c:7/7d/Nihonji_daibutsu_and_Prunus_DSCN2878_20120314.JPG",2048,1536,"鋸南町"]]},{"id":"12_oyumi_jo","n":"小弓城（小弓公方 足利義明）","yomi":"おゆみじょう","cat":"城","rank":"B","y":1517,"era":["muromachi"],"sh":"","ad":"千葉市中央区南生実町","st":"京成千原線 学園前駅から歩いて約15〜20分、またはJR外房線 鎌取駅からバス","la":35.557,"lo":140.139,"hook":"«われこそ関東の主»。将軍家の血をひく男が、房総の小さな城を «御所» にした。","lead":"小弓城は、戦国時代に «小弓公方（おゆみくぼう）» とよばれた足利義明が本拠にした城です。義明は古河公方の一族で、兄とあらそって房総に入り、ここから関東の支配をめざしました。今は住宅地や畑の中に、わずかな地形が残るだけの城跡です。","story":["室町時代、関東には将軍家の一族 «公方» が置かれ、関東をまとめていました。ところが戦国時代になると、その公方の家（古河公方）の中で親子・兄弟げんかがくり返されます。足利義明もその一人。兄の高基と対立し、«自分こそ公方にふさわしい» と考えていました。","そこへ手をさしのべたのが、上総の真里谷武田氏です。1517年、武田氏は下総の千葉氏の重臣・原氏が守っていた小弓城を攻め落とし、義明を迎え入れました。«将軍家の血をひく人を担げば、自分たちの力も強くなる»。武田氏にはそんな計算があったといわれます。","こうして義明は小弓城に入り、«小弓公方» とよばれるようになります。房総の武士たちや、安房の里見氏も義明に味方しました。小さな城は、関東の半分を動かす «御所» になったのです。","しかし、関東にはもう一つの大きな力が育っていました。相模の北条氏です。1538年、義明は下総の国府台（今の市川市）で北条氏綱の軍とぶつかります。これが «第一次国府台合戦»。義明は自ら先頭に立って戦いましたが討ち死にし、小弓公方はわずか一代、約20年で終わりました。","義明の死後、小弓城には原氏が戻ったとされます。義明の息子の頼淳は里見氏のもとに逃れ、その子孫はのちに喜連川氏として江戸時代まで続きました。«関東の主» の夢は、房総の小さな城で一瞬かがやいて消えたのです。"],"tl":[["室町時代","千葉氏の重臣・原氏の城として使われる"],["1517年","真里谷武田氏が小弓城を攻め落とし、足利義明を迎える"],["1517年以後","義明が «小弓公方» として勢力をもつ"],["1538年","第一次国府台合戦で義明が討ち死に"],["その後","原氏が戻ったとされる"],["1590年","豊臣秀吉の小田原攻めで北条方の城は役目を終える"]],"who":[["足利義明","小弓公方。古河公方の一族で、兄と争った"],["真里谷信清（恕鑑）","上総武田氏。義明を小弓に迎えた"],["北条氏綱","相模の戦国大名。国府台で義明を破った"],["里見義堯","安房の戦国大名。義明に味方した"],["原氏","小弓城のもとの城主。千葉氏の重臣"]],"deep":["«小弓» は «生実» とも書き、どちらも «おゆみ» と読みます。今の千葉市中央区の «生実町»«南生実町» にその名が残ります。","小弓城と生実城は、名前が似ていて混同されやすい城です。研究では、南側の小弓城が古く、義明の御所となり、北側の生実城がのちの原氏の城と考える説が有力ですが、異論もあります。","第一次国府台合戦では、義明に味方した里見義堯はほとんど戦わずに引き上げたといわれます。義明の死は、結果として里見氏が房総で勢力を広げるきっかけになりました。","義明の子孫は喜連川氏（栃木県）となり、江戸時代には石高が少ないのに «御所» の格式を認められた特別な家でした。","城跡は開発で多くが失われ、私有地も多いです。土塁などの見学は外から、周りの人の迷惑にならないようにしましょう。"],"look":["南生実町に残る台地のへりと谷（城の地形）","周りの寺社に残る城の伝え","近くの生実城跡とくらべて歩く"],"q":["足利義明が討ち死にした戦いは?","1538年の第一次国府台合戦です。"],"koji":[],"myth":"小弓城と生実城の位置・関係には諸説ある。義明の討ち死にの様子は軍記物による部分が多い。","img":["足利義明","小弓公方","国府台合戦"],"wp":"小弓城","rel":{"ev":[],"grave":[]},"ph":[["c:4/4d/Minamioumio2.jpg",800,600,"小弓城"],["c:7/7d/Ch%C3%A2teau_de_Himeji02.jpg",2592,1944],["c:c/c5/%E6%97%A5%E6%9C%AC%E3%81%AE%E5%9F%8E%E8%B7%A1.png",971,940],["c:9/99/Oyumi3.jpg",1000,750],["c:6/65/Oyumi2.jpg",1000,750],["c:0/00/%E8%B6%B3%E5%88%A9%E7%BE%A9%E6%98%8E%E3%81%AE%E8%8A%B1%E6%8A%BC.jpg",1743,1536,"足利義明"],["c:d/d4/Battle_of_K%C5%8Dnodai_%28Osaka_battlefield%29.jpg",4592,3056,"国府台合戦"]]},{"id":"12_yoritomo_joriku","n":"源頼朝上陸地（竜島・石橋山から逃れて）","yomi":"みなもとのよりともじょうりくち","cat":"伝承","rank":"B","y":1180,"era":["heian","kamakura"],"sh":"","ad":"安房郡鋸南町竜島","st":"JR内房線 安房勝山駅から歩いて約10分","la":35.123,"lo":139.832,"hook":"戦いに敗れ、小舟で海をわたった頼朝。この浜から、鎌倉幕府への逆転劇が始まった。","lead":"1180年、平家をたおそうと兵をあげた源頼朝は、石橋山（神奈川県）の戦いで大敗しました。わずかな家来と船で相模湾から逃れ、たどりついたのが安房の竜島だといわれます。ここで力をたくわえた頼朝は、わずか2か月ほどで鎌倉に入り、やがて武士の政権をつくりました。","story":["1180年8月、伊豆に流されていた源頼朝は、平家をたおすために兵をあげました。ところが、相模の石橋山で平家方の大軍にやぶれてしまいます。頼朝は山の中をさまよい、洞窟に隠れたという話まで残るほど、命からがらの逃避行でした。","«ここにいては命がない。海をわたって安房へ行こう»。頼朝は真鶴の浜から小舟に乗り、相模湾を横切りました。鎌倉幕府の記録『吾妻鏡』には、頼朝が安房国の «猟島（りょうしま）» に着いたと書かれています。これが今の鋸南町竜島のことだと考えられています。","安房には、頼朝に味方する武士たちがいました。安西景益らがかけつけ、頼朝をむかえます。浜に立った頼朝は、きっと海の向こうの相模をふりかえったことでしょう。«ここからもう一度やり直すのだ»。","頼朝は房総半島を北へ進み、上総の上総広常、下総の千葉常胤といった大きな武士団を味方につけていきます。軍勢はみるみるふくれあがり、同じ年の10月には鎌倉に入りました。わずか2か月前には逃げていた男が、東国の主になったのです。","竜島の浜には «源頼朝上陸地» の碑が立っています。周りには頼朝ゆかりの伝説も多く残ります。«負けても、あきらめなければ道はひらける»。房総の人々は、この上陸の話を誇りをもって語りついできました。"],"tl":[["1180年8月","頼朝が伊豆で挙兵。石橋山の戦いで敗れる"],["1180年8月末","真鶴から船で安房へ。«猟島» に上陸（吾妻鏡）"],["1180年9月","上総広常・千葉常胤らが味方に加わる"],["1180年10月","頼朝、鎌倉に入る"],["1185年","平家が壇ノ浦で滅亡"],["1192年","頼朝、征夷大将軍になる"]],"who":[["源頼朝","石橋山で敗れ、安房に上陸して再起した"],["安西景益","安房の武士。頼朝をむかえた"],["上総広常","上総の大武士団の長。大軍で頼朝に合流した"],["千葉常胤","下総の武士。頼朝を支え、鎌倉幕府の重臣になった"]],"deep":["『吾妻鏡』は鎌倉幕府がのちにまとめた歴史書です。頼朝の上陸地 «猟島» を竜島にあてるのが通説ですが、上陸地には別の説もあります。","頼朝が海をわたったのは、北条時政や三浦氏の人々が先に安房へ向かっていたこととも関係があるといわれます。三浦半島と房総は、海でつながる近い土地でした。","上総広常は大軍をつれて合流したものの、遅れてきたことを頼朝にしかられたという話が『吾妻鏡』にあります。のちに広常は頼朝に殺されました。","千葉常胤は、頼朝に «相模の鎌倉を本拠にしなさい» とすすめたと『吾妻鏡』に記されています。鎌倉幕府の場所選びに房総の武士が関わっていたのです。","房総半島には、頼朝が休んだ石、水を飲んだ井戸など、頼朝ゆかりの伝説地がたくさんあります。多くは言い伝えです。","竜島の近くの勝山は、江戸時代には捕鯨でも知られた港町でした。"],"look":["«源頼朝上陸地» の碑","竜島の浜と相模湾の眺め（天気がよいと対岸が見える）","近くの勝山の港町"],"q":["頼朝が安房へわたる前に敗れた戦いは?","石橋山の戦い（1180年）です。"],"koji":[{"w":"捲土重来（けんどちょうらい）","m":"一度敗れた者が、力をたくわえてふたたび勢いよく盛り返すこと"}],"myth":"上陸地を竜島とするのは通説で、異説もある。洞窟に隠れた話など逃避行の細部は伝承・軍記物による。","img":["源頼朝","石橋山の戦い","吾妻鏡"],"wp":"鋸南町","rel":{"ev":[],"grave":[]},"ph":[["c:7/7d/Nihonji_daibutsu_and_Prunus_DSCN2878_20120314.JPG",2048,1536,"鋸南町"],["c:e/e2/%E6%B1%9F%E6%9C%88%E6%B0%B4%E4%BB%99%E3%83%AD%E3%83%BC%E3%83%89_-_panoramio_%288%29.jpg",5471,3647],["c:9/9c/%E5%AF%8C%E6%B4%A5%E9%A4%A8%E5%B1%B1%E9%81%93%E8%B7%AF_-_panoramio.jpg",5471,3647],["c:2/20/Uki-Island_Kyonan_town.JPG",4000,3000],["c:4/43/Nihonji_Temple_-_Kwan_Non.JPG",4928,3264],["c:c/c6/Flickr_-_%E2%80%A6trialsanderrors_-_Hiroshige%2C_The_coast_at_Hota_in_Awa_province%2C_1858.jpg",5064,7696],["c:5/5c/Awa-Katsuyama_Station_2024_%28cropped%29.jpg",4254,2903],["c:2/28/Hota_kyakuden.JPG",3072,2304]]},{"id":"12_hara_oyumi_jo","n":"生実城（原氏の城）","yomi":"おゆみじょう","cat":"城","rank":"B","y":1540,"era":["muromachi","azuchi","edo"],"sh":"","ad":"千葉市中央区生実町","st":"京成千原線 学園前駅から歩いて約15分","la":35.566,"lo":140.135,"hook":"千葉氏をささえた重臣・原氏が、公方を追い出したあとにきずいた城。江戸時代には小さな藩の陣屋になった。","lead":"生実城は、戦国時代に下総の千葉氏の重臣・原氏が本拠とした城です。近くの小弓城が小弓公方にうばわれたあと、原氏はふたたび勢力を回復し、この地を拠点にしたと考えられています。江戸時代には生実藩の陣屋が置かれました。","story":["原氏は、下総の名門・千葉氏の家臣の中でもとくに力のあった一族です。戦国時代、原氏は «生実（おゆみ）» の地を本拠にしていました。ところが1517年、上総の武田氏に攻められ、城を足利義明にうばわれてしまいます。","それから約20年。1538年の国府台合戦で義明が討ち死にすると、原氏は生実の地に戻ってきました。«この地は、もともと我らのものだ»。原胤清らはふたたび生実を拠点にし、勢力を広げていったと考えられています。","原氏は相模の北条氏と結び、安房・上総の里見氏と何度も争いました。房総半島は、北条と里見の «にらみ合いの最前線» だったのです。生実城は、千葉の町と上総を結ぶ道をおさえる大事な城でした。","1590年、豊臣秀吉が北条氏を攻めると、北条方だった原氏も運命を共にし、生実城は役目を終えました。戦国の終わりとともに、原氏の名も歴史の表舞台から消えていきます。","江戸時代になると、この地には森川氏が入り、生実藩の陣屋が置かれました。小さな藩でしたが、明治まで続きます。近くのお寺には森川氏ゆかりの墓もあり、城と陣屋の記憶を今に伝えています。近くには小弓城跡もあり、二つの城跡を歩きくらべると、«どちらがどんな役目をもっていたのか?» という歴史の謎を自分の目で考えることができます。"],"tl":[["室町時代","原氏が生実の地を拠点にする"],["1517年","武田氏に攻められ、小弓の地を足利義明にうばわれる"],["1538年","義明の敗死後、原氏が生実に戻る"],["戦国時代後半","北条氏と結び、里見氏と争う"],["1590年","小田原攻めで北条方が敗れ、城は役目を終える"],["1627年","森川重俊が入り、のちに生実藩の陣屋が置かれる"]],"who":[["原胤清","原氏の当主。義明の死後に生実に戻ったとされる"],["足利義明","小弓公方。原氏から城をうばった"],["森川重俊","江戸時代の生実藩の初代藩主"]],"deep":["生実城と小弓城の位置関係には議論があります。北側の生実町にあった城を生実城、南側の南生実町の城を小弓城とする見方が多いものの、同じ城を指すとする説もあります。","原氏は千葉氏の «家宰（かさい）» として主家をしのぐほどの力をもち、臼井城なども一族の拠点でした。","生実藩は1万石ほどの小さな藩で、森川氏が江戸時代を通して治めました。","城の遺構の多くは宅地化や学校用地の開発で失われ、台地のへりや地名が手がかりとして残るだけです。","近くの重俊院は、森川重俊にちなむ名前の寺といわれます。","戦国時代の房総では、北条方の原氏・千葉氏と、里見氏とが、国府台や臼井などで何度もぶつかりました。生実城はその争いの中で、千葉と上総を結ぶ道をおさえる位置にありました。","«おゆみ» の地名は、今も «おゆみ野» というニュータウンの名前に受けつがれています。古い城の名が新しい町の名に生きている例です。"],"look":["生実町の台地と谷の地形","森川氏ゆかりの寺","近くの小弓城跡とあわせて歩くと、城と地形の関係がよくわかる","おゆみ野の町名に残る «おゆみ» の地名"],"q":["江戸時代に生実の地を治めた藩主の家は?","森川氏です。生実藩として明治まで続きました。"],"koji":[],"myth":"小弓城と生実城の関係、原氏が戻った時期と人物には諸説ある。森川氏の入部年は資料で確認が必要。","img":["小弓城","原氏","生実藩","千葉氏"],"wp":"生実城","rel":{"ev":[],"grave":[]},"ph":[["c:7/74/Kitaoyumi4.jpg",1000,750,"生実城"],["c:c/c5/%E6%97%A5%E6%9C%AC%E3%81%AE%E5%9F%8E%E8%B7%A1.png",971,940],["c:8/83/Kitaoyumi6.jpg",1000,750],["c:5/59/Kitaoyumi5.jpg",1000,750],["c:5/5d/Kitaoyumi2.jpg",1000,750],["c:1/10/Kitaoyumi.jpg",1000,750],["c:4/4d/Minamioumio2.jpg",800,600,"小弓城"]]},{"id":"12_togane_jo","n":"東金城（酒井氏）","yomi":"とうがねじょう","cat":"城","rank":"B","y":1560,"era":["muromachi","azuchi","edo"],"sh":"","ad":"東金市東金","st":"JR東金線 東金駅から歩いて約15分","la":35.563,"lo":140.364,"hook":"湖のほとりの山城から、戦国の酒井氏が九十九里の平野をにらんでいた。のちには家康が鷹狩りに通った。","lead":"東金城は、戦国時代に上総の酒井氏（東金酒井氏）が本拠にした山城です。城の下には八鶴湖という池があり、今は桜の名所として知られます。豊臣秀吉の小田原攻めで城は開かれ、江戸時代には徳川家康が鷹狩りのための «東金御殿» をこの近くに建てました。","story":["戦国時代、上総の土気（とけ）と東金を治めたのが酒井氏です。一族の祖とされる酒井定隆は、土気城を本拠とし、その一族が東金城に入ったといわれます。東金城は、九十九里の平野を見わたせる台地の上にありました。","酒井定隆には、おもしろい言い伝えがあります。定隆は熱心な日蓮宗の信者で、領内の寺や人々をみな日蓮宗に改めさせたというのです。«上総七里法華» とよばれるこの話のとおり、東金の周りには今も日蓮宗の寺が多く見られます。","酒井氏は、北条氏と里見氏という二つの大きな力のあいだで、どちらにつくか何度も迷い、揺れ動きました。«強い方につかなければ、家が滅びる»。戦国の小さな領主の苦しい立場が見えてきます。最後は北条方につきました。","1590年、豊臣秀吉の小田原攻めで北条氏が敗れると、東金城も開城しました。関東には徳川家康が入ります。家康は鷹狩りが大好きで、九十九里の平野は鷹狩りにぴったり。東金には家康の休む «東金御殿» が建てられ、江戸から東金まで、ほぼまっすぐな «御成街道» がつくられました。","八鶴湖は、この御殿を建てるときに整えられたといわれます。春には湖のまわりを桜がうめつくし、たくさんの人が訪れます。«戦の城» から «将軍の遊びの場» へ。東金の歴史は、時代の移り変わりをよく表しています。"],"tl":[["室町時代後期","酒井定隆が土気城に入り、一族が東金を治めたといわれる"],["戦国時代","東金酒井氏が北条・里見のあいだで揺れ動く"],["1590年","小田原攻めで北条氏が敗れ、東金城は開城"],["江戸時代はじめ","家康の鷹狩りのため東金御殿が建てられる"],["江戸時代はじめ","船橋から東金へ «御成街道» が整えられる"],["現在","八鶴湖は桜の名所。御殿跡は学校の敷地に"]],"who":[["酒井定隆","土気・東金酒井氏の祖とされる。«上総七里法華» の伝説で知られる"],["東金酒井氏","戦国時代の東金城主"],["徳川家康","東金で鷹狩りを楽しんだ"],["徳川秀忠","2代将軍。東金に鷹狩りに来たといわれる"]],"deep":["御成街道は、船橋から東金まで約37kmをほぼ一直線に結ぶ道です。«一晩でつくられた» という伝説から «一夜街道» ともよばれますが、実際にはもっと長い時間をかけて整えられたと考えられます。","東金御殿の跡は、今の県立東金高校の敷地にあたるといわれます（学校の敷地なので、見学はできません）。","«上総七里法華» は、定隆が領民をみな日蓮宗に改めさせたという伝えで、史実としては確かめにくい部分もあります。","東金城の本丸は、八鶴湖の西側の台地にあったといわれます。今は寺や住宅地になっていて、遺構ははっきりしません。","八鶴湖の名前の由来には、湖のまわりに鶴が舞い降りたからなど、いくつかの言い伝えがあります。"],"look":["八鶴湖と桜並木","湖の西側の城山（台地の地形）","近くの日蓮宗の寺（最福寺など）","御成街道の道すじ"],"q":["家康が鷹狩りのために船橋から東金まで通したという道の名前は?","«御成街道（おなりかいどう）»。«一夜街道» の伝説でも知られます。"],"koji":[],"myth":"«上総七里法華»、«一夜街道»、八鶴湖の名の由来は言い伝え。東金酒井氏の系譜や東金城主の代々には諸説ある。","img":["八鶴湖","御成街道","土気城","東金市"],"wp":"東金城","rel":{"ev":[],"grave":[]},"ph":[["c:6/65/Toganejo.jpg",800,600,"東金城"],["c:c/c5/%E6%97%A5%E6%9C%AC%E3%81%AE%E5%9F%8E%E8%B7%A1.png",971,940],["c:a/ab/Hakkakukosakura.jpg",3520,2484,"八鶴湖"],["c:4/4a/Toke_Castle.jpg",2048,1536,"土気城"],["c:1/1e/%E5%85%AB%E9%B6%B4%E6%B9%96-%E6%9C%80%E7%A6%8F%E5%AF%BA.jpg",5460,3644,"東金市"]]},{"id":"12_oji_jo","n":"大椎城（千葉氏の旧城）","yomi":"おおじじょう","cat":"城","rank":"B","y":1126,"era":["heian","muromachi"],"sh":"","ad":"千葉市緑区大椎町","st":"JR外房線 土気駅から歩いて約20〜25分","la":35.535,"lo":140.265,"hook":"千葉市の «はじまり» は、この丘の城から千葉へ本拠を移した日にさかのぼる。","lead":"大椎城は、平安時代に千葉氏の先祖が住んでいたと伝わる城です。1126年、千葉常重がここから千葉の亥鼻（いのはな）へ本拠を移したことが «千葉開府» とされ、千葉市の誕生のもとになりました。今は緑に囲まれた丘に、土塁や堀の跡がわずかに残ります。","story":["平安時代の房総には、桓武天皇の血をひく «坂東平氏» の一族が勢力をもっていました。その中の一人・平忠常が、この大椎の地に城を築いたという言い伝えがあります。忠常は1028年に朝廷にそむいて乱を起こし、房総は大きく荒れました。","乱のあと、忠常の子孫は房総に根をはり、やがて «千葉氏» とよばれるようになります。大椎の丘は、その千葉氏の先祖たちが暮らした場所と伝えられてきました。«ここから一族は大きくなっていった» と、地元では語りつがれています。","1126年、千葉常重は大椎から千葉の亥鼻へ本拠を移したといわれます。海に近く、川が流れこむ千葉の地は、物や人が集まる便利な場所でした。«これからは千葉の地で一族を栄えさせよう»。千葉市は、この年の6月1日を «千葉開府» の日としています。","常重の子・常胤は、のちに源頼朝をたすけて鎌倉幕府の重臣になり、千葉氏は関東屈指の武士団になりました。その出発点が大椎だったと考えると、この静かな丘の見え方も変わってきます。","戦国時代にも大椎城は使われ、土気の酒井氏の城の一つになったともいわれます。今、城跡のまわりは住宅地や緑地に囲まれ、土塁や空堀の跡が残る場所もあります。千年前の武士たちの気配を探しに、そっと歩いてみたくなる場所です。"],"tl":[["1028年","平忠常の乱。房総が大きく荒れる"],["平安時代後期","忠常の子孫が大椎に住んだと伝わる"],["1126年","千葉常重が大椎から千葉（亥鼻）へ本拠を移す（千葉開府）"],["1180年","常重の子・常胤が源頼朝に味方する"],["戦国時代","酒井氏などが城を使ったといわれる"],["現在","城跡の一部に土塁・空堀の跡が残る"]],"who":[["平忠常","房総の豪族。大椎に城を築いたという伝えがある"],["千葉常重","大椎から千葉へ本拠を移し、千葉開府の人とされる"],["千葉常胤","常重の子。頼朝を支え、千葉氏を大きくした"]],"deep":["千葉市は毎年6月1日を «千葉開府記念日» とし、千葉氏と千葉市のはじまりを祝っています。","忠常が大椎城を築いたという話は後世の伝えで、同時代の史料で確かめられるものではありません。","«大椎（おおじ）» の読みは、ふつうの読み方から想像しにくい地名です。昔の地名が今も生きている例といえます。","千葉氏の家紋は «月星»（または «九曜»）。妙見信仰と深く結びつき、千葉神社（千葉市中央区）は妙見をまつる千葉氏ゆかりの神社です。","城跡の多くは私有地や保全緑地です。立ち入れない場所には入らず、周りの住民に配慮して見学しましょう。","常重が本拠を移した亥鼻は、都川の河口に近く、海と川の交通をおさえる場所でした。大椎の山の城から、水運に便利な平地の町へ。武士の本拠の移り方として典型的な例といえます。"],"look":["丘の上に残る土塁と空堀の跡（見学できる範囲で）","城跡の説明板","丘から見る谷の地形"],"q":["千葉常重が大椎から本拠を移した先は、今の千葉市のどこ?","亥鼻（いのはな）です。今は亥鼻公園に千葉市立郷土博物館があります。"],"koji":[],"myth":"平忠常の築城、千葉開府の年月日は伝承にもとづく部分がある。戦国期の城主にも諸説ある。","img":["千葉氏","平忠常の乱","千葉常重","亥鼻城"],"wp":"大椎城","rel":{"ev":[],"grave":[]},"ph":[["c:0/08/Oji_castle_site.jpg",1000,750,"大椎城"],["c:c/c5/%E6%97%A5%E6%9C%AC%E3%81%AE%E5%9F%8E%E8%B7%A1.png",971,940],["c:a/a2/Ojijo2.jpg",1000,750],["c:6/6f/View_of_the_Chiba_City_Folk_Museum_from_Chiba_Prefectural_Government_Office_Main_Building.jpg",3264,2448,"亥鼻城"]]},{"id":"12_inamura_jo","n":"稲村城（里見氏の天文の内乱）","yomi":"いなむらじょう","cat":"城","rank":"B","y":1533,"era":["muromachi"],"sh":"国指定史跡（里見氏城跡 稲村城跡）","ad":"館山市稲","st":"JR内房線 九重駅から歩いて約20分","la":34.978,"lo":139.878,"hook":"おじとおい、いとこ同士が城をめぐって殺し合った。«南総里見八犬伝» の里見家に、本当にあった骨肉の争い。","lead":"稲村城は、戦国時代の前半に安房の里見氏が本拠にした山城です。1533〜34年、ここを舞台に里見家の中で «天文の内乱» とよばれる争いが起き、当主の里見義豊が一族の義堯にたおされました。城跡には曲輪（くるわ）や堀切がよく残り、国の史跡になっています。","story":["里見氏は、室町時代の中ごろに安房に入り、しだいに勢力を広げた一族です。のちに小説『南総里見八犬伝』のモデルとなる家として有名になります。戦国時代のはじめ、里見氏は館山の平野を見下ろす稲村城を本拠にしていました。","1533年、城で事件が起きます。当主の里見義豊が、叔父の里見実堯と、重臣の正木通綱を殺したのです。«叔父が自分の地位をねらっている» と義豊は考えたのでしょうか。理由ははっきりしませんが、これが一族を二つに割る大きな内乱の始まりでした。","父を殺された実堯の子・義堯は、上総へ逃れ、相模の北条氏綱に助けを求めます。«必ず父のかたきを討つ»。北条氏の支援を受けた義堯は安房に攻め入り、1534年、犬掛（いぬかけ、今の南房総市）の戦いで義豊を破りました。義豊は命を落とし、稲村城の時代は終わります。","勝った義堯は、のちに房総半島の広い範囲を支配する大名へと成長しました。ところが、この内乱の話は長いあいだ «義豊が悪い殿さまだった» という、義堯側から見た物語で語られてきました。最近の研究では、«じつは義堯のほうが北条と組んで家をうばったのでは?» という見方も出ています。","稲村城跡は、住宅地の裏にある小高い山です。主郭（本丸）の平らな場所や、尾根を断ち切る堀切がよく残り、2012年に岡本城跡とともに «里見氏城跡» として国の史跡になりました。勝者の物語の裏にかくれた真実を想像しながら、静かな山道を登ってみてください。"],"tl":[["室町時代中ごろ","里見氏が安房に入ったといわれる"],["戦国時代はじめ","里見氏が稲村城を本拠にする"],["1533年","義豊が叔父・実堯と正木通綱を殺す（天文の内乱の始まり）"],["1534年","犬掛の戦いで義堯が義豊を破る"],["戦国時代後半","義堯・義弘の代に里見氏が房総の大名に成長"],["2012年","岡本城跡とともに «里見氏城跡» として国の史跡に"]],"who":[["里見義豊","稲村城の城主。内乱で敗れて死んだ"],["里見実堯","義豊の叔父。稲村城で殺された"],["里見義堯","実堯の子。北条氏の力を借りて義豊をたおした"],["正木通綱","里見家の重臣。実堯とともに殺された"],["北条氏綱","相模の戦国大名。義堯を支援した"]],"deep":["天文の内乱の原因については、«義豊の暴走» という古い説と、«義堯側のクーデター» とみる新しい説があり、研究者のあいだで議論が続いています。","犬掛の戦いのあと、義堯はすぐに北条氏と手を切り、のちには北条と長く争うことになりました。支援をうけた相手と敵になるのが戦国の世です。","稲村城の近くには、安房国の国府があったとされる府中（南房総市）があり、城は安房の政治の中心に近い場所にありました。","城跡は私有地をふくむため、見学のときは案内板や決められた道にしたがいましょう。","«里見氏城跡» は、稲村城跡と岡本城跡の二つをまとめた国史跡です。館山城は、里見氏のもっと後の時代の城です。"],"look":["主郭（本丸）の平らな場所","尾根を断ち切る堀切","城の入り口の説明板","山の上から見る館山の平野"],"q":["里見家の内乱で、義豊が義堯に敗れた戦いは?","1534年の犬掛（いぬかけ）の戦いです。"],"koji":[],"myth":"内乱の原因や細部には諸説ある。里見氏の安房入国の時期・経緯も伝承が多い。","img":["里見氏","里見義堯","南総里見八犬伝"],"wp":"稲村城","rel":{"ev":[],"grave":[]},"ph":[["c:c/c5/%E6%97%A5%E6%9C%AC%E3%81%AE%E5%9F%8E%E8%B7%A1.png",971,940],["c:b/b7/Futatsuhikiryo_sw.jpg",300,300,"里見氏"],["c:0/04/%E9%87%8C%E8%A6%8B%E7%BE%A9%E5%A0%AF%E6%9C%A8%E5%83%8F.jpg",1055,1200,"里見義堯"],["c:f/fe/Satomi_and_the_Eight_%E2%80%9CDogs%E2%80%9D_WDL2937.pdf",1831,2500,"南総里見八犬伝"]]},{"id":"12_okamoto_jo","n":"岡本城（里見義頼の海城）","yomi":"おかもとじょう","cat":"城","rank":"B","y":1580,"era":["muromachi","azuchi"],"sh":"国指定史跡（里見氏城跡 岡本城跡）","ad":"南房総市富浦町豊岡","st":"JR内房線 富浦駅から歩いて約15〜20分","la":35.043,"lo":139.835,"hook":"海に突き出した崖の上の城。里見の水軍は、ここから東京湾ににらみをきかせた。","lead":"岡本城は、戦国時代の終わりごろに里見氏が本拠にした城です。海に面した丘の上にあり、船の出入りする港をおさえる «海城（うみじろ）» でした。里見義頼の時代に大事な拠点となり、のちに館山城へ本拠が移ります。城跡は国の史跡で、公園として歩くことができます。","story":["戦国時代の里見氏は «海の大名» でもありました。房総半島の南は三方を海に囲まれ、東京湾をはさんで北条氏と向き合っています。«海を制する者が、房総を制する»。里見氏は強い水軍をもち、たびたび三浦半島まで攻めこみました。","岡本城は、富浦の海に突き出した丘に築かれました。城の下には入り江があり、船をつなぐのにぴったりです。崖は海から切り立ち、攻めるのはむずかしい。まさに水軍の本拠にふさわしい場所でした。","里見義頼は、義弘のあとをついで里見家をまとめた人物です。義弘の晩年に里見氏は長く争ってきた北条氏と和睦しており、義頼の時代には岡本城が里見家の中心として使われたと考えられています。家族や家臣の屋敷もあったと考えられます。","義頼の子・義康の時代になると、里見氏は館山城に本拠を移します。1590年の小田原攻めのあと、里見氏は安房一国の大名として生き残りましたが、江戸時代のはじめ、1614年に安房を取り上げられ、伯耆国（今の鳥取県）の倉吉へ移されてしまいます。","岡本城跡は、今は城山公園として整備されています。丘の上から見る富浦の海はとても美しく、晴れた日には対岸の三浦半島や富士山が見えることも。«この海を見ながら、里見の武将たちは何を考えていたのだろう?» 潮風の中で想像してみてください。"],"tl":[["戦国時代","里見氏が富浦の丘に岡本城を築く"],["1570年代後半〜1580年代","里見義頼の時代に本拠として使われる"],["1587年","義頼没。子の義康があとをつぐ"],["1590年ごろ","義康が館山城に本拠を移す"],["1614年","里見氏、安房を没収され伯耆国倉吉へ"],["2012年","稲村城跡とともに «里見氏城跡» として国の史跡に"]],"who":[["里見義頼","戦国末期の当主。岡本城を拠点に家をまとめた"],["里見義康","義頼の子。本拠を館山城へ移した"],["里見忠義","義康の子。安房を没収され倉吉へ移された"],["里見水軍","東京湾を舞台に北条水軍と戦った"]],"deep":["岡本城がいつ誰によって築かれたかははっきりしません。義頼より前から城があったとする説もあります。","発掘調査では建物の跡などが確認され、城の中に屋敷があったことがうかがえます。城の構造にはまだわからない点も多く残っています。","里見氏は1614年、縁戚の大久保忠隣の失脚に連なる形で安房を没収されたといわれます。倉吉で当主・忠義が亡くなり、大名としての里見家は絶えました。","倉吉で忠義に殉じた8人の家臣の話が『南総里見八犬伝』の «八犬士» のもとになったという説がありますが、はっきりした証拠はありません。","城の周りには、船の出入りに使われたと考えられる入り江があり、海城の性格をよく表しています。","里見氏の歴代の本拠は、稲村城 → 岡本城 → 館山城と移ったと考えられています。時代とともに、山の城から海と町に近い城へと移っていったことがわかります。"],"look":["城山公園の主郭（本丸）あと","海に面した崖と入り江","丘から見る富浦湾の景色","城の説明板"],"q":["里見氏が岡本城のあとに本拠を移した城は?","館山城です。"],"koji":[],"myth":"築城者・築城年は諸説。倉吉の殉死家臣と八犬士を結びつける話は説の一つ。","img":["里見義頼","館山城"],"wp":"里見氏","rel":{"ev":[],"grave":[]},"ph":[["c:b/b7/Futatsuhikiryo_sw.jpg",300,300,"里見氏"],["c:a/a1/Tateyama_Castle%2C_tenshu.JPG",5502,3655,"館山城"],["c:f/fb/JR_Uchib%C5%8D_Line_Tomiura_Station_building.jpg",4161,2949,"近く: 富浦駅 (千葉県)"],["c:5/5b/Michinoeki_Tomiura.jpg",3072,2304,"近く: 富浦町"],["c:2/23/Minamiboso_Montage.jpg",2468,3412,"近く: 南房総市"],["c:1/17/Tomiura_IC.JPG",1280,960,"近く: 富浦インターチェンジ"],["c:7/79/Tomiura_Haraoka_Pier_201808c.jpg",2400,1800,"近く: 原岡桟橋"]]},{"id":"12_mariyatsu_jo","n":"真里谷城（上総武田氏）","yomi":"まりやつじょう","cat":"城","rank":"B","y":1460,"era":["muromachi"],"sh":"","ad":"木更津市真里谷","st":"JR久留里線 馬来田駅から車で約10分。公共交通では行きにくいので車が便利","la":35.335,"lo":140.045,"hook":"甲斐の武田の血をひく一族が、房総の山深い城で «公方» をかつぎ、関東を揺らした。","lead":"真里谷城は、室町時代に甲斐（山梨県）の武田氏の一族が上総に入って築いた山城です。この一族は «上総武田氏»、城の名から «真里谷武田氏» とよばれました。戦国時代には小弓公方・足利義明をかつぐほどの力をもちましたが、やがて内紛で力を失いました。","story":["室町時代の中ごろ、関東では «享徳の乱» という大きな戦乱が続いていました。古河公方の足利成氏は、甲斐の武田信長を上総に送りこみ、敵方をおさえさせました。信長は上総に根をおろし、その子孫が真里谷と長南（ちょうなん）を拠点に勢力を広げていきます。","真里谷城は、深い谷にかこまれた山の上にありました。«真里谷（まりやつ）» の «やつ» は、谷を意味する房総や鎌倉の言葉です。いくつもの谷がいりくんだ地形は、敵の攻撃を防ぐ天然の堀になりました。","戦国時代、真里谷武田氏の当主・真里谷信清（恕鑑）は、古河公方の一族の足利義明をむかえて «小弓公方» としてかつぎました。«公方さまを味方にすれば、房総で一番の力をもてる»。武田氏は原氏の小弓城をうばい、義明を入れました。","ところが、1538年の国府台合戦で義明が討たれ、恕鑑も亡くなると、武田家では後つぎをめぐる争いが起きます。一族はばらばらになり、北条氏と里見氏がそれぞれに介入しました。真里谷武田氏はしだいに力を失い、房総の支配権は里見氏や北条氏へと移っていきました。","今、真里谷城跡の一帯は緑の森の中にあり、曲輪や堀の跡が残っています。«甲斐の武田» というと信玄が有名ですが、房総にも武田の一族がいて、関東の歴史を動かしていた。そんな意外な事実に出会える城です。"],"tl":[["1455年ごろ","享徳の乱。武田信長が上総に入る"],["室町時代後期","真里谷・長南に武田氏が根をおろす"],["1517年","真里谷武田氏が小弓城を攻め、足利義明を迎える"],["1538年","国府台合戦で義明が敗死"],["1530年代〜40年代","武田家で後つぎ争いが起き、北条・里見が介入"],["戦国時代後半","真里谷武田氏が衰え、城は役目を終える"]],"who":[["武田信長","甲斐武田氏の一族。上総に入り、上総武田氏の祖となった"],["真里谷信清（恕鑑）","小弓公方を擁立した当主"],["足利義明","真里谷武田氏がかついだ小弓公方"],["里見義堯","武田家の内紛に介入した安房の大名"]],"deep":["«上総武田氏» は甲斐武田氏の分家です。武田信玄とは遠い親戚にあたりますが、戦国時代には別々に行動していました。","信長が上総に入った年や、真里谷城をいつ築いたかについては諸説があり、はっきりしません。","武田氏の後つぎ争いは、信応と信隆の対立として知られます。信隆は北条氏、信応は里見氏をたのんだといわれます。","«やつ（谷）» の地名は房総に多く、真里谷のほかに «〇〇谷（やつ）» と読む地名がたくさんあります。","城跡の周辺は山林やキャンプ場などに利用されてきました。立ち入りできる範囲は現地で確認し、山道では足元に注意しましょう。","長南武田氏は、真里谷武田氏とならぶもう一つの上総武田氏の家で、今の長南町を拠点にしました。二つの家は協力したり対立したりしながら、上総に勢力をもちました。"],"look":["山の上の曲輪（平らな場所）","谷をせきとめる堀や切岸","城跡から見る上総の山なみ"],"q":["«真里谷» の «やつ» は何を表す言葉?","«谷（やつ）»。房総や鎌倉で谷を指す言葉です。"],"koji":[],"myth":"武田信長の上総入国年、築城年、城主の代々には諸説がある。","img":["上総武田氏","武田信長 (上総武田氏)","享徳の乱"],"wp":"真里谷城","rel":{"ev":[],"grave":[]},"ph":[["c:6/6d/Mariyatsu-Castle_Senjyojiki.JPG",3008,2000,"真里谷城"],["c:6/60/Mariyatsu-Castle_Shiroyama-Jinjya_Torii.JPG",3008,2000],["c:7/7d/Ch%C3%A2teau_de_Himeji02.jpg",2592,1944],["c:c/c5/%E6%97%A5%E6%9C%AC%E3%81%AE%E5%9F%8E%E8%B7%A1.png",971,940],["c:6/65/Kisarazu-campground.jpg",600,450]]},{"id":"12_mangi_jo","n":"万喜城（土岐氏）","yomi":"まんぎじょう","cat":"城","rank":"B","y":1560,"era":["muromachi","azuchi"],"sh":"","ad":"いすみ市万木","st":"JR外房線 長者町駅から車で約10分、またはいすみ鉄道 国吉駅から歩いて約30分","la":35.265,"lo":140.328,"hook":"川が大きく曲がる丘の上。美濃の名門の流れをくむ土岐氏が、ここで最後まで里見と北条のあいだを戦いぬいた。","lead":"万喜城は、戦国時代に上総の土岐氏が本拠にした山城です。夷隅川が城の周りを大きく回りこむように流れ、天然の堀になっていました。1590年、豊臣秀吉の関東攻めのあと、徳川家の本多忠勝の軍に攻められて落城したといわれます。今は城跡公園として展望台が建っています。","story":["土岐氏は、もともと美濃（岐阜県）の守護をつとめた名門の一族です。その流れをくむ一族が上総に来て、夷隅地方に根をおろしたといわれます。万喜城の土岐氏は «上総土岐氏» とよばれ、戦国時代には夷隅地方を治める領主でした。","城は、夷隅川がぐるりと曲がる場所の丘の上にありました。«川が堀で、崖が城壁»。自然の地形を生かした、攻めにくい城です。丘からは周りの田んぼや村が見わたせ、敵が近づけばすぐにわかりました。","戦国時代の房総は、里見氏と北条氏の争いの舞台でした。土岐氏は、はじめは里見氏と結んでいましたが、のちに北条氏の側につきます。«どちらにつけば家を守れるのか»。土岐氏は里見氏の攻撃を何度も受けながらも、万喜城を守りぬいたといわれます。","しかし1590年、豊臣秀吉が北条氏を攻めると、北条方の城は次々に落ちていきます。万喜城も、家康の家臣・本多忠勝の軍に攻められて落城したと伝わります。忠勝はそのあと近くの大多喜城に入り、この地を治めました。","今、万喜城跡は «万木城跡公園» として整備され、丘の上には天守のような形の展望台が建っています（戦国時代の建物を再現したものではありません）。展望台からは夷隅川の流れやいすみの田園が見わたせます。春には桜も咲き、ハイキングにぴったりの場所です。"],"tl":[["室町時代後期","上総土岐氏が夷隅地方に勢力をもつ"],["戦国時代","土岐氏が万喜城を本拠にする"],["戦国時代後半","里見氏から北条氏の側へ移り、里見氏と争う"],["1590年","小田原攻めのあと、本多忠勝の軍に攻められ落城したといわれる"],["1590年","本多忠勝が大多喜城に入る"],["現在","万木城跡公園として整備"]],"who":[["土岐為頼","上総土岐氏の当主。万喜城を拠点にした"],["本多忠勝","徳川家康の家臣。万喜城を攻め、大多喜城主になった"],["里見義弘","安房・上総の大名。土岐氏と争った"]],"deep":["城の名は «万喜» と書くほか、地名では «万木» と書きます。どちらも «まんぎ» と読みます。","上総土岐氏がいつ、どのように上総に来たのかははっきりしていません。美濃の土岐氏との系図のつながりにも諸説があります。","本多忠勝による落城については、軍記物や地元の伝えによる部分が多く、実際の戦いの規模ははっきりしません。","丘の上の展望台は昭和以降に建てられたもので、城の建物を再現したものではありません。","城跡には曲輪や堀切の跡があり、戦国の山城の形をよく伝えています。","本多忠勝は «徳川四天王» の一人で、生涯に一度も戦で傷を負わなかったと伝わる猛将です。大多喜城主となった忠勝は、城下町の整備も進めました。"],"look":["万木城跡公園の展望台","夷隅川が城を回りこむ地形","曲輪や堀切の跡","春の桜","近くの大多喜城（千葉県立中央博物館 大多喜城分館）とあわせてめぐる"],"q":["万喜城を落としたといわれる徳川家の武将はだれ?","本多忠勝です。のちに近くの大多喜城主になりました。"],"koji":[],"myth":"土岐氏の出自、万喜城の落城のようすには諸説・伝承がある。","img":["本多忠勝","大多喜城","いすみ市"],"wp":"万喜城","rel":{"ev":[],"grave":[]},"ph":[["c:0/02/Mangijo.jpg",800,600,"万喜城"],["c:7/7d/Ch%C3%A2teau_de_Himeji02.jpg",2592,1944],["c:c/c5/%E6%97%A5%E6%9C%AC%E3%81%AE%E5%9F%8E%E8%B7%A1.png",971,940],["c:4/40/Portrait-Honda-Tadakatsu.jpg",824,1189,"本多忠勝"],["c:7/7d/Otaki_Castle_02.jpg",3463,2309,"大多喜城"],["c:0/03/Isumi_Montage.jpg",2460,3488,"いすみ市"]]},{"id":"12_sanuki_jo","n":"佐貫城","yomi":"さぬきじょう","cat":"城","rank":"B","y":1567,"era":["muromachi","edo"],"sh":"","ad":"富津市佐貫","st":"JR内房線 佐貫町駅から歩いて約25分","la":35.208,"lo":139.88,"hook":"北条と里見がぶつかった房総の最前線。戦国の城は、江戸時代には小さな藩の城として明治まで続いた。","lead":"佐貫城は、東京湾に近い富津市の丘にあった城です。戦国時代には里見氏の大事な拠点となり、北条氏との激しい争いの舞台になりました。江戸時代には佐貫藩の城となり、明治まで使われました。今は森の中に曲輪や堀の跡が残っています。","story":["佐貫城は、室町時代に上総の武田氏が築いたともいわれます。東京湾に近く、海からも陸からも攻められる場所にあった佐貫は、房総の «入り口» をおさえる大事な土地でした。","戦国時代、里見氏がこの城を手に入れると、佐貫城は里見氏の北の守りの要になりました。里見義弘はこの城を拠点にして、北条氏と何度も戦ったといわれます。«ここを破られれば、安房まで攻めこまれる»。城を守る兵たちは、いつも緊張していたはずです。","1567年、北条氏政の軍が佐貫の近くまで攻めこみました。里見義弘は三船山のあたりで迎え撃ち、北条軍を破ります。これが «三船山合戦» です。里見氏はこの勝利で上総での勢いを取りもどしました。","江戸時代になると、佐貫城には徳川家の家臣が入り、佐貫藩の城になりました。城主の家は何度か入れかわり、18世紀のはじめからは阿部氏が明治まで治めたといわれます。戦の城から、藩の政治をおこなう城へと役割が変わったのです。","明治になって城は取りこわされ、今は森の中に曲輪や土塁、堀の跡が残るばかりです。城の入り口あたりには説明板があります。«かつてここで、房総の運命を決める戦いがあった»。そう思って耳をすますと、森のざわめきがちがって聞こえてきます。«なぜこんな山の中に城を?» と思うかもしれません。でも丘の上に立つと、東京湾と内房の道がひと目で見わたせます。城の場所には、必ず理由があるのです。"],"tl":[["室町時代","武田氏が築いたともいわれる"],["戦国時代","里見氏の拠点となり、北条氏と争う"],["1567年","三船山合戦で里見義弘が北条軍を破る"],["1590年","関東に徳川家康が入り、城は徳川方へ"],["江戸時代","佐貫藩の城として使われる"],["1871年","廃藩置県。やがて城は役目を終える"]],"who":[["里見義弘","佐貫城を拠点に北条氏と戦った"],["北条氏政","三船山合戦で里見軍に敗れた"],["阿部氏","江戸時代の佐貫藩主の家"]],"deep":["三船山合戦の «三船山» は、今の君津市・富津市の境にある山です。合戦の正確な場所や規模には諸説があります。","佐貫城の築城者と築城年については、武田氏説などがありますが、はっきりしていません。","江戸時代の佐貫藩の藩主は、内藤氏・松平氏などを経て阿部氏に落ちついたとされます。","城跡の多くは山林や私有地です。見学は説明板のあたりや、立ち入りが認められた場所にとどめましょう。","戦国時代の里見氏の城の中では、佐貫城は «久留里城» と並ぶ上総の重要拠点でした。","里見義弘は1578年に亡くなりました。その死後、里見家では後つぎをめぐる争いがおこり、義頼が家をまとめることになります。","佐貫の近くには、江戸時代の内房の港町や、東京湾をわたる海の道がありました。佐貫城は海と陸の両方を見はる位置にあったのです。"],"look":["城跡入り口の説明板","森の中の曲輪と土塁","堀の跡（谷になっている部分）","近くの海岸から見る東京湾（城が見はった海）"],"q":["1567年、里見義弘が北条軍を破った戦いは?","三船山合戦です。"],"koji":[],"myth":"築城者・築城年、三船山合戦の詳細、江戸期の藩主家の変遷の細部には諸説がある。","img":["里見義弘","三船山合戦","佐貫藩"],"wp":"佐貫城","rel":{"ev":[],"grave":[]},"ph":[["c:a/a9/Sanuki_Castle.jpg",3872,2592,"佐貫城"],["c:c/c5/%E6%97%A5%E6%9C%AC%E3%81%AE%E5%9F%8E%E8%B7%A1.png",971,940],["c:3/3b/%E9%87%8C%E8%A6%8B%E7%BE%A9%E5%BC%98%E5%83%8F.jpg",518,528,"里見義弘"]]},{"id":"12_kanegasaku","n":"金ヶ作陣屋跡（小金牧の野馬奉行）","yomi":"かねがさくじんやあと","cat":"城","rank":"B","y":1730,"era":["edo"],"sh":"","ad":"松戸市常盤平陣屋前","st":"新京成線 常盤平駅から歩いて約10分","la":35.798,"lo":139.956,"hook":"団地の町の地名 «陣屋前»。そこにはかつて、何千頭もの野馬を見守る役人の屋敷があった。","lead":"江戸時代、下総の台地には幕府の «小金牧» が広がり、野馬が放し飼いにされていました。金ヶ作陣屋は、その牧を管理する «野馬奉行» の役所です。建物は残っていませんが、今の松戸市常盤平の «陣屋前» という地名と記念碑が、その場所を伝えています。","story":["江戸のすぐ東、今の松戸・柏・鎌ケ谷・船橋のあたりには、草原と林が果てしなく続いていました。幕府はここに «小金牧» という広い牧場を置き、軍馬になる馬を育てました。馬たちはほとんど人の手をかけずに、群れで自由に暮らしていました。","この広い牧を管理したのが «野馬奉行» の綿貫氏です。綿貫家は代々この役目を受けつぎ、その役所と屋敷が金ヶ作に置かれました。«今年は何頭生まれたか»«村の畑が馬に荒らされていないか»。奉行は牧士（もくし）たちを指図し、牧と周りの村の両方に目を配りました。","8代将軍・徳川吉宗は、小金牧で大がかりな «鹿狩り» を行いました。何万人もの村人が勢子（せこ）としてかり出され、鹿やイノシシを追いたてる、まるでお祭りのような大行事だったといわれます。吉宗は、狩りを通して武士の気風を取りもどそうとしたとも考えられています。","明治になると牧は廃止され、開墾が始まりました。やがて昭和の高度成長期、この一帯には «常盤平団地» という大きな団地がつくられます。«馬の原っぱ» は、たくさんの家族が暮らす «団地の町» へと生まれ変わったのです。","陣屋の建物は残っていませんが、近くには陣屋跡を示す碑が立ち、«陣屋前» という地名が残っています。団地の並木道を歩きながら、ここを馬の群れが駆けていた時代を思いうかべてみてください。"],"tl":[["江戸時代はじめ","幕府が小金牧を直轄の牧として運営"],["江戸時代","野馬奉行の綿貫氏が金ヶ作に陣屋を置く"],["1726年","徳川吉宗が小金原で大規模な鹿狩りを行う"],["1869年","明治政府が牧の開墾を始める"],["1960年","常盤平団地の入居が始まる"],["現在","陣屋跡の碑と «陣屋前» の地名が残る"]],"who":[["綿貫氏","代々の野馬奉行。小金牧を管理した"],["徳川吉宗","8代将軍。小金原で鹿狩りを行った"],["牧士（もくし）","地元の有力者。奉行の下で牧の実務にあたった"],["勢子の村人たち","鹿狩りや野馬捕りにかり出された"]],"deep":["小金牧は、高田台牧・上野牧・中野牧・下野牧・印西牧の «小金五牧» からなるといわれ、今の千葉県北西部の広い範囲にまたがっていました。","吉宗の鹿狩りは、のちに11代家斉、12代家慶の時代にも行われたといわれます。","金ヶ作陣屋がいつ置かれたか、正確な年ははっきりしません。資料によって書き方に幅があります。","常盤平団地は、日本住宅公団がつくった初期の大規模団地の一つで、高度成長期の暮らしを象徴する場所になりました。","«金ヶ作» の地名は今も松戸市に残っています。牧の時代の地名が、団地の町の中に生きているのです。","小金牧の野馬は、将軍の乗る馬や軍馬の候補として選ばれました。牧で育つ馬は数千頭にのぼったともいわれますが、正確な数は時代によって変わります。"],"look":["金ヶ作陣屋跡の碑","«陣屋前» の地名と周辺の町並み","常盤平のけやき並木（団地の町の景色）"],"q":["小金牧を管理した役人を何という?","«野馬奉行（のまぶぎょう）»。綿貫氏が代々務めました。"],"koji":[],"myth":"陣屋の設置年、鹿狩りに動員された人数は資料で幅がある。常盤平団地の入居年は資料で確認を。","img":["常盤平団地","徳川吉宗"],"wp":"小金牧","rel":{"ev":[],"grave":[]},"ph":[["c:d/dc/MET_DP149423.jpg",3667,1873],["c:8/80/%E4%B8%8A%E9%87%8E%E7%89%A7%E9%AB%98%E7%94%B0%E5%8F%B0%E7%89%A7%E8%A9%B3%E7%B4%B0%E5%9B%B3.jpg",2000,2500],["c:2/24/S3p15106-%E9%87%8E%E9%A6%AC%E5%A0%80.jpg",1200,1500],["c:8/80/Kogane_shimonomaki.png",1298,1121],["c:f/f6/%E5%B0%8F%E9%87%91%E7%89%A7%E4%B8%AD%E9%87%8E%E7%89%A7.png",1172,1142],["c:0/0a/Koganemaki_inzaimaki.PNG",1519,868],["c:9/9f/Nomadshounai.png",1075,1098],["c:4/4b/Kaminomaki.png",828,1130]]},{"id":"12_iino_jinya","n":"飯野陣屋（保科氏の水堀）","yomi":"いいのじんや","cat":"城","rank":"B","y":1648,"era":["edo"],"sh":"県指定史跡（飯野陣屋濠跡）","ad":"富津市下飯野","st":"JR内房線 青堀駅から歩いて約20分","la":35.305,"lo":139.858,"hook":"小さな藩の «陣屋» なのに、まるでお城のような水堀がぐるりとめぐる。会津の名君につながる一族の屋敷跡。","lead":"飯野陣屋は、江戸時代に上総の飯野藩を治めた保科氏の陣屋（藩の役所と屋敷）の跡です。ふつう陣屋はお城より簡単なつくりですが、ここには城のような水堀が今もよく残っています。保科氏は、会津藩の祖・保科正之と深いつながりのある家でした。","story":["江戸時代、大名には «城をもつ大名» と、城をもたず «陣屋» を構える小さな大名がいました。飯野藩は約2万石の小さな藩で、藩主の保科氏は陣屋を拠点に政治を行いました。","藩をおこしたのは保科正貞です。正貞は、信濃の高遠藩主・保科正光の弟にあたります。正光には、2代将軍秀忠の子である正之が養子に入り、正之はのちに会津藩の藩主となって名君とたたえられました。飯野の保科家は、その会津の保科（松平）家と親せき同士だったのです。","1648年、正貞は上総の飯野に移り、飯野藩が生まれました。陣屋の周りには、深く大きな水堀がめぐらされました。«小さな藩でも、備えはおこたらない»。水堀は、敵を防ぐためだけでなく、藩の格式を示すものでもあったのでしょう。","保科氏は、江戸時代を通して飯野藩を治め、明治をむかえました。幕末の戊辰戦争では、親せきの会津藩が新政府軍と戦い、飯野藩も難しい立場に立たされたといわれます。やがて廃藩置県で藩はなくなり、陣屋も役目を終えました。","今、陣屋の建物は残っていませんが、水堀が形をとどめ、千葉県の史跡になっています。跡地には飯野神社がまつられています。水面に映る木々をながめながら、小さな藩が守った誇りを感じてみてください。"],"tl":[["1648年","保科正貞が飯野に入り、飯野藩が成立"],["江戸時代","保科氏が陣屋を拠点に藩を治める"],["1868年","戊辰戦争。親せきの会津藩が新政府軍と戦う"],["1871年","廃藩置県で飯野藩が廃止される"],["現在","陣屋の水堀が残り、県の史跡に"]],"who":[["保科正貞","飯野藩の初代藩主。保科正光の弟"],["保科正光","高遠藩主。正之を養子にむかえた"],["保科正之","秀忠の子。会津藩の祖となった名君"],["飯野藩の歴代藩主","明治まで保科氏が続いた"]],"deep":["陣屋の周りの堀は «濠（ほり）» として県の史跡に指定されています。陣屋で、これほど水堀がよく残る例は全国でもめずらしいといわれます。","飯野藩の石高は約2万石とされます。小さな藩の陣屋としては敷地が広く、堀の規模も大きいのが特徴です。","保科正之は、のちに将軍家から «松平» の姓を許され、会津藩主は松平家を名乗りました。飯野藩主は «保科» の名をそのまま受けつぎました。","戊辰戦争のとき、飯野藩の中には会津に心を寄せる人もいたといわれますが、藩としての行動については資料による確認が必要です。","陣屋跡の周辺は住宅地や田畑です。堀のまわりは足場が悪い所もあるので、見学のときは注意しましょう。","陣屋の周りの水堀は、近くの小糸川などからの水を引いていたと考えられています。平らな土地に堀をめぐらすことで、城のような守りをつくったのです。","飯野藩の藩主・保科氏は、江戸時代を通して一度も国替えをしませんでした。同じ家が長く同じ土地を治めた、落ちついた藩でした。"],"look":["陣屋をかこむ水堀","飯野神社（陣屋跡）","堀にかかる橋と土塁"],"q":["飯野藩の藩主の家と親せきだった、会津藩の祖はだれ?","保科正之。2代将軍秀忠の子で、保科家の養子になりました。"],"koji":[],"myth":"戊辰戦争での飯野藩の動き、陣屋の規模に関する «全国有数» といった表現は資料で幅がある。","img":["飯野藩","保科正之","保科正貞"],"wp":"飯野陣屋","rel":{"ev":[],"grave":[]},"ph":[["c:a/a6/Iinozinya1.jpg",2472,3296,"飯野陣屋"],["c:5/53/Sanjozukakohun4.JPG",3296,2472],["c:9/9b/Iinozinya4.JPG",3296,2472],["c:d/d8/Iinozinya3.JPG",3296,2472],["c:e/eb/Iinozinya2.JPG",3296,2472],["c:2/2c/Hoshina_Masayuki2.jpg",414,402,"保科正之"],["c:f/fe/Hoshina_Masasada.jpg",1261,899,"保科正貞"]]},{"id":"12_nomadote","n":"野馬土手（小金牧の土塁）","yomi":"のまどて","cat":"産業","rank":"B","y":1700,"era":["edo"],"sh":"国指定史跡（下総小金中野牧跡）","ad":"鎌ケ谷市中沢ほか","st":"新京成線 くぬぎ山駅から歩いて約15分（捕込跡）","la":35.778,"lo":140.001,"hook":"林の中に続く、人の背よりも高い土の壁。それは «馬を村に入れない» ための、江戸時代の長い長いフェンスだった。","lead":"江戸時代、幕府の小金牧では野馬が放し飼いにされていました。馬が村の畑を荒らさないように、村と牧のあいだには «野馬土手» という土の土手がつくられました。鎌ケ谷市には、土手や馬を捕まえる «捕込（とっこめ）» の跡がよく残り、国の史跡になっています。","story":["江戸時代の下総の台地は、見わたすかぎりの草原でした。ここは幕府の «小金牧»。野馬とよばれる馬が群れをつくって、自由に草を食べていました。でも、困ったことがひとつ。«馬が村の畑に入ってきて、作物を食べてしまう!»","そこで、村と牧の境に、土を高く積み上げた土手がつくられました。これが «野馬土手（野馬除土手）» です。土手の片側には堀をほって、馬が乗りこえられないようにしました。土手は何キロにもわたって続き、村人たちが力を合わせて築き、こわれると直しました。","年に一度、牧では «野馬捕り» が行われました。村人たちが大勢で馬を追い、«捕込（とっこめ）» という土手で囲んだ場所に追いこみます。そこでよい馬を選び、幕府へ送りました。選ばれなかった馬は、村人に払い下げられることもあったといいます。«走れ、走れ! そっちに行ったぞ!» 野馬捕りは、見物人も集まるにぎやかな行事だったと伝わります。","鎌ケ谷市には、小金牧のうち «中野牧» の捕込の跡がよく残っています。土手で囲まれた広場がいくつも組み合わさり、馬を追いこむ順路がわかる貴重な遺構です。野馬土手とあわせて «下総小金中野牧跡» として国の史跡に指定されました。","明治になると牧は廃止され、土手の多くはくずされて畑や住宅地になりました。それでも、林の中や道ばたに、ぽつんと土の高まりが残っていることがあります。«これは何だろう?» と思ったら、それは江戸時代の馬の歴史の証人かもしれません。"],"tl":[["江戸時代はじめ","幕府が小金牧を直轄の牧として運営"],["江戸時代","村との境に野馬土手、牧の中に捕込がつくられる"],["江戸時代","毎年、野馬捕りが行われる"],["1869年","明治政府が牧の開墾を始める"],["2000年代","鎌ケ谷市の捕込跡・野馬土手が «下総小金中野牧跡» として国の史跡に"]],"who":[["野馬奉行・綿貫氏","小金牧を管理した役人"],["牧士（もくし）","地元の有力者。野馬捕りなどの実務にあたった"],["村人たち","土手を築き、野馬捕りにかり出された"]],"deep":["野馬土手は、牧の外側（村との境）を囲むものと、牧の中を区切るものがありました。高さは人の背たけほどのものが多かったといわれます。","«捕込» は、いくつかの囲いを組み合わせたつくりで、馬を少しずつせまい場所へ追いこむ工夫がされていました。","国の史跡 «下総小金中野牧跡» は、捕込跡と野馬土手の一部などからなります。牧の遺構が国の史跡になった数少ない例です。","野馬捕りの様子は、江戸時代の絵図や記録に残されていて、その場面を再現した展示が地元の資料館で紹介されることがあります。","鎌ケ谷市の «鎌ケ谷» や周りの «五香»«六実»«初富» などの地名は、明治の開墾と深く結びついています。","土手は私有地にあるものも多いので、見学は公開されている場所で行いましょう。"],"look":["捕込跡（土手で囲まれた広場）","林の中に続く野馬土手","史跡の説明板"],"q":["野馬を追いこんで捕まえる囲いを何という?","«捕込（とっこめ）»。土手で囲んだ場所です。"],"koji":[],"myth":"史跡指定年、捕込跡の正確な所在地（町名）や最寄り駅からの時間は資料で要確認。","img":["鎌ケ谷市","佐倉牧"],"wp":"小金牧","rel":{"ev":[],"grave":[]},"ph":[["c:d/dc/MET_DP149423.jpg",3667,1873],["c:8/80/%E4%B8%8A%E9%87%8E%E7%89%A7%E9%AB%98%E7%94%B0%E5%8F%B0%E7%89%A7%E8%A9%B3%E7%B4%B0%E5%9B%B3.jpg",2000,2500],["c:2/24/S3p15106-%E9%87%8E%E9%A6%AC%E5%A0%80.jpg",1200,1500],["c:8/80/Kogane_shimonomaki.png",1298,1121],["c:f/f6/%E5%B0%8F%E9%87%91%E7%89%A7%E4%B8%AD%E9%87%8E%E7%89%A7.png",1172,1142],["c:0/0a/Koganemaki_inzaimaki.PNG",1519,868],["c:9/9f/Nomadshounai.png",1075,1098],["c:4/4b/Kaminomaki.png",828,1130]]},{"id":"12_sukezawa","n":"墨古沢遺跡（旧石器の環状ブロック群）","yomi":"すみこざわいせき","cat":"遺跡","rank":"B","y":-34000,"era":["kyuseki"],"sh":"国指定史跡","ad":"印旛郡酒々井町墨","st":"JR成田線 南酒々井駅から歩いて約20分。車が便利","la":35.715,"lo":140.28,"hook":"3万年以上前の人々が、石器のかけらで大きな «輪» をえがいて暮らしていた。","lead":"墨古沢遺跡は、旧石器時代の遺跡です。今から3万年以上前、人々はここで石器をつくりながら、輪のような形に集まって暮らしていました。その跡は «環状ブロック群» とよばれ、日本で最大級の大きさです。2019年、国の史跡に指定されました。","story":["今から3万年以上前、日本列島は今よりずっと寒い «氷河時代» でした。人々はまだ土器も田んぼももたず、狩りをしながら移動して暮らしていました。使っていた道具は石器。石を打ちかいて、するどい刃をつくっていたのです。","墨古沢遺跡では、石器や石のかけらがたくさん見つかりました。おもしろいのは、その出かたです。石器がまとまって出る場所（ブロック）が、大きなドーナツのように輪の形に並んでいたのです。«なぜ輪の形なのだろう?»","研究者たちは、こう考えています。いくつかの家族やグループが、広場を真ん中にして輪のように集まり、それぞれの場所で石器をつくったり、食事をしたりしたのではないか。つまり «ムラ» のような集まりです。輪の真ん中の広場では、みんなで話し合ったり、獲物を分けたりしたのかもしれません。","こうした «環状ブロック群» は、旧石器時代のはじめごろ、関東地方を中心に見つかっています。墨古沢遺跡の輪は直径が約60mもあり、日本最大級です。大きな輪は、たくさんの人が集まっていたことを示しています。ナウマンゾウなどの大きな動物を、みんなで協力して狩ったのではないかという説もあります。","遺跡は、印旛沼の南の台地にあります。現地は畑や林が広がる静かな場所で、昔の人が暮らした様子を想像するしかありません。でも、足もとの土の下に3万年以上前の人々の «輪» がねむっていると思うと、わくわくしてきます。"],"tl":[["約3万4千年前ごろ","旧石器時代の人々が環状ブロック群をつくる"],["平成の発掘調査","直径約60mの環状ブロック群が確認される"],["2019年","国の史跡に指定"],["現在","酒々井町が保存と活用を進めている"]],"who":[["旧石器時代の人々","石器をつくり、輪の形に集まって暮らした"],["発掘調査にあたった研究者たち","遺跡の広がりと形を明らかにした"],["酒々井町の人々","遺跡の保存と紹介に取り組んでいる"]],"deep":["«ブロック» は、石器や石のかけらがまとまって見つかる範囲のこと。そこで石器づくりなどの作業が行われたと考えられます。","環状ブロック群は、日本列島の旧石器時代のはじめ（後期旧石器時代の前半）に特徴的な遺構で、世界的にもめずらしいといわれます。","墨古沢遺跡の環状ブロック群は直径約60mで、全国の例の中でも最大級とされます。","石器の材料には、遠くの産地から運ばれた石もふくまれていると考えられ、人々の広い行動範囲がうかがえます。","輪の形の理由については、«ムラの集まり» 説のほかに、«大きな動物を狩るための集合» 説などがあり、まだはっきりしていません。","年代は、地層や炭などをもとにした推定で、«約3万4千年前» という数字には幅があります。"],"look":["遺跡のある台地の景色（現地の説明板）","酒々井町の資料展示（出土した石器）","近くの印旛沼の風景"],"q":["石器などがまとまって出る場所が輪の形に並んだ遺構を何という?","«環状ブロック群»。墨古沢遺跡のものは直径約60mで日本最大級です。"],"koji":[],"myth":"年代（約3万4千年前）や輪の形の意味は推定で諸説ある。現地の見学方法は町の案内を確認。","img":["旧石器時代","酒々井町","印旛沼"],"wp":"墨古沢遺跡","rel":{"ev":[],"grave":[]},"ph":[["c:1/12/Sumi-Furusawa_Archeological_Site_20250209.jpg",4032,3024,"墨古沢遺跡"],["c:a/a9/Sumi-Furusawa_Archeological_Site_Restored_Tent_20250209.jpg",4032,3024],["c:b/b0/Middle_Jomon_Period_rope_pottery_5000-4000BC.jpg",727,1189],["c:6/6f/Iinumahonke_magariya_shisui.JPG",4000,3000,"酒々井町"],["c:6/6b/Lake_Inba.JPG",4608,3456,"印旛沼"]]},{"id":"12_inaridai","n":"稲荷台1号墳（「王賜」銘鉄剣）","yomi":"いなりだいいちごうふん","cat":"遺跡","rank":"B","y":450,"era":["kofun"],"sh":"","ad":"市原市山田橋","st":"JR内房線 八幡宿駅・五井駅からバスまたは車","la":35.506,"lo":140.123,"hook":"さびた鉄剣をX線で調べたら、«王が賜う» という文字が浮かび上がった。日本最古級の文字資料の発見だった。","lead":"稲荷台1号墳は、市原市にあった古墳時代の円墳です。ここから出た鉄剣には、銀で «王賜（おうし）» などの文字が刻まれていました。5世紀中ごろのものと考えられ、日本で見つかった文字入りの刀剣の中でも最も古いものの一つです。","story":["1970年代、市原市で古墳の発掘調査が行われました。直径約27mほどの円墳の中から、さびついた鉄の剣が見つかります。«ただの古い剣だろう»。そのときは、だれもがそう思っていました。","それから十年ほどたった1980年代の終わり、この剣をX線で調べたところ、さびの下に、銀をはめこんでつくった文字が浮かび上がりました。表には «王賜□□敬安»、裏には «此廷□□□□»（□は読めない字）。«王が（この剣を）賜う。つつしんで…» という意味だと考えられます。","«王とはいったいだれなのか?» 研究者のあいだでは、ヤマト王権の大王（おおきみ）だとする説が有力です。大王が、上総の有力な人物に剣を与えた。つまり、5世紀の中ごろには、ヤマト王権と房総の豪族がつながっていたことを示す証拠だと考えられています。","埼玉県の稲荷山古墳の鉄剣（471年とされる）や、熊本県の江田船山古墳の大刀も、文字の入った有名な剣です。稲荷台1号墳の剣は、それらよりも少し古いと考えられ、«日本最古級の文字資料» とよばれています。","古墳そのものは、開発によって今は形をとどめていないといわれます。しかし、剣は大切に保管され、市原市の博物館などで紹介されてきました。«さびの下にかくれた数文字» が、古代の日本と房総の関係を語りだしたのです。"],"tl":[["5世紀中ごろ","稲荷台1号墳がつくられ、鉄剣がおさめられる"],["1970年代","古墳が発掘され、鉄剣が見つかる"],["1980年代後半","X線調査で «王賜» 銘が見つかる"],["現在","鉄剣は市原市で保管・紹介されている"]],"who":[["古墳に葬られた人物","大王から剣を賜った上総の有力者と考えられる"],["«王»","剣を与えた人物。ヤマト王権の大王とする説が有力"],["発掘・研究にあたった人々","X線調査で文字を見つけ、読み解いた"]],"deep":["銘文は «王賜□□敬安»（表）、«此廷□□□□»（裏）と読まれています。読めない字が多く、全文の意味にはいくつかの解釈があります。","«王» がだれかについて、ヤマト王権の大王とする説のほか、地域の王とする説もあります。«大王» ではなく «王» と書かれている点も議論の的です。","文字は、鉄に溝を彫って銀の線をはめこむ «銀象嵌（ぎんぞうがん）» という技法でつくられています。","年代は、古墳の形や一緒に出た遺物から5世紀中ごろと推定されています。稲荷山古墳鉄剣（辛亥年＝471年説）より古いとみる見方が一般的です。","市原は古代の上総国の中心地で、のちに上総国分寺や国府が置かれました。古墳時代から大事な土地だったことがわかります。","古墳の現状や見学の可否ははっきりしないので、訪ねる前に市の案内で確認しましょう。"],"look":["市原市の博物館などでの鉄剣の展示（公開状況を確認）","周辺の台地に点在する古墳","近くの上総国分寺跡"],"q":["稲荷台1号墳の鉄剣の文字は、何という技法でつくられていた?","«銀象嵌（ぎんぞうがん）»。鉄に彫った溝に銀をはめこむ技法です。"],"koji":[],"myth":"銘文の読みと «王» の正体は諸説。古墳の規模・現状、X線調査の年は資料で要確認。","img":["稲荷山古墳","上総国"],"wp":"王賜銘鉄剣","rel":{"ev":[],"grave":[]},"ph":[["c:d/db/Ichihara_montage.jpg",2464,3496,"近く: 市原市"],["c:4/4b/Tokai_University_Ichihara_Boyo_Senior_High_School.JPG",2560,1920,"近く: 東海大学付属市原望洋高等学校"],["c:3/3d/Inaridai_Kofun_Group-1%2C_funkyu.jpg",5976,3938,"近く: 稲荷台1号墳"],["c:d/d3/Ichihara_Civic_Hall.JPG",2592,1944,"近く: 市原市市民会館"],["c:d/d1/Ichihara_Fire_Department.JPG",2592,1944,"近く: 市原市消防局"],["c:4/41/Kazusa-kokubunji_yakushi-dou-2.jpg",5986,3956,"近く: 市原村 (千葉県)"]]},{"id":"12_anesaki_futagozuka","n":"姉崎二子塚古墳","yomi":"あねさきふたごづかこふん","cat":"遺跡","rank":"B","y":470,"era":["kofun"],"sh":"県指定史跡","ad":"市原市姉崎","st":"JR内房線 姉ケ崎駅から歩いて約20分","la":35.4865,"lo":140.0435,"hook":"東京湾を見下ろす台地に眠る、全長100mをこえる前方後円墳。キラキラの耳飾りをつけた «海の王» の墓かもしれない。","lead":"姉崎二子塚古墳は、古墳時代の中ごろ（5世紀ごろ）につくられた大きな前方後円墳です。房総半島の東京湾側では指折りの大きさで、中からは銀の耳飾りや石の枕が見つかりました。このあたりを治めた有力者の墓と考えられています。","story":["市原市の姉崎は、東京湾に面したおだやかな土地です。今は工場の煙突が並ぶ海ぞいも、昔は干潟と砂浜が広がり、魚や貝、塩がとれる豊かな場所でした。その海を見下ろす台地の上に、ひときわ大きな «山» があります。それが姉崎二子塚古墳。遠くから見ると山が二つ並んだように見えるので、«ふたごづか» と呼ばれてきました。","前方後円墳は、上から見ると «鍵穴» の形をしたお墓です。丸い部分（後円部）に主人を葬り、四角い部分（前方部）で儀式をしたと考えられています。この古墳は長さが100mをこえ、東京湾の東岸でとても大きい部類に入ります。«なぜ、こんなに大きなお墓を?» それは、ヤマト王権とつながった地方の王が、自分の力を人々や海を行く船に見せつけるためだった、という見方があります。","明治から昭和にかけての調査で、中から見事な品々が見つかりました。銀でつくった垂れ飾りつきの耳飾り、刀や鏡、そして石でできた枕。石枕は、亡くなった人の頭をのせるためのもので、ふちに «立花（りっか）» という飾りを差しこむ穴があるのが特徴です。この形は房総から常陸（茨城）にかけてよく見つかり、«東の海ぞい独自の葬り方» として研究者に注目されています。","ではここに眠るのはだれでしょう。古い記録には、このあたりに «上海上（かみつうなかみ）国造» という豪族がいたと出てきます。«うなかみ» は «海の上»。海とともに生きた一族にぴったりの名前です。二子塚古墳の主は、その一族の王だったのではないか、と考える人が多いのですが、名前を書いた札などは出ていないので、はっきりとはわかっていません。","古墳のまわりには、大小の古墳がいくつも集まっていて «姉崎古墳群» と呼ばれます。何世代にもわたって、この台地が王の眠る場所だったのです。ふもとには古い社・姉崎神社もあり、古墳とあわせて歩くと、1500年前の人々が海と台地をどう見ていたのか、少し想像しやすくなります。"],"tl":[["5世紀ごろ","姉崎二子塚古墳がつくられる（中期の前方後円墳）"],["6世紀ごろ","周辺に古墳が次々とつくられ、姉崎古墳群となる"],["明治時代","墳丘から副葬品が見つかる"],["昭和時代","発掘調査が行われ、石枕や耳飾りなどが確認される"],["昭和時代","千葉県の史跡に指定される"]],"who":[["上海上国造","このあたりを治めたとされる豪族。古墳の主の候補"],["ヤマト王権の大王","前方後円墳という形を広めた中央の王。地方の王とつながっていた"],["古墳をつくった人々","土を運び、斜面を整えた地元の人々。何年もかかったと考えられる"]],"deep":["«石枕» は房総半島から茨城県南部にかけて特に多く出る遺物で、ふちに «立花» という石の飾りを差した穴がある。この地域の首長層に共通した葬送の作法を示すと考えられている。","出土した銀製の垂飾付耳飾は、朝鮮半島からの影響が見られる型式。5世紀の東国の首長が、ヤマト王権を通じて、あるいは直接に大陸系の文物を手に入れていたことをうかがわせる。","«国造本紀» には «上海上国造» と «下海上国造» の名が見え、前者が上総側、後者が下総（香取・銚子方面）側と考えられている。古墳の主と直接結びつける史料はない。","姉崎古墳群には前方後円墳や円墳が集まり、首長墓が数世代にわたって続いた可能性がある。二子塚はその中でも早い段階の大型墳とみられる。","墳丘の長さは100m余りとされるが、後世の削平や道路で形が変わっており、数値は調査・資料によって少し違う。","出土品の一部は東京国立博物館に収められている。現地で実物は見られないが、市原市の埋蔵文化財の展示で房総の古墳文化を知ることができる。"],"look":["前方部と後円部のふくらみ（鍵穴の形を足で感じる）","墳丘の上から見える東京湾側の景色","周辺に点在する姉崎古墳群の小さな古墳","近くの姉崎神社"],"q":["二子塚古墳から見つかった、亡くなった人の頭をのせる道具は？","«石枕»。房総から茨城でよく見つかる、この地域らしい葬り方の道具です。"],"koji":[],"myth":"古墳の主を上海上国造とするのは推定。墳丘の長さは資料により数値に幅がある。","img":["姉崎古墳群","前方後円墳","石枕"],"wp":"姉崎二子塚古墳","rel":{"ev":[],"grave":[]},"ph":[["c:6/64/Anesaki_Futago-zuka_Kofun%2C_zenkei.JPG",6014,3996,"姉崎二子塚古墳"],["c:d/d9/Anesaki_Futago-zuka_Kofun%2C_koenbu.JPG",6016,4000],["c:5/57/Anesaki_Futago-zuka_Kofun%2C_funkyu.JPG",5996,3970],["j:d/d0/%E5%A7%89%E5%B4%8E%E4%BA%8C%E5%AD%90%E5%A1%9A%E5%8F%A4%E5%A2%B3%E5%87%BA%E5%9C%9F_%E7%9F%B3%E6%9E%95.JPG",4632,3602],["j:e/ea/%E5%A7%89%E5%B4%8E%E4%BA%8C%E5%AD%90%E5%A1%9A%E5%8F%A4%E5%A2%B3_%E5%87%BA%E5%9C%9F%E5%93%81.JPG",4882,2755],["j:3/39/%E5%A7%89%E5%B4%8E%E4%BA%8C%E5%AD%90%E5%A1%9A%E5%8F%A4%E5%A2%B3%E5%87%BA%E5%9C%9F_%E8%99%BA%E7%AB%9C%E6%96%87%E9%8F%A1.JPG",2590,2590],["c:c/c3/NintokuTomb_Aerial_photograph_2007.jpg",1000,982,"前方後円墳"],["j:0/0d/%E5%A5%88%E8%89%AF%E7%9C%8C%E5%A4%A9%E7%90%86%E5%B8%82%E6%B8%8B%E8%B0%B7%E5%87%BA%E5%9C%9F_%E7%9F%B3%E6%9E%95.JPG",5004,3555,"石枕"]]},{"id":"12_nagara_oketsu","n":"長柄横穴群","yomi":"ながらおうけつぐん","cat":"遺跡","rank":"B","y":650,"era":["kofun","asuka"],"sh":"国指定史跡","ad":"長生郡長柄町徳増","st":"JR外房線 茂原駅から車で約20分。公共交通では行きにくい","la":35.442,"lo":140.233,"hook":"がけに掘られた «家の形の部屋»。天井には屋根の棟木まで彫りこまれ、壁には謎の線刻画が残る。","lead":"長柄横穴群は、古墳時代の終わりごろ（7世紀ごろ）に、丘のがけをくりぬいてつくられたお墓の集まりです。中は家の部屋のような形にていねいに彫られ、屋根のつくりまでまねしています。壁には人や動物などをえがいたと思われる線刻もあります。","story":["千葉県のまん中あたり、長柄町の丘を歩くと、がけにぽっかりと四角い穴がいくつも並んでいるのに出会います。穴の中をのぞくと、ただのほら穴ではありません。天井は屋根のように左右に傾き、まん中には «棟木（むなぎ）» のような出っぱりまで彫られています。まるで «石でつくった家»。これが長柄横穴群です。","横穴墓（おうけつぼ）は、古墳の代わりにがけの横から穴を掘ってつくるお墓です。«なぜ、わざわざ家の形に?» それは、亡くなった人があの世でも家で暮らせるように、と願ったからだと考えられています。大きな古墳をつくれるのは一部の王だけでしたが、横穴墓は、村のリーダーやその家族が代々使った «家族のお墓» でした。","長柄の横穴群が特に注目されるのは、その彫りのていねいさです。平らな天井、アーチ形の天井、屋根形の天井など形はさまざまで、入口のまわりをきちんと整えたものもあります。房総半島は、やわらかくて掘りやすい砂岩や泥岩の丘が多く、横穴墓がとてもたくさんある地域ですが、その中でも長柄は «見本市» のように形がそろっています。","壁をよく見ると、細い線で何かがえがかれています。人の姿、家、鳥のようなもの……。何を意味するのかは研究者の間でも意見が分かれています。お葬式の場面なのか、墓をつくった人のいたずら書きなのか、後の時代の人が刻んだものなのか。«これはだれが、何のために?» と想像するのも、横穴を見る楽しみのひとつです。","横穴群は国の史跡に指定され、町によって整備されています。すぐ近くに穴の中の様子や出土品を紹介する施設もあります。1300年以上前、この丘でどんな家族が暮らし、どんな思いで墓を掘ったのか。静かな里山の中で、その答えを探してみてください。"],"tl":[["6世紀末〜7世紀ごろ","丘のがけに横穴墓が次々と掘られる"],["7世紀後半","横穴墓がくり返し使われ、追葬（あとから家族を葬ること）も行われる"],["昭和時代","発掘調査で多くの横穴が確認される"],["2002年ごろ","国の史跡に指定される"],["平成時代","史跡公園として整備される"]],"who":[["横穴墓に葬られた人々","このあたりの村の有力な家族。数世代にわたってお墓を使った"],["墓を掘った工人","やわらかい岩を削り、家の形を再現した職人たち"],["長柄町の人々","史跡を守り、見学できるよう整備してきた"]],"deep":["横穴墓の天井形態には、ドーム形・アーチ形・家形（切妻・寄棟）などがあり、長柄では棟木や垂木まで表現した精巧な家形が見られる。家形表現は死者の住まいとしての意識を示すとされる。","房総半島は全国でも横穴墓が多い地域で、上総地方の丘陵部に数千基あるともいわれる。やわらかい第三紀層の地盤が掘削に適していたことが一因。","壁の線刻画の解釈は定まっておらず、葬送儀礼、魔よけ、後世の落書きなど諸説がある。年代の決め手になる証拠が少ないことが議論を難しくしている。","横穴墓は一度で終わりではなく、同じ家族が何度も遺体を運び入れる «追葬» が行われた。群れをなしていることは、村の集団構造を反映しているとも考えられる。","古墳時代の終わりには、大きな前方後円墳がつくられなくなる一方で、横穴墓や小さな円墳が増える。王の時代から、より多くの人が墓を持つ時代への変化を示す遺跡といえる。","入口を閉じる «閉塞石» や、前庭部の整え方など、内部だけでなく入口周りにも注目すると、墓の使われ方がより見えてくる。"],"look":["天井の «棟木» の彫り（家の形がよくわかる）","壁の線刻画（見学時は照明の案内に従う）","がけに横一列に並ぶ横穴の配置","近くのガイダンス施設の展示"],"q":["がけに横から穴を掘ってつくったお墓を何という？","«横穴墓（おうけつぼ）»。古墳時代の終わりごろ、房総半島でたくさんつくられました。"],"koji":[],"myth":"線刻画の意味と年代は諸説。指定年や基数は資料で確認を。","img":["横穴墓","長柄町","古墳時代"],"wp":"長柄横穴群","rel":{"ev":[],"grave":[]},"ph":[["c:e/e7/Nagara_Yokoana_Group%2C_gaikan-1.jpg",5568,3712,"長柄横穴群"],["c:d/d0/%E9%95%B7%E6%9F%84%E6%A8%AA%E7%A9%B4%E7%BE%A42%E5%8F%B7%E5%A2%93%E7%8E%84%E5%AE%A4.JPG",5184,3456],["c:8/8f/%E9%95%B7%E6%9F%84%E6%A8%AA%E7%A9%B4%E7%BE%A42%E5%8F%B7%E5%A2%93.JPG",3456,5184],["c:b/bf/%E9%95%B7%E6%9F%84%E6%A8%AA%E7%A9%B4%E7%BE%A419%E5%8F%B7%E5%A2%93%E7%8E%84%E5%AE%A4.JPG",5184,3456],["c:e/ea/%E9%95%B7%E6%9F%84%E6%A8%AA%E7%A9%B4%E7%BE%A416%E5%8F%B7%E5%A2%93.JPG",3456,5184],["c:2/25/Nagara_Yokoana_Group-8%2C_sendou.jpg",5568,3712],["c:c/cb/Nagara_Yokoana_Group-8%2C_genshitsu.jpg",5568,3712],["c:e/ee/Nagara_Yokoana_Group-8%2C_entrance.jpg",5568,3712]]},{"id":"12_kazusa_amadera","n":"上総国分尼寺跡","yomi":"かずさこくぶんにじあと","cat":"遺跡","rank":"B","y":760,"era":["nara","heian"],"sh":"国指定史跡","ad":"市原市国分寺台中央","st":"JR内房線 五井駅からバスで約10分、下車して歩いて数分","la":35.5045,"lo":140.1,"hook":"全国の国分尼寺でもとびきり広い寺の跡。朱色の回廊と中門がよみがえり、奈良時代の «国家プロジェクト» を体で感じられる。","lead":"奈良時代、聖武天皇は全国に «国分寺» と «国分尼寺» をつくるよう命じました。上総国分尼寺はその尼寺（尼さんの寺）で、寺の敷地がとても広いことで知られます。建物は残っていませんが、中門と回廊が復元され、展示館もあります。","story":["741年、聖武天皇は一つの命令を出しました。«国ごとに、僧の寺と尼の寺を建てよ»。当時の日本は、病気のはやりや災害、反乱が続き、国じゅうが不安に包まれていました。天皇は、仏の力で国を守ってもらおうと考えたのです。こうして全国に、国分寺と国分尼寺が生まれました。","上総国（今の千葉県中部）では、国の役所・国府に近いと考えられる市原の台地に、二つの寺がつくられました。国分寺から少し離れて建てられたのが、この国分尼寺です。尼寺の正式な名前は «法華滅罪之寺（ほっけめつざいのてら）»。法華経の力で罪を消し、国を守るという意味がこめられていました。","«どうして尼寺の跡がこんなに広いの?» 発掘調査で、上総国分尼寺は寺全体の敷地がとても広く、全国の尼寺の中でも最大級だとわかりました。金堂や講堂、尼さんたちが暮らした尼坊の跡、さらに寺の運営を支えた倉や工房のような建物の跡まで見つかっています。お寺は祈る場であると同時に、大きな «役所» のような組織でもあったのです。","昭和の終わりごろ、このあたりは住宅地として開発されることになりました。しかし発掘で重要な遺構が次々に見つかり、国の史跡として守られることになりました。平成に入ると、奈良時代の建て方を研究して、中門と回廊の一部が木造で復元されました。朱色の柱と白い壁、瓦の屋根。奈良の都の寺と同じ雰囲気が、房総の台地によみがえったのです。","復元された回廊の下に立つと、1200年以上前、ここでお経を唱えた尼さんたちの声が聞こえてくるような気がします。隣の展示館では、出土した瓦や土器、寺の模型が見られます。すぐ近くの上総国分寺跡とあわせて歩けば、奈良時代の «国の守り» の考え方がよくわかります。"],"tl":[["741年","聖武天皇が国分寺・国分尼寺建立の詔を出す"],["8世紀中ごろ〜後半","上総国分尼寺が建てられる"],["平安時代","律令制のゆるみとともに、しだいに衰える"],["昭和40年代〜","宅地開発にともない発掘調査が進む"],["昭和時代","国の史跡に指定される"],["平成時代","中門・回廊の一部が復元され、展示館が開館"]],"who":[["聖武天皇","国分寺・国分尼寺建立の詔を出した天皇"],["光明皇后","聖武天皇の皇后。国分寺政策を支えたといわれる"],["国分尼寺の尼たち","ここで国の平安を祈った僧尼"],["上総国司","都から派遣され、寺の建設を進めた役人"]],"deep":["国分尼寺の正式名 «法華滅罪之寺» に対し、国分寺は «金光明四天王護国之寺»。尼寺は法華経、国分寺は金光明最勝王経を中心とした。","上総国分尼寺は、寺の中心部だけでなく、周囲の付属施設を含めた寺域全体が発掘で明らかになった数少ない例として評価されている。","復元された中門と回廊は、発掘の成果と奈良時代の建築様式をもとにした研究復元。細部には推定が含まれる。","上総国府の正確な位置は、市原市内のどこかと考えられているが確定していない。国分寺・国分尼寺の位置は国府探しの手がかりにもなっている。","周辺の国分寺台は、昭和の大規模な区画整理で生まれた住宅地。開発と遺跡保存の両立が問われた、全国的にも知られる例である。","出土した瓦には文字が刻まれたものもあり、瓦を納めた郡や村を示すと考えられる。寺の建設に国じゅうの人々が動員された様子が読みとれる。"],"look":["復元された中門と回廊（朱色の柱と瓦屋根）","展示館の出土品と寺全体の模型","金堂・講堂跡の基壇表示","近くの上総国分寺跡（七重塔の跡）"],"q":["国分尼寺の正式な名前は？","«法華滅罪之寺»。法華経の力で罪を消し、国を守ることを祈る寺でした。"],"koji":[],"myth":"復元建物は研究にもとづく推定復元。上総国府の位置は未確定。","img":["上総国分寺","国分寺","聖武天皇"],"wp":"上総国分尼寺","rel":{"ev":[],"grave":[]},"ph":[["c:a/a3/Kazusa-kokubunniji-ato_kondou-2.jpg",6014,3998,"上総国分尼寺"],["c:3/3a/Kazusa-kokubunniji-ato_shourou-2.jpg",6016,4000],["c:e/ec/Kazusa-kokubunniji-ato_nibou.jpg",6016,4000],["c:9/90/Kazusa-kokubunniji-ato_kyourou-2.jpg",6016,4000],["c:6/62/Kazusa-kokubunniji-ato_koudou.jpg",6016,4000],["c:3/37/Kazusa-kokubunniji-ato_kondou-3.jpg",6016,4000],["c:1/1d/Kazusa-kokubunniji-ato_kairou-4.jpg",6016,4000],["c:7/7c/Kazusa-kokubunniji-ato_kairou-3.jpg",5976,3938]]},{"id":"12_iikaoka","n":"飯香岡八幡宮","yomi":"いいがおかはちまんぐう","cat":"寺社","rank":"B","y":1450,"era":["asuka","muromachi","edo"],"sh":"国の重要文化財","ad":"市原市八幡","st":"JR内房線 八幡宿駅から歩いて約5分","la":35.537,"lo":140.098,"hook":"室町時代の本殿が、工場の町のすぐそばで500年以上立ち続ける。上総の «国の八幡さま»。","lead":"飯香岡八幡宮は、市原市八幡にある古い神社です。飛鳥・奈良時代のころに始まったと伝わり、上総国の八幡宮として大切にされてきました。室町時代に建てられた本殿は国の重要文化財です。","story":["内房線の八幡宿駅をおりて少し歩くと、町なかに大きな森があらわれます。その中にあるのが飯香岡八幡宮。«八幡宿（やわたじゅく）» という駅の名前も、この神社の門前町だったことから来ています。今は臨海の工場地帯が近いこの町も、昔は海辺の宿場として人でにぎわいました。","神社の始まりははっきりしませんが、白鳳時代（7世紀後半）のころにさかのぼると伝わります。奈良時代に国分寺がつくられたころ、国ごとに八幡の神をまつる動きがあり、飯香岡八幡宮は上総国の «総社八幡» として国司にも大事にされたといわれます。«飯香岡» という名前には、昔の地名や、神に供える飯の香りにちなむなど、いくつかの説があります。","境内でいちばんの見どころは本殿です。室町時代の中ごろに建てられたと考えられ、国の重要文化財に指定されています。戦国時代の戦乱、江戸時代の地震や火事、関東大震災、そして太平洋戦争の空襲……。«どうしてこの建物は生き残れたのだろう?» 地元の人々が修理を重ね、守り続けてきたからこそ、今もここに立っているのです。","この神社には、珍しいお祭りも伝わっています。«柳楯（やなぎだて）神事» と呼ばれる行事で、柳の枝でつくった楯を、決まった道すじで運んで神社に納めます。いつ、なぜ始まったのかは諸説ありますが、長い間、地域の人々が受け継いできた大切な祭りです。","境内には、根もとがつながった大きなイチョウもあり、«夫婦銀杏（めおといちょう）» として親しまれています。秋には黄金色の葉が本殿の屋根に舞い落ち、室町の建物と色鮮やかに重なります。工場の町の真ん中で、500年前の建物と古い祭りが今も生きている。そんな不思議さを味わえる場所です。"],"tl":[["7世紀後半ごろ","創建と伝わる（白鳳年間）"],["奈良〜平安時代","上総国の八幡宮として国司に崇敬されたといわれる"],["室町時代中ごろ","現在の本殿が建てられる"],["江戸時代","門前は八幡宿としてにぎわう。徳川家から社領を受けたといわれる"],["昭和時代","本殿が国の重要文化財に指定される"]],"who":[["上総国司","都から派遣された国の長官。国の神社として崇敬したと伝わる"],["源頼朝","房総の武士をたばねて鎌倉幕府を開いた人物。八幡神は源氏の守り神で、この地の八幡宮も源氏との縁が語られる"],["八幡宿の人々","祭りを受け継ぎ、本殿を守ってきた地元の人々"]],"deep":["本殿は三間社流造とされ、室町時代中期の建築。関東地方で室町期の神社本殿が残る例は少なく、建築史上の価値が高い。","«総社» とは、国司が国内の神々を一か所にまとめて参拝するための神社。飯香岡八幡宮が総社的な役割を担ったとする伝承があるが、上総の総社については別の神社を挙げる説もある。","«柳楯神事» は千葉県の無形民俗文化財として知られ、楯を運ぶ道すじや役割が細かく決まっている。起源は国府の行事と結びつける説などがあり、はっきりしない。","社名の «飯香岡» の由来は諸説あり、地名説、神饌説などが語られている。","八幡宿は房総往還（房総の海ぞいの道）の宿場で、神社の門前町として発展した。駅名にその名が残る。","境内の夫婦銀杏は、二本の幹が寄りそうように立つ大イチョウで、縁結びの木としても親しまれている。"],"look":["室町時代の本殿（国の重要文化財）の組物と屋根の曲線","夫婦銀杏（秋の黄葉が見事）","社殿を囲む鎮守の森","八幡宿の旧道の雰囲気"],"q":["駅名 «八幡宿» の «八幡» は何に由来する？","飯香岡八幡宮です。その門前にできた宿場町だったことから名づけられました。"],"koji":[],"myth":"創建年代（白鳳年間）や社名の由来は伝承・諸説。総社であったかも説が分かれる。","img":["八幡神","上総国","八幡宿駅"],"wp":"飯香岡八幡宮","rel":{"ev":[],"grave":[]},"ph":[["c:a/aa/Iigaoka-hachimangu%2C_haiden.jpg",6002,3978,"飯香岡八幡宮"],["c:8/84/20240615_Iigaoka_Hachimangu_no_Meoto_Icho_Ichihara-JPN.jpg",4032,3024],["c:4/4d/IigaokaHachimangu20110804.jpg",800,1185],["c:0/00/%E5%85%AB%E5%B9%A1%E7%A5%9E%E5%9D%90%E5%83%8F%2C_Hachiman.jpg",4912,3264,"八幡神"],["c:4/4b/JR_Uchib%C5%8D_Line_Yawatajuku_Station_East_Exit.jpg",4161,2949,"八幡宿駅"]]},{"id":"12_omura_jinja","n":"意富比神社（船橋大神宮）","yomi":"おおひじんじゃ（ふなばしだいじんぐう）","cat":"寺社","rank":"B","y":1880,"era":["heian","edo","meiji"],"sh":"","ad":"船橋市宮本5丁目","st":"京成本線 大神宮下駅から歩いて約3分","la":35.696,"lo":139.992,"hook":"境内に «灯台» が立つ神社。明治の漁師たちの海を照らした、和と洋が混ざった不思議な塔。","lead":"意富比神社は、船橋の町で «船橋大神宮» と呼ばれて親しまれる古い神社です。平安時代の «延喜式» にも名前がのっていて、天照大神をまつります。境内には明治時代に建てられた灯明台（灯台）が残っています。","story":["船橋駅から少し東へ歩くと、大きな鳥居と森が見えてきます。意富比神社、通称 «船橋大神宮»。«意富比（おおひ）» という不思議な名前は、«大きな日»、つまり太陽を意味するのではないかといわれます。昔の人は、東京湾から昇る朝日をこの地でおがんだのかもしれません。","神社の始まりは、とても古い伝説と結びついています。日本武尊（やまとたけるのみこと）が東の国へ向かったとき、この地で祈ったのがはじまりだと伝わります。本当かどうかはわかりませんが、平安時代にまとめられた «延喜式» の神名帳に «意富比神社» の名が見えるので、1000年以上前にはすでに大事な神社だったことは確かです。","江戸時代、船橋は漁業と宿場の町として栄えました。徳川家康もこの神社をあつく敬い、社領を寄進したと伝わります。町の人々は «大神宮さま» と呼び、海の安全と豊かな漁を祈りました。今も境内には、力士が寄進した «力石» や、奉納された相撲にまつわるものがあり、町と神社の深い結びつきを感じさせます。","境内でひときわ目をひくのが、木造の «灯明台» です。明治時代のはじめ、船橋の漁師たちが夜の海で迷わないように建てたもので、3階建ての瓦屋根の建物の上に、洋風の灯室がのった、和と洋のまじった姿をしています。«なぜ神社に灯台が?» それは、神社が町でいちばん高い台地にあり、神の力とともに海を照らすのにぴったりだったからでしょう。","灯明台は、のちに国からも正式な灯台として認められ、長い間、船の目じるしになりました。今は明かりを灯していませんが、船橋の海と町の歴史を伝える大切な文化財です。お祭りの日には多くの人でにぎわい、古代の太陽の神と、明治の灯台と、今の町が一つの境内に重なる、ユニークな場所です。"],"tl":[["伝説の時代","日本武尊が東征の途中に祈ったのが始まりと伝わる"],["927年","«延喜式» 神名帳が完成。意富比神社の名が記される"],["江戸時代初め","徳川家康が社領を寄進したと伝わる"],["1880年","境内に灯明台が建てられる（明治13年）"],["明治時代","灯明台が公の灯台として使われる"],["現在","船橋の総鎮守として親しまれる"]],"who":[["日本武尊","神社の始まりに関わると伝わる伝説の皇子"],["徳川家康","社領を寄進したと伝わる"],["船橋の漁師たち","灯明台を建て、海の安全を祈った"]],"deep":["«延喜式» 神名帳で下総国葛飾郡の式内社として記載される。«意富比» の読みと意味については、«大日（おおひ）» すなわち太陽神とする説が有力だが確定していない。","現在の主祭神は天照皇大神。中世以降、伊勢信仰の広まりとともに «大神宮» と呼ばれるようになったと考えられている。","灯明台は1880年（明治13年）に建てられたとされ、和風3階建ての上に洋風の灯室を載せた独特の構造。漁民の手による私設灯台が、のちに航路標識として公認された経緯を持つ。","船橋は中世に «夏見御厨» という伊勢神宮の荘園（御厨）が置かれた地とされ、伊勢信仰との結びつきが深い土地柄である。","境内の力石や相撲関係の奉納物は、江戸時代以来の奉納相撲の伝統を物語る。","灯明台は通常、内部非公開。見学できる日が限られているので、訪れる前に神社の案内を確認するとよい。"],"look":["和洋折衷の灯明台（外から見学。内部は通常非公開）","社殿と大鳥居","境内の力石","台地から町と海の方向を眺める"],"q":["意富比神社の境内に立つ、明治時代に漁師のために建てられたものは？","«灯明台»（灯台）。和風の建物の上に洋風の灯室がのった珍しい灯台です。"],"koji":[],"myth":"日本武尊の創祀、家康の寄進は伝承。«意富比» の語義は諸説。","img":["船橋市","延喜式神名帳","灯台"],"wp":"意富比神社","rel":{"ev":[],"grave":[]},"ph":[["c:f/fd/Oohijinjya3.jpg",1024,768,"意富比神社"],["c:7/78/Oohijinja-dohyo.jpg",1824,1216],["c:c/c6/%E5%A4%A7%E7%A5%9E%E5%AE%AE%E4%B8%8B%E4%BA%A4%E5%B7%AE%E7%82%B920241014-P1058599.jpg",1600,1200],["c:6/63/Tomeidai%E2%85%B1.jpg",1404,1084],["c:9/99/Oohijinjya7.jpg",1024,768],["c:e/e5/Oohijinjya5.jpg",1024,768],["c:a/a0/Oohijinjya1.jpg",1024,768],["c:d/dc/Funabashi_montage.jpg",2468,3492,"船橋市"]]},{"id":"12_hondoji","n":"本土寺（あじさい寺・日蓮宗の古刹）","yomi":"ほんどじ","cat":"寺社","rank":"B","y":1277,"era":["kamakura","muromachi","edo"],"sh":"","ad":"松戸市平賀","st":"JR常磐線 北小金駅から歩いて約10分","la":35.827,"lo":139.9335,"hook":"6月、5万株ともいわれるアジサイが咲きほこる古寺。その寺には、戦国の人々の死を書きとめた «過去帳» が眠る。","lead":"本土寺は、鎌倉時代に始まった日蓮宗のお寺です。日蓮の弟子・日朗が開いたと伝わり、«あじさい寺» として有名です。寺に伝わる «本土寺過去帳» は、戦国時代の関東の歴史を知る貴重な史料です。","story":["梅雨の季節、北小金駅から続く参道は人でいっぱいになります。お目当ては、境内をうめつくすアジサイ。青やむらさき、白の花が、古い山門や五重塔をかこみます。けれども本土寺の本当の魅力は、花の奥にある700年以上の歴史です。","寺の始まりは鎌倉時代。この地には平賀氏という武士の屋敷があり、その家から日朗・日像・日輪という三人の僧が出たと伝わります。三人とも日蓮の教えを広めたことで知られ、とくに日像は京都で布教して、日蓮宗を西へ広めた人物です。建治3年（1277年）、日朗がこの屋敷を寺に改めたのが本土寺の始まりとされます。","日蓮宗の中で、本土寺は古くから重要な寺でした。池上本門寺、中山法華経寺とならんで、日蓮の教えを伝える大寺院のひとつと数えられることもあります。多くの僧がここで学び、関東の各地へ教えを広げていきました。","本土寺には «過去帳» という一冊の記録が伝わります。過去帳とは、亡くなった人の名前や日付を記した帳面。本土寺の過去帳には、戦国時代に関東で起きた合戦で亡くなった武士や、飢饉・疫病で亡くなった人々の名が書きとめられています。«なぜ、お寺の帳面が歴史の研究に役立つの?» 他に記録が少ない戦国時代の関東で、いつ、どこで、どんな人が亡くなったかを教えてくれるからです。","境内には、徳川家康の側室で、武田信吉の母となった女性（秋山夫人）の墓も伝わります。アジサイの季節だけでなく、春の桜、秋の紅葉も美しい寺です。花を楽しみながら、この静かな境内に書きとめられた無数の人生にも、思いをはせてみてください。"],"tl":[["鎌倉時代","平賀氏の屋敷に日朗・日像らが生まれたと伝わる"],["1277年","日朗が屋敷を寺に改め、本土寺が始まったとされる"],["室町〜戦国時代","«本土寺過去帳» に関東の人々の死が書き継がれる"],["江戸時代","家康の側室・秋山夫人の墓がつくられたと伝わる"],["昭和時代以降","アジサイの名所として知られるようになる"]],"who":[["日朗","日蓮の高弟。本土寺を開いたと伝わる"],["日像","日朗の弟子。京都に日蓮宗を広めた。平賀の出身と伝わる"],["日蓮","日蓮宗の開祖。安房（千葉県南部）の生まれ"],["秋山夫人","徳川家康の側室で武田信吉の母。墓が本土寺にあると伝わる"]],"deep":["«本土寺過去帳» は、戦国期の関東の合戦・災害・疫病の死者を記す一級史料として研究者に知られ、小田原北条氏と周辺勢力の抗争を読み解く手がかりにもなる。","日像は京都での布教で三度の流罪にあいながら、のちに妙顕寺を開いた。京都町衆への日蓮宗の広まりの出発点といわれる。","本土寺は、日朗の系統（朗門）の中心寺院の一つとされる。池上本門寺・比企谷妙本寺などと並び称されることがある。","アジサイは戦後になって植えられたもので、寺の古い伝統というより近年の名所化による。株数は «約5万株» などと紹介される。","五重塔は近年に建てられたもので、古建築ではない。山門など、時代の異なる建物が並んでいる点にも注目したい。","平賀の地名は、寺を開いた平賀氏にちなむとされる。寺の周囲には中世の屋敷の地形を思わせる起伏が残る。"],"look":["アジサイの参道と境内（6月）","山門と五重塔","秋山夫人の墓と伝わる墓所","菖蒲池・紅葉の庭"],"q":["戦国時代の関東の人々の死を書きとめた、本土寺の有名な記録は？","«本土寺過去帳»。合戦や飢饉で亡くなった人の記録として、歴史研究に使われています。"],"koji":[],"myth":"日朗・日像・日輪の平賀出身、開創年、秋山夫人の墓は寺伝による部分がある。","img":["日朗","日像","松戸市"],"wp":"本土寺","rel":{"ev":[],"grave":[]},"ph":[["c:b/b5/Chiba-matsudo-hondoji-sanmon.jpg",480,360,"本土寺"],["c:b/b1/Matsudo_Hondo_Temple_Pagoda_and_Hydrangea.JPG",2592,1944],["c:6/63/Hondoji-nioumon.jpg",1824,1216],["c:a/a8/Hondoji-hondou.jpg",1824,1216],["c:1/1a/Hondoji-akiyama.jpg",1216,1824],["c:3/3f/%E7%A7%8B%E3%81%AE%E6%9C%AC%E5%9C%9F%E5%AF%BA05.JPG",1920,1080],["c:5/50/%E7%A7%8B%E3%81%AE%E6%9C%AC%E5%9C%9F%E5%AF%BA02.JPG",1900,1069],["c:0/01/%E7%A7%8B%E3%81%AE%E6%9C%AC%E5%9C%9F%E5%AF%BA04.JPG",1800,1013]]},{"id":"12_guhoji","n":"真間山弘法寺と手児奈霊堂","yomi":"ままさんぐほうじとてこなれいどう","cat":"伝承","rank":"B","y":750,"era":["nara","kamakura"],"sh":"","ad":"市川市真間","st":"京成本線 市川真間駅から歩いて約10分","la":35.7355,"lo":139.913,"hook":"万葉の歌人がこぞって歌った、美しすぎた娘 «手児奈»。その悲しい伝説が、1300年たった今も真間の坂に息づく。","lead":"市川市の真間には、万葉集に歌われた «真間の手児奈» の伝説が残っています。多くの男性に求婚された手児奈は、争いを悲しんで海に身を投げたと伝わります。手児奈をまつる手児奈霊堂と、坂の上の弘法寺をあわせて歩くと、伝説の舞台がよくわかります。","story":["むかしむかし、真間の里に手児奈（てこな）という娘がいました。粗末な麻の衣を着て、はだしで井戸へ水をくみに行く、ただそれだけの姿が、まるで月のように美しかったといいます。うわさは遠くまで広がり、村の若者も、都から来た役人も、みな手児奈に心をうばわれました。","けれど手児奈は喜びませんでした。«わたしのために、人々が争い、傷つけあっている»。そう悲しんだ手児奈は、ついに真間の入江に身を投げてしまったと伝わります。奈良時代の歌人・高橋虫麻呂や山部赤人は、この話を聞いて歌を詠みました。赤人は «われも見つ 人にも告げむ 葛飾の 真間の手児名が 奥つ城処» と詠み、手児奈の墓を見たことを後の人に伝えようとしました。","«なぜ、そんなに古い話が今も残っているの?» それは万葉集という歌集に書きとめられたからです。当時の真間は入江が深く入りこみ、国府のあった国府台のすぐ下でした。都から来た役人たちが、地元の悲しい物語を聞き、歌にしたのでしょう。手児奈がくんだとされる «真間の井»、入江にかかっていた «真間の継橋» も、名前が今に伝わっています。","手児奈霊堂は、手児奈の墓所と伝わる場所に建てられたお堂です。安産や子育ての神さまとして、今も多くの人がお参りに来ます。そこから石段を上がると、高台に真間山弘法寺があります。行基が開き、弘法大師（空海）が名前を改めたと伝わる古い寺で、鎌倉時代に日蓮宗の寺になりました。","弘法寺の境内には、春になると «伏姫桜» と呼ばれる大きなしだれ桜が咲きます。石段の上から町を見下ろすと、かつての入江の広がりを想像できるかもしれません。伝説の娘、万葉の歌人、そして後の時代の僧たち。いくつもの時代の物語が、真間の坂に重なっているのです。"],"tl":[["奈良時代","高橋虫麻呂・山部赤人らが手児奈を歌に詠む（«万葉集»）"],["奈良時代","行基が真間に寺を開いたと伝わる（弘法寺の前身）"],["平安時代","空海が寺名を «弘法寺» に改めたと伝わる"],["鎌倉時代","日蓮宗の寺となる（日頂によると伝わる）"],["江戸時代","手児奈霊堂が整えられ、安産・子育ての信仰を集める"]],"who":[["手児奈","真間に住んでいたと伝わる美しい娘。伝説の主人公"],["山部赤人","万葉歌人。手児奈の墓を見て歌を詠んだ"],["高橋虫麻呂","万葉歌人。手児奈の物語を長歌に詠んだ"],["行基","奈良時代の僧。弘法寺を開いたと伝わる"]],"deep":["«万葉集» 巻3に山部赤人、巻9に高橋虫麻呂の手児奈の歌があり、東歌（巻14）にも真間の手児奈が登場する。東国の伝承が都の歌人に取りこまれた代表例。","«手児奈» の名は固有名詞ではなく、«かわいい娘» を意味する東国の言葉だったとする説もある。","真間はかつて入江（真間の浦）に面し、下総国府（国府台）の足もとにあった。国府に赴任した官人が伝承を聞いたと考えられている。","弘法寺の «行基開山・空海改称» は寺伝で、史料による裏づけはない。日蓮宗への改宗は鎌倉時代、日頂の時期と伝わる。","«伏姫桜» の名は、曲亭馬琴の «南総里見八犬伝» の伏姫にちなむ後世の名づけ。八犬伝の作中で真間は直接の舞台ではない。","手児奈霊堂の近くには «真間の継橋» の名を伝える小さな橋や、«真間の井» とされる井戸（亀井院）がある。"],"look":["手児奈霊堂と手児奈池","真間の継橋（名前を伝える朱色の橋）","弘法寺の石段と仁王門","伏姫桜（3月下旬〜4月上旬）"],"q":["手児奈の伝説を詠んだ歌がのっている、奈良時代の歌集は？","«万葉集»。山部赤人や高橋虫麻呂が手児奈を歌いました。"],"koji":[{"w":"われも見つ 人にも告げむ 葛飾の 真間の手児名が 奥つ城処","m":"山部赤人の歌。わたしも見た、人にも伝えよう、葛飾の真間の手児奈の墓所を、という意味"}],"myth":"手児奈は伝説上の人物。弘法寺の行基開山・空海改称は寺伝。","img":["弘法寺","山部赤人","万葉集"],"wp":"手児奈","rel":{"ev":[],"grave":[]},"ph":[["c:3/35/Sanj%C5%ABrokkasen-gaku_-_6_-_Kan%C5%8D_Tan%E2%80%99y%C5%AB_-_Yamabe_no_Akahito.jpg",450,640,"山部赤人"],["c:a/ae/Genryaku_Manyosyu.JPG",1333,1000,"万葉集"],["c:8/87/Konodaistation-outside-2018-9-23.jpg",6214,4090,"近く: 国府台駅"],["c:2/21/Ichikawamama-Sta-S-2025.jpg",4608,3456,"近く: 市川真間駅"],["c:4/45/JR_Sobu-Main-Line_Ichikawa_Station_South_Exit%28cropped%29.jpg",3865,2242,"近く: 市川駅"],["c:4/41/Konodai_Girls%27_Junior_and_Senior_High_School.JPG",2048,1536,"近く: 国府台女子学院小学部・中学部・高等部"],["c:4/4e/Guhouji-honden.jpg",1824,1216,"近く: 弘法寺 (市川市)"],["c:3/3c/Tekonareishindo.jpg",1824,1216,"近く: 手児奈霊神堂"]]},{"id":"12_fujohime","n":"伏姫籠穴（南総里見八犬伝の舞台）","yomi":"ふせひめろうけつ","cat":"伝承","rank":"B","y":1814,"era":["edo","showa"],"sh":"","ad":"南房総市合戸","st":"JR内房線 岩井駅から車で約10分。駐車場から山道を少し歩く","la":35.093,"lo":139.872,"hook":"«仁義礼智忠信孝悌» ――8つの玉が飛び散った洞窟。江戸のベストセラー小説の世界が、房総の山に «実在» する。","lead":"«南総里見八犬伝» は、江戸時代の作家・曲亭馬琴が28年かけて書いた長編小説です。物語の始まりで、里見家の姫・伏姫が犬の八房とこもったのが富山（とみさん）の洞窟でした。南房総市には、その洞窟を «伏姫籠穴» として再現した場所があります。","story":["時は戦国時代。安房の国の里見義実は、敵に城を囲まれて追いつめられていました。苦しまぎれに、飼い犬の八房に «敵の大将の首をとってきたら、娘の伏姫をやろう» と冗談を言います。ところが八房は本当に敵将の首をくわえて帰ってきました。約束は約束。伏姫は八房とともに、富山の奥深くへ入っていきました。――これが «南総里見八犬伝» の始まりです。","山の洞窟で、伏姫は法華経を読んで暮らしました。やがて、自分の身に八房の «気» が宿ったことを知った伏姫は、身の潔白を示すため、自ら命を絶ちます。そのとき、姫が身につけていた数珠から8つの玉が飛び散り、空へ消えていきました。玉には «仁・義・礼・智・忠・信・孝・悌» の文字。この玉を持って生まれた8人の若者 «八犬士» が、やがて里見家のもとに集まる、という壮大な物語が始まるのです。","作者の曲亭馬琴は、江戸の人気作家でした。1814年に第1集を出し、完結まで28年。とちゅうで目が見えなくなり、息子の妻・お路に口で伝えて書きとらせたといいます。«なぜそこまでして書き続けたの?» 馬琴にとって八犬伝は、勧善懲悪（よいことをすすめ、悪をこらしめる）の理想を描く、一生の仕事だったのです。","里見氏は実在した戦国大名ですが、伏姫や八犬士は馬琴が創った登場人物です。それでも物語があまりに人気になったため、後の時代の人々は、富山のふもとに «伏姫籠穴» をつくり、物語の世界を訪ねられるようにしました。洞窟の中には、8つの玉を思わせる飾りが置かれています。","富山は、ふたつの峰を持つ美しい山で、頂上からは東京湾や富士山が見わたせます。«伏姫はこの景色を見ていたのかな»と想像しながら歩くのも楽しいでしょう。物語と現実の境目をふみこえて、200年前の江戸の人々が夢中になった冒険に浸れる場所です。"],"tl":[["戦国時代","里見氏が安房を治める（物語の時代背景）"],["1814年","曲亭馬琴が «南総里見八犬伝» 第1集を刊行"],["1842年","全98巻106冊で完結"],["昭和時代","物語にちなみ、富山のふもとに «伏姫籠穴» が整えられる"],["現在","八犬伝ゆかりの地として訪れる人が多い"]],"who":[["曲亭馬琴（滝沢馬琴）","«南総里見八犬伝» の作者"],["伏姫","物語のヒロイン（架空の人物）。里見義実の娘とされる"],["八房","伏姫とともに山にこもった犬（物語の登場者）"],["里見義実","物語で伏姫の父。実在の里見氏の祖として描かれる"],["お路","馬琴の息子の妻。失明した馬琴の口述を書きとった"]],"deep":["«南総里見八犬伝» は1814年から1842年にかけて刊行された全98巻106冊の大長編。日本の長編小説の中でもとても長いものの一つ。","物語の骨組みには中国の «水滸伝» の影響がある。宿星に導かれた豪傑が集まる構成は、108人の豪傑が集う水滸伝を下敷きにしている。","実在の里見義実は里見氏の安房での祖とされるが、その事績は史料が少なく不明な点が多い。作中の出来事は大部分が創作。","馬琴は晩年に失明し、息子・宗伯の妻であるお路が漢字を学びながら口述筆記をした。この苦労は馬琴の日記などから知られる。","伏姫籠穴は物語を記念して後につくられた場所で、伏姫が実在したことを示す遺跡ではない。","八犬士の名には全員 «犬» の字が入る（犬塚信乃、犬川荘助、犬山道節など）。この «犬» の縁が、八房から続く物語の糸になっている。"],"look":["洞窟の中の8つの玉の飾り","洞窟へ向かう山道と石段","富山の山容（ふたつの峰）","時間があれば富山の山頂からの眺め"],"q":["八犬士が持っていた8つの玉に書かれた文字のうち、«仁・義・礼・智» に続く4つは？","«忠・信・孝・悌»。儒教で大切にされる8つの徳を表しています。"],"koji":[{"w":"勧善懲悪","m":"よい行いをすすめ、悪い行いをこらしめること。八犬伝のテーマとされる"}],"myth":"伏姫・八房・八犬士は小説の創作。籠穴も物語にちなんで後につくられた場所。","img":["曲亭馬琴","富山 (千葉県)","里見氏"],"wp":"南総里見八犬伝","rel":{"ev":[],"grave":[]},"ph":[["c:f/fe/Satomi_and_the_Eight_%E2%80%9CDogs%E2%80%9D_WDL2937.pdf",1831,2500,"南総里見八犬伝"],["c:9/9a/Nans%C5%8D_Satomi_Hakkenden_-_Rampaging_cattle.jpg",4646,3743],["c:9/94/NDL-DC_1309141-Utagawa_Kunisada-%E8%B1%8A%E5%9B%BD%E6%8F%AE%E6%AF%AB%E5%A5%87%E8%A1%93%E7%AB%B6_%E5%B0%BC%E5%A6%99%E6%A4%BF-crd.jpg",3309,4817],["c:3/3e/Mamasan_Guhoji_Fushihimezakura.JPG",3648,2736],["c:0/0e/Fusehime_saving_Inue_Shimbyoe_Masahi_from_a_thunderboit.jpg",2317,3545],["c:0/04/Kuniyoshi_Utagawa%2C_The_actor_5.jpg",2149,3117],["c:d/dc/Satomi_Jirotaro_Yoshinari_Inspecting_a_Head_Carried_by_a_Dog_LACMA_M.84.31.378.jpg",1566,2100],["c:d/d3/No._2_Itabashi_%E6%9D%BF%E6%A9%8B_%28BM_2008%2C3037.14702%29.jpg",1094,1600]]},{"id":"12_tempo_suikoden","n":"笹川（天保水滸伝の舞台）","yomi":"ささがわ（てんぽうすいこでん）","cat":"伝承","rank":"B","y":1844,"era":["edo"],"sh":"","ad":"香取郡東庄町笹川","st":"JR成田線 笹川駅から歩いて約10分","la":35.843,"lo":140.67,"hook":"利根川の河原で、侠客どうしが刀を抜いた。浪曲で日本じゅうに知れわたった «大利根河原の決闘» の里。","lead":"天保水滸伝は、江戸時代の終わりごろ、利根川ぞいの笹川と飯岡を舞台に、二人の親分が争った実話をもとにした講談・浪曲の物語です。笹川の繁蔵と飯岡の助五郎の争い、そして剣客・平手造酒の最期が語り継がれています。","story":["天保の時代（1830〜1844年）、利根川の下流は、米や醤油を運ぶ船でにぎわっていました。人とお金が集まれば、ばくちやけんかも起こります。その土地の顔役として力を持ったのが «侠客（きょうかく）» と呼ばれる親分たちでした。笹川には繁蔵、海ぞいの飯岡には助五郎。二人はなわばりをめぐって、しだいに対立を深めていきます。","笹川繁蔵は、もとは相撲取りだったといわれます。地元の諏訪神社で相撲や «花会（はなかい）» という大きな集まりを開き、人望を集めました。一方の飯岡助五郎は、漁師の親方で、幕府の «十手（じって）» を預かる役目も持っていたといわれます。«侠客なのに役人の手先?» ――このねじれた立場が、二人の争いを複雑にしました。","天保15年（1844年）、ついに助五郎の一家が、笹川へ押しよせます。これが «大利根河原の決闘»。繁蔵方の用心棒として加わったのが、平手造酒（ひらてみき）という剣の達人でした。病に苦しむ身ながら戦いにのぞみ、この戦いで命を落としたと伝わります。この決闘で、双方に死者やけが人が出ました。","争いはそれで終わりませんでした。数年後、繁蔵は闇討ちにあって命を落とします。のちにこの話は講談師や浪曲師によって語られ、«天保水滸伝» として大人気になりました。とくに昭和の浪曲で «利根の川風 袂に入れて……» と歌われた平手造酒の場面は、多くの人の涙をさそいました。","笹川の延命寺には、繁蔵の碑や平手造酒の墓とされるものがあり、ゆかりの品を伝える展示もあります。物語では英雄のように描かれる親分たちですが、実際には争いで人が亡くなった悲しい出来事でもあります。利根川の川風に吹かれながら、物語と史実のあいだを考えてみるのもよいでしょう。"],"tl":[["天保年間","笹川繁蔵と飯岡助五郎が利根川下流で勢力を争う"],["1842年ごろ","繁蔵が諏訪神社で相撲や花会を開いたと伝わる"],["1844年","大利根河原の決闘。平手造酒らが亡くなる"],["1847年","繁蔵が闇討ちにあい亡くなる"],["明治〜昭和","講談・浪曲 «天保水滸伝» として人気を集める"]],"who":[["笹川繁蔵","笹川の侠客。元力士といわれる"],["飯岡助五郎","飯岡の侠客で漁業の親方。十手を預かったといわれる"],["平手造酒","繁蔵方の用心棒の剣客。決闘で亡くなったと伝わる"],["宝井琴凌","講談で天保水滸伝を広めた講談師として知られる"]],"deep":["題名の «水滸伝» は、中国の小説 «水滸伝» の豪傑たちになぞらえたもの。江戸後期〜明治に講談として成立し、昭和の浪曲・歌謡曲で全国に広まった。","平手造酒は講談での名で、実在のモデル（平田深喜などの名が伝わる）の経歴は確かでない部分が多い。«千葉周作の門下» とする話も講談の脚色の可能性がある。","飯岡助五郎が十手を預かっていたとする点は、いわゆる «二足の草鞋»（ばくち打ちと役人の手先の兼業）の典型例として語られる。","利根川下流は銚子・佐原へつながる水運の大動脈で、河岸の経済力が侠客の勢力の背景にあったと考えられる。","決闘の死傷者数や経過は資料・語りによって異なり、講談の誇張が含まれる。","東庄町では天保水滸伝にちなむ催しや史跡めぐりが行われ、地域の物語として大切にされている。"],"look":["延命寺の繁蔵の碑と平手造酒の墓とされる墓","諏訪神社（相撲・花会の舞台と伝わる）","利根川の堤防からの眺め","天保水滸伝ゆかりの展示（開館日を確認）"],"q":["天保水滸伝で、笹川繁蔵と争った飯岡の親分はだれ？","«飯岡助五郎»。漁業の親方で、十手も預かっていたといわれます。"],"koji":[{"w":"二足の草鞋","m":"一人で二つの立場や仕事をかけもちすること。ばくち打ちが役人の手先をつとめる例から広まった言葉"}],"myth":"講談・浪曲の脚色が多い。平手造酒の経歴、決闘の細部や人数は諸説。","img":["笹川繁蔵","飯岡助五郎","平手造酒"],"wp":"天保水滸伝","rel":{"ev":[],"grave":[]},"ph":[["c:1/1d/%E5%B9%B3%E6%89%8B%E5%A3%B1%E5%B2%90.jpg",1285,1906,"平手造酒"],["c:1/13/JR_Sasagawa_sta_005%28cropped%29.jpg",2235,1138,"近く: 笹川駅"],["c:8/85/Enmeiji_Temple_%28Tonosho_Town%2C_Chiba_Prefecture%29_02.jpg",4928,3280,"近く: 東庄町"],["c:8/8a/Tohnosho_Elementary_School.jpg",4624,3472,"近く: 東庄町立東庄小学校"]]},{"id":"12_shojoji","n":"證誠寺（狸囃子の寺）","yomi":"しょうじょうじ","cat":"伝承","rank":"B","y":1924,"era":["edo","taisho"],"sh":"","ad":"木更津市富士見2丁目","st":"JR内房線 木更津駅から歩いて約5分","la":35.382,"lo":139.9265,"hook":"«しょ、しょ、しょうじょうじ»――あの童謡の «ポンポコポン» は、木更津の小さなお寺から生まれた。","lead":"證誠寺は、木更津駅の近くにある浄土真宗のお寺です。月夜にたぬきが集まって腹つづみを打ったという伝説があり、これをもとに童謡 «証城寺の狸囃子» がつくられました。境内には «狸塚» があります。","story":["むかし、證誠寺の庭は、秋になると月の光に照らされていました。ある晩、和尚さんが三味線をひいていると、どこからか «ポンポコポン» と、つづみのような音が聞こえてきます。見ると、庭に何十匹ものたぬきが集まり、おなかをたたいておどっているではありませんか。","«負けてなるものか!» 和尚さんも三味線をひきながら、いっしょに歌っておどりました。たぬきと和尚の音楽合戦は、何晩も続いたといいます。ところがある晩、たぬきたちが姿を見せません。翌朝、庭の片すみで、大だぬきがおなかを破って死んでいるのが見つかりました。張りきってたたきすぎてしまったのだ、と伝えられています。和尚さんはあわれに思い、ていねいに葬りました。その塚が、境内の «狸塚» だと伝えられています。","この話を聞いて童謡を書いたのが、詩人の野口雨情です。作曲は中山晋平。«しょ、しょ、しょうじょうじ、しょうじょうじの庭は、つ、つ、月夜だ、みんな出て来い来い来い»。大正時代の終わりに発表されたこの歌は、子どもたちに大人気になりました。«なぜ、字が «証城寺» なの?» 童謡の題名は «証城寺» と書かれ、実際のお寺の «證誠寺» とは字がちがいます。","昭和に入ると、この曲は海をこえて知られるようになります。戦後には、進駐したアメリカ兵のあいだで英語の歌詞がつけられて歌われたこともありました。やさしいメロディーとユーモラスなリズムは、国や言葉をこえて人々を楽しませてきたのです。","今の證誠寺は、町なかの静かなお寺です。境内の狸塚や、たぬきの像を見ながら、秋の月夜にはどんな音が聞こえるだろうと想像してみてください。木更津の町では、この歌にちなんだ行事も行われ、たぬきは町のシンボルのように親しまれています。"],"tl":[["江戸時代","證誠寺の庭にたぬきが集まったという伝説が語られる"],["1924年ごろ","野口雨情作詞・中山晋平作曲の童謡 «証城寺の狸囃子» が発表される"],["昭和初期","レコード化され全国に広まる"],["戦後","英語の歌詞でも歌われる"],["現在","境内の狸塚が伝説を伝える"]],"who":[["野口雨情","童謡の作詞者。«赤い靴» «シャボン玉» なども書いた詩人"],["中山晋平","童謡の作曲者"],["證誠寺の和尚","伝説でたぬきと音楽合戦をしたとされる"],["木更津の人々","狸塚と伝説を守り伝えてきた"]],"deep":["寺の正式な表記は «證誠寺»、童謡の題は «証城寺の狸囃子»。雨情が意図して字を変えたとも、単に取り違えたともいわれ、はっきりしない。","たぬきが腹つづみを打つ伝説は各地にあり、«狸囃子» は江戸の本所七不思議にも登場する。證誠寺の話はその代表格として童謡で有名になった。","野口雨情・中山晋平のコンビは、大正期の童謡運動を代表する組み合わせで、«シャボン玉» «あの町この町» などを生んだ。","戦後、進駐軍向けの英語詞がつけられ «Come, Come, Everybody» のメロディーとして英語講座番組で使われたことが知られる。","狸塚は伝説のたぬきを葬った場所として伝わるが、現在の塚や碑がいつ整えられたかは諸説あり、童謡のヒットが伝説の知名度を大きく高めたことは確か。","證誠寺は浄土真宗の寺院で、観光寺院ではない。見学の際は参拝のマナーを守りたい。"],"look":["境内の狸塚","たぬきの像や童謡の歌碑","本堂（参拝のマナーを守って）","木更津駅前周辺のたぬきのモチーフ"],"q":["童謡 «証城寺の狸囃子» の作詞者はだれ？","«野口雨情»。作曲は中山晋平です。"],"koji":[],"myth":"たぬきの音楽合戦は伝説。狸塚の成立時期は諸説。童謡の発表年は資料に幅。","img":["野口雨情","中山晋平","木更津市"],"wp":"証城寺の狸囃子","rel":{"ev":[],"grave":[]},"ph":[["c:c/c8/Manhole_cover_of_Kisarazu.jpg",2304,1728],["c:9/9e/Noguchi_Ujo.jpg",300,462,"野口雨情"],["c:4/49/%E4%B8%AD%E5%B1%B1%E6%99%8B%E5%B9%B3.jpg",569,743,"中山晋平"],["c:6/6a/Kisarazu_montage.jpg",2472,3512,"木更津市"]]},{"id":"12_kyoninji","n":"鏡忍寺（小松原法難の地）","yomi":"きょうにんじ","cat":"寺社","rank":"B","y":1264,"era":["kamakura"],"sh":"","ad":"鴨川市広場","st":"JR外房線 安房鴨川駅から車で約10分","la":35.13,"lo":140.08,"hook":"日蓮が額を斬られ、弟子と武士が命をかけて守った夕暮れの道。その «身代わり» の名が寺の名になった。","lead":"鏡忍寺は、鴨川市にある日蓮宗の寺です。1264年、日蓮がこの近くの小松原で、地頭の東条景信に襲われました（小松原法難）。このとき日蓮を守って亡くなった弟子・鏡忍房と武士・工藤吉隆をとむらうために建てられた寺です。","story":["文永元年（1264年）の秋、日蓮は故郷の安房に帰っていました。鎌倉で «法華経こそが正しい教えだ» と説き、伊豆に流されたあと、ようやく許されての帰郷でした。病気の母を見舞うためだったとも伝わります。けれど、故郷には日蓮をにくむ人物が待っていました。地頭の東条景信です。","景信は、かつて清澄寺をめぐる争いで日蓮と対立し、日蓮の教えを強くきらっていました。11月11日の夕暮れ、日蓮の一行が小松原の道を通りかかったとき、景信の兵たちが一斉におそいかかりました。一行はわずか十人ほどだったといいます。","弟子の鏡忍房は、日蓮の前に立ちはだかって戦い、その場で命を落としました。知らせを聞いて天津の領主・工藤吉隆がかけつけ、日蓮を守りましたが、深い傷を負って亡くなります。日蓮自身も額を斬られ、左手を折られたと伝わります。«なぜ、そこまでして守ったのか?» 二人にとって日蓮は、命をかけて信じる師だったのでしょう。","この出来事は «小松原法難» と呼ばれ、日蓮の生涯の «四大法難» の一つに数えられます。のちに、工藤吉隆の子が出家して僧となり、父と鏡忍房をとむらうため、この地に寺を建てたと伝わります。寺の名 «鏡忍寺» は、身代わりとなった鏡忍房の名から取られました。","境内には、日蓮が襲われたときに身をかくしたと伝わる木や、法難にちなむ史跡があり、毎年11月には法難をしのぶ行事が行われます。静かな山里の寺ですが、ここには師を守った人々の祈りが今も残っています。訪れるときは、亡くなった人々をしのぶ気持ちでお参りしたい場所です。"],"tl":[["1253年","日蓮が清澄寺で教えを始めたと伝わる"],["1261年","日蓮が伊豆に流される（伊豆法難）"],["1264年11月11日","小松原法難。鏡忍房と工藤吉隆が亡くなる"],["1281年ごろ","工藤吉隆の子・日隆が寺を開いたと伝わる"],["江戸時代以降","法難の霊場として多くの参詣者を集める"]],"who":[["日蓮","日蓮宗の開祖。小松原で襲われ、額に傷を負ったと伝わる"],["鏡忍房","日蓮の弟子。師を守って亡くなり、寺名の由来となった"],["工藤吉隆","天津の領主。日蓮を守って亡くなったと伝わる"],["東条景信","安房東条の地頭。日蓮を襲撃した"],["日隆","工藤吉隆の子と伝わる僧。鏡忍寺の開山"]],"deep":["«四大法難» は、松葉ヶ谷法難・伊豆法難・小松原法難・龍口法難を指す。小松原は日蓮自身が負傷した点で特別な意味を持つ。","日蓮の書状（遺文）には、小松原で襲われ、弟子が討たれ、自分も傷を負ったことが記されているとされ、法難自体は日蓮自身の言葉で裏づけられる出来事である。","東条景信は、清澄寺・二間寺の所領をめぐり、領家の尼（日蓮の両親の主家筋）と争った際に日蓮と対立したといわれる。","日蓮の額の傷は «眉間の傷» として日蓮像にも表され、後世の日蓮信仰で重要なモチーフになった。","工藤吉隆の子が出家したという開山の経緯は寺伝による。寺の開創年は資料によって表記が異なる。","鴨川市には、日蓮の誕生地とされる誕生寺（小湊）、立教開宗の清澄寺もあり、あわせて回ると日蓮の前半生がたどれる。"],"look":["本堂と法難の史跡","日蓮が身をかくしたと伝わる木（降神槇と呼ばれる）","鏡忍房・工藤吉隆をしのぶ墓所","11月11日前後の法難会（行事の日程は要確認）"],"q":["鏡忍寺の名前は、だれの名前から取られた？","«鏡忍房»。小松原法難で日蓮を守って亡くなった弟子です。"],"koji":[],"myth":"一行の人数、隠れた木、開山の経緯・年は伝承による部分がある。","img":["日蓮","小松原法難","清澄寺","誕生寺"],"wp":"鏡忍寺","rel":{"ev":[],"grave":[]},"ph":[["c:0/06/Kyoninji-Kamogawa.jpg",1024,768,"鏡忍寺"],["c:0/06/Nichiren_Daishonin_Hakii_Portrait.jpg",600,612,"日蓮"]]},{"id":"12_goganji","n":"藻原寺（日蓮宗の古刹）","yomi":"そうげんじ","cat":"寺社","rank":"B","y":1280,"era":["kamakura","edo"],"sh":"","ad":"茂原市茂原","st":"JR外房線 茂原駅から歩いて約10分","la":35.428,"lo":140.288,"hook":"«東の身延» と呼ばれた町なかの大寺院。茂原という町の名前の由来とも関わる、藻の原の寺。","lead":"藻原寺は、茂原市の中心にある日蓮宗の大きな寺です。鎌倉時代、この地の領主が日蓮に帰依し、日蓮の高弟・日向によって開かれたと伝わります。身延山とのつながりが深く «東身延» とも呼ばれます。","story":["茂原駅から歩いてすぐ、町なかに大きな山門と、高くそびえる堂の屋根が見えてきます。藻原寺です。«茂原» という町の名前は、昔この地が «藻原（もばら）» と書かれたことに由来するといわれます。水辺に藻がしげる、湿った原っぱだったのでしょう。寺の名前にも、その古い地名が残っています。","寺の始まりは鎌倉時代。このあたりの領主・斎藤兼綱が日蓮の教えを信じ、自分の土地に寺を建てたと伝わります。開いたのは日蓮の六人の高弟（六老僧）の一人、日向。«どうして茂原に、そんな大物の弟子が?» 日向は上総の出身ともいわれ、上総・安房の信者との結びつきが強かったのです。","日向はのちに、日蓮が晩年を過ごした身延山久遠寺をつぐ僧となりました。身延山の二代目です。そのため、日向が開いた藻原寺は身延山との関係がとても深く、«東の身延（東身延）» と呼ばれるようになりました。関東の日蓮宗の人々にとって、身延山は遠い場所。藻原寺は、身近に身延の教えにふれられる大切な寺だったのです。","江戸時代、茂原は周辺の村々の市場町として栄え、藻原寺はその中心にありました。境内には多くの堂や塔頭（寺の中の小さな寺）が立ち並び、町の人々の信仰と暮らしの中心になりました。寺の門前町のにぎわいが、今の茂原の町のもとになったともいえます。","今の藻原寺は、大きな本堂や山門が立つ落ちついた寺です。春には桜、秋には紅葉が境内をいろどります。町なかにいながら、鎌倉時代から続く信仰の歴史にふれることができる場所です。静かにお参りして、藻の原だった時代の風景を想像してみてください。"],"tl":[["鎌倉時代","領主の斎藤兼綱が日蓮に帰依したと伝わる"],["1280年前後","日向が寺を開いたと伝わる（はじめは妙光寺と称したともいう）"],["鎌倉時代後期","日向が身延山久遠寺の二代目となる"],["江戸時代","茂原の市場町の中心寺院として栄える"],["現在","«東身延» として信仰を集める"]],"who":[["日向","日蓮の六老僧の一人。藻原寺を開いたと伝わる。のち身延山二世"],["斎藤兼綱","この地の領主。日蓮に帰依し寺の建立を支えたと伝わる"],["日蓮","日蓮宗の開祖"],["茂原の町人","門前町を形づくり、寺を支えてきた人々"]],"deep":["六老僧は、日蓮が亡くなる前に後継として定めた六人の高弟（日昭・日朗・日興・日向・日頂・日持）。日向はその一人で、身延山を継いだ。","日向の身延継承には、同じ六老僧の日興が身延を離れた経緯が関わる。この対立は、のちの日蓮宗の諸派の分かれ方にも影響した。","寺の開創年や当初の寺名については資料によって記述が分かれ、確定的ではない。","«藻原» は中世の荘園名としても現れ、«藻原荘» と呼ばれた地域があった。現在の «茂原» の表記は後の時代のもの。","藻原寺は日蓮宗の «本山» の一つとして扱われ、周辺に多くの末寺を持った。","境内の建物の多くは近世以降の再建で、鎌倉時代の建築は残っていない。"],"look":["大きな山門と本堂","境内の塔頭の並び","日向をしのぶ祖師堂・墓所","門前町の名残の道すじ"],"q":["藻原寺を開いたと伝わり、のちに身延山の二代目になった僧は？","«日向»。日蓮の六老僧の一人です。"],"koji":[],"myth":"開創年・旧寺名・斎藤兼綱の事績は寺伝による。地名の由来も諸説。","img":["日向 (僧)","身延山久遠寺","茂原市","六老僧"],"wp":"藻原寺","rel":{"ev":[],"grave":[]},"ph":[["c:7/7a/SogenjiSanmon20120819.jpg",1200,1600,"藻原寺"],["c:a/af/Kuonji-temple-Hondou.jpg",800,600,"身延山久遠寺"],["c:1/1c/Mobara_montage_%E5%8D%83%E8%91%89%E7%9C%8C%E8%8C%82%E5%8E%9F%E5%B8%82%E3%83%A2%E3%83%B3%E3%82%BF%E3%83%BC%E3%82%B8%E3%83%A5.png",2048,2732,"茂原市"]]},{"id":"12_togane_goten","n":"東金御殿跡と御成街道","yomi":"とうがねごてんあととおなりかいどう","cat":"街道","rank":"B","y":1614,"era":["edo"],"sh":"","ad":"東金市東金","st":"JR東金線 東金駅から歩いて約10分（御殿跡は八鶴湖のほとり）","la":35.562,"lo":140.364,"hook":"«家康が鷹狩りに行くぞ!» ――船橋から東金まで、ほぼまっすぐな道が突貫工事で引かれた。","lead":"江戸時代のはじめ、徳川家康は鷹狩りのため東金に来ることになり、そのための御殿（宿泊所）と、船橋から東金までの道 «御成街道» がつくられました。御殿の跡は今の東金高校のあたりで、そばの八鶴湖は桜の名所です。","story":["徳川家康は、鷹狩りが大好きでした。鷹を放って鳥をとる狩りは、体をきたえ、土地のようすを見て回るのにもよい、と考えていたようです。慶長19年（1614年）ごろ、家康は上総の東金で鷹狩りをすることにしました。九十九里の平野には、鳥がたくさんいたのです。","そのためにつくられたのが «御成街道»。«御成（おなり）» とは、将軍などえらい人が出かけることを言います。船橋から東金まで、およそ37km。野原や林をつらぬき、ほとんどまっすぐな道が引かれました。沿道の村々から人が集められ、きわめて短い期間で完成させたと伝わります。«一夜でつくった» という言い伝えまであるほどです。","道の工事を指揮したのは、佐倉の城主・土井利勝だと伝わります。«なぜ、そんなに急いだの?» 将軍の外出に遅れは許されません。さらに、江戸から房総へ一気に移動できる道は、いざというとき軍勢を動かす道にもなりました。鷹狩りは、じつは軍事の演習や、地方の大名への «にらみ» の意味もあったのです。","東金に建てられた御殿は、家康や二代将軍秀忠が鷹狩りのときに泊まった場所でした。御殿の前にある池は «八鶴湖（はっかくこ）»。御殿をつくるときに整えられたといわれます。のちに御殿はとりこわされ、跡地は今、東金高校になっています。建物はもう残っていません。","今も、船橋から千葉市、東金へ続く道すじには «御成街道» の名が残り、ところどころに一直線の道路や、昔の並木の名残があります。春、八鶴湖のまわりに咲く桜をながめながら、将軍の行列がこの道を進んだ日のにぎわいを想像してみてください。"],"tl":[["1614年ごろ","家康の東金での鷹狩りのため、御成街道と東金御殿がつくられたと伝わる"],["1614〜1615年ごろ","家康が東金で鷹狩りをしたと伝わる"],["江戸時代前期","秀忠も東金で鷹狩りを行ったといわれる"],["江戸時代前期","東金御殿がとりこわされる"],["明治時代以降","御殿跡に学校が建てられる（現在の東金高校）"]],"who":[["徳川家康","鷹狩りのため東金を訪れたと伝わる"],["徳川秀忠","二代将軍。東金御殿を利用したといわれる"],["土井利勝","佐倉城主。御成街道の工事を指揮したと伝わる"],["沿道の村人","街道の工事に動員された人々"]],"deep":["御成街道は船橋から東金まで約37km。起伏の多い下総台地を、ほぼ直線でつないでいるのが特徴で、測量の方法についても関心が持たれている。","工事期間については «一夜»«三日» など誇張を含む伝承があり、実際の工期ははっきりしない。村ごとに担当区間を割り当てたといわれる。","家康の鷹狩りは、軍事演習・民情視察・大名統制の意味があったと考えられている。関東各地に御殿や御殿跡の伝承がある。","八鶴湖は、もともとあった池を御殿造営にあわせて整えたとされ、現在は桜の名所として知られる。","東金御殿は将軍の鷹狩りが減るとともに役目を終え、取りこわされた。年代は資料によって記述が異なる。","千葉市内の御成街道沿いには、休憩所として使われた «御茶屋御殿» の跡（千葉市若葉区）もあり、土塁などが残る。"],"look":["八鶴湖と湖畔の桜","東金高校のあたり（御殿跡。学校敷地のため外から見る）","一直線に延びる御成街道の道すじ","千葉市若葉区の御茶屋御殿跡もあわせて"],"q":["将軍などが出かけることを何という？","«御成（おなり）»。御成街道の名前はこの言葉から来ています。"],"koji":[],"myth":"工期の «一夜で完成»、土井利勝の指揮は伝承を含む。家康の東金訪問の回数や年も諸説。","img":["御成街道","八鶴湖","鷹狩","土井利勝"],"wp":"東金市","rel":{"ev":[],"grave":[]},"ph":[["c:1/1e/%E5%85%AB%E9%B6%B4%E6%B9%96-%E6%9C%80%E7%A6%8F%E5%AF%BA.jpg",5460,3644,"東金市"],["c:b/b2/%E9%A1%98%E6%88%90%E5%B0%B1%E5%AF%BA%E3%83%BB%E5%B1%B1%E9%96%80.jpg",4032,3024],["c:7/76/%E6%97%A5%E5%90%89%E7%A5%9E%E7%A4%BE%E5%A2%83%E5%86%852.jpg",4032,3024],["c:f/fe/%E5%B9%B3%E6%88%9029%E5%B9%B4%E6%92%AE%E5%BD%B1%E6%9C%AC%E5%A0%82.jpg",3264,2448],["c:0/0a/T%C5%8Dgane_central_park.jpg",3264,2448],["c:0/0a/T%C5%8Dgane_City_Office.jpg",3264,2448],["c:c/c0/Kujukuri_Railway_Head_Office_02.jpg",3264,2448],["c:e/e5/Kujukuri_Railway_302_at_T%C5%8Dgane_Station_01.jpg",3044,2284]]},{"id":"12_narita_kaido","n":"成田街道（佐倉道）","yomi":"なりたかいどう（さくらみち）","cat":"街道","rank":"B","y":1700,"era":["edo"],"sh":"","ad":"成田市上町（成田山表参道）ほか","st":"JR・京成 成田駅から表参道を歩いて約15分で成田山新勝寺","la":35.786,"lo":140.318,"hook":"«成田屋!» のかけ声とともに、江戸っ子たちが歩いた参詣の道。お不動さまへの旅は、江戸時代のレジャーだった。","lead":"成田街道は、江戸から佐倉を通って成田山新勝寺へ向かう道です。もとは佐倉城へ向かう «佐倉道» でしたが、江戸時代の中ごろから成田山への参拝がブームになり、«成田街道» と呼ばれるようになりました。船橋・佐倉などに宿場がありました。","story":["江戸時代、江戸の人々のあいだで «成田のお不動さまにお参りしよう» という旅が大流行しました。江戸から成田まではおよそ60km。2泊3日ほどの旅です。仕事を休んで友だちと歩く旅は、お参りでもあり、今でいう観光旅行でもありました。その道が、成田街道です。","道のはじまりは、水戸街道の新宿（今の東京都葛飾区）。江戸川をこえて市川・八幡へ入り、船橋、大和田、臼井、佐倉、酒々井をへて成田へ。もともとは佐倉藩の城下町・佐倉へ向かう «佐倉道» でした。佐倉は江戸の東を守る大切な城で、幕府の重役をつとめる大名が城主になることが多かったのです。","成田山新勝寺は、平安時代、平将門の乱をしずめるために不動明王をまつったのが始まりと伝わる寺です。江戸時代、このお不動さまを江戸で公開する «出開帳（でがいちょう）» が何度も開かれ、人気に火がつきました。さらに歌舞伎の名優・初代市川團十郎が成田山を深く信じ、«成田屋» を屋号にしたことで、ファンまで成田へ向かうようになりました。","«なぜ、そんなに成田が人気だったの?» 江戸から近すぎず遠すぎず、途中の宿場ではおいしいものや名物も楽しめたからです。船橋の宿は海辺の町として栄え、佐倉には城下町の風景がありました。成田の門前町には、今も川魚のうなぎ料理の店や、昔ながらの旅館が並びます。","今の成田街道は、大部分が国道や県道になっていますが、ところどころに道しるべや常夜灯、古い商家が残っています。成田山の表参道を歩けば、江戸の旅人たちと同じように、門前町のにぎわいの中を大本堂へ向かうことができます。«成田屋!» と心の中でかけ声をかけながら歩いてみてはいかがでしょう。"],"tl":[["940年","平将門の乱の平定を祈り、成田山が開かれたと伝わる"],["江戸時代初め","佐倉城が整い、江戸と佐倉を結ぶ佐倉道が使われる"],["1703年","成田山の不動明王が江戸・深川で出開帳され、評判となる"],["江戸時代中期","初代市川團十郎が «成田屋» を名のり、成田山参詣が大流行"],["明治時代","鉄道の開通で、徒歩の参詣は減っていく"]],"who":[["初代市川團十郎","歌舞伎役者。成田山を信仰し «成田屋» の屋号を用いた"],["寛朝","成田山を開いたと伝わる平安時代の僧"],["佐倉藩主","佐倉道の終点・佐倉城の城主。幕府の重職につく大名が多かった"],["江戸の参詣者","成田詣を楽しんだ町人たち"]],"deep":["成田街道は、水戸街道の新宿で分かれる道とされることが多い。道中奉行の管轄した五街道ではなく、脇往還の一つ。","«出開帳» とは、地方の寺の本尊などを江戸などに運んで公開すること。成田山は江戸の深川で何度も出開帳を行い、信者を増やした。","初代市川團十郎が成田山に祈って子（二代目）を授かったという話が伝わり、成田屋と成田山の深い縁のもとになったとされる。","佐倉藩は堀田氏などが藩主をつとめ、幕府の老中を出した。佐倉は «江戸の東の守り» として重視された。","船橋宿は成田街道と、東金へ向かう御成街道、房総往還などが交わる交通の要で、宿場と漁師町の二つの顔を持っていた。","成田山の門前町では、印旛沼や利根川でとれた川魚を使ったうなぎ料理が名物となり、今も表参道に店が並ぶ。"],"look":["成田山表参道の古い商家や旅館","成田山新勝寺の大本堂と三重塔","佐倉の城下町（武家屋敷通り）","街道沿いに残る道しるべや常夜灯"],"q":["成田山を深く信仰し、屋号を «成田屋» とした歌舞伎役者はだれ？","«初代市川團十郎»。今も團十郎の家の屋号は成田屋です。"],"koji":[],"myth":"成田山の開山年・團十郎の子授けは寺伝・伝承を含む。街道の起点は資料で表記に幅がある。","img":["成田山新勝寺","市川團十郎","佐倉城","佐倉道"],"wp":"成田街道","rel":{"ev":[],"grave":[]},"ph":[["c:7/7d/Ch%C3%A2teau_de_Himeji02.jpg",2592,1944],["c:6/66/Naritakaido2.jpg",1024,768],["c:7/7b/Naritakaido1.jpg",1024,768],["c:1/15/Naritasan-Shinshoji-Temple-2008.jpg",800,450,"成田山新勝寺"],["c:d/d7/Sakura_Castle_2.JPG",4608,3456,"佐倉城"]]},{"id":"12_kisaradu_kaigun","n":"木更津海軍航空隊跡","yomi":"きさらづかいぐんこうくうたいあと","cat":"昭和","rank":"B","y":1936,"era":["showa"],"sh":"","ad":"木更津市（陸上自衛隊木更津駐屯地）","st":"JR内房線 巌根駅または木更津駅から歩いて約20分（駐屯地は外から見る）","la":35.398,"lo":139.91,"hook":"東京湾の干潟を埋め立ててつくられた海軍の飛行場。ここを飛び立った爆撃機は、海をこえて大陸へ向かった。","lead":"木更津海軍航空隊は、昭和の戦争の時代に、東京湾ぞいの木更津につくられた海軍の航空部隊です。日中戦争では海をこえて中国大陸を爆撃する作戦に加わりました。飛行場は今、陸上自衛隊木更津駐屯地として使われており、ふだんは中に入れません。","story":["昭和のはじめ、日本の海軍は «飛行機の時代» が来ることを感じていました。広い太平洋で戦うには、遠くまで飛べる大型の飛行機が必要です。そこで東京湾の干潟を埋め立てて、大きな飛行場をつくることにしました。こうして1936年に開かれたのが木更津海軍航空隊です。","ここに置かれたのは、«中攻（ちゅうこう）» と呼ばれる双発の陸上攻撃機でした。翼にエンジンを二つつけ、長い距離を飛べるのが自慢の飛行機です。1937年、日中戦争が始まると、木更津の部隊は九州などの基地から東シナ海をこえ、中国大陸の都市を爆撃する «渡洋爆撃» に加わりました。«海をこえて爆撃する» という前例のない作戦で、多くの搭乗員が帰ってきませんでした。","太平洋戦争が始まると、木更津は首都を守る基地の一つとなり、また南方へ向かう部隊の出発点にもなりました。戦争の終わりが近づくと、アメリカ軍の空襲も受けました。基地のまわりには、飛行機を空襲から守るための «掩体壕（えんたいごう）» がつくられ、その一部が今も残っています。","1945年、戦争が終わると、飛行場はアメリカ軍に接収されました。«なぜ、戦争が終わっても飛行場は残ったの?» 東京に近く、広い滑走路を持つ木更津は、アメリカ軍にとっても大切な場所だったからです。のちに日本に返され、陸上自衛隊のヘリコプターなどの基地として使われるようになりました。","今、駐屯地の中はふだん入ることができません。けれど、年に一度ほど行われる行事の日には、一般の人も入れることがあります。まわりの町に残る掩体壕や記念碑を訪ねると、この飛行場から飛び立ち、帰らなかった人々のことを思い起こさせてくれます。戦争で亡くなったすべての人をしのびながら、静かに歩きたい場所です。"],"tl":[["1936年","木更津海軍航空隊が開隊する"],["1937年","日中戦争で、渡洋爆撃に参加する"],["1941〜1945年","太平洋戦争。首都防衛や南方への出撃の拠点となる"],["1945年","終戦。飛行場はアメリカ軍に接収される"],["戦後","日本に返還され、陸上自衛隊木更津駐屯地となる"]],"who":[["木更津航空隊の搭乗員","中攻に乗って出撃した兵士たち。多くが戦死した"],["山本五十六","海軍の航空戦力の育成を進めた軍人。長距離攻撃機の開発に関わった"],["木更津の人々","基地の建設や空襲を経験した地元の人々"]],"deep":["«中攻» は «中型陸上攻撃機» の略。九六式陸上攻撃機は海軍が長距離の対艦攻撃用に開発した機体で、木更津空などに配備された。","1937年8月の «渡洋爆撃» では、木更津空と鹿屋空の中攻が九州・台湾などから出撃し、中国の都市を爆撃した。長距離の無護衛爆撃で大きな損害も出た。","基地は東京湾岸の干拓・埋め立て地に建設された。広い平地と海に近い立地が、大型機の運用に適していた。","木更津市周辺には、コンクリート製の掩体壕がいくつか残っているが、多くは私有地や民家の敷地にあり、見学は外からに限られる。","戦後の米軍接収期を経て、陸上自衛隊のヘリコプター部隊などの拠点となった。現在も現役の基地であり、撮影や立ち入りのルールに注意が必要。","«渡洋爆撃» は当時の新聞で大きく報じられ、海軍航空の力を示す宣伝にも使われた。一方で、爆撃を受けた側に多くの犠牲が出たことも忘れてはならない。"],"look":["駐屯地の外周から見える滑走路の広がり（立ち入り不可）","周辺に残る掩体壕（私有地は外から）","基地公開の行事日の見学","慰霊碑や記念碑"],"q":["飛行機を空襲から守るためにつくられた、かまぼこ形の施設を何という？","«掩体壕（えんたいごう）»。木更津や茂原の周辺に今も残っています。"],"koji":[],"myth":"山本五十六と木更津空の直接の関わりは限定的。所在地（町名）は基地の範囲が広いため目安。","img":["九六式陸上攻撃機","木更津駐屯地","渡洋爆撃","掩体壕"],"wp":"木更津海軍航空隊","rel":{"ev":[],"grave":[]},"ph":[["c:3/35/Kisarazu_Airfield_Aerial_photograph_1947.jpg",1666,1250],["c:e/ea/G3M-37.jpg",400,189,"九六式陸上攻撃機"],["c:3/35/JGSDF_Camp_Kisarazu_2016.jpg",3024,3369,"木更津駐屯地"],["c:f/f8/Typhoon_Takes_Off_from_RAF_Coningsby_as_Part_of_Op_Ellamy_MOD_45152517.jpg",3000,1805,"掩体壕"]]},{"id":"12_mobara_kaigun","n":"茂原海軍航空基地の掩体壕","yomi":"もばらかいぐんこうくうきちのえんたいごう","cat":"昭和","rank":"B","y":1944,"era":["showa"],"sh":"","ad":"茂原市（旧茂原海軍航空基地の周辺）","st":"JR外房線 茂原駅から車で約10分。点在しているので車か自転車が便利","la":35.445,"lo":140.31,"hook":"田んぼの中に、巨大なコンクリートのかまぼこがうずくまる。戦闘機をかくした «掩体壕» が、今も10基ほど残る町。","lead":"太平洋戦争のころ、茂原には海軍の飛行場がありました。空襲から飛行機を守るためにつくられたコンクリートの格納庫 «掩体壕» が、今も田畑や住宅地の中にいくつも残っています。これほど多く残る場所は全国でも珍しく、戦争を伝える遺跡になっています。","story":["茂原の郊外を車で走ると、田んぼの向こうに、奇妙な形の建物が見えてきます。横から見ると半円形、まるで巨大なかまぼこのよう。高さは人の背の何倍もあり、中はがらんとした空洞です。今は農機具置き場や倉庫として使われているものもありますが、じつはこれ、戦争中に飛行機をかくすためにつくられた «掩体壕（えんたいごう）» なのです。","太平洋戦争が始まるころ、海軍はここに飛行場をつくりました。首都・東京を守り、太平洋から近づく敵を見張るための基地でした。多くの若い搭乗員がここで訓練を受け、戦場へ向かいました。やがて戦況が悪くなると、アメリカ軍の飛行機が関東の空にも現れるようになります。","«飛行機を地上で壊されてしまったら戦えない»。そこで基地のまわりに、飛行機を一機ずつしまう掩体壕がつくられました。土を山のように盛って型にし、その上に鉄筋とコンクリートをかぶせ、固まったら中の土をかき出す。重機の少ない時代、この作業には多くの人手が必要で、地元の人々や学生たちも工事に動員されたと伝わります。","戦争の終わりが近づくと、茂原の基地からも特攻隊が出撃したといわれています。«なぜ、若者たちは帰らない出撃に向かったのか?» その問いは、今も私たちに重くのしかかります。1945年、戦争が終わると、飛行場は使われなくなり、跡地は田畑や住宅、工場へと姿を変えました。けれど、頑丈な掩体壕だけは壊すのがむずかしく、そのまま残されたのです。","今、茂原市は残った掩体壕を戦争の記憶を伝える大切な遺跡として紹介しています。多くは個人の土地にあるので、見学するときは道路から静かに見るようにしましょう。コンクリートのかたまりの前に立つと、ここで働き、ここから飛び立った人々のこと、そして戦争で亡くなったすべての人のことが思われます。"],"tl":[["1941年ごろ","茂原に海軍の飛行場の建設が進む"],["太平洋戦争中","海軍航空隊の基地として使われる"],["1944〜1945年","空襲に備えて掩体壕がつくられる"],["1945年","終戦。飛行場は役目を終える"],["戦後","跡地は農地や住宅地となり、掩体壕が各地に残る"],["平成以降","茂原市が掩体壕を戦争遺跡として紹介"]],"who":[["茂原基地の搭乗員","ここで訓練し、出撃した海軍の飛行機乗りたち"],["工事に動員された人々","地元の住民や学生。掩体壕の建設にあたったと伝わる"],["戦後の土地の持ち主","掩体壕を倉庫などとして使い、残してきた人々"]],"deep":["掩体壕は、屋根のある «有蓋掩体壕» と、土手で囲っただけの «無蓋掩体» に分かれる。茂原に残るのはコンクリート製の有蓋掩体壕。","茂原には大型の掩体壕が10基前後残っているとされ、一つの基地の周辺にこれほど多く残るのは全国的にも珍しい。","施工は土を盛って型にし、その上にコンクリートを打ち、固まってから土をかき出す方法が一般的だったとされる。","茂原基地に配備された部隊の名前や時期、特攻隊の出撃については資料によって記述に差があり、細部は確認が必要。","掩体壕の多くは個人所有で、倉庫や作業場として今も使われている。保存と活用のあり方が課題になっている。","高知県や大分県など、各地の海軍航空基地の周辺にも掩体壕が残り、戦争遺跡として保存の動きがある。"],"look":["田んぼの中に立つ掩体壕の姿（道路から静かに見る）","かまぼこ形の屋根の厚み","入口の大きさ（飛行機の翼の幅がわかる）","市の案内板"],"q":["飛行機を空襲から守るためにつくられたコンクリートの格納庫を何という？","«掩体壕»。茂原には今も多く残っています。"],"koji":[],"myth":"基地の開設年、残存数、特攻出撃の有無などは資料で差があり要確認。位置は代表点の目安。","img":["掩体壕","茂原市","特別攻撃隊"],"wp":"茂原海軍航空基地","rel":{"ev":[],"grave":[]},"ph":[["c:f/f8/Typhoon_Takes_Off_from_RAF_Coningsby_as_Part_of_Op_Ellamy_MOD_45152517.jpg",3000,1805,"掩体壕"],["c:1/1c/Mobara_montage_%E5%8D%83%E8%91%89%E7%9C%8C%E8%8C%82%E5%8E%9F%E5%B8%82%E3%83%A2%E3%83%B3%E3%82%BF%E3%83%BC%E3%82%B8%E3%83%A5.png",2048,2732,"茂原市"],["c:2/2d/USS_Missouri_Zero_Kamikaze.jpg",1850,2128,"特別攻撃隊"]]},{"id":"12_tetsudo_rentai","n":"鉄道連隊の演習線跡（千葉公園）","yomi":"てつどうれんたいのえんしゅうせんあと","cat":"近代","rank":"B","y":1908,"era":["meiji","taisho","showa"],"sh":"","ad":"千葉市中央区弁天","st":"千葉都市モノレール 千葉公園駅からすぐ","la":35.623,"lo":140.1165,"hook":"«戦場に線路を敷け!» ――鉄道をつくる兵隊が、千葉の町で訓練していた。その線路は、今の新京成線に生まれ変わった。","lead":"明治時代の終わりから昭和の戦争のころまで、千葉と津田沼には、線路をつくったり列車を走らせたりする陸軍の部隊 «鉄道連隊» がありました。千葉公園のあたりには連隊の演習の跡が残り、訓練用の線路の一部は今の新京成線のもとになりました。","story":["戦争で大切なのは、兵士や食料、武器を早く運ぶことです。明治時代、日本の陸軍は «戦場に鉄道を敷き、動かす専門の部隊» をつくりました。これが鉄道連隊です。日露戦争では、中国東北部の戦場で線路を敷き、列車を走らせる仕事をしました。","1908年、鉄道連隊は東京から千葉へ移ってきました。のちに部隊が二つに分かれ、第一連隊は千葉、第二連隊は津田沼に置かれます。千葉公園のあたりは、その第一連隊の敷地や演習場でした。兵隊たちは、ここで線路を敷く、橋をかける、機関車を動かすといった訓練をくり返したのです。","連隊は、訓練のために千葉県内にいくつもの «演習線» を敷きました。津田沼から松戸へ向かう演習線は、わざと大きく曲がりくねって敷かれたといわれます。«なぜ、まっすぐにしなかったの?» 短い距離でも長い線路を敷く練習ができるように、という説があります。戦後、この線路の用地を使って新京成電鉄が開業しました。今も新京成線にカーブが多いのは、そのなごりだといわれています。","千葉公園の中には、鉄道連隊の訓練に使われたと伝わるコンクリートの構造物が残り、公園の周辺にも、れんが造りの古い建物など連隊の時代を伝える遺構があります。連隊の兵隊たちは、戦争中には東南アジアなどでも鉄道の建設に関わりました。その中には、多くの人の命が失われた工事もあり、その歴史も忘れてはなりません。","今の千葉公園は、池やボート、ハスの花で知られる市民の憩いの場です。モノレールが頭上を走り、子どもたちが走り回る公園の中に、かつて線路を敷く兵隊の声がひびいていたことを想像すると、同じ場所がまったくちがって見えてきます。"],"tl":[["1896年","陸軍に鉄道大隊がつくられる"],["1904〜1905年","日露戦争で野戦鉄道の建設・運行を担う"],["1907年","鉄道連隊に改められる"],["1908年","鉄道連隊が千葉へ移る"],["1918年","鉄道第一連隊（千葉）と第二連隊（津田沼）に分かれる"],["1945年","終戦により連隊が解散"],["1947年","旧演習線の用地を使って新京成電鉄が開業（部分開業）"]],"who":[["鉄道連隊の兵士","線路の建設や列車の運行を訓練した兵隊たち"],["新京成電鉄","旧演習線の用地を活用して開業した鉄道会社"],["千葉市民","戦後、連隊跡地を公園や学校として受けついだ"]],"deep":["鉄道連隊は、線路の敷設・橋梁の架設・機関車の運転などを担う工兵系の部隊。戦場で使う軽便鉄道の車両（K2形機関車など）も運用した。","新京成線は、津田沼〜松戸の旧演習線の用地を利用して建設された。曲線が多いのは演習線の線形を引きついだためとされるが、演習目的の意図的な蛇行という説明には異論もある。","連隊の演習線は千葉県内の複数の区間に敷かれ、演習で敷いた線路を公共の鉄道として活用した例もある。","千葉公園周辺と千葉経済大学のあたりには、連隊の材料廠などとして使われたれんが造りの建物や施設の跡が伝わる。敷地内のものは見学に制限がある。","第二次世界大戦中、鉄道連隊は東南アジアでの鉄道建設にも従事した。泰緬鉄道の建設では、捕虜や現地の人々に多くの犠牲が出た。","連隊の機関車の一部は戦後、各地の軽便鉄道などに譲られたといわれ、保存されている車両もある。"],"look":["千葉公園内の鉄道連隊ゆかりの構造物と案内板","公園周辺に残るれんが建築（見学は外から）","新京成線のカーブの多い線形","モノレールと公園の池の景色"],"q":["鉄道連隊の演習線の用地を使って戦後に開業した鉄道は？","«新京成線»。カーブが多いのは演習線のなごりといわれます。"],"koji":[],"myth":"演習線の蛇行を «わざと» とする説明は諸説。千葉公園内の遺構の用途は伝承を含む。","img":["新京成電鉄新京成線","千葉公園","泰緬鉄道"],"wp":"鉄道連隊","rel":{"ev":[],"grave":[]},"ph":[["c:c/cc/%E5%A4%A7%E6%97%A5%E6%9C%AC%E5%B8%9D%E5%9B%BD%E9%99%B8%E8%BB%8D%E9%89%84%E9%81%93%E9%80%A3%E9%9A%8A%E3%81%AE%E6%BC%94%E7%BF%92%E3%81%AB%E7%94%A8%E3%81%84%E3%82%89%E3%82%8C%E3%81%9F%E6%A9%8B%E8%84%9A.jpg",3023,4031],["c:9/95/%E3%82%A6%E3%82%A3%E3%83%B3%E3%83%81%E5%8F%B0%EF%BC%88%E5%A4%A7%E6%97%A5%E6%9C%AC%E5%B8%9D%E5%9B%BD%E9%99%B8%E8%BB%8D%E9%89%84%E9%81%93%E9%80%A3%E9%9A%8A%EF%BC%89.jpg",4031,3023],["c:2/23/Frankfurter_Feldbahnmuseum_2018_%2841%29.jpg",5456,3632],["c:f/fb/Tsudanuma-Chiba_Institute_of_Technology.JPG",3648,2736],["c:6/6f/Chiba_Park.jpg",2934,1938],["c:7/7f/%E9%89%84%E9%81%93%E7%AC%AC1%E9%80%A3%E9%9A%8A01.jpg",1108,709],["c:b/b8/2nd_railway_regiment%2CTsudanuma.jpg",769,596],["c:c/c6/%E9%89%84%E9%81%93%E7%AC%AC2%E9%80%A3%E9%9A%8A01.jpg",868,474]]},{"id":"12_kamiya_villa","n":"旧神谷伝兵衛稲毛別荘","yomi":"きゅうかみやでんべえいなげべっそう","cat":"近代","rank":"B","y":1918,"era":["taisho"],"sh":"国の登録有形文化財","ad":"千葉市稲毛区稲毛1丁目","st":"京成千葉線 京成稲毛駅から歩いて約10分","la":35.6365,"lo":140.079,"hook":"«電気ブラン» と «日本初の本格ワイン» の男が、海辺に建てた白い洋館。大正の鉄筋コンクリートが、100年の時をこえて立つ。","lead":"旧神谷伝兵衛稲毛別荘は、浅草の «神谷バー» や茨城県牛久のワイン醸造所で知られる実業家・神谷伝兵衛が、大正時代に建てた別荘です。日本でも早い時期の鉄筋コンクリート造の住宅で、国の登録有形文化財になっています。","story":["明治から大正のころ、千葉の稲毛の海岸は、遠浅の海と松林が美しい保養地でした。東京から汽車に乗って、たくさんの人が海水浴や潮干狩りにやってきました。その海を見下ろす高台に、白い洋館を建てたのが神谷伝兵衛です。","伝兵衛は、今の愛知県で生まれ、若いころに横浜の外国人の酒屋で働いて、ワインづくりを学びました。やがて東京・浅草に店を開き、ブランデーをもとにしたお酒 «電気ブラン» を売り出して大人気に。さらに茨城県の牛久に大きなワイン醸造所 «牛久シャトー» を建て、日本で本格的なワインづくりに挑戦しました。«日本人の口にあうワインを!» それが伝兵衛の夢でした。","この別荘が建てられたのは1918年（大正7年）。当時、住宅はふつう木でつくられていましたが、伝兵衛の別荘は鉄筋コンクリートでつくられました。«なぜ、そんな新しい造りに?» 海辺の強い風や湿気に負けない、じょうぶな家にしたかったのかもしれません。この建物は、日本で早い時期の鉄筋コンクリート造の住宅として貴重なのです。","建物は2階建てで、1階は洋風、2階には和室があります。和と洋がまじりあったつくりは、大正時代の «ハイカラ» な暮らしを思わせます。1923年の関東大震災でも大きな被害を受けず、コンクリート建築の丈夫さを示したとも伝えられます。","伝兵衛がこの別荘ですごした時間は長くはなく、数年後の1922年に亡くなりました。その後、建物は持ち主が変わりながら残り、今は千葉市が保存して公開しています。今は海が埋め立てられて遠くなりましたが、2階の窓から外をながめ、かつて広がっていた稲毛の海を想像してみてください。"],"tl":[["1856年","神谷伝兵衛が生まれる"],["1880年代","浅草で酒の店を始め、のち «電気ブラン» が評判に"],["1903年","茨城県牛久にワイン醸造所（牛久シャトー）が完成"],["1918年","稲毛に鉄筋コンクリート造の別荘を建てる"],["1922年","神谷伝兵衛が亡くなる"],["1997年","国の登録有形文化財に登録"],["現在","千葉市が管理し、一般に公開"]],"who":[["神谷伝兵衛","実業家。神谷バー・牛久シャトーの創業者で、この別荘の建て主"],["稲毛を訪れた文人たち","稲毛の海岸は保養地として多くの文化人に愛された"],["千葉市","別荘を保存・公開している"]],"deep":["建物は1918年竣工の鉄筋コンクリート造2階建て。日本の住宅建築で鉄筋コンクリートが使われ始めた時期の例として評価される。","1階は洋風の応接空間、2階は和室を中心とした構成で、和洋折衷の意匠が見られる。2階の和室の壁画も見どころの一つ。","«牛久シャトー» は1903年に完成した日本初の本格的なワイン醸造場として知られ、建物は国の重要文化財に指定されている。","«電気ブラン» の名は、明治の «電気» が最新のものの代名詞だったことに由来するといわれる。","稲毛の海岸は昭和の埋め立てで大きく姿を変えた。別荘の立地は、かつての海岸段丘の上にあたる。","公開日や時間は千葉市の案内で確認が必要。周辺には愛新覚羅溥傑夫妻の旧居 «千葉市ゆかりの家・いなげ» もあり、あわせて見学できる。"],"look":["白い外観と鉄筋コンクリートの壁","2階の和室と壁画","海に向かって開いた窓（かつての海岸線を想像）","近くの «千葉市ゆかりの家・いなげ»"],"q":["神谷伝兵衛が浅草で売り出した人気のお酒は？","«電気ブラン»。今も浅草の神谷バーで飲めます。"],"koji":[],"myth":"関東大震災で無事だったという話は伝承を含む。別荘の利用の実態は不明な点がある。","img":["神谷伝兵衛","牛久シャトー","神谷バー","稲毛区"],"wp":"旧神谷伝兵衛稲毛別荘","rel":{"ev":[],"grave":[]},"ph":[["c:6/66/Old_Kamiya_Denbei_Inage_Villa_ac_%281%29.jpg",6016,4000,"旧神谷伝兵衛稲毛別荘"],["c:d/d5/Inage_Villa_stairs_ac_%284%29.jpg",5863,3899],["c:1/12/Inage_Villa_porch_ac_%281%29.jpg",5861,3897],["c:7/7c/Inage_Villa_garden_ac_%281%29.jpg",5948,3955],["c:a/a1/Inage_Villa_exhibition_room_ac_%281%29.jpg",5961,3964],["c:b/be/Inage_Villa_Western-style_room_ac_%284%29.jpg",5926,3939],["c:7/7e/Inage_Villa_Japanese-style_room_ac_%2815%29.jpg",5863,3899],["c:1/17/Inage_Beach.jpg",5049,3234]]},{"id":"12_kyu_yoshida","n":"旧吉田家住宅（柏の豪農屋敷）","yomi":"きゅうよしだけじゅうたく","cat":"町","rank":"B","y":1836,"era":["edo","meiji"],"sh":"国の重要文化財","ad":"柏市花野井","st":"JR常磐線 柏駅からバスで約20分、下車して歩いてすぐ","la":35.887,"lo":139.949,"hook":"門をくぐれば、江戸の «大百姓» の世界。名主をつとめ、醤油をつくり、野馬を見張った一族の屋敷が丸ごと残る。","lead":"旧吉田家住宅は、柏市花野井にある江戸時代の大きな農家の屋敷です。吉田家は村の名主をつとめ、醤油づくりなどの商売でも栄えました。主屋や長屋門などが国の重要文化財に指定され、歴史公園として公開されています。","story":["利根川に近い柏の花野井。ここに、どっしりとした長屋門をかまえた屋敷があります。門の両わきには部屋が続き、奥には大きなかやぶき屋根の主屋。ここが旧吉田家住宅です。«長屋門» は、ふつうの農家には許されない、格の高い家のしるしでした。","吉田家は、江戸時代にこのあたりの村の «名主（なぬし）» をつとめた家です。名主は、年貢を集めて幕府や領主に納めたり、村の争いをおさめたりする村のリーダー。さらに吉田家は、醤油の醸造などの商売でも成功し、大きな財産をきずきました。«農家なのに商売も?» 江戸時代の後半になると、このように農業と商売を両方行う «豪農» があちこちに生まれていたのです。","花野井のまわりには、江戸時代、幕府の «小金牧（こがねまき）» という広い牧場がありました。そこでは馬が放し飼いにされ、«野馬（のま）» と呼ばれていました。吉田家は、この野馬の管理に関わる役目もつとめたと伝わります。野馬を集めて選び出す «野馬捕り» は、村人総出の大行事でした。","主屋は江戸時代後期に建てられたもので、広い土間、いくつもの座敷、りっぱな式台（玄関）があり、身分の高い客をもてなせるつくりになっています。明治時代以降も吉田家は地域の有力者として続き、屋敷にはさまざまな時代の建物が加わりました。蔵や書院などが並ぶ敷地全体が、一つの «村の歴史の資料館» のようです。","その後、屋敷は柏市に寄贈され、修理をへて歴史公園として公開されました。土間に立つと、かまどの煙や醤油のにおい、名主をたずねてくる村人たちの声が聞こえてきそうです。季節ごとの行事も行われ、江戸から続く農村の暮らしを身近に感じられる場所です。"],"tl":[["江戸時代前期","吉田家が花野井に住み、のちに名主をつとめる"],["江戸時代中期以降","醤油の醸造などで家業を広げる"],["江戸時代後期","現在の主屋が建てられる"],["明治時代以降","書院や蔵などが加わる"],["平成時代","柏市に寄贈され、国の重要文化財に指定。歴史公園として公開"]],"who":[["吉田家の当主たち","名主をつとめ、醤油づくりなどで家を栄えさせた"],["花野井の村人","吉田家とともに村を支えた人々"],["小金牧の野馬役人","幕府の牧場を管理した役人。吉田家も関わったと伝わる"]],"deep":["主屋は江戸時代後期の建築とされ、式台つきの玄関や多数の座敷を持つ。名主として役人を迎えるための格式が建物に表れている。","長屋門・土蔵・書院など複数の建物がまとめて重要文化財に指定されており、屋敷構え全体が残る点が評価されている。","小金牧は幕府直轄の牧場で、下総台地に広がっていた。吉田家が牧の管理に関わる役を担ったことは地域史で紹介されるが、詳細は資料で確認したい。","江戸時代の下総は、野田・銚子を中心に醤油醸造が盛んな地域で、利根川・江戸川の水運を通じて江戸へ出荷された。","吉田家には多くの古文書が伝わり、村の運営や商売の実態を知る資料として研究されている。","建物の見学は公開日・時間の制限がある。季節の行事日は混むこともある。"],"look":["格式の高い長屋門","主屋の広い土間と式台","書院と庭","土蔵群"],"q":["村のリーダーとして、年貢を集めたり村の争いをおさめたりした役職を何という？","«名主（なぬし）»。関西では «庄屋» とも呼ばれました。"],"koji":[],"myth":"主屋の建築年、小金牧との関わりの具体的な内容、醸造業の規模は要確認。","img":["小金牧","豪農","柏市","長屋門"],"wp":"旧吉田家住宅","rel":{"ev":[],"grave":[]},"ph":[["c:e/eb/Kashiwa_montage.jpg",2496,3476,"柏市"],["c:9/98/Odake_nagayamon01_2816.jpg",2816,1584,"長屋門"],["c:e/e3/Edogawa_University-202604.JPG",3794,2399,"近く: 江戸川大学"],["c:f/f1/%E3%81%A4%E3%81%8F%E3%81%B0Ex.%E6%9F%8F%E3%81%AE%E8%91%89%E3%82%AD%E3%83%A3%E3%83%B3%E3%83%91%E3%82%B9%E9%A7%85_-_panoramio%28cropped%29.jpg",2514,1767,"近く: 柏の葉キャンパス駅"],["c:d/d1/National_Research_Institute_of_Police_Science_%28Japan%29.JPG",2048,1536,"近く: 科学警察研究所"],["c:b/b7/Kashiwanoha_Park_Makigahara-en.JPG",2048,1536,"近く: 柏の葉公園"],["c:d/d5/Kashiwanoha-HighSchool.JPG",3648,2736,"近く: 千葉県立柏西高等学校"]]},{"id":"12_gyotoku_enden","n":"行徳塩田（家康も保護した塩浜）","yomi":"ぎょうとくえんでん","cat":"産業","rank":"B","y":1600,"era":["edo","meiji","taisho"],"sh":"","ad":"市川市本行徳","st":"東京メトロ東西線 妙典駅または行徳駅から歩いて約15分（常夜灯公園）","la":35.689,"lo":139.916,"hook":"江戸の台所をささえた «しお» の浜。家康は塩を運ぶために、運河まで掘らせた。","lead":"行徳は、江戸時代、江戸にいちばん近い塩の産地でした。海辺に広がる塩田で海水から塩をつくり、船で江戸へ運びました。徳川家康はこの塩浜をとても大切にし、塩を運ぶための水路も整えたといわれます。今は塩田は残っていませんが、常夜灯や寺町に当時のにぎわいが感じられます。","story":["人は、塩がなければ生きていけません。食べ物の味つけだけでなく、魚や野菜を保存するのにも塩は欠かせませんでした。1590年、徳川家康が江戸に入ったとき、まず気にしたことの一つが «塩をどうやって手に入れるか» だったといわれます。もし戦になって塩が届かなくなったら、城も町もたちまち困ってしまうからです。","そこで目をつけたのが、江戸のすぐ東、行徳の浜でした。遠浅の海が広がる行徳では、昔から塩づくりが行われていたのです。家康は行徳の塩浜を保護し、年貢を軽くするなどして塩づくりをすすめたと伝わります。さらに、江戸と行徳を船で結ぶため、小名木川などの水路を整えました。塩を運ぶ «塩の道» が、江戸の町の中まで通じたのです。","塩づくりは、とても手間のかかる仕事でした。砂をしいた塩田に海水をまき、太陽と風で乾かして、塩分のついた砂を集めます。その砂に海水をかけて濃い塩水をつくり、大きな釜で煮つめて、ようやく白い塩ができあがります。夏の暑い日も、浜の人々は汗まみれで働きました。«どうして行徳の塩は重宝されたの?» 江戸に近く、船ですぐ運べたからです。","やがて行徳には、江戸と結ぶ «行徳船» が行き来するようになり、塩だけでなく、人も運ぶようになりました。成田山へ参詣する江戸の人々も、行徳船で行徳まで来て、そこから歩いたのです。本行徳の河岸に今も立つ «常夜灯» は、江戸時代の後半に江戸の人々が寄進したもので、夜の船着き場を照らしました。","しかし明治以降、全国から安い塩が入ってくるようになり、さらに大正時代の大きな高潮の被害を受けて、行徳の塩田はしだいに姿を消していきました。今、かつての塩浜は住宅地や埋立地になっています。江戸川の土手に立つ常夜灯を見上げながら、塩を煮る煙がたなびいていた浜の風景を思い浮かべてみてください。"],"tl":[["戦国時代以前","行徳の浜で塩づくりが行われる"],["1590年","徳川家康が江戸に入る"],["江戸時代初め","家康が行徳の塩浜を保護し、小名木川などで江戸と結ぶ"],["江戸時代","行徳船が江戸と行徳を往来し、成田参詣の道にもなる"],["1812年","本行徳に常夜灯が建てられる"],["1917年","大きな高潮で塩田が大きな被害を受ける"],["昭和時代","塩田が姿を消し、住宅地となる"]],"who":[["徳川家康","行徳の塩浜を保護したと伝わる"],["行徳の塩焼きの人々","塩田で働き、塩をつくった人々"],["江戸の町人","行徳の塩を使い、行徳船で成田参詣に向かった人々"]],"deep":["行徳の製塩は «入浜式» が中心だったとされる。潮の満ち引きを利用して塩田に海水を入れ、砂に塩分を付着させる方法で、瀬戸内海の十州塩田と同じ系統の技術。","小名木川は江戸時代初めに開削された運河で、隅田川と中川を結び、行徳の塩を江戸へ運ぶ «塩の道» として知られる。開削の年は資料によって表記がある。","行徳船は本行徳と江戸の小網町（日本橋）を結んだ乗合船で、幕府に公認された航路として運航した。","本行徳の常夜灯は1812年（文化9年）に江戸の成田山参詣の講中が寄進したもので、市川市の文化財になっている。","行徳は寺が多い «寺町» としても知られ、塩浜と船着き場で栄えた町の豊かさを今に伝えている。","明治末の塩専売制度（1905年）以降、地方の小規模な塩田は整理の対象となり、行徳の製塩も衰退へ向かった。"],"look":["常夜灯公園の常夜灯（江戸川の土手）","本行徳・本塩の寺町の家並み","«本塩» «塩焼» など塩にちなむ地名","市川市の博物館での塩田の展示（開館を確認）"],"q":["江戸と行徳を結び、塩を運ぶのに使われた運河の名は？","«小名木川»。家康のころに整えられたといわれます。"],"koji":[],"myth":"家康の保護の内容（年貢の軽減など）は伝承を含む。入浜式か揚浜式かの時期区分は要確認。","img":["小名木川","常夜灯","入浜式塩田"],"wp":"行徳","rel":{"ev":[],"grave":[]},"ph":[["c:3/3e/%E8%A1%8C%E5%BE%B3%E5%AF%8C%E5%A3%AB.jpg",4032,3024],["c:7/7d/Ch%C3%A2teau_de_Himeji02.jpg",2592,1944],["c:6/63/Onagiga_Riv.jpg",1900,1267,"小名木川"],["c:2/23/KonpiraKouTourou01.jpg",3072,2304,"常夜灯"],["c:9/93/Marakkanam_Salt_Pans.JPG",4055,2693,"入浜式塩田"]]},{"id":"12_kisaradu_kashi","n":"木下河岸（利根川の河岸と木下茶船）","yomi":"きおろしがし（きおろしちゃぶね）","cat":"産業","rank":"B","y":1760,"era":["edo","meiji"],"sh":"","ad":"印西市木下","st":"JR成田線 木下駅から歩いて約5分","la":35.807,"lo":140.198,"hook":"江戸っ子の «週末旅行» はここから船に乗った。利根川をくだって鹿島・香取・息栖の三社めぐりへ。","lead":"木下河岸は、利根川にあった江戸時代の船着き場です。江戸から陸路でここまで来た人々は、«木下茶船» という乗合船に乗って、鹿島・香取・息栖の神社参りや銚子の見物に出かけました。米や魚を運ぶ船も集まり、町は大いににぎわいました。","story":["江戸時代、江戸の人々は «三社参り» にあこがれていました。三社とは、常陸の鹿島神宮、下総の香取神宮、そして息栖神社。どれも古くから人々があつく信仰してきた神社です。ではどうやって行ったのか。江戸から行徳まで船で行き、そこから歩いて木下へ。そして木下から、利根川をくだる船に乗ったのです。","この船が «木下茶船（きおろしちゃぶね）»。十数人が乗れる屋根つきの乗合船で、江戸時代の中ごろから運航が始まったといわれます。朝に木下を出ると、流れにのって下流へ。香取、息栖、鹿島を回り、さらに銚子の海まで足をのばす旅もありました。船の上では、景色をながめ、お弁当を広げ、おしゃべりを楽しむ。まるで観光バスのような船旅だったのです。","«なぜ、木下が船着き場になったの?» 利根川はこのあたりで江戸に最も近づく場所の一つで、江戸からの陸路（木下街道）と、利根川の水運が出会う «乗りかえ地点» だったからです。旅人だけでなく、銚子でとれた魚や、周辺の村の米、薪なども、ここで船から荷車へと積みかえられ、江戸へ運ばれていきました。","木下の町には、船問屋や宿屋、茶屋が並び、夜おそくまで人の声がたえなかったといいます。旅人の中には、紀行文や絵を残した文人もいました。河岸のにぎわいは、明治時代になっても続き、蒸気船が行き来するようになります。しかし鉄道が開通すると、人も荷物も汽車で運ばれるようになり、河岸はしだいにさびれていきました。","今、木下の町を歩くと、古い商家の建物や、かつての河岸の場所を示す案内板が見つかります。町の一角には、古い家を使った小さな博物館もあり、河岸の時代の品々が展示されています。利根川の堤防に上がって、ゆったりと流れる川を見下ろせば、茶船に乗りこむ江戸っ子たちのはずんだ声が聞こえてくるようです。"],"tl":[["江戸時代初め","利根川の流れを東へ変える «利根川東遷» が進み、水運が発達"],["江戸時代","木下河岸が利根川水運の拠点となる"],["江戸時代中期","木下茶船による三社参り・銚子遊覧が人気になる"],["明治時代","蒸気船が利根川を行き来する"],["1901年","成田線（成田鉄道）の木下駅が開業し、しだいに河岸は衰える"]],"who":[["江戸の旅人","木下茶船で三社参りを楽しんだ人々"],["木下の船問屋","船と荷物の取り次ぎをした商人たち"],["船頭","利根川をくだる茶船をあやつった人々"]],"deep":["«河岸» は川の港のこと。利根川・江戸川の水系には多くの河岸があり、江戸と関東各地を結ぶ物流網を形づくっていた。","木下街道は行徳から鎌ヶ谷・白井を通って木下へ至る道で、銚子の鮮魚を江戸へ運ぶ «鮮魚街道» の一部としても使われた。","三社参りの鹿島神宮・香取神宮・息栖神社は «東国三社» と呼ばれ、江戸時代には伊勢参りの «禊ぎ» として三社を巡る習わしがあったとも伝わる。","利根川東遷は、江戸時代初めに利根川の流れを銚子へ向けた大工事。これにより利根川下流の水運が大きく発展した。","木下茶船の運航開始の時期や乗客数については、資料によって記述が異なり、正確な数字ははっきりしない。","木下には «木下貝層» と呼ばれる古い貝の化石層があり、千葉県の天然記念物として知られる。河岸見物とあわせて見学できる。"],"look":["利根川の堤防からの眺め（かつての河岸の方向）","木下の町に残る古い商家","河岸の歴史を紹介する町の博物館や案内板","近くの木下貝層"],"q":["鹿島神宮・香取神宮と並んで «東国三社» に数えられる神社は？","«息栖神社»。木下茶船でこの三社をめぐる旅が人気でした。"],"koji":[],"myth":"茶船の運航開始時期、乗客数などは資料で差がある。","img":["木下駅","利根川","香取神宮","息栖神社"],"wp":"印西市","rel":{"ev":[],"grave":[]},"ph":[["c:4/41/Inzai_montages.jpg",2481,3491,"印西市"],["c:4/44/%E6%A0%84%E7%A6%8F%E5%AF%BA%E8%96%AC%E5%B8%AB%E5%A0%82.JPG",3456,4608],["c:6/6b/Lake_Inba.JPG",4608,3456],["c:a/ab/Iwai-ke_Jyutaku_Syuoku.jpg",4320,3240],["c:9/9a/Inzai_police_station.JPG",3648,2736],["c:b/b2/Hokusou_hananooka_kouen_20171102.jpg",3648,2736],["c:9/90/Inzai_city_hall.JPG",3231,2454],["c:f/ff/Inzai_Makinohara_Sta._building_%282013.02%29_1.jpg",3060,1952]]},{"id":"12_oyama_senmaida","n":"大山千枚田","yomi":"おおやませんまいだ","cat":"産業","rank":"B","y":1700,"era":["edo","heisei"],"sh":"","ad":"鴨川市平塚","st":"JR外房線 安房鴨川駅から車で約30分。公共交通では行きにくい","la":35.11,"lo":140.067,"hook":"山の斜面に375枚の田んぼが階段のように重なる。水を引く川はなく、たよりは空からの雨だけ。","lead":"大山千枚田は、鴨川市の山あいにある棚田です。小さな田んぼが斜面にびっしりと並び、«日本の棚田百選» にも選ばれました。川から水を引かず、雨水だけで米をつくる «天水田» であることでも知られています。","story":["鴨川の海から山のほうへ車を走らせると、突然、目の前が大きく開けます。山の斜面に、大小さまざまな田んぼが、まるで階段のように何段も何段も重なっているのです。その数、およそ375枚。これが大山千枚田です。«千枚田» とは、数えきれないほどたくさんの田んぼ、という意味です。","«なぜ、こんな急な斜面に田んぼをつくったの?» 平らな土地が少ない山あいの村では、米をつくるには斜面を切りひらくしかありませんでした。石や土で «あぜ» を積み、少しずつ平らな面をつくっていく。いつ始まったのかははっきりしませんが、何世代にもわたる人々の努力によって、この景色が生まれたのです。","大山千枚田には、水を引く川がありません。田んぼをうるおすのは、空から降る雨と、山からしみ出す水だけ。だから、上の田んぼから下の田んぼへ、水を少しずつ分けあって使います。いちばん上の田んぼで一滴の水をむだにすると、下の田んぼが困ってしまう。村の人たちは、昔から水を大切にし、助けあって米をつくってきました。","しかし、昭和の終わりから平成にかけて、農家の高齢化で棚田を続けるのがむずかしくなりました。機械が入りにくい小さな田んぼは手間がかかり、荒れてしまうところも出てきたのです。そこで始まったのが «棚田オーナー制度»。都会の人がお金を出して田んぼの «オーナー» になり、地元の人に教わりながら田植えや稲刈りをするしくみです。","今では、多くの人が大山千枚田をおとずれ、米づくりを体験しています。田植えのころには水面に空がうつり、夏には緑のじゅうたん、秋には黄金色の稲穂が風にゆれます。秋から冬にかけては、あぜにたくさんの明かりをともす催しもあります。人の手で守られてきた風景の美しさを、ぜひ自分の目で確かめてみてください。"],"tl":[["江戸時代ごろ","山の斜面が切りひらかれ、棚田がつくられていったと考えられる"],["昭和時代後期","農家の高齢化で耕作の継続が課題となる"],["1999年","«日本の棚田百選» に選ばれる"],["2000年","棚田オーナー制度が始まる"],["平成時代以降","米づくり体験やライトアップの催しでにぎわう"]],"who":[["大山の農家の人々","何世代にもわたって棚田を耕し、守ってきた"],["棚田オーナー","都会から来て米づくりに参加する人々"],["棚田を守る保存会","オーナー制度や催しを運営する地元の団体"]],"deep":["«天水田» は、川やため池からの用水路に頼らず、雨水や湧き水で耕作する田。大山千枚田は «日本で唯一、雨水のみで耕作を行っている天水田» と紹介されることがある。","«日本の棚田百選» は1999年に農林水産省が選定したもの。大山千枚田は «東京から一番近い棚田» とも呼ばれる。","棚田の総面積は約3ha余りとされ、1枚あたりの田はとても小さい。大型の機械が入れないため、多くの作業が手作業になる。","棚田の起源ははっきりせず、江戸時代にはすでにあったと考えられているが、開発の時期を示す確かな史料は少ない。","棚田は米づくりだけでなく、土砂崩れを防ぎ、雨水をたくわえる «小さなダム» の役割も果たしている。","周辺の嶺岡山系には、江戸時代に幕府の牧場 «嶺岡牧» があり、日本の酪農発祥の地ともいわれる。"],"look":["展望所から見下ろす棚田の全景","田植え後の水鏡（5月ごろ）","秋の稲穂とはさ掛け","夜の棚田のライトアップ（開催日を確認）"],"q":["川から水を引かず、雨水などだけで米をつくる田んぼを何という？","«天水田»。大山千枚田はその代表例として知られます。"],"koji":[],"myth":"棚田の起源は不明。枚数・面積は数え方で差がある。","img":["棚田","日本の棚田百選","鴨川市","嶺岡牧"],"wp":"大山千枚田","rel":{"ev":[],"grave":[]},"ph":[["c:9/90/%E5%A4%A7%E5%B1%B1%E5%8D%83%E6%9E%9A%E7%94%B0_%E5%8D%83%E8%91%89%E7%9C%8C%E9%B4%A8%E5%B7%9D%E5%B8%82_%E7%94%B0%E6%A4%8D%E3%81%88%E7%9B%B4%E5%BE%8C_-_panoramio.jpg",1600,1067,"大山千枚田"],["c:6/67/Oyama_Senmaida_in_Summer.JPG",4288,3216],["c:e/e5/Oyamasenmaida.JPG",1600,1200],["c:f/ff/RiceTerracesVietnam.jpg",4752,3168,"棚田"],["c:7/77/Aragijima003.JPG",4032,3024,"日本の棚田百選"],["c:0/04/Kamogawa_Montage.jpg",2464,3492,"鴨川市"]]},{"id":"12_niemon_jima","n":"仁右衛門島（頼朝伝説の島）","yomi":"にえもんじま","cat":"島","rank":"B","y":1180,"era":["kamakura","edo"],"sh":"県指定名勝","ad":"鴨川市太海","st":"JR内房線 太海駅から歩いて約15分、手こぎの渡し船で約5分","la":35.087,"lo":140.096,"hook":"一つの家族が、何百年も «島の主» として暮らし続ける島。岩屋には、敗れた頼朝がかくれたと伝わる。","lead":"仁右衛門島は、鴨川市の太海の沖に浮かぶ小さな島です。代々 «平野仁右衛門» を名のる一家が住み続けてきた、個人が所有する島として知られます。源頼朝がかくれたという洞窟の伝説もあり、手こぎの船で渡ることができます。","story":["太海の浜から海を見ると、すぐ目の前に緑におおわれた島があります。浜の船着き場で待っていると、船頭さんが手こぎの小舟で迎えに来てくれます。ギィ、ギィと櫓の音をひびかせて、わずか数分。着いた先が仁右衛門島です。","この島には、ふしぎな歴史があります。島に住むのは、平野家という一つの家族だけ。当主は代々 «仁右衛門» という名前をつぎ、島の名前もそこから来ています。«なぜ一つの家族がずっと島に住んでいるの?» はっきりした始まりはわかりませんが、戦国時代には、この地を治めた里見氏から島を与えられたとも伝わります。","島には、源頼朝の伝説が残っています。1180年、頼朝は伊豆で兵を挙げましたが、石橋山の戦いで大敗し、海をわたって安房へ逃げました。追っ手から身をかくすため、この島の岩屋にひそんだところ、平野家の祖先がかくまい、食べ物を届けたと伝わります。のちに天下をとった頼朝は、このときの恩を忘れなかった、という話も語られています。","島にはほかにも、日蓮が修行したと伝わる場所や、美しい海岸の岩場があります。ごつごつした岩に波がくだけ、潮だまりには小さな生き物が暮らしています。平野家の古い屋敷も見学でき、江戸時代からの暮らしのようすをしのぶことができます。","島全体は千葉県の名勝に指定され、その景色の美しさが守られています。個人の島なので、見学には渡し船の料金が必要で、決まった時間と場所の中で楽しむルールがあります。860年以上も前の頼朝の逃避行を想像しながら、岩屋の前に立ってみてください。"],"tl":[["1180年","石橋山の戦いに敗れた源頼朝が安房へ渡る。この島の岩屋にかくれたと伝わる"],["鎌倉時代","日蓮がこの島で修行したとの伝承がある"],["戦国時代","里見氏のもとで平野家が島を与えられたと伝わる"],["江戸時代","平野家が代々 «仁右衛門» を名のり島に住む"],["昭和時代","千葉県の名勝に指定される"]],"who":[["源頼朝","石橋山の敗戦後、この島にかくれたと伝わる"],["平野仁右衛門","島の主。代々この名を受けつぐ平野家の当主"],["日蓮","この島で修行したと伝わる"],["里見氏","戦国時代の安房の大名。平野家との関係が伝わる"]],"deep":["頼朝の安房上陸は «吾妻鏡» にも記されるが、仁右衛門島にかくれたという話は地元の伝承で、史料による裏づけはない。","平野家は数十代にわたって島の主をつとめているとされ、当主の代数は伝承を含むため資料で異なる。","島への渡し船は手こぎの小舟で、観光船としても珍しい存在。天候や海の状態によって運休することがある。","島の周辺は房総半島南部の隆起海岸にあたり、波に削られた岩棚や海食洞が見られる。","安房では頼朝の上陸伝説が各地に残り、鋸南町の竜島（上陸地と伝わる）などとあわせて «頼朝伝説の道» をたどることができる。","島の見学は、個人の生活の場でもあることに配慮し、決められた順路とルールを守る必要がある。"],"look":["手こぎの渡し船","頼朝がかくれたと伝わる岩屋","平野家の屋敷","島の周囲の岩場と太海の海"],"q":["仁右衛門島にかくれたと伝わる、のちの鎌倉幕府の将軍はだれ？","«源頼朝»。石橋山の戦いに敗れて安房へ逃れたときの伝説です。"],"koji":[],"myth":"頼朝・日蓮の伝説は伝承。平野家の起源や当主の代数は諸説。","img":["源頼朝","石橋山の戦い","鴨川市","太海駅"],"wp":"仁右衛門島","rel":{"ev":[],"grave":[]},"ph":[["c:f/fc/%E4%BB%81%E5%8F%B3%E8%A1%9B%E9%96%80%E5%B3%B6_006.jpg",2288,1712,"仁右衛門島"],["c:f/f3/Niemon_Island_Ferry.jpg",3840,2160],["c:2/2b/%E4%BB%81%E5%8F%B3%E8%A1%9B%E9%96%80%E5%B3%B6_042.jpg",2288,1712],["c:6/66/%E4%BB%81%E5%8F%B3%E8%A1%9B%E9%96%80%E5%B3%B6_039.jpg",1712,2288],["c:f/f4/%E3%81%AD%E3%81%98%E5%BC%8F_%E5%A4%AA%E6%B5%B7034.jpg",2288,1712],["c:0/08/%E5%B1%B1%E6%A2%A8%E7%B8%A3%E7%94%B2%E5%BA%9C%E5%B8%82%E5%96%84%E5%85%89%E5%AF%BA%E6%BA%90%E8%B3%B4%E6%9C%9D%E6%9C%A8%E5%83%8F.jpg",1792,2560,"源頼朝"],["c:4/49/Battlefield_of_Ishibashiyama%2C_sekihi-1.jpg",5323,3551,"石橋山の戦い"],["c:0/04/Kamogawa_Montage.jpg",2464,3492,"鴨川市"]]},{"id":"12_okinoshima","n":"沖ノ島（館山湾の縄文遺跡の島）","yomi":"おきのしま","cat":"島","rank":"B","y":-6000,"era":["jomon","taisho"],"sh":"","ad":"館山市富士見","st":"JR内房線 館山駅からバスで約10分、下車して歩いて約20分","la":34.998,"lo":139.824,"hook":"歩いて渡れる無人島。その海辺の地面の下から、縄文人がとったイルカの骨が大量に見つかった。","lead":"沖ノ島は、館山湾に浮かぶ周囲1kmほどの小さな島です。関東大震災で土地が隆起したことなどから、今は砂浜で陸とつながり、歩いて渡れます。島では縄文時代早期の遺跡が見つかり、イルカなどの骨が大量に出土しました。","story":["館山の海辺を歩いていくと、こんもりと木におおわれた島が見えてきます。砂浜を歩いて、そのまま島へ。«え、島なのに歩いて行けるの?» じつは沖ノ島は、もとは海に浮かぶ島でした。1923年の関東大震災で房総半島の南部の土地がもち上がり、さらに砂がたまって、陸と島がつながったのです。","島の中は、タブノキやスダジイなどの木がうっそうとしげる森。小さな神社もまつられています。ぐるりと一周しても1時間かからないほどの島ですが、磯には潮だまりが広がり、夏は海水浴やシュノーケリングの人でにぎわいます。館山湾は、サンゴが見られる北のほうの海としても知られています。","この島で、驚くべき発見がありました。島の海辺で行われた調査で、縄文時代早期、いまから何千年も前の人々の暮らしの跡が見つかったのです。出てきたのは、土器や石器、そしてたくさんの動物の骨。その中には、イルカの骨が大量に含まれていました。«縄文人は、イルカをどうやってとったのだろう?» 丸木舟で湾に追いこんだのか、浜に打ちあげられたものを使ったのか。研究者たちの想像は広がります。","さらに、遺跡からは黒曜石の石器も見つかりました。黒曜石はどこでもとれる石ではありません。伊豆の島々など、海をこえた遠くから運ばれてきたと考えられています。縄文の人々は、舟をあやつって海を行き来し、ものを交換していたのです。小さな島の遺跡は、海とともに生きた縄文人の姿を教えてくれます。","今、沖ノ島は «館山市の自然公園» として大切に守られ、島の自然や歴史を伝える活動も行われています。すぐ近くには海上自衛隊の基地があり、ヘリコプターの音がひびくこともあります。何千年も前、この浜でイルカを囲んでいた縄文人たちと、同じ海を見ていると思うと、ふしぎな気持ちになるでしょう。"],"tl":[["縄文時代早期","沖ノ島に人々がくらし、イルカなどをとっていた跡が残る"],["江戸時代","海に浮かぶ島として知られる"],["1923年","関東大震災で土地が隆起。のちに砂がたまって陸とつながる"],["平成時代","島の海辺で縄文時代の遺跡の調査が行われる"],["現在","自然と歴史を学べる島として親しまれる"]],"who":[["縄文時代の人々","沖ノ島で海の恵みをとってくらした"],["館山市の調査団","遺跡の発掘調査を行った"],["島の自然を守る人々","沖ノ島の森や海の保全に取り組む地元の人々"]],"deep":["沖ノ島遺跡は縄文時代早期の遺跡とされ、イルカ類の骨がまとまって出土したことで注目された。縄文早期の海の狩りの具体的な証拠として重要。","出土した黒曜石の一部は、伊豆諸島の神津島産と推定されている。縄文時代の海を越えた交流を示す例として知られる。","房総半島南部は、1703年の元禄地震や1923年の関東大震災で大きく隆起した。沖ノ島が陸続きになったのも、この地殻変動と砂の堆積による。","館山湾は黒潮の影響を受け、サンゴの北限に近い海域の一つとして知られる。沖ノ島周辺でもサンゴが観察される。","島の森は、タブノキ・スダジイなどの照葉樹林で、人の手があまり入っていない房総南部の海岸林の姿をよく残している。","遺跡の年代や出土品の数などの詳細は、調査報告や館山市の資料で確認するのがよい。"],"look":["歩いて渡れる砂州（島と陸をつなぐ）","島の照葉樹林と小さな神社","磯の潮だまりの生き物","遺跡の説明板（あれば）"],"q":["沖ノ島が陸とつながるきっかけとなった、1923年の大きな地震は？","«関東大震災»。房総半島の南部の土地がもち上がりました。"],"koji":[],"myth":"遺跡の年代（縄文早期の具体的な年数）、黒曜石の産地推定は要確認。y は推定。","img":["館山市","関東大震災","黒曜石"],"wp":"沖ノ島 (千葉県)","rel":{"ev":[],"grave":[]},"ph":[["c:5/59/%E6%B2%96%E3%83%8E%E5%B3%B6_-_panoramio.jpg",1920,1440,"沖ノ島 (千葉県)"],["c:7/75/Tateyama_Okinoshima_shrine.jpg",3285,2300],["c:d/d6/Tateyama_Okinoshima.jpg",3354,2202],["c:c/cc/Tateyama_Montage.jpg",2472,3500,"館山市"],["c:3/3a/Kanto-daishinsai.jpg",798,575,"関東大震災"],["c:1/17/Lipari-Obsidienne_%285%29.jpg",3648,2736,"黒曜石"]]},{"id":"12_nojimasaki","n":"野島埼灯台","yomi":"のじまさきとうだい","cat":"近代","rank":"B","y":1869,"era":["meiji","taisho"],"sh":"","ad":"南房総市白浜町白浜","st":"JR内房線 館山駅からバスで約35分、野島崎灯台口で下車して歩いて約5分","la":34.9016,"lo":139.8886,"hook":"房総半島の最南端で、明治のはじめから光を放つ白い塔。日本で2番目に生まれた洋式灯台だ。","lead":"野島埼灯台は、房総半島のいちばん南の岬に立つ灯台です。明治のはじめ、フランス人技術者の設計で建てられ、日本で2番目に古い洋式灯台とされます。関東大震災で倒れ、のちに建て直されました。上まで登ることができる灯台です。","story":["江戸時代の終わり、日本は長い鎖国をやめ、外国の船が日本の港に出入りするようになりました。けれど、日本の海岸には船を安全に導く明かりがほとんどありません。«夜の海は危なくて進めない!» 外国からは、灯台をつくるよう強い要望が出されました。幕府は外国と約束をかわし、明治政府がそれを引きついで、各地に洋式灯台を建てることになりました。","東京湾の入口は、世界の船が江戸・横浜へ向かう大切な海の道です。まず三浦半島の観音埼に灯台がつくられ、続いて対岸の房総半島の南の端、野島崎にも灯台が建てられました。設計したのは、横須賀の造船所づくりでも知られるフランス人技術者、ヴェルニーです。こうして明治2年（西暦では1870年1月）、野島埼灯台に初めて明かりがともりました。","最初の灯台は、れんがを積んだ八角形の塔でした。岬の先で、波の音を聞きながら、灯台守たちは毎晩明かりをともし続けました。油をつぎ足し、レンズをみがき、嵐の夜も休むことはできません。«なぜ、そこまで?» 一晩でも明かりが消えれば、船が岩にぶつかってしまうかもしれないからです。","1923年、関東大震災が房総半島をおそいました。野島埼灯台は大きくこわれ、倒れてしまいました。けれど、灯台がなくては船が困ります。すぐに仮の明かりがつくられ、1925年、鉄筋コンクリートの新しい灯台が完成しました。白く、すらりとした今の姿は、このとき生まれたものです。","今の野島埼灯台は、中に入って上まで登ることができる «参観灯台» です。らせん階段を上ると、目の前には太平洋が広がり、晴れた日には伊豆大島も見えます。灯台のまわりは公園になっていて、岬の先の岩場まで歩けます。150年以上、この岬で海を照らし続けてきた灯台と、それを守ってきた人々の思いを感じてみてください。"],"tl":[["1866年","幕府が外国と灯台建設を約束する（江戸条約）"],["1869年","観音埼灯台が点灯（日本初の洋式灯台）"],["明治2年12月（1870年1月）","野島埼灯台が点灯"],["1923年","関東大震災で倒壊する"],["1925年","鉄筋コンクリート造で再建される"],["現在","参観灯台として一般公開"]],"who":[["ヴェルニー","フランス人技術者。横須賀製鉄所を建設し、野島埼灯台を設計した"],["灯台守","明かりをともし、灯台を守った職員たち"],["明治政府","各地に洋式灯台を整備した"]],"deep":["1866年の江戸条約（改税約書）で、幕府は開港に伴う灯台の整備を約束した。この約束にもとづく灯台は «条約灯台» と呼ばれ、野島埼灯台はその一つ。","観音埼灯台は明治2年1月1日（1869年2月11日）点灯、野島埼灯台は明治2年12月18日点灯とされ、西暦に直すと1870年1月にあたる。«日本で2番目の洋式灯台» といわれる根拠。","初代の灯台はれんが造の八角形の塔だったとされる。現在の塔も八角形を基本としたデザインを受けついでいる。","ヴェルニーは横須賀製鉄所（のちの横須賀海軍工廠）を建設した人物で、観音埼・野島埼・城ヶ島・品川の灯台の建設にも関わった。","関東大震災で房総半島南部は大きく隆起し、野島崎も周辺の海岸線が変わったとされる。もとは島だった野島が、元禄地震で陸続きになったという話も伝わる。","参観灯台は全国で十数か所しかない。開館時間や料金は変わることがあるので、行く前に確認したい。"],"look":["白い灯台の外観と、らせん階段","灯台の上から見る太平洋と伊豆大島","灯台の資料展示","岬の先の岩場と «房総半島最南端» の碑"],"q":["野島埼灯台を設計したフランス人技術者はだれ？","«ヴェルニー»。横須賀製鉄所をつくったことでも知られます。"],"koji":[],"myth":"初代灯台の形状や、野島が元禄地震で陸続きになった話は資料で確認を。","img":["フランソワ・レオンス・ヴェルニー","観音埼灯台","条約灯台"],"wp":"野島埼灯台","rel":{"ev":[],"grave":[]},"ph":[["c:1/17/Nojimasakitodai0.jpg",3008,2000,"野島埼灯台"],["c:3/37/%E5%8D%97%E6%B5%B7%E8%8D%98%E3%81%8B%E3%82%89%E3%81%AE%E9%A2%A8%E6%99%AF_-_panoramio_%283%29.jpg",4752,3168],["c:e/e3/%E5%8D%97%E6%B5%B7%E8%8D%98%E3%81%8B%E3%82%89%E3%81%AE%E9%A2%A8%E6%99%AF_-_panoramio.jpg",4752,3168],["c:4/47/Nojimasaki_Light_House_Museum_2.jpg",5472,3648],["c:1/1a/Nojimasaki_Light_House_Museum_1.jpg",4964,3309],["c:d/d7/View_of_Nojimazaki-Lighthouse_5.jpg",3072,2304],["c:0/02/View_of_Nojimazaki-Lighthouse_4.jpg",3072,2304],["c:8/8e/View_of_Nojimazaki-Lighthouse_3.jpg",3072,2304]]}];
